import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import api from '../utils/api';

export interface CartItem {
  productId: string;
  variantId: string;
  productName: string;
  productImage: string;
  brandName: string;
  variantName: string;
  unit: string;
  listPrice: number;
  discountPercent: number;
  discountAmount: number;
  gstPercent: number;
  gstType: string;
  gstAmount: number;
  finalPrice: number;
  primaryThreshold: number;
  secondaryThreshold: number;
  tertiaryThreshold: number;
  quantity: number;
}

interface CartContextType {
  items: CartItem[];
  addItem: (item: Omit<CartItem, 'quantity'>, qty?: number) => void;
  removeItem: (productId: string, variantId: string) => void;
  updateQty: (productId: string, variantId: string, qty: number) => void;
  clearCart: () => void;
  totalItems: number;
  totalAmount: number;
  totalDiscount: number;
  totalGst: number;
}

const CartContext = createContext<CartContextType>({} as CartContextType);

const CART_KEY = 'bm_cart';

export const CartProvider = ({ children }: { children: ReactNode }) => {
  const [items, setItems] = useState<CartItem[]>(() => {
    try { return JSON.parse(localStorage.getItem(CART_KEY) || '[]'); } catch { return []; }
  });

  useEffect(() => {
    localStorage.setItem(CART_KEY, JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    const token = localStorage.getItem('token');
    const role = localStorage.getItem('role');

    if (!token || role !== 'user') return;

    const syncCart = async () => {
      try {
        await api.put('/admin/user/cart-sync', { items });
      } catch (error) {
        // Keep cart local when user is not authenticated or the server is temporarily unavailable.
      }
    };

    syncCart();
  }, [items]);

  const addItem = (item: Omit<CartItem, 'quantity'>, qty = 1) => {
    setItems(prev => {
      const existing = prev.find(i => i.productId === item.productId && i.variantId === item.variantId);
      if (existing) return prev.map(i => i.productId === item.productId && i.variantId === item.variantId ? { ...i, quantity: i.quantity + qty } : i);
      return [...prev, { ...item, quantity: qty }];
    });
  };

  const removeItem = (productId: string, variantId: string) => {
    setItems(prev => prev.filter(i => !(i.productId === productId && i.variantId === variantId)));
  };

  const updateQty = (productId: string, variantId: string, qty: number) => {
    if (qty <= 0) { removeItem(productId, variantId); return; }
    setItems(prev => prev.map(i => i.productId === productId && i.variantId === variantId ? { ...i, quantity: qty } : i));
  };

  const clearCart = () => setItems([]);

  const totalItems = items.reduce((sum, i) => sum + i.quantity, 0);
  const totalAmount = items.reduce((sum, i) => sum + i.finalPrice * i.quantity, 0);
  const totalDiscount = items.reduce((sum, i) => sum + i.discountAmount * i.quantity, 0);
  const totalGst = items.reduce((sum, i) => sum + i.gstAmount * i.quantity, 0);

  return (
    <CartContext.Provider value={{ items, addItem, removeItem, updateQty, clearCart, totalItems, totalAmount, totalDiscount, totalGst }}>
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => useContext(CartContext);
