import React, { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import api from '../../../utils/api';
import { getMiniUsers, createMiniUser, updateMiniUser, deleteMiniUser, updateMiniUserStatus, getNextMiniId } from '../../../mini/adminMiniApi';

interface MiniUser {
  _id?: string;
  miniId?: string;
  name?: string;
  phone?: string;
  email?: string;
  address?: string;
  note?: string;
  status?: 'published' | 'draft' | string;
  memberId?: string;
}

interface Member {
  _id?: string;
  memberId?: string;
  name?: string;
  phone?: string;
  email?: string;
  status?: string;
}

export const AdminMiniUsers = () => {
  const [users, setUsers] = useState<MiniUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [nextId, setNextId] = useState('');
  const [members, setMembers] = useState<Member[]>([]);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    miniId: '',
    memberId: '',
    name: '',
    phone: '',
    email: '',
    address: '',
    note: '',
  });

  useEffect(() => {
    fetchUsers();
    fetchNextId();
    fetchMembers();
  }, []);

  const fetchMembers = async () => {
    try {
      const res = await api.get('/members/admin/all', { params: { page: 1, limit: 1000 } });
      setMembers(res.data?.members || res.data?.data || []);
    } catch {
      toast.error('Failed to load members');
    }
  };

  const fetchUsers = async () => {
    try {
      const res = await getMiniUsers();
      if (res.data?.success) {
        setUsers(res.data.data || []);
      }
    } catch (error) {
      toast.error('Failed to load users');
    } finally {
      setLoading(false);
    }
  };

  const fetchNextId = async () => {
    try {
      const res = await getNextMiniId();
      if (res.data?.success) {
        setNextId(res.data.nextId);
        setFormData((prev) => prev.memberId ? prev : ({ ...prev, miniId: res.data.nextId }));
      }
    } catch (error) {
      console.error('Error fetching next ID:', error);
    }
  };

  const handleCreateUser = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    try {
      const res = editingUserId
        ? await updateMiniUser(editingUserId, formData)
        : await createMiniUser(formData);
      if (res.data?.success) {
        toast.success(editingUserId ? 'Mini user updated' : 'Mini user created');
        setUsers((prev) => editingUserId
          ? prev.map((user) => user._id === editingUserId ? res.data.data as MiniUser : user)
          : [res.data.data as MiniUser, ...prev]);
        setShowForm(false);
        setEditingUserId(null);
        setFormData({ miniId: nextId, memberId: '', name: '', phone: '', email: '', address: '', note: '' });
        if (!editingUserId) fetchNextId();
      }
    } catch (error: unknown) {
      const err = error as { response?: { data?: { message?: string } } };
      toast.error(err.response?.data?.message || 'Failed to create user');
    }
  };

  const handleEditUser = (user: MiniUser) => {
    setEditingUserId(user._id || null);
    setShowForm(true);
    setFormData({
      miniId: user.miniId || '',
      memberId: user.memberId || '',
      name: user.name || '',
      phone: user.phone || '',
      email: user.email || '',
      address: user.address || '',
      note: user.note || '',
    });
  };

  const handleNewUser = () => {
    setEditingUserId(null);
    setFormData({ miniId: nextId, memberId: '', name: '', phone: '', email: '', address: '', note: '' });
    setShowForm(true);
    fetchNextId();
  };

  const handleCloseForm = () => {
    setEditingUserId(null);
    setShowForm(false);
  };

  const handleToggleStatus = async (id: string, status?: string) => {
    const newStatus = status === 'published' ? 'draft' : 'published';
    try {
      const res = await updateMiniUserStatus(id, newStatus);
      if (res.data?.success) {
        setUsers((prev) => prev.map((u) => (u._id === id ? { ...u, status: newStatus } : u)));
        toast.success(`User status updated to ${newStatus}`);
      }
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const handleDeleteUser = async (id: string) => {
    if (window.confirm('Are you sure?')) {
      try {
        await deleteMiniUser(id);
        setUsers((prev) => prev.filter((u) => u._id !== id));
        toast.success('User deleted');
      } catch (error) {
        toast.error('Failed to delete user');
      }
    }
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="admin-section">
      <div className="section-header">
        <h2>Mini Users (Keys)</h2>
        <button className="btn btn-primary" onClick={showForm ? handleCloseForm : handleNewUser}>
          {showForm ? 'Close' : '+ New User'}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleCreateUser} className="form-card">
          <div className="form-grid">
            <input
              type="text"
              placeholder="Mini ID (e.g., BM26001)"
              value={formData.miniId}
              onChange={(e) => setFormData({ ...formData, miniId: e.target.value })}
              className="form-control"
              required
            />
            <select
              className="form-control"
              value={formData.memberId}
              onChange={(e) => {
                const member = members.find((item) => item.memberId === e.target.value);
                setFormData({
                  ...formData,
                  memberId: member?.memberId || '',
                  miniId: member?.memberId || nextId,
                  name: member?.name || formData.name,
                  phone: member?.phone || formData.phone,
                  email: member?.email || formData.email,
                });
              }}
            >
              <option value="">Select member (optional)</option>
              {members.map((member) => (
                <option key={member._id || member.memberId} value={member.memberId || ''}>
                  {member.memberId || 'No ID'} - {member.name || 'Unnamed'}
                </option>
              ))}
            </select>
            <input
              type="text"
              placeholder="Name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              className="form-control"
            />
            <input
              type="tel"
              placeholder="Phone"
              value={formData.phone}
              onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
              className="form-control"
            />
            <input
              type="email"
              placeholder="Email"
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              className="form-control"
            />
            <textarea
              placeholder="Address"
              value={formData.address}
              onChange={(e) => setFormData({ ...formData, address: e.target.value })}
              className="form-control"
              rows={2}
            />
            <textarea
              placeholder="Note"
              value={formData.note}
              onChange={(e) => setFormData({ ...formData, note: e.target.value })}
              className="form-control"
              rows={2}
            />
          </div>
          <button type="submit" className="btn btn-primary">
            {editingUserId ? 'Update User' : 'Create User'}
          </button>
        </form>
      )}

      <div className="table-responsive">
        <table className="admin-table">
          <thead>
            <tr>
              <th>Mini ID</th>
              <th>Name</th>
              <th>Phone</th>
              <th>Email</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => {
              const userId = user._id ?? '';
              const userStatus = user.status ?? 'draft';
              const miniId = user.miniId ?? '-';

              return (
                <tr key={userId || miniId}>
                  <td>
                    <strong>{miniId}</strong>
                  </td>
                  <td>{user.name || '-'}</td>
                  <td>{user.phone || '-'}</td>
                  <td>{user.email || '-'}</td>
                  <td>
                    <span
                      className={`badge ${userStatus === 'published' ? 'badge-success' : 'badge-warning'}`}
                    >
                      {userStatus}
                    </span>
                  </td>
                  <td>
                    <button className="btn btn-sm btn-secondary" onClick={() => handleEditUser(user)}>
                      Edit
                    </button>
                    <button
                      className="btn btn-sm btn-info"
                      onClick={() => userId && handleToggleStatus(userId, userStatus)}
                    >
                      {userStatus === 'published' ? 'Unpublish' : 'Publish'}
                    </button>
                    <button className="btn btn-sm btn-danger" onClick={() => userId && handleDeleteUser(userId)}>
                      Delete
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AdminMiniUsers;
