              {!!showViewModal.descriptions?.filter((d: any) => d.heading || d.subHeading || d.paragraph).length && (
                <div style={{ marginBottom: 20 }}>
                  <h4 style={{ marginBottom: 8 }}>📝 Description</h4>
                  {showViewModal.descriptions.map((d: any, i: number) => (
                    (d.heading || d.subHeading || d.paragraph) && (
                      <div key={i} style={{ marginBottom: 10, padding: 12, background: 'var(--gray-50)', borderRadius: 8, border: '1px solid var(--gray-200)' }}>
                        {d.heading && <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>{d.heading}</div>}
                        {d.subHeading && <div style={{ fontWeight: 600, fontSize: 12, color: 'var(--gray-500)', marginBottom: 6 }}>{d.subHeading}</div>}
                        {d.paragraph && <div style={{ fontSize: 13, lineHeight: 1.6, color: 'var(--gray-700)', whiteSpace: 'pre-wrap' }}>{d.paragraph}</div>}
                      </div>
                    )
                  ))}
                </div>
              )}

