              {!!showViewModal.videoLinks?.filter((v: any) => v.url).length && (
                <div style={{ marginBottom: 20 }}>
                  <h4 style={{ marginBottom: 8 }}>🎬 Video Links</h4>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                    {showViewModal.videoLinks.filter((v: any) => v.url).map((v: any, i: number) => (
                      <a key={i} href={v.url} target="_blank" rel="noreferrer" style={{ fontSize: 13, color: 'var(--primary)' }}>
                        ▶ {v.title || v.url}
                      </a>
                    ))}
                  </div>
                </div>
              )}

