
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api, { formatINR } from '../../utils/api';
import { useCart } from '../../context/CartContext';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';
import { trackGoogleAdsPurchase } from '../../utils/googleAds';

declare global { interface Window { Razorpay: any; } }

const emptyAddr = { name: '', mobile: '', email: '', addressLine1: '', addressLine2: '', city: '', state: '', pincode: '', country: 'India' };

function AddressForm({ addr, setAddr }: { addr: any; setAddr: React.Dispatch<React.SetStateAction<any>> }) {
  return (
    <div>
      <div className="grid-2 checkout-form-grid">
        {[
          ['name', 'Full Name'], ['mobile', 'Mobile Number'], ['email', 'Email'],
          ['addressLine1', 'Address Line 1'], ['addressLine2', 'Address Line 2 (Optional)'],
          ['city', 'City'], ['state', 'State'], ['pincode', 'Pincode'],
        ].map(([key, label]) => (
          <div key={key} className="form-group" style={{ marginBottom: 12 }}>
            <label className="form-label">{label}</label>
            <input className="form-control" value={addr[key] || ''} onChange={e => setAddr((p: any) => ({ ...p, [key]: e.target.value }))} />
          </div>
        ))}
      </div>
    </div>
  );
}

export default function CheckoutPage() {
  const { items, totalAmount, clearCart } = useCart();
  const { user, refreshUser } = useAuth();
  const navigate = useNavigate();
  const [billing, setBilling] = useState({ ...emptyAddr });
  const [shipping, setShipping] = useState({ ...emptyAddr });
  const [sameAsBilling, setSameAsBilling] = useState(true);
  const [placing, setPlacing] = useState(false);
  const [savedAddresses, setSavedAddresses] = useState<any[]>([]);
  const [showSaved, setShowSaved] = useState(false);
  const [bankModalOpen, setBankModalOpen] = useState(false);
  const [paymentProofFile, setPaymentProofFile] = useState<File | null>(null);
  const [proofPreviewUrl, setProofPreviewUrl] = useState('');
  const [submittedBankOrder, setSubmittedBankOrder] = useState<any>(null);
  const [secondsRemaining, setSecondsRemaining] = useState(20 * 60);

  useEffect(() => {
    if (user) {
      const a = user as any;
      if (a.addresses?.length) {
        setSavedAddresses(a.addresses);
        const def = a.addresses.find((ad: any) => ad.isDefault) || a.addresses[0];
        setBilling({ name: def.name, mobile: def.mobile, email: def.email, addressLine1: def.addressLine1, addressLine2: def.addressLine2, city: def.city, state: def.state, pincode: def.pincode, country: def.country || 'India' });
      } else {
        setBilling(p => ({ ...p, name: user.name, email: user.email }));
      }
    }
    // Load Razorpay script
    const s = document.createElement('script');
    s.src = 'https://checkout.razorpay.com/v1/checkout.js';
    document.body.appendChild(s);
  }, [user]);

  const effectiveShipping = sameAsBilling ? billing : shipping;

  useEffect(() => {
    if (!paymentProofFile) {
      setProofPreviewUrl('');
      return;
    }
    const previewUrl = URL.createObjectURL(paymentProofFile);
    setProofPreviewUrl(previewUrl);
    return () => URL.revokeObjectURL(previewUrl);
  }, [paymentProofFile]);

  useEffect(() => {
    const orderId = submittedBankOrder?._id;
    if (!bankModalOpen || !orderId || submittedBankOrder.paymentStatus === 'paid') return;

    let active = true;
    const refreshPaymentStatus = async () => {
      try {
        const response = await api.get(`/orders/${orderId}`);
        if (active && response.data?.order) setSubmittedBankOrder(response.data.order);
      } catch { }
    };
    refreshPaymentStatus();
    const interval = window.setInterval(refreshPaymentStatus, 5000);
    return () => { active = false; window.clearInterval(interval); };
  }, [bankModalOpen, submittedBankOrder?._id, submittedBankOrder?.paymentStatus]);

  useEffect(() => {
    if (!bankModalOpen || !submittedBankOrder || submittedBankOrder.paymentStatus === 'paid') return;
    const fallbackDeadline = new Date(submittedBankOrder.paymentSubmittedAt).getTime() + 20 * 60 * 1000;
    const deadline = new Date(submittedBankOrder.paymentReviewDeadline || fallbackDeadline).getTime();
    const updateCountdown = () => setSecondsRemaining(Number.isFinite(deadline) ? Math.max(0, Math.ceil((deadline - Date.now()) / 1000)) : 0);
    updateCountdown();
    const interval = window.setInterval(updateCountdown, 1000);
    return () => window.clearInterval(interval);
  }, [bankModalOpen, submittedBankOrder?._id, submittedBankOrder?.paymentStatus, submittedBankOrder?.paymentReviewDeadline]);

  useEffect(() => {
    if (!bankModalOpen || submittedBankOrder) return;
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setBankModalOpen(false);
    };
    window.addEventListener('keydown', closeOnEscape);
    return () => window.removeEventListener('keydown', closeOnEscape);
  }, [bankModalOpen, submittedBankOrder]);

  const submitBankPayment = async () => {
    if (!billing.name || !billing.mobile || !billing.addressLine1 || !billing.city || !billing.pincode) {
      toast.error('Fill all billing address fields');
      return;
    }
    if (!paymentProofFile) {
      toast.error('Upload your payment screenshot');
      return;
    }

    setPlacing(true);
    const formData = new FormData();
    formData.append('items', JSON.stringify(items.map(i => ({ productId: i.productId, variantId: i.variantId, quantity: i.quantity }))));
    formData.append('billingAddress', JSON.stringify(billing));
    formData.append('shippingAddress', JSON.stringify(effectiveShipping));
    formData.append('paymentMethod', 'bank_transfer');
    formData.append('paymentProof', paymentProofFile);

    try {
      const response = await api.post('/orders', formData);
      setSubmittedBankOrder(response.data.order);
      setSecondsRemaining(20 * 60);
      clearCart();
      toast.success('Payment screenshot submitted');
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Could not submit payment screenshot');
    } finally {
      setPlacing(false);
    }
  };

  const formatCountdown = (totalSeconds: number) =>
    `${String(Math.floor(totalSeconds / 60)).padStart(2, '0')}:${String(totalSeconds % 60).padStart(2, '0')}`;

  const placeOrder = async (paymentMethod: 'razorpay' | 'pay_later') => {
    if (!billing.name || !billing.mobile || !billing.addressLine1 || !billing.city || !billing.pincode) {
      toast.error('Fill all billing address fields'); return;
    }
    setPlacing(true);
    try {
      if (paymentMethod === 'razorpay') {
        // Create Razorpay order
        const keyRes = await api.get('/payment/key');
        const orderRes = await api.post('/payment/create-order', { amount: totalAmount, receipt: `order_${Date.now()}` });
        const rzpOrder = orderRes.data.order;

        const options = {
          key: keyRes.data.key,
          amount: rzpOrder.amount,
          currency: 'INR',
          name: 'Basava Mart',
          description: 'Purchase',
          order_id: rzpOrder.id,
          handler: async (response: any) => {
            // Verify payment
            const verifyRes = await api.post('/payment/verify', {
              razorpay_order_id: response.razorpay_order_id,
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_signature: response.razorpay_signature,
            });
            if (!verifyRes.data?.success) {
              throw new Error('Payment verification failed');
            }
            // Create order
            const createRes = await api.post('/orders', {
              items: items.map(i => ({ productId: i.productId, variantId: i.variantId, quantity: i.quantity })),
              billingAddress: billing, shippingAddress: effectiveShipping,
              paymentMethod: 'razorpay',
              razorpayOrderId: response.razorpay_order_id,
              razorpayPaymentId: response.razorpay_payment_id,
              razorpaySignature: response.razorpay_signature,
            });
            const createdOrder = createRes.data?.order;
            if (createdOrder && createdOrder._id && createdOrder.paymentStatus === 'paid') {
              try { trackGoogleAdsPurchase({ orderId: createdOrder._id, value: createdOrder.totalAmount }); } catch (e) { }
            }
            clearCart(); toast.success('Order placed successfully!'); navigate('/my-orders');
          },
          prefill: { name: billing.name, email: billing.email, contact: billing.mobile },
          theme: { color: '#e26a26' },
          modal: { ondismiss: () => { setPlacing(false); } }
        };
        const rzp = new window.Razorpay(options);
        rzp.open();
        setPlacing(false);
      } else {
        // Pay later
        await api.post('/orders', {
          items: items.map(i => ({ productId: i.productId, variantId: i.variantId, quantity: i.quantity })),
          billingAddress: billing, shippingAddress: effectiveShipping,
          paymentMethod: 'pay_later',
        });
        clearCart(); toast.success('Order placed with Pay Later!'); navigate('/my-orders');
      }
    } catch (e: any) { toast.error(e.response?.data?.message || 'Error placing order'); setPlacing(false); }
  };

  return (
    <div className="checkout-page">
      <style>{`
        .checkout-page { padding-top: 20px; padding-bottom: 48px; }
        .checkout-title { font-size: 22px; font-weight: 800; margin-bottom: 20px; color: var(--gray-900); letter-spacing: -0.01em; }
        .checkout-layout { display: grid; grid-template-columns: 1fr 360px; gap: 28px; align-items: start; }

        .checkout-section-card { background: white; border-radius: var(--radius-lg); border: 1px solid var(--gray-200); box-shadow: var(--shadow-sm); padding: 22px; margin-bottom: 18px; }
        .checkout-section-title { font-size: 15px; font-weight: 700; color: var(--gray-900); display: flex; align-items: center; gap: 8px; }

        .saved-addr-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; }
        .saved-addr-list { display: flex; flex-direction: column; gap: 10px; }
        .saved-addr-item { border: 1.5px solid var(--gray-200); border-radius: 10px; padding: 14px; cursor: pointer; display: flex; gap: 12px; align-items: center; transition: var(--transition); }
        .saved-addr-item:hover { border-color: var(--primary-light); background: var(--primary-bg); }
        .saved-addr-name { font-weight: 600; font-size: 14px; color: var(--gray-900); }
        .saved-addr-detail { font-size: 12.5px; color: var(--gray-500); margin-top: 2px; }

        .shipping-header-row { display: flex; align-items: center; gap: 10px; margin-bottom: 16px; flex-wrap: wrap; }
        .same-as-billing-toggle { display: flex; align-items: center; gap: 7px; cursor: pointer; margin-left: auto; font-size: 13.5px; color: var(--gray-600); font-weight: 500; }
        .same-as-billing-toggle input { width: 16px; height: 16px; accent-color: var(--primary); cursor: pointer; }
        .shipping-note { color: var(--gray-500); font-size: 13.5px; background: var(--gray-50); border-radius: 8px; padding: 10px 12px; }

        .checkout-summary-card { position: sticky; top: 80px; }
        .checkout-summary-inner { background: white; border-radius: var(--radius-lg); border: 1px solid var(--gray-200); box-shadow: var(--shadow-sm); padding: 24px; }
        .checkout-summary-title { font-size: 16px; font-weight: 700; margin-bottom: 14px; color: var(--gray-900); }
        .summary-line-item { display: flex; justify-content: space-between; gap: 8px; font-size: 13px; padding: 8px 0; border-bottom: 1px solid var(--gray-100); }
        .summary-line-name { color: var(--gray-700); }
        .summary-line-amount { font-weight: 600; color: var(--gray-900); flex-shrink: 0; }
        .summary-total-row { display: flex; justify-content: space-between; align-items: center; font-size: 18px; font-weight: 800; color: var(--primary); margin-top: 16px; padding-top: 14px; border-top: 2px solid var(--gray-200); }
        .secure-note { font-size: 12px; color: var(--gray-500); text-align: center; margin-top: 12px; }

        .mobile-pay-bar { display: none; }
        .bank-transfer-overlay { z-index: 1000; padding: max(12px, env(safe-area-inset-top)) 12px max(12px, env(safe-area-inset-bottom)); overflow-y: auto; box-sizing: border-box; }
        .bank-transfer-modal { width: 100%; max-width: 500px; max-height: calc(100vh - 24px); max-height: calc(100dvh - 24px); overflow-y: auto; margin: auto; }

        @media (max-width: 860px) {
          .checkout-layout { grid-template-columns: 1fr; gap: 16px; }
          .checkout-title { font-size: 19px; margin-bottom: 14px; }
          .checkout-section-card { padding: 16px; margin-bottom: 14px; }
          .checkout-summary-card { position: static; }
          .checkout-summary-inner .pay-primary-btn { display: none; }
          .checkout-page { padding-bottom: 100px; }
          .saved-addr-item { flex-wrap: wrap; }
          .saved-addr-item .btn { width: 100%; margin-left: 0 !important; }

          .mobile-pay-bar {
            display: flex; align-items: center; justify-content: space-between; gap: 12px;
            position: fixed; left: 0; right: 0; bottom: 0; z-index: 50;
            background: white; border-top: 1px solid var(--gray-200);
            padding: 12px 16px calc(12px + env(safe-area-inset-bottom));
            box-shadow: 0 -6px 20px rgba(0,0,0,0.08);
          }
          .mobile-pay-bar .mpb-total-label { font-size: 11px; color: var(--gray-500); font-weight: 500; }
          .mobile-pay-bar .mpb-total-value { font-size: 18px; font-weight: 800; color: var(--primary); }
          .mobile-pay-bar .btn { flex-shrink: 0; min-width: 150px; }
        }

        @media (max-width: 520px) {
          .checkout-form-grid.grid-2 { grid-template-columns: 1fr; }
          .bank-transfer-overlay { align-items: flex-end; padding: 8px 8px calc(8px + env(safe-area-inset-bottom)); }
          .bank-transfer-modal { max-height: calc(100vh - 16px); max-height: calc(100dvh - 16px); }
        }
      `}</style>

      <h1 className="checkout-title">🏠 Checkout</h1>

      <div className="checkout-layout">
        <div>
          {/* Saved Addresses */}
          {savedAddresses.length > 0 && (
            <div className="checkout-section-card">
              <div className="saved-addr-header">
                <h3 className="checkout-section-title">📍 Saved Addresses</h3>
                <button className="btn btn-gray btn-sm" onClick={() => setShowSaved(p => !p)}>{showSaved ? 'Hide' : 'Show'}</button>
              </div>
              {showSaved && (
                <div className="saved-addr-list">
                  {savedAddresses.map((a, i) => (
                    <div key={i} className="saved-addr-item"
                      onClick={() => { setBilling({ name: a.name, mobile: a.mobile, email: a.email, addressLine1: a.addressLine1, addressLine2: a.addressLine2, city: a.city, state: a.state, pincode: a.pincode, country: a.country }); setShowSaved(false); }}>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div className="saved-addr-name">{a.name}</div>
                        <div className="saved-addr-detail">{a.addressLine1}, {a.city} - {a.pincode}</div>
                        <div className="saved-addr-detail">{a.mobile}</div>
                      </div>
                      <button className="btn btn-outline btn-sm" style={{ marginLeft: 'auto', flexShrink: 0 }}>Use</button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Billing Address */}
          <div className="checkout-section-card">
            <h3 className="checkout-section-title" style={{ marginBottom: 16 }}>📬 Billing Address</h3>
            <AddressForm addr={billing} setAddr={setBilling} />
          </div>

          {/* Shipping Address */}
          <div className="checkout-section-card">
            <div className="shipping-header-row">
              <h3 className="checkout-section-title">🚚 Shipping Address</h3>
              <label className="same-as-billing-toggle">
                <input type="checkbox" checked={sameAsBilling} onChange={e => setSameAsBilling(e.target.checked)} />
                Same as billing
              </label>
            </div>
            {!sameAsBilling && <AddressForm addr={shipping} setAddr={setShipping} />}
            {sameAsBilling && <div className="shipping-note">Using billing address for shipping</div>}
          </div>
        </div>

        {/* Summary */}
        <div className="checkout-summary-card">
          <div className="checkout-summary-inner">
            <h3 className="checkout-summary-title">Order Summary</h3>
            {items.map(item => (
              <div key={`${item.productId}-${item.variantId}`} className="summary-line-item">
                <span className="summary-line-name">{item.productName} × {item.quantity}</span>
                <span className="summary-line-amount">₹{formatINR(item.finalPrice * item.quantity)}</span>
              </div>
            ))}
            <div className="summary-total-row">
              <span>Total</span><span>₹{formatINR(totalAmount)}</span>
            </div>

            <button className="btn btn-primary btn-lg pay-primary-btn" style={{ width: '100%', marginTop: 20 }} onClick={() => placeOrder('razorpay')} disabled={placing}>
              {placing ? <div className="spinner" /> : '💳 Pay with Razorpay'}
            </button>
            <button className="btn btn-outline" style={{ width: '100%', marginTop: 10 }} onClick={() => { setPaymentProofFile(null); setSubmittedBankOrder(null); setBankModalOpen(true); }} disabled={placing}>
              🏦 Show Bank Details of Basava Mart
            </button>
            <div className="secure-note">🔒 Secure checkout powered by Razorpay</div>
          </div>
        </div>
      </div>

      {/* Sticky mobile pay bar */}
      <div className="mobile-pay-bar">
        <div>
          <div className="mpb-total-label">Total</div>
          <div className="mpb-total-value">₹{formatINR(totalAmount)}</div>
        </div>
        <button className="btn btn-primary" onClick={() => placeOrder('razorpay')} disabled={placing}>
          {placing ? <div className="spinner" /> : '💳 Pay Now'}
        </button>
      </div>

      {bankModalOpen && (
        <div className="modal-overlay bank-transfer-overlay" onClick={e => { if (e.target === e.currentTarget && !submittedBankOrder) setBankModalOpen(false); }}>
          <div className="modal bank-transfer-modal" role="dialog" aria-modal="true" aria-labelledby="bank-payment-title" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2 id="bank-payment-title">Basava Mart bank transfer</h2>
              {!submittedBankOrder && <button className="modal-close" type="button" aria-label="Close bank details" onClick={() => setBankModalOpen(false)}>✕</button>}
            </div>
            <div className="modal-body">
              {!submittedBankOrder ? (
                <>
                  <img src="/assets/images/myQR.webp" alt="Basava Mart payment QR code" style={{ display: 'block', width: 'min(100%, 230px)', aspectRatio: '1', objectFit: 'contain', margin: '0 auto 18px', border: '1px solid var(--gray-200)', borderRadius: 8 }} />
                  <div style={{ display: 'grid', gap: 6, padding: 14, background: 'var(--gray-50)', borderRadius: 8, fontSize: 13 }}>
                    <strong>BASAVA MART.</strong>
                    <span>ICICI BANK</span>
                    <span>Basaveshwarnagar Branch, Bangalore</span>
                    <span>Current Account No: 230105001976</span>
                    <span>IFSC Code: ICIC0002301</span>
                    <strong style={{ marginTop: 6 }}>Transfer amount: ₹{formatINR(totalAmount)}</strong>
                  </div>
                  <label className="form-label" htmlFor="payment-proof" style={{ display: 'block', marginTop: 16 }}>Upload payment screenshot</label>
                  <input id="payment-proof" className="form-control" type="file" accept="image/jpeg,image/png,image/webp" onChange={e => setPaymentProofFile(e.target.files?.[0] || null)} />
                  {proofPreviewUrl && <img src={proofPreviewUrl} alt="Payment screenshot preview" style={{ display: 'block', maxHeight: 180, maxWidth: '100%', objectFit: 'contain', margin: '12px auto 0', borderRadius: 6 }} />}
                  <button className="btn btn-primary" style={{ width: '100%', marginTop: 18 }} onClick={submitBankPayment} disabled={placing || !items.length}>
                    {placing ? <div className="spinner" /> : 'I have paid, submit screenshot'}
                  </button>
                </>
              ) : (
                <div style={{ textAlign: 'center', padding: '8px 0' }}>
                  {submittedBankOrder.paymentStatus === 'paid' ? (
                    <>
                      <h3 style={{ color: 'var(--success, #218838)' }}>Payment verified</h3>
                      <p>Your order is marked as paid.</p>
                      <button className="btn btn-primary" onClick={() => navigate('/my-orders')}>View my orders</button>
                    </>
                  ) : (
                    <>
                      <h3>Please wait a while</h3>
                      <p>Your payment screenshot has been sent for verification.</p>
                      <div aria-live="polite" style={{ fontSize: 32, fontWeight: 800, color: 'var(--primary)', margin: '12px 0' }}>{formatCountdown(secondsRemaining)}</div>
                      <p style={{ fontSize: 13, color: 'var(--gray-600)' }}>{secondsRemaining > 0 ? 'Please allow up to 20 minutes for confirmation.' : 'Confirmation is taking longer than expected. Please call us.'}</p>
                      <a className="btn btn-outline" href="tel:+919844192551" style={{ display: 'inline-block', marginTop: 8 }}>Call +91 9844192551</a>
                    </>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}