import React from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useCart } from '../../context/CartContext';
import { formatINR, getImageUrl } from '../../utils/api';

function calcPkgBreakdown(qty: number, t: number, s: number, p: number) {
  let rem = qty;
  const res = { tertiary: { qty: t, count: 0, total: 0 }, secondary: { qty: s, count: 0, total: 0 }, primary: { qty: p, count: 0, total: 0 }, remainder: 0 };
  if (t > 0) { res.tertiary.count = Math.floor(rem / t); rem %= t; res.tertiary.total = res.tertiary.count * t; }
  if (s > 0) { res.secondary.count = Math.floor(rem / s); rem %= s; res.secondary.total = res.secondary.count * s; }
  if (p > 0) { res.primary.count = Math.floor(rem / p); rem %= p; res.primary.total = res.primary.count * p; }
  res.remainder = rem;
  return res;
}

export default function CartPage() {
  const { items, removeItem, updateQty, totalAmount, totalDiscount, totalGst } = useCart();
  const navigate = useNavigate();

  const goToProduct = (productId: string) => navigate(`/products/${productId}`);
  const stop = (e: React.SyntheticEvent) => e.stopPropagation();

  if (items.length === 0) return (
    <div style={{ textAlign: 'center', padding: '96px 20px' }}>
      <div style={{ fontSize: 72, lineHeight: 1 }}>🛒</div>
      <h2 style={{ fontSize: 22, fontWeight: 700, marginTop: 20, color: 'var(--gray-800)' }}>Your cart is empty</h2>
      <p style={{ color: 'var(--gray-500)', marginTop: 6, fontSize: 14 }}>Add products to get started</p>
      <Link to="/products" className="btn btn-primary" style={{ marginTop: 24, display: 'inline-flex' }}>Browse Products</Link>
    </div>
  );

  const subtotal = items.reduce((s, i) => s + i.listPrice * i.quantity, 0);

  return (
    <div className="cart-page">
      <style>{`
        .cart-page { padding-top: 20px; padding-bottom: 48px; }
        .cart-title { font-size: 22px; font-weight: 800; margin-bottom: 20px; color: var(--gray-900); letter-spacing: -0.01em; }
        .cart-layout { display: grid; grid-template-columns: 1fr 360px; gap: 28px; align-items: start; }
        .cart-items { display: flex; flex-direction: column; gap: 14px; }

        .cart-item-card { background: white; border-radius: var(--radius-lg); border: 1px solid var(--gray-200); box-shadow: var(--shadow-sm); overflow: hidden; transition: box-shadow 0.2s ease, border-color 0.2s ease; cursor: pointer; }
        .cart-item-card:hover { box-shadow: var(--shadow-md); border-color: var(--primary-light); }
        .cart-item-inner { display: flex; gap: 16px; padding: 16px; }
        .cart-item-thumb { width: 88px; height: 88px; object-fit: contain; border-radius: 10px; border: 1px solid var(--gray-200); background: var(--gray-50); flex-shrink: 0; }
        .cart-item-main { flex: 1; min-width: 0; }
        .cart-item-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
        .cart-item-brand { font-size: 11px; color: var(--gray-500); font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; }
        .cart-item-name { font-weight: 600; font-size: 15px; margin-top: 3px; color: var(--gray-900); line-height: 1.35; }
        .cart-item-variant { font-size: 12.5px; color: var(--gray-500); margin-top: 3px; }
        .cart-item-remove { border: none; background: var(--gray-50); cursor: pointer; color: var(--gray-500); font-size: 15px; padding: 7px; border-radius: 8px; line-height: 1; flex-shrink: 0; transition: var(--transition); }
        .cart-item-remove:hover { background: #fee2e2; color: var(--red); }

        .cart-item-bottom { display: flex; align-items: center; justify-content: space-between; margin-top: 14px; gap: 12px; flex-wrap: wrap; }
        .qty-control { display: flex; align-items: center; border: 1.5px solid var(--gray-200); border-radius: 9px; overflow: hidden; background: var(--gray-50); }
        .qty-btn { width: 34px; height: 34px; border: none; background: transparent; cursor: pointer; font-size: 16px; color: var(--gray-700); display: flex; align-items: center; justify-content: center; transition: var(--transition); }
        .qty-btn:hover { background: white; color: var(--primary); }
        .qty-input { width: 46px; height: 34px; border: none; background: transparent; text-align: center; font-size: 14px; font-weight: 700; color: var(--gray-900); }
        .qty-input::-webkit-outer-spin-button, .qty-input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }

        .cart-item-price { text-align: right; }
        .cart-item-price-final { font-size: 18px; font-weight: 800; color: var(--primary); }
        .cart-item-price-unit { font-size: 12px; color: var(--gray-500); margin-top: 1px; }
        .cart-item-price-off { font-size: 11.5px; color: var(--green); font-weight: 600; margin-top: 2px; }

        .cart-item-gst { margin-top: 10px; font-size: 12px; color: var(--gray-500); }

        .cart-summary-card { position: sticky; top: 80px; }
        .cart-summary-inner { background: white; border-radius: var(--radius-lg); border: 1px solid var(--gray-200); box-shadow: var(--shadow-sm); padding: 24px; }
        .cart-summary-title { font-size: 16px; font-weight: 700; margin-bottom: 18px; color: var(--gray-900); }
        .cart-summary-total { border-top: 2px solid var(--gray-200); margin-top: 12px; padding-top: 14px; display: flex; justify-content: space-between; align-items: center; }
        .cart-save-banner { background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 10px; padding: 10px 12px; margin-top: 14px; font-size: 13px; color: #15803d; font-weight: 600; }

        .mobile-checkout-bar { display: none; }

        @media (max-width: 860px) {
          .cart-layout { grid-template-columns: 1fr; gap: 16px; }
          .cart-title { font-size: 19px; margin-bottom: 14px; }
          .cart-item-inner { padding: 14px; gap: 12px; }
          .cart-item-thumb { width: 72px; height: 72px; }
          .cart-item-name { font-size: 14px; }
          .cart-summary-card { position: static; }
          .cart-summary-inner .btn-lg.checkout-btn { display: none; }
          .cart-page { padding-bottom: 92px; }

          .mobile-checkout-bar {
            display: flex; align-items: center; justify-content: space-between; gap: 12px;
            position: fixed; left: 0; right: 0; bottom: 0; z-index: 50;
            background: white; border-top: 1px solid var(--gray-200);
            padding: 12px 16px calc(12px + env(safe-area-inset-bottom));
            box-shadow: 0 -6px 20px rgba(0,0,0,0.08);
          }
          .mobile-checkout-bar .mcb-total-label { font-size: 11px; color: var(--gray-500); font-weight: 500; }
          .mobile-checkout-bar .mcb-total-value { font-size: 18px; font-weight: 800; color: var(--primary); }
          .mobile-checkout-bar .btn { flex-shrink: 0; }
        }
      `}</style>

      <h1 className="cart-title">🛒 Shopping Cart ({items.length} {items.length === 1 ? 'item' : 'items'})</h1>

      <div className="cart-layout">
        {/* Items */}
        <div className="cart-items">
          {items.map(item => {
            const pkg = calcPkgBreakdown(item.quantity, item.tertiaryThreshold, item.secondaryThreshold, item.primaryThreshold);
            return (
              <div
                key={`${item.productId}-${item.variantId}`}
                className="cart-item-card"
                onClick={() => goToProduct(item.productId)}
                role="link"
                tabIndex={0}
                onKeyDown={(e) => { if (e.key === 'Enter') goToProduct(item.productId); }}
              >
                <div className="cart-item-inner">
                  <img src={getImageUrl(item.productImage)} alt={item.productName} className="cart-item-thumb" />
                  <div className="cart-item-main">
                    <div className="cart-item-top">
                      <div>
                        <div className="cart-item-brand">{item.brandName}</div>
                        <div className="cart-item-name">{item.productName}</div>
                        <div className="cart-item-variant">Variant: {item.variantName} ({item.unit})</div>
                      </div>
                      <button
                        className="cart-item-remove"
                        onClick={(e) => { stop(e); removeItem(item.productId, item.variantId); }}
                        aria-label="Remove item"
                      >🗑️</button>
                    </div>

                    <div className="cart-item-bottom">
                      <div className="qty-control" onClick={stop}>
                        <button className="qty-btn" onClick={() => updateQty(item.productId, item.variantId, item.quantity - 1)} aria-label="Decrease quantity">−</button>
                        <input
                          type="number"
                          className="qty-input"
                          value={item.quantity}
                          onChange={e => updateQty(item.productId, item.variantId, Math.max(1, +e.target.value))}
                        />
                        <button className="qty-btn" onClick={() => updateQty(item.productId, item.variantId, item.quantity + 1)} aria-label="Increase quantity">+</button>
                      </div>

                      <div className="cart-item-price">
                        <div className="cart-item-price-final">₹{formatINR(item.listPrice * item.quantity)}</div>
                        <div className="cart-item-price-unit">₹{formatINR(item.listPrice)} × {item.quantity}</div>
                        {item.discountPercent > 0 && <div className="cart-item-price-off">-{item.discountPercent}% off</div>}
                      </div>
                    </div>

                    <div className="cart-item-gst">
                      GST ({item.gstPercent}% {item.gstType}): ₹{formatINR(item.gstAmount * item.quantity)}
                    </div>

                    {(item.primaryThreshold > 0 || item.secondaryThreshold > 0 || item.tertiaryThreshold > 0) && item.quantity > 1 && (
                      <div className="pkg-breakdown" style={{ marginTop: 10 }} onClick={stop}>
                        <div style={{ fontSize: 11, fontWeight: 600, color: 'var(--primary)', marginBottom: 4 }}>📦 Package Breakdown (qty: {item.quantity})</div>
                        {pkg.tertiary.count > 0 && <div className="pkg-row"><span className="pkg-label">Tertiary Box ({pkg.tertiary.qty})</span><span>{pkg.tertiary.count} box × {pkg.tertiary.qty} = {pkg.tertiary.total} pcs</span></div>}
                        {pkg.secondary.count > 0 && <div className="pkg-row"><span className="pkg-label">Secondary ({pkg.secondary.qty})</span><span>{pkg.secondary.count} pack × {pkg.secondary.qty} = {pkg.secondary.total} pcs</span></div>}
                        {pkg.primary.count > 0 && <div className="pkg-row"><span className="pkg-label">Primary ({pkg.primary.qty})</span><span>{pkg.primary.count} pack × {pkg.primary.qty} = {pkg.primary.total} pcs</span></div>}
                        {pkg.remainder > 0 && <div className="pkg-row"><span className="pkg-label">Loose</span><span>{pkg.remainder} pcs</span></div>}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Order Summary */}
        <div className="cart-summary-card">
          <div className="cart-summary-inner">
            <h3 className="cart-summary-title">Order Summary</h3>
            <div className="price-row"><span>Subtotal ({items.length} items)</span><span>₹{formatINR(subtotal)}</span></div>
            <div className="price-row"><span>Total Discount</span><span style={{ color: 'var(--green)' }}>-₹{formatINR(totalDiscount)}</span></div>
            <div className="price-row"><span>Total GST (18%)</span><span>₹{formatINR(totalGst)}</span></div>
            <div className="cart-summary-total">
              <span style={{ fontSize: 15, fontWeight: 700, color: 'var(--gray-900)' }}>Total Amount</span>
              <span style={{ fontSize: 22, fontWeight: 800, color: 'var(--primary)' }}>₹{formatINR(totalAmount)}</span>
            </div>
            {totalDiscount > 0 && (
              <div className="cart-save-banner">🎉 You save ₹{formatINR(totalDiscount)} on this order!</div>
            )}
            <button className="btn btn-primary btn-lg checkout-btn" style={{ width: '100%', marginTop: 20 }} onClick={() => navigate('/checkout')}>
              Proceed to Checkout →
            </button>
            <Link to="/products" style={{ display: 'block', textAlign: 'center', marginTop: 12, fontSize: 14, color: 'var(--gray-500)', textDecoration: 'none' }}>← Continue Shopping</Link>
          </div>
        </div>
      </div>

      {/* Sticky mobile checkout bar */}
      <div className="mobile-checkout-bar">
        <div>
          <div className="mcb-total-label">Total ({items.length} items)</div>
          <div className="mcb-total-value">₹{formatINR(totalAmount)}</div>
        </div>
        <button className="btn btn-primary" onClick={() => navigate('/checkout')}>
          Checkout →
        </button>
      </div>
    </div>
  );
}