

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import api, { getImageUrl } from '../../utils/api';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';
import {
  FiCheckCircle,
  FiShoppingCart,
  FiHome,
  FiChevronRight,
  FiPackage,
  FiArrowLeft,
  FiDownload,
  FiPlay,
  FiPlus,
  FiMinus,
  FiLock,
  FiTag,
  FiAlertCircle,
  FiXCircle,
} from 'react-icons/fi';
import { MdOutlineInventory2 } from 'react-icons/md';

const formatWeight = (value: number | null | undefined) => value == null ? '0' : String(value);

/* ─── Responsive styles ─── */
const detailStyles = `
  * { box-sizing: border-box; }

  .detail-page {
    padding: clamp(12px, 3vw, 24px);
    padding-bottom: 48px;
  }

  .detail-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 16px;
  }

  .detail-breadcrumb {
    font-size: 13px;
    color: var(--gray-500);
    margin-bottom: 18px;
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    align-items: center;
    line-height: 1.8;
  }
  .detail-breadcrumb a { color: var(--gray-500); text-decoration: none; }
  .detail-breadcrumb a:hover { color: var(--primary); }

  .detail-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: clamp(20px, 4vw, 40px);
  }

  .gallery-main {
    background: var(--gray-50);
    border-radius: 16px;
    overflow: hidden;
    margin-bottom: 12px;
    aspect-ratio: 1;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .gallery-main img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    padding: clamp(12px, 3vw, 20px);
  }

  .gallery-thumbs {
    display: flex;
    gap: 8px;
    overflow-x: auto;
    padding-bottom: 4px;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: thin;
  }
  .gallery-thumb {
    flex-shrink: 0;
    width: 66px;
    height: 66px;
    border-radius: 10px;
    overflow: hidden;
    cursor: pointer;
    background: var(--gray-50);
    transition: border-color 0.2s;
  }
  .gallery-thumb img { width: 100%; height: 100%; object-fit: contain; padding: 4px; }

  .variant-gallery {
    margin-top: 20px; padding: 16px;
    background: var(--gray-50); border: 1px solid var(--gray-200); border-radius: 16px;
  }
  .variant-gallery-title { margin: 0 0 12px; font-size: 14px; font-weight: 700; color: var(--gray-800); overflow-wrap: anywhere; }
  .variant-gallery-main {
    aspect-ratio: 1; max-height: 280px; margin-bottom: 10px;
    display: flex; align-items: center; justify-content: center;
    background: white; border: 1px solid var(--gray-200); border-radius: 12px; overflow: hidden;
  }
  .variant-gallery-main img { width: 100%; height: 100%; object-fit: contain; padding: 18px; }
  .variant-gallery-thumbs { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 2px; }
  .variant-gallery-thumb { flex: 0 0 60px; width: 60px; height: 60px; padding: 4px; background: white; border: 2px solid var(--gray-200); border-radius: 10px; cursor: pointer; overflow: hidden; }
  .variant-gallery-thumb.active { border-color: var(--primary); }
  .variant-gallery-thumb img { width: 100%; height: 100%; object-fit: contain; }

  .product-title {
    font-size: clamp(20px, 5vw, 26px);
    font-weight: 800;
    color: var(--gray-900);
    line-height: 1.3;
    margin-bottom: 8px;
  }

  .variant-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  .qty-row {
    display: flex;
    gap: 10px;
    align-items: center;
    margin-bottom: 20px;
    flex-wrap: wrap;
  }
  .qty-control {
    display: flex;
    align-items: center;
    border: 1.5px solid var(--gray-200);
    border-radius: 8px;
    overflow: hidden;
    flex-shrink: 0;
  }
  .qty-btn {
    width: 42px; height: 44px;
    border: none; background: var(--gray-50);
    cursor: pointer; font-size: 16px;
    display: flex; align-items: center; justify-content: center;
    transition: background 0.15s;
  }
  .qty-btn:hover { background: var(--gray-200); }
  .qty-input {
    width: 56px; height: 44px;
    border: none; text-align: center;
    font-size: 15px; font-weight: 600;
  }
  .add-to-cart-btn { flex: 1; min-width: 140px; }

  .catalog-links { display: flex; flex-wrap: wrap; gap: 8px; }
  .video-links   { display: flex; flex-wrap: wrap; gap: 8px; }

  .descriptions-list { display: flex; flex-direction: column; gap: 20px; }
  .desc-card {
    background: var(--gray-50);
    border-radius: 12px;
    padding: clamp(16px, 3vw, 24px);
    border-left: 4px solid var(--primary);
  }

  /* cart badge */
  .cart-btn-wrap { position: relative; }
  .cart-badge {
    position: absolute;
    top: -8px; right: -8px;
    background: #ef4444;
    color: #fff;
    border-radius: 50%;
    min-width: 22px; height: 22px;
    display: flex; align-items: center; justify-content: center;
    font-size: 11px; font-weight: 700;
    pointer-events: none;
  }

  @media (max-width: 640px) {
    .detail-grid {
      grid-template-columns: 1fr;
      gap: 20px;
    }
    .gallery-main { aspect-ratio: 4/3; }
    .gallery-thumb { width: 58px; height: 58px; }
    .add-to-cart-btn { width: 100%; }
    .qty-row { flex-direction: row; align-items: center; }
  }

  @media (max-width: 380px) {
    .gallery-thumb { width: 50px; height: 50px; }
    .qty-btn { width: 36px; }
    .qty-input { width: 48px; }
  }
`;

function injectDetailStyles() {
  if (document.getElementById('product-detail-styles')) return;
  const tag = document.createElement('style');
  tag.id = 'product-detail-styles';
  tag.textContent = detailStyles;
  document.head.appendChild(tag);
}

export default function MemberProductDetail() {
  const { id } = useParams();
  const [product, setProduct] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [activeImage, setActiveImage] = useState(0);
  const [activeVariantImage, setActiveVariantImage] = useState(0);
  const [selectedVariant, setSelectedVariant] = useState<any>(null);
  const [qty, setQty] = useState(1);
  const { member } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const openedFromBasket = Boolean((location.state as any)?.fromBasket);
  const [addedVariants, setAddedVariants] = useState<string[]>([]);

  const galleryImages: string[] = product?.images || [];
  const variantImages: string[] = selectedVariant?.images || [];

  useEffect(() => { injectDetailStyles(); }, []);

  const cartCount = (() => {
    try {
      return JSON.parse(localStorage.getItem('bm_member_cart') || '[]')
        .reduce((sum: number, item: any) => sum + item.qty, 0);
    } catch { return 0; }
  })();

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    api.get(`/products/${id}`, { params: { accessLevel: 'member' } }).catch(() => api.get(`/pipes/${id}`, { params: { accessLevel: 'member' } }).then(r => ({ data: { product: { ...r.data.pipe, _catalogType: 'pipe' } } })))
      .then(r => {
        setProduct(r.data.product);
        if (r.data.product.variants?.length) setSelectedVariant(r.data.product.variants[0]);
        setLoading(false);
        api.post(`/${r.data.product._catalogType === 'pipe' ? 'pipes' : 'products'}/${id}/view`, { memberId: member?._id }).catch(() => { });
      })
      .catch(() => { setLoading(false); navigate('/products'); });
  }, [id]);

  // Auto-slide
  useEffect(() => {
    if (!product?.images?.length) return;
    const t = setInterval(() => setActiveImage(p => (p + 1) % product.images.length), 3000);
    return () => clearInterval(t);
  }, [product?.images?.length]);

  // Sync addedVariants from localStorage
  useEffect(() => {
    try {
      const cart = JSON.parse(localStorage.getItem('bm_member_cart') || '[]');
      setAddedVariants(cart.filter((i: any) => i.productId === product?._id).map((i: any) => i.variantId));
    } catch { setAddedVariants([]); }
  }, [product]);

  const handleAddToCart = () => {
    if (!member) { toast.error('Please login as member'); navigate('/member/login'); return; }
    if (!selectedVariant) { toast.error('Select a variant'); return; }

    const cart = JSON.parse(localStorage.getItem('bm_member_cart') || '[]');
    const existing = cart.find((c: any) => c.productId === product._id && c.variantId === selectedVariant._id);
    const newCart = existing
      ? cart.map((c: any) => c.productId === product._id && c.variantId === selectedVariant._id ? { ...c, qty: c.qty + qty } : c)
      : [...cart, {
        productId: product._id, variantId: selectedVariant._id,
        productName: product.name, productImage: product.images?.[0] || '',
        brandName: product.brand?.name || '', variantName: selectedVariant.name,
        unit: selectedVariant.unit, primaryThreshold: selectedVariant.primaryThreshold || 0,
        secondaryThreshold: selectedVariant.secondaryThreshold || 0,
        tertiaryThreshold: selectedVariant.tertiaryThreshold || 0, qty,
      }];

    localStorage.setItem('bm_member_cart', JSON.stringify(newCart));
    setAddedVariants(prev => prev.includes(selectedVariant._id) ? prev : [...prev, selectedVariant._id]);
    toast.success('Added to Member Cart!');
  };

  if (loading) return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: 400 }}>
      <div className="spinner" style={{ width: 40, height: 40, borderWidth: 3 }} />
    </div>
  );
  if (!product) return null;

  const inStock = selectedVariant && selectedVariant.stock > 0;
  const images = product.images?.length ? product.images : [''];

  return (
    <div className="detail-page">

      {/* ── Header row ── */}
      <div className="detail-header">
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
          {openedFromBasket && <button className="btn btn-outline" onClick={() => navigate(-1)} style={{ display: 'flex', alignItems: 'center', gap: 6 }}><FiArrowLeft size={15} /> Back to basket</button>}
          <h2 style={{ fontSize: 'clamp(17px,4.5vw,22px)', fontWeight: 700, margin: 0, display: 'flex', alignItems: 'center', gap: 8 }}>
            <FiPackage size={22} color="var(--primary)" /> Product Details
          </h2>
        </div>
        <div className="cart-btn-wrap">
          <button className="btn btn-primary" onClick={() => navigate('/member/cart')}
            style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <FiShoppingCart size={16} /> Cart
          </button>
          {cartCount > 0 && <span className="cart-badge">{cartCount}</span>}
        </div>
      </div>

      {/* ── Breadcrumb ── */}
      <div className="detail-breadcrumb">
        <a href="/"><FiHome size={13} style={{ verticalAlign: 'middle' }} /> Home</a>
        <FiChevronRight size={13} />
        <a href="/member/products">Products</a>
        <FiChevronRight size={13} />
        <span style={{ color: 'var(--gray-800)' }}>{product.name}</span>
      </div>

      {/* ── Main grid ── */}
      <div className="detail-grid">

        {/* Gallery */}
        <div>
          <div className="gallery-main">
            <img
              src={getImageUrl(images[activeImage])}
              alt={product.name}
              onError={e => (e.currentTarget.src = '/placeholder.png')}
            />
          </div>
          {images.length > 1 && (
            <div className="gallery-thumbs">
              {images.map((img: string, i: number) => (
                <div key={i} className="gallery-thumb"
                  style={{ border: `2px solid ${i === activeImage ? 'var(--primary)' : 'var(--gray-200)'}` }}
                  onClick={() => setActiveImage(i)}>
                  <img src={getImageUrl(img)} alt="" />
                </div>
              ))}
            </div>
          )}
          {variantImages.length > 0 && (
            <div className="variant-gallery">
              <h3 className="variant-gallery-title">{selectedVariant.name} Images</h3>
              <div className="variant-gallery-main">
                <img src={getImageUrl(variantImages[activeVariantImage])} alt={`${selectedVariant.name} variant`} onError={e => (e.currentTarget.src = '/placeholder.png')} />
              </div>
              {variantImages.length > 1 && (
                <div className="variant-gallery-thumbs">
                  {variantImages.map((img: string, i: number) => (
                    <button key={i} type="button" className={`variant-gallery-thumb${i === activeVariantImage ? ' active' : ''}`} onClick={() => setActiveVariantImage(i)}>
                      <img src={getImageUrl(img)} alt="" />
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Info */}
        <div>
          {/* Brand + badges */}
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginBottom: 10, alignItems: 'center' }}>
            {product.brand && (
              <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <img src={getImageUrl(product.brand.logo)} style={{ width: 84, height: 84, minWidth: 84, flexShrink: 0, padding: 4, objectFit: 'contain', borderRadius: 8, background: '#fff' }} alt={product.brand.name} />
                <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--gray-600)' }}>{product.brand.name}</span>
              </span>
            )}
            {product.category && (
              <span className="badge badge-gray" style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                <FiTag size={11} /> {product.category.name}
              </span>
            )}
            {product.subcategory && (
              <span className="badge badge-gray" style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                <FiTag size={11} /> {product.subcategory.name}
              </span>
            )}
          </div>

          <h1 className="product-title">{product.name}</h1>

          {product.hsnCode && (
            <div style={{ fontSize: 12, color: 'var(--gray-500)', marginBottom: 16 }}>HSN Code: {product.hsnCode}</div>
          )}

          {/* Variant Selection */}
          {product.variants?.length > 0 && (
            <div style={{ marginBottom: 20 }}>
              <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--gray-700)', marginBottom: 10 }}>Select Variant:</div>
              <div className="variant-grid">
                {product.variants.map((v: any) => {
                  const isAdded = addedVariants.includes(v._id);
                  const isSelected = selectedVariant?._id === v._id;
                  return (
                    <button
                      key={v._id}
                      className={`variant-btn${isSelected ? ' selected' : ''}`}
                      onClick={() => { setSelectedVariant(v); setActiveVariantImage(0); }}
                      style={{
                        display: 'flex', alignItems: 'center', gap: 6,
                        border: isAdded ? '2px solid #2563eb' : undefined,
                        background: isAdded ? '#eff6ff' : undefined,
                        fontSize: 'clamp(12px,3vw,14px)',
                      }}
                    >
                      {v.name} ({v.weight ?? 0} kg)
                      {isAdded && <FiCheckCircle size={15} style={{ color: '#2563eb', flexShrink: 0 }} />}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* Member Pricing Info */}
          {selectedVariant && (
            <div style={{ marginBottom: 20 }}>
              <div className="price-breakdown" style={{ marginBottom: 12, fontWeight: 600 }}>Know the Price</div>

              <div style={{ marginTop: 10, fontSize: 13, fontWeight: 500, display: 'flex', alignItems: 'center', gap: 5, color: inStock ? 'var(--green)' : 'var(--red)' }}>
                {inStock
                  ? <><FiCheckCircle size={14} /> In Stock ({selectedVariant.stock} {selectedVariant.unit})</>
                  : <><FiXCircle size={14} /> Out of Stock</>}
              </div>
              <div style={{ marginTop: 10, fontSize: 13, color: 'var(--gray-600)', fontWeight: 600 }}>
                Weight: {formatWeight(selectedVariant.weight)} kg | Unit: {selectedVariant.unit || '-'}
              </div>
              <div style={{ marginTop: 8, fontSize: 13, color: 'var(--gray-600)' }}>
                Selected date: {selectedVariant.date || '-'}
              </div>
              <div style={{ marginTop: 8, fontSize: 13, color: 'var(--gray-600)' }}>
                Packaging: {selectedVariant.primaryThreshold || 0} {selectedVariant.primaryThresholdUnit || 'pcs'} primary, {selectedVariant.secondaryThreshold || 0} {selectedVariant.secondaryThresholdUnit || 'pcs'} secondary, {selectedVariant.tertiaryThreshold || 0} {selectedVariant.tertiaryThresholdUnit || 'pcs'} tertiary
              </div>
            </div>
          )}

          {/* Selected variant documents */}
          {selectedVariant?.documents?.length > 0 && (
            <div style={{ marginBottom: 18 }}>
              <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}>
                <FiDownload size={15} color="var(--primary)" /> Variant Documents
              </div>
              <div className="catalog-links">
                {selectedVariant.documents.map((doc: any, i: number) => (
                  <a key={i} href={getImageUrl(doc.path)} target="_blank" rel="noreferrer" download className="btn btn-outline btn-sm" style={{ display: 'inline-flex', alignItems: 'center', gap: 5 }}>
                    <FiDownload size={13} /> {doc.name || `Document ${i + 1}`}
                  </a>
                ))}
              </div>
            </div>
          )}

          {/* Qty + Add to Cart */}
          <div className="qty-row">
            <div className="qty-control">
              <button className="qty-btn" onClick={() => setQty(p => Math.max(1, p - 1))}><FiMinus size={14} /></button>
              <input type="number" className="qty-input" value={qty} onChange={e => setQty(Math.max(1, +e.target.value))} />
              <button className="qty-btn" onClick={() => setQty(p => p + 1)}><FiPlus size={14} /></button>
            </div>
            <button
              className="btn btn-primary btn-lg add-to-cart-btn"
              onClick={handleAddToCart}
              disabled={!selectedVariant || selectedVariant.stock === 0}
              style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 7 }}
            >
              <FiShoppingCart size={17} /> Add to Cart
            </button>
          </div>

          {/* Catalogues */}
          {product.catalogs?.length > 0 && (
            <div style={{ marginBottom: 18 }}>
              <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}>
                <FiDownload size={15} color="var(--primary)" /> Download Catalogue
              </div>
              <div className="catalog-links">
                {product.catalogs.map((c: any, i: number) => (
                  <a key={i} href={`${c.path}`} target="_blank" download
                    className="btn btn-outline btn-sm"
                    style={{ display: 'inline-flex', alignItems: 'center', gap: 5 }}>
                    <FiDownload size={13} /> {c.name || `Catalogue ${i + 1}`}
                  </a>
                ))}
              </div>
            </div>
          )}

          {/* Video Links */}
          {product.videoLinks?.filter((v: any) => v.url).length > 0 && (
            <div>
              <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}>
                <FiPlay size={15} color="var(--primary)" /> Videos
              </div>
              <div className="video-links">
                {product.videoLinks.filter((v: any) => v.url).map((v: any, i: number) => (
                  <a key={i} href={v.url} target="_blank"
                    className="btn btn-gray btn-sm"
                    style={{ display: 'inline-flex', alignItems: 'center', gap: 5 }}>
                    <FiPlay size={13} /> {v.title || `Video ${i + 1}`}
                  </a>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* ── Product Descriptions ── */}
      {product.descriptions?.length > 0 && (
        <div style={{ marginTop: 'clamp(28px,5vw,40px)' }}>
          <h2 style={{ fontSize: 'clamp(16px,4vw,20px)', fontWeight: 700, marginBottom: 18, display: 'flex', alignItems: 'center', gap: 8 }}>
            <FiAlertCircle size={18} color="var(--primary)" /> Product Details
          </h2>
          <div className="descriptions-list">
            {product.descriptions.map((d: any, i: number) => (
              <div key={i} className="desc-card">
                {d.heading && <h3 style={{ fontSize: 'clamp(15px,4vw,18px)', fontWeight: 700, color: 'var(--primary)', marginBottom: 4 }}>{d.heading}</h3>}
                {d.subHeading && <h4 style={{ fontSize: 'clamp(13px,3.5vw,15px)', fontWeight: 600, color: 'var(--gray-700)', marginBottom: 8 }}>{d.subHeading}</h4>}
                {d.paragraph && <p style={{ fontSize: 'clamp(12px,3.5vw,14px)', color: 'var(--gray-600)', lineHeight: 1.75, margin: 0 }}>{d.paragraph}</p>}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}