import React, { createContext, useContext, useState, useEffect } from 'react';
import { isMiniAuthenticated } from './miniApi';

interface MiniUser {
  id?: string;
  miniId?: string;
  name?: string;
  email?: string;
  phone?: string;
}

interface MiniContextValue {
  isAuthenticated: boolean;
  miniUser: MiniUser | null;
  setMiniAuth: (user: MiniUser | null, token: string) => void;
  clearMiniAuth: () => void;
}

const MiniContext = createContext<MiniContextValue | null>(null);

export const useMini = (): MiniContextValue => {
  const context = useContext(MiniContext);
  if (!context) {
    throw new Error('useMini must be used within MiniProvider');
  }
  return context;
};

export const MiniProvider = ({ children }: { children: React.ReactNode }) => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => isMiniAuthenticated());
  const [miniUser, setMiniUser] = useState<MiniUser | null>(() => {
    if (typeof window === 'undefined') return null;
    const stored = localStorage.getItem('miniUser');
    return stored ? JSON.parse(stored) as MiniUser : null;
  });

  const setMiniAuth = (user: MiniUser | null, token: string) => {
    if (user && token) {
      localStorage.setItem('miniToken', token);
      localStorage.setItem('miniUser', JSON.stringify(user));
      setMiniUser(user);
      setIsAuthenticated(true);
    }
  };

  const clearMiniAuth = () => {
    localStorage.removeItem('miniToken');
    localStorage.removeItem('miniUser');
    setMiniUser(null);
    setIsAuthenticated(false);
  };

  useEffect(() => {
    const handleStorageChange = () => {
      const token = localStorage.getItem('miniToken');
      const user = localStorage.getItem('miniUser');
      setIsAuthenticated(!!token);
      setMiniUser(user ? JSON.parse(user) as MiniUser : null);
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  return (
    <MiniContext.Provider
      value={{
        isAuthenticated,
        miniUser,
        setMiniAuth,
        clearMiniAuth,
      }}
    >
      {children}
    </MiniContext.Provider>
  );
};
