import React, { useEffect, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';

export const siteConfig = {
  siteName: 'Basava Mart',
  siteUrl: 'https://basavamart.com',
  defaultDescription: 'Basava Mart offers fire safety products, industrial PPE, extinguishers and safety solutions for Bengaluru and India.',
  defaultImage: 'https://basavamart.com/assets/logo/BasavaMartLogo.webp',
  locale: 'en_IN',
};

type JsonLdValue = Record<string, unknown>;

type SEOProps = {
  title: string;
  description: string;
  canonical?: string;
  image?: string;
  type?: string;
  noindex?: boolean;
  jsonLd?: JsonLdValue | JsonLdValue[];
  robots?: string;
};

function absoluteUrl(value?: string): string {
  if (!value) return siteConfig.siteUrl;
  if (/^https?:\/\//i.test(value)) return value;
  if (value.startsWith('//')) return `https:${value}`;
  return `${siteConfig.siteUrl}${value.startsWith('/') ? '' : '/'}${value}`;
}

function normalizeCanonical(rawValue?: string): string {
  const fallback = typeof window === 'undefined' ? '/' : window.location.pathname + window.location.search;
  const candidate = rawValue || fallback;
  const url = new URL(candidate, siteConfig.siteUrl);
  url.search = url.search.replace(/(?:\?|&)utm_[^&]+/gi, '').replace(/(?:\?|&)fbclid=[^&]*/gi, '').replace(/[?&]+$/, '');
  if (url.pathname === '') url.pathname = '/';
  return url.toString().replace(/\/$/, '') || `${siteConfig.siteUrl}/`;
}

export default function SEO({
  title,
  description,
  canonical,
  image,
  type = 'website',
  noindex = false,
  jsonLd,
  robots,
}: SEOProps) {
  const trimmedTitle = title.trim();
  const fullTitle = trimmedTitle.toLowerCase().endsWith(siteConfig.siteName.toLowerCase())
    ? trimmedTitle
    : `${trimmedTitle} | ${siteConfig.siteName}`;
  const canonicalUrl = normalizeCanonical(canonical || (typeof window === 'undefined' ? '/' : window.location.pathname + window.location.search));
  const imageUrl = absoluteUrl(image || siteConfig.defaultImage);
  const structuredData = jsonLd ? (Array.isArray(jsonLd) ? jsonLd : [jsonLd]) : [];

  const finalRobots = useMemo(() => {
    if (robots) return robots.trim();
    return noindex ? 'noindex, nofollow' : 'index, follow, max-image-preview:large';
  }, [noindex, robots]);

  useEffect(() => {
    if (process.env.NODE_ENV !== 'production') {
      if (fullTitle.length > 60) console.warn(`SEO title is ${fullTitle.length} characters (recommended: 60 or fewer).`);
      if (description.length > 160) console.warn(`SEO description is ${description.length} characters (recommended: 160 or fewer).`);
    }
  }, [description, fullTitle]);

  return (
    <Helmet>
      <title>{fullTitle}</title>
      <meta name="description" content={description} />
      <meta name="robots" content={finalRobots} />
      <link rel="canonical" href={canonicalUrl} />
      <meta property="og:type" content={type} />
      <meta property="og:site_name" content={siteConfig.siteName} />
      <meta property="og:title" content={fullTitle} />
      <meta property="og:description" content={description} />
      <meta property="og:url" content={canonicalUrl} />
      <meta property="og:image" content={imageUrl} />
      <meta property="og:locale" content={siteConfig.locale} />
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={fullTitle} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={imageUrl} />
      {structuredData.map((entry, index) => (
        <script key={index} type="application/ld+json">{JSON.stringify(entry).replace(/</g, '\\u003c')}</script>
      ))}
    </Helmet>
  );
}
