import React, { useState } from 'react';
import { Routes, Route, Link, useLocation } from 'react-router-dom';
import AdminMiniUsers from './AdminMiniUsers';
import AdminMiniSphere from './AdminMiniSphere';
import AdminMiniPublic from './AdminMiniPublic';
import AdminMiniTracking from './AdminMiniTracking';
import AdminMiniRequests from './AdminMiniRequests';
import './AdminMiniLayout.css';

export const AdminMiniLayout = () => {
  const location = useLocation();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const menuItems = [
    { label: 'Mini Users', path: '/admin/mini' },
    { label: 'Sphere Products', path: '/admin/mini/sphere' },
    { label: 'Public Mini', path: '/admin/mini/public' },
    { label: 'Tracking', path: '/admin/mini/tracking' },
    { label: 'Requests', path: '/admin/mini/requests' },
  ];

  return (
    <div className="admin-mini-layout">
      <div className="admin-mini-toolbar">
        <h3>Mini Module</h3>
        <nav className="admin-mini-nav" aria-label="Mini module sections">
          {menuItems.map((item) => (
            <Link
              key={item.path}
              to={item.path}
              className={`admin-mini-nav-item ${location.pathname === item.path ? 'active' : ''}`}
              onClick={() => setMobileMenuOpen(false)}
            >
              {item.label}
            </Link>
          ))}
        </nav>
      </div>

      <div className="admin-mini-content">
        <Routes>
          <Route index element={<AdminMiniUsers />} />
          <Route path="sphere" element={<AdminMiniSphere />} />
          <Route path="public" element={<AdminMiniPublic />} />
          <Route path="tracking" element={<AdminMiniTracking />} />
          <Route path="requests" element={<AdminMiniRequests />} />
        </Routes>
      </div>
    </div>
  );
};

export default AdminMiniLayout;
