import React, {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type FormEvent,
} from "react";
import {
  FiArrowRight as ArrowRight,
  FiGrid as Boxes,
  FiCheck as Check,
  FiMail as Mail,
  FiPackage as Package,
  FiPhone as Phone,
  FiShoppingBag as ShoppingBag,
  FiX as X,
  FiLoader as Loader2,
} from "react-icons/fi";

/* -------------------------------------------------------------------------- */
/*  Types                                                                      */
/* -------------------------------------------------------------------------- */

export type OrderType = "single" | "bulk";

export interface EnquiryData {
  orderType: OrderType;
  category: string;
  product: string;
  quantity: string;
}

export interface MemberpopupProps {
  /** Controls visibility. Parent keeps ownership of the trigger logic. */
  open: boolean;
  onClose: () => void;
  /**
   * Result of the app's EXISTING auth check (e.g. `useAuth().isAuthenticated`).
   * Do not pass `Boolean(localStorage.token)`; use your verified auth state.
   */
  isAuthenticated: boolean;
  /** Existing router navigate, e.g. `useNavigate()` from react-router-dom. */
  onNavigate?: (to: string) => void;
  /**
   * Integration point for your existing enquiry endpoint.
   * Must throw / reject on failure. If omitted, the popup does NOT claim
   * anything was submitted; it offers WhatsApp / email with the details instead.
   */
  onSubmitEnquiry?: (data: EnquiryData) => Promise<void>;
  /** Change if your project uses a different login route. */
  loginPath?: string;
  membershipPath?: string;
  /** Build the login URL carrying the return destination. */
  buildLoginUrl?: (loginPath: string, returnTo: string) => string;
  categories?: string[];
  /** sessionStorage key used to avoid immediately re-opening after dismissal. */
  dismissStorageKey?: string;
}

/* -------------------------------------------------------------------------- */
/*  Constants                                                                  */
/* -------------------------------------------------------------------------- */

const WHATSAPP_URL = "https://wa.me/917406380406";
// Supplied number used exactly as given. VERIFY before launch (unusual length).
const PHONE_HREF = "tel:+91984492551";
const PHONE_LABEL = "+91 984492551";
const EMAIL = "info@basavamart.com";

const SLIDES = [
  {
    src: "/assets/images/memberimage.webp",
    alt: "Map of India showing BasavaMart's nationwide reach",
  },
  {
    src: "/assets/images/member2.webp",
    alt: "BasavaMart industrial products and marketplace",
  },
] as const;

const SLIDE_INTERVAL_MS = 4500;

const DEFAULT_CATEGORIES = [
  "Electrical",
  "Industrial Supplies",
  "Pipes & Fittings",
  "Automation",
  "Fire & Safety",
  "Other",
];

const defaultLoginUrl = (loginPath: string, returnTo: string) =>
  `${loginPath}?redirect=${encodeURIComponent(returnTo)}`;

/* -------------------------------------------------------------------------- */
/*  Helpers                                                                    */
/* -------------------------------------------------------------------------- */

function buildMessage(d: EnquiryData): string {
  const parts = [
    `Hello BasavaMart, I need assistance with a ${
      d.orderType === "single" ? "single" : "bulk"
    } order.`,
  ];
  if (d.category.trim()) parts.push(`Category: ${d.category.trim()}.`);
  if (d.product.trim()) parts.push(`Product/requirement: ${d.product.trim()}.`);
  if (d.quantity.trim()) parts.push(`Quantity: ${d.quantity.trim()}.`);
  return parts.join(" ");
}

const whatsappLink = (message: string) =>
  `${WHATSAPP_URL}?text=${encodeURIComponent(message)}`;

const mailLink = (message: string) =>
  `mailto:${EMAIL}?subject=${encodeURIComponent(
    "Order enquiry - BasavaMart"
  )}&body=${encodeURIComponent(message)}`;

function WhatsAppIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" className={className} aria-hidden="true">
      <path d="M17.47 14.38c-.3-.15-1.76-.87-2.03-.97-.27-.1-.47-.15-.67.15-.2.3-.77.97-.94 1.17-.17.2-.35.22-.65.07-.3-.15-1.26-.46-2.4-1.48-.89-.79-1.49-1.77-1.66-2.07-.17-.3-.02-.46.13-.61.13-.13.3-.35.45-.52.15-.17.2-.3.3-.5.1-.2.05-.37-.02-.52-.07-.15-.67-1.61-.92-2.2-.24-.58-.49-.5-.67-.51h-.57c-.2 0-.52.07-.8.37-.27.3-1.04 1.02-1.04 2.48 0 1.46 1.07 2.88 1.21 3.08.15.2 2.1 3.2 5.08 4.49.71.31 1.26.49 1.69.63.71.23 1.36.2 1.87.12.57-.08 1.76-.72 2.01-1.41.25-.7.25-1.29.17-1.41-.07-.12-.27-.2-.57-.35zM12.05 21.5h-.01a9.45 9.45 0 0 1-4.82-1.32l-.35-.2-3.58.94.96-3.49-.23-.36a9.43 9.43 0 0 1-1.45-5.03c0-5.21 4.24-9.45 9.46-9.45 2.52 0 4.9.99 6.68 2.77a9.4 9.4 0 0 1 2.76 6.68c0 5.21-4.25 9.46-9.42 9.46zM20.5 3.49A11.4 11.4 0 0 0 12.05 0C5.74 0 .6 5.13.6 11.44c0 2.02.53 3.99 1.53 5.73L.5 23.5l6.5-1.7a11.43 11.43 0 0 0 5.05 1.2h.01c6.31 0 11.45-5.14 11.45-11.45 0-3.06-1.19-5.93-3.35-8.1z" />
    </svg>
  );
}

/* -------------------------------------------------------------------------- */
/*  Image carousel                                                             */
/* -------------------------------------------------------------------------- */

function Carousel({ active }: { active: boolean }) {
  const [index, setIndex] = useState(0);
  const [failed, setFailed] = useState<Record<number, boolean>>({});
  const [pageVisible, setPageVisible] = useState(true);

  useEffect(() => {
    const onVis = () => setPageVisible(!document.hidden);
    document.addEventListener("visibilitychange", onVis);
    return () => document.removeEventListener("visibilitychange", onVis);
  }, []);

  useEffect(() => {
    if (!active || !pageVisible) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) return;
    const id = window.setInterval(
      () => setIndex((i) => (i + 1) % SLIDES.length),
      SLIDE_INTERVAL_MS
    );
    return () => window.clearInterval(id);
  }, [active, pageVisible]);

  return (
    <div className="absolute inset-0 flex items-center justify-center bg-white">
      {SLIDES.map((s, i) => (
        <div
          key={s.src}
          className={`absolute inset-0 transition-opacity duration-1000 ease-in-out motion-reduce:transition-none ${
            i === index ? "opacity-100" : "opacity-0"
          }`}
          aria-hidden={i !== index}
        >
          {!failed[i] && (
            <img
              src={s.src}
              alt={s.alt}
              loading={i === 0 ? "eager" : "lazy"}
              decoding="async"
              onError={() => setFailed((f) => ({ ...f, [i]: true }))}
              className="h-full w-full object-contain"
            />
          )}
        </div>
      ))}

      <div
        className="absolute bottom-4 right-4 flex gap-1.5 rounded-full bg-slate-950/75 px-2.5 py-2 shadow md:bottom-5 md:right-6"
        role="tablist"
        aria-label="Slides"
      >
        {SLIDES.map((_, i) => (
          <button
            key={i}
            type="button"
            role="tab"
            aria-selected={i === index}
            aria-label={`Show slide ${i + 1}`}
            onClick={() => setIndex(i)}
            className={`h-1.5 rounded-full transition-all ${
              i === index ? "w-6 bg-orange-500" : "w-1.5 bg-white/40 hover:bg-white/70"
            }`}
          />
        ))}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*  Main component                                                             */
/* -------------------------------------------------------------------------- */

type Errors = Partial<Record<"category" | "product" | "quantity", string>>;

export default function Memberpopup({
  open,
  onClose,
  isAuthenticated,
  onNavigate,
  onSubmitEnquiry,
  loginPath = "/login",
  membershipPath = "/membership",
  buildLoginUrl = defaultLoginUrl,
  categories = DEFAULT_CATEGORIES,
  dismissStorageKey = "basavamart_smart_order_dismissed",
}: MemberpopupProps) {
  const uid = useId();
  const dialogRef = useRef<HTMLDivElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const lastFocused = useRef<HTMLElement | null>(null);

  const [orderType, setOrderType] = useState<OrderType | null>("single");
  const [form, setForm] = useState({ category: "", product: "", quantity: "" });
  const [errors, setErrors] = useState<Errors>({});
  const [status, setStatus] = useState<"idle" | "loading" | "ready" | "submitted">("idle");
  const [submitError, setSubmitError] = useState<string | null>(null);

  const handleClose = useCallback(() => {
    try {
      sessionStorage.setItem(dismissStorageKey, "1");
    } catch {
      /* storage unavailable: ignore */
    }
    onClose();
  }, [onClose, dismissStorageKey]);

  /* Scroll lock, Escape, focus management */
  useEffect(() => {
    if (!open) return;
    lastFocused.current = document.activeElement as HTMLElement | null;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    closeRef.current?.focus();

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        handleClose();
        return;
      }
      if (e.key === "Tab" && dialogRef.current) {
        const nodes = dialogRef.current.querySelectorAll<HTMLElement>(
          'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
        );
        if (!nodes.length) return;
        const first = nodes[0];
        const last = nodes[nodes.length - 1];
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault();
          last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    };
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prevOverflow;
      lastFocused.current?.focus?.();
    };
  }, [open, handleClose]);

  const data: EnquiryData | null = useMemo(
    () => (orderType ? { orderType, ...form } : null),
    [orderType, form]
  );
  const message = data ? buildMessage(data) : "";

  const set = (k: keyof typeof form) => (v: string) => {
    setForm((f) => ({ ...f, [k]: v }));
    setErrors((e) => ({ ...e, [k]: undefined }));
    if (status !== "idle") setStatus("idle");
  };

  const validate = (): boolean => {
    const e: Errors = {};
    if (orderType === "bulk") {
      if (!form.category) e.category = "Please choose a category.";
      if (!form.quantity.trim()) e.quantity = "Enter an approximate quantity.";
    }
    if (!form.product.trim())
      e.product =
        orderType === "bulk"
          ? "Tell us the product or specification."
          : "Tell us what you are looking for.";
    else if (form.product.trim().length < 2) e.product = "Please add a little more detail.";
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const onSubmit = async (ev: FormEvent) => {
    ev.preventDefault();
    if (!data || !validate()) return;
    setSubmitError(null);

    if (!onSubmitEnquiry) {
      // No backend handler wired: do NOT claim submission.
      setStatus("ready");
      return;
    }
    setStatus("loading");
    try {
      await onSubmitEnquiry(data);
      setStatus("submitted");
    } catch {
      setStatus("idle");
      setSubmitError("We couldn't send your enquiry. Please try again or use WhatsApp.");
    }
  };

  const goMembership = () => {
    const go = (to: string) =>
      onNavigate ? onNavigate(to) : window.location.assign(to);
    handleClose();
    if (isAuthenticated) go(membershipPath);
    else go(buildLoginUrl(loginPath, membershipPath));
  };

  if (!open) return null;

  const inputCls = (err?: string) =>
    `h-10 w-full rounded-lg border bg-white px-3 text-sm text-slate-900 placeholder:text-slate-400 outline-none transition focus:ring-2 focus:ring-orange-500/40 focus:border-orange-500 ${
      err ? "border-red-400" : "border-slate-300"
    }`;

  const iconBtn =
    "group relative flex h-10 w-10 items-center justify-center rounded-full border border-slate-200 text-slate-600 transition hover:border-orange-500 hover:text-orange-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-500/50";

  const orderTypes: {
    id: OrderType;
    label: string;
    hint: string;
    Icon: typeof Package;
  }[] = [
    { id: "single", label: "Single Order", hint: "A product or a few items", Icon: ShoppingBag },
    { id: "bulk", label: "Bulk Order", hint: "Larger quantities or business needs", Icon: Boxes },
  ];

  return (
    <div
      className="fixed inset-0 z-[9999] flex items-center justify-center bg-slate-950/60 p-2 backdrop-blur-sm sm:p-4"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) handleClose();
      }}
    >
      <style>{`
        @keyframes bm-pop { from { opacity:0; transform: translateY(8px) scale(.97);} to { opacity:1; transform:none;} }
        .bm-modal { animation: bm-pop .35s ease-out both; }
        @media (prefers-reduced-motion: reduce) { .bm-modal { animation: none; } }
      `}</style>

      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={`${uid}-title`}
        className="bm-modal relative flex max-h-[96vh] w-full max-w-[1100px] flex-col overflow-y-auto overflow-x-hidden rounded-[22px] border border-white/10 bg-white shadow-[0_30px_80px_-20px_rgba(2,6,23,0.6)] md:h-[min(620px,92vh)] md:flex-row md:overflow-hidden"
      >
        {/* Close */}
        <button
          ref={closeRef}
          type="button"
          onClick={handleClose}
          aria-label="Close"
          className="absolute right-3 top-3 z-30 flex h-9 w-9 items-center justify-center rounded-full bg-white/90 text-slate-700 shadow ring-1 ring-slate-200 transition hover:bg-white hover:text-slate-950 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-500"
        >
          <X className="h-4 w-4" />
        </button>

        {/* ============================ LEFT / TOP ============================ */}
        <aside className="relative h-[min(112vw,420px)] shrink-0 overflow-hidden bg-white sm:h-[min(70vw,460px)] md:h-auto md:w-[55%]">
          <Carousel active={open} />
        </aside>

        {/* ============================== RIGHT =============================== */}
        <section className="flex min-h-0 flex-1 flex-col bg-gradient-to-b from-white to-orange-50/30 md:w-[45%]">
          <div className="flex-1 overflow-y-auto px-5 pb-3 pt-5 sm:px-7 md:pt-6">
            <div className="text-sm font-bold tracking-tight text-slate-900">
              Basava<span className="text-orange-600">Mart</span>
            </div>

            {status === "ready" || status === "submitted" ? (
              /* ------------------------- Next step panel ------------------------ */
              <div className="mt-5" aria-live="polite">
                <div className="flex h-10 w-10 items-center justify-center rounded-full bg-orange-100 text-orange-600">
                  <Check className="h-5 w-5" />
                </div>
                <h3 id={`${uid}-title`} className="mt-3 text-xl font-semibold text-slate-900">
                  {status === "submitted" ? "Enquiry received" : "Your requirement is ready"}
                </h3>
                <p className="mt-1 text-sm text-slate-600">
                  {status === "submitted"
                    ? "Our team will review it. You can also reach us directly below."
                    : "Choose how you'd like to send it to our team."}
                </p>
                <div className="mt-4 rounded-lg border border-slate-200 bg-white p-3 text-sm text-slate-700">
                  {message}
                </div>
                <div className="mt-4 flex flex-col gap-2 sm:flex-row">
                  <a
                    href={whatsappLink(message)}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex h-11 flex-1 items-center justify-center gap-2 rounded-lg bg-orange-600 px-4 text-sm font-semibold text-white transition hover:bg-orange-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-500 focus-visible:ring-offset-2"
                  >
                    <WhatsAppIcon className="h-4 w-4" /> Send on WhatsApp
                  </a>
                  <a
                    href={mailLink(message)}
                    className="inline-flex h-11 flex-1 items-center justify-center gap-2 rounded-lg border border-slate-300 bg-white px-4 text-sm font-semibold text-slate-800 transition hover:border-orange-500 hover:text-orange-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-500"
                  >
                    <Mail className="h-4 w-4" /> Send by Email
                  </a>
                </div>
                <button
                  type="button"
                  onClick={() => setStatus("idle")}
                  className="mt-3 text-xs font-medium text-slate-500 underline-offset-2 hover:text-slate-800 hover:underline"
                >
                  Edit my requirement
                </button>
              </div>
            ) : (
              /* ------------------------------ Form ------------------------------ */
              <form onSubmit={onSubmit} noValidate className="mt-3">
                <p className="text-[11px] font-semibold uppercase tracking-[0.18em] text-orange-600">
                  Quick enquiry
                </p>
                <h3 id={`${uid}-title`} className="mt-1 text-xl font-semibold text-slate-900">
                  What do you need?
                </h3>
                <p className="mt-1 text-xs text-slate-600">
                  Share a few details and our team will help.
                </p>

                <fieldset className="mt-3">
                  <legend className="sr-only">Order type</legend>
                  <div className="grid grid-cols-2 gap-2">
                    {orderTypes.map(({ id, label, hint, Icon }) => {
                      const selected = orderType === id;
                      return (
                        <label
                          key={id}
                          className={`relative cursor-pointer rounded-lg border p-2.5 transition focus-within:ring-2 focus-within:ring-orange-500/50 ${
                            selected
                              ? "border-orange-500 bg-orange-50 shadow-sm"
                              : "border-slate-200 bg-white hover:border-slate-400"
                          }`}
                        >
                          <input
                            type="radio"
                            name={`${uid}-type`}
                            value={id}
                            checked={selected}
                            onChange={() => {
                              setOrderType(id);
                              setErrors({});
                              setSubmitError(null);
                            }}
                            className="sr-only"
                          />
                          <Icon
                            className={`h-4 w-4 ${selected ? "text-orange-600" : "text-slate-500"}`}
                          />
                          <div className="mt-1 text-sm font-semibold text-slate-900">{label}</div>
                          <div className="text-xs leading-snug text-slate-500">{hint}</div>
                          {selected && (
                            <span className="absolute right-2 top-2 flex h-4 w-4 items-center justify-center rounded-full bg-orange-600 text-white">
                              <Check className="h-3 w-3" />
                            </span>
                          )}
                        </label>
                      );
                    })}
                  </div>
                </fieldset>

                {orderType && (
                  <div className="mt-3 space-y-2">
                    {orderType === "bulk" && (
                      <div>
                        <label htmlFor={`${uid}-cat`} className="mb-1 block text-xs font-medium text-slate-700">
                          Product category
                        </label>
                        <select
                          id={`${uid}-cat`}
                          value={form.category}
                          onChange={(e) => set("category")(e.target.value)}
                          aria-invalid={!!errors.category}
                          aria-describedby={errors.category ? `${uid}-cat-err` : undefined}
                          className={inputCls(errors.category)}
                        >
                          <option value="">Select a category</option>
                          {categories.map((c) => (
                            <option key={c} value={c}>
                              {c}
                            </option>
                          ))}
                        </select>
                        {errors.category && (
                          <p id={`${uid}-cat-err`} role="alert" className="mt-1 text-xs text-red-600">
                            {errors.category}
                          </p>
                        )}
                      </div>
                    )}

                    <div>
                      <label htmlFor={`${uid}-prod`} className="mb-1 block text-xs font-medium text-slate-700">
                        {orderType === "bulk" ? "Product / specification" : "Product or requirement"}
                      </label>
                      <input
                        id={`${uid}-prod`}
                        type="text"
                        value={form.product}
                        onChange={(e) => set("product")(e.target.value)}
                        placeholder={
                          orderType === "bulk" ? "e.g. 25mm GI pipes" : "e.g. Safety helmet"
                        }
                        aria-invalid={!!errors.product}
                        aria-describedby={errors.product ? `${uid}-prod-err` : undefined}
                        className={inputCls(errors.product)}
                        autoComplete="off"
                      />
                      {errors.product && (
                        <p id={`${uid}-prod-err`} role="alert" className="mt-1 text-xs text-red-600">
                          {errors.product}
                        </p>
                      )}
                    </div>

                    <div>
                      <label htmlFor={`${uid}-qty`} className="mb-1 block text-xs font-medium text-slate-700">
                        {orderType === "bulk" ? "Approximate quantity" : "Quantity (optional)"}
                      </label>
                      <input
                        id={`${uid}-qty`}
                        type="text"
                        inputMode="text"
                        value={form.quantity}
                        onChange={(e) => set("quantity")(e.target.value)}
                        placeholder={orderType === "bulk" ? "e.g. 500 units" : "e.g. 2"}
                        aria-invalid={!!errors.quantity}
                        aria-describedby={errors.quantity ? `${uid}-qty-err` : undefined}
                        className={inputCls(errors.quantity)}
                        autoComplete="off"
                      />
                      {errors.quantity && (
                        <p id={`${uid}-qty-err`} role="alert" className="mt-1 text-xs text-red-600">
                          {errors.quantity}
                        </p>
                      )}
                    </div>

                    {submitError && (
                      <p role="alert" className="rounded-md bg-red-50 px-3 py-2 text-xs text-red-700">
                        {submitError}
                      </p>
                    )}

                    <button
                      type="submit"
                      disabled={status === "loading"}
                      className="inline-flex h-10 w-full items-center justify-center gap-2 rounded-lg bg-orange-600 px-4 text-sm font-semibold text-white shadow-sm transition hover:bg-orange-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-500 focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-70"
                    >
                      {status === "loading" ? (
                        <>
                          <Loader2 className="h-4 w-4 animate-spin" /> Sending…
                        </>
                      ) : (
                        <>
                          Continue with My Requirement <ArrowRight className="h-4 w-4" />
                        </>
                      )}
                    </button>
                  </div>
                )}
              </form>
            )}

            {/* Membership prompt */}
            <div className="mt-3 flex items-center justify-between gap-2 rounded-lg border border-slate-200 bg-slate-50/80 px-3 py-2">
              <div className="min-w-0">
                <p className="text-xs font-semibold text-slate-900">Buying for business?</p>
                <p className="text-[11px] text-slate-500">Get member pricing and bulk benefits.</p>
              </div>
              <button
                type="button"
                onClick={goMembership}
                className="shrink-0 whitespace-nowrap rounded-md px-2 py-1 text-xs font-semibold text-orange-700 transition hover:bg-orange-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-500"
              >
                Membership →
              </button>
            </div>
          </div>

          {/* Contact row */}
          <div className="flex items-center justify-center gap-3 border-t border-slate-200/70 bg-white/70 px-5 py-3">
            <a
              href={whatsappLink(message || "Hello BasavaMart, I need assistance with an order.")}
              target="_blank"
              rel="noopener noreferrer"
              aria-label="Chat on WhatsApp (+91 7406380406)"
              title="WhatsApp +91 7406380406"
              className={iconBtn}
            >
              <WhatsAppIcon className="h-[18px] w-[18px]" />
            </a>
            <a
              href={PHONE_HREF}
              aria-label={`Call ${PHONE_LABEL}`}
              title={`Call ${PHONE_LABEL}`}
              className={iconBtn}
            >
              <Phone className="h-[18px] w-[18px]" />
            </a>
            <a
              href={`mailto:${EMAIL}`}
              aria-label={`Email ${EMAIL}`}
              title={EMAIL}
              className={iconBtn}
            >
              <Mail className="h-[18px] w-[18px]" />
            </a>
          </div>
        </section>
      </div>
    </div>
  );
}