import React, { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useNavigate, useLocation } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { AuthProvider, useAuth } from './context/AuthContext';
import { CartProvider } from './context/CartContext';


// Admin Pages
import AdminLayout from './pages/admin/AdminLayout';
import AdminDashboard from './pages/admin/AdminDashboard';
import AdminVisitors from './pages/admin/AdminVisitors';
import AdminBrands from './pages/admin/AdminBrands';
import AdminProducts from './pages/admin/AdminProducts';
import AdminPipes from './pages/admin/PipesManagement';
import AdminOrders from './pages/admin/AdminOrders';
import AdminPaymentVerifications from './pages/admin/AdminPaymentVerifications';
import AdminMembers from './pages/admin/AdminMembers';
import AdminMemberOrders from './pages/admin/AdminMemberOrders';
import AdminUserTracking from './pages/admin/AdminUserTracking';
import AdminAds from './pages/admin/AdminAds';
import AdminSettings from './pages/admin/AdminSettings';
import CreateMyQt from './pages/admin/CreateMyQt';
import AdminReports from './pages/admin/AdminReports';
import AdminRequests from './pages/admin/AdminRequests';
import AdminSites from './pages/admin/AdminSites';
import AdminLogin from './pages/admin/AdminLogin';

// User Pages
import UserLayout from './pages/user/UserLayout';
import HomePage from './pages/user/HomePage';
import ProductListPage from './pages/user/ProductListPage';
import ProductDetailPage from './pages/user/ProductDetailPage';
import BrandCategoryPage from './pages/user/BrandCategoryPage';
import CartPage from './pages/user/CartPage';
import CheckoutPage from './pages/user/CheckoutPage';
import MyOrdersPage from './pages/user/MyOrdersPage';
import ProfilePage from './pages/user/ProfilePage';
import MembershipPage from './pages/user/MembershipPage';
import LoginPage from './pages/user/LoginPage';
import AuthCallback from './pages/user/AuthCallback';

// Member Pages
import MemberLayout from './pages/member/MemberLayout';
import MemberLogin from './pages/member/MemberLogin';
import MemberDashboard from './pages/member/MemberDashboard';
import MemberProducts from './pages/member/MemberProducts';
import MemberCart from './pages/member/MemberCart';
import MemberBasket from './pages/member/MemberBasket';
import MemberOrders from './pages/member/MemberOrders';
import MemberDelivery from './pages/member/MemberDelivery';
import MemberProfile from './pages/member/MemberProfile';
import MemberSites from './pages/member/MemberSites';

// Public
import VendorForm from './pages/VendorForm';
import MemberProductDetail from 'pages/member/MemberProductDetail';
import MediaSlider from 'pages/Slider/MediaSlider';
import MemberPopup from 'pages/user/MemberPopup';

// Mini Pages
import MiniLayout from './mini/pages/MiniLayout';
import MiniHome from './mini/pages/MiniHome';
import MySphere from './mini/pages/MySphere';
import RequestSphere from './mini/pages/RequestSphere';
import TrackAndDeal from './mini/pages/TrackAndDeal';
import PaymentPage from './mini/pages/PaymentPage';
import AdminMiniLayout from './pages/admin/mini/AdminMiniLayout';
import ImageSlider from 'pages/user/Imageslider';
import VisitorTracker from './components/VisitorTracker';

// Route guards
const AdminGuard = ({ children }: { children: React.ReactNode }) => {
  const { isAdmin, loading } = useAuth();
  if (loading) return <div className="flex-center" style={{ height: '100vh' }}><div className="spinner" /></div>;
  return isAdmin ? <>{children}</> : <Navigate to="/admin/login" replace />;
};

const UserGuard = ({ children }: { children: React.ReactNode }) => {
  const { user, loading } = useAuth();
  if (loading) return <div className="flex-center" style={{ height: '100vh' }}><div className="spinner" /></div>;
  return user ? <>{children}</> : <Navigate to="/login" replace />;
};

const MemberGuard = ({ children }: { children: React.ReactNode }) => {
  const { member, loading } = useAuth();
  if (loading) return <div className="flex-center" style={{ height: '100vh' }}><div className="spinner" /></div>;
  return member ? <>{children}</> : <Navigate to="/member/login" replace />;
};

function MemberPopupHost() {
  const { user, member, loading } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);

  useEffect(() => {
    setOpen(false);
    if (location.pathname !== '/' || loading) return;

    try {
      if (sessionStorage.getItem('basavamart_smart_order_dismissed')) return;
    } catch {
      // Continue without session-based dismissal when storage is unavailable.
    }

    const timer = window.setTimeout(() => setOpen(true), 10000);
    return () => window.clearTimeout(timer);
  }, [location.pathname, loading]);

  return (
    <MemberPopup
      open={open}
      onClose={() => setOpen(false)}
      isAuthenticated={Boolean(user || member)}
      onNavigate={navigate}
    />
  );
}

function App() {
  return (

    <Router>

      <AuthProvider>
        <CartProvider>

          <Toaster
            position="top-center"
            toastOptions={{
              duration: 3000,
              className: 'rounded-xl border border-ink-100 bg-white text-ink-900 shadow-card',
              style: { fontSize: '14px', background: '#fff', color: '#0F172A' },
              success: { iconTheme: { primary: '#E26A26', secondary: '#FFF4ED' } },
              error: { iconTheme: { primary: '#D62828', secondary: '#FEF2F2' } },
            }}
          />
          <MemberPopupHost />
          <VisitorTracker />
          <Routes>
            {/* Public */}
            <Route path="/login" element={<LoginPage />} />
            <Route path="/auth/callback" element={<AuthCallback />} />
            <Route path="/vendor-form/:token" element={<VendorForm />} />

            {/* Admin */}
            <Route path="/admin/login" element={<AdminLogin />} />
            <Route path="/admin" element={<AdminGuard><AdminLayout /></AdminGuard>}>
              <Route index element={<AdminDashboard />} />
              <Route path="visitors" element={<AdminVisitors />} />
              <Route path="brands" element={<AdminBrands />} />
              <Route path="products" element={<AdminProducts />} />
              <Route path="pipes" element={<AdminPipes />} />
              <Route path="orders" element={<AdminOrders />} />
              <Route path="payment-verifications" element={<AdminPaymentVerifications />} />
              <Route path="user-tracking" element={<AdminUserTracking />} />
              <Route path="members" element={<AdminMembers />} />
              <Route path="member-orders" element={<AdminMemberOrders />} />
              <Route path="ads" element={<AdminAds />} />
              <Route path="settings" element={<AdminSettings />} />
              <Route path="reports" element={<AdminReports />} />
              <Route path="requests" element={<AdminRequests />} />
              <Route path="sites" element={<AdminSites />} />
              <Route path="mini/*" element={<AdminMiniLayout />} />
            </Route>
            <Route path="/createmyqt" element={<AdminGuard><AdminLayout /></AdminGuard>}>
              <Route index element={<CreateMyQt />} />
            </Route>

            {/* User (public layout) */}
            <Route path="/" element={<UserLayout />}>
              <Route index element={<HomePage />} />
              <Route path="slide" element={<MediaSlider />} />
              <Route path="products" element={<ProductListPage />} />
              <Route path="products/brand/:brandId" element={<ProductListPage />} />
              <Route path="products/:id" element={<ProductDetailPage />} />
              <Route path="brand-categories/:categoryId" element={<BrandCategoryPage />} />
              <Route path="cart" element={<UserGuard><CartPage /></UserGuard>} />
              <Route path="checkout" element={<UserGuard><CheckoutPage /></UserGuard>} />
              <Route path="my-orders" element={<UserGuard><MyOrdersPage /></UserGuard>} />
              <Route path="profile" element={<UserGuard><ProfilePage /></UserGuard>} />
              <Route path="membership" element={<UserGuard><MembershipPage /></UserGuard>} />
              <Route path="imageslider" element={<UserGuard><ImageSlider /></UserGuard>} />
            </Route>

            {/* Member */}
            <Route path="/member/login" element={<MemberLogin />} />
            <Route path="/member" element={<MemberGuard><MemberLayout /></MemberGuard>}>
              <Route index element={<MemberDashboard />} />
              <Route path="products" element={<MemberProducts />} />
              <Route
                path="products/:id"
                element={<MemberProductDetail />}
              />
              <Route path="cart" element={<MemberCart />} />
              <Route path="basket" element={<MemberBasket />} />
              <Route path="orders" element={<MemberOrders />} />
              <Route path="delivery" element={<MemberDelivery />} />
              <Route path="profile" element={<MemberProfile />} />
              <Route path="sites" element={<MemberSites />} />
            </Route>

            {/* Mini */}
            <Route path="/mini" element={<MiniLayout />}>
              <Route index element={<MiniHome />} />
              <Route path="my-sphere" element={<MySphere />} />
              <Route path="request" element={<RequestSphere />} />
              <Route path="track" element={<TrackAndDeal />} />
              <Route path="payment/:orderId" element={<PaymentPage />} />
            </Route>

            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </CartProvider>
      </AuthProvider>
    </Router>
  );
}

export default App;
