import React, { useState, useEffect } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import api, { formatINR, getImageUrl } from '../utils/api';
import toast from 'react-hot-toast';

export default function VendorForm() {
  const { token } = useParams();
  const [searchParams] = useSearchParams();
  const itemIds = searchParams.get('items')?.split(',') || [];

  const [basketItems, setBasketItems] = useState<any[]>([]);
  const [requestItem, setRequestItem] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [submitted, setSubmitted] = useState(false);
  const [vendor, setVendor] = useState({ vendorName: '', vendorEmail: '', vendorPhone: '' });
  const [prices, setPrices] = useState<any[]>([]);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    api.get(`/vendors/form/${token}`, { params: { items: itemIds.join(',') } })
      .then(r => {
        if (r.data.mode === 'request') {
          setRequestItem(r.data.request);
          setBasketItems([]);
          setPrices([{ requestId: r.data.request._id, pricePerUnit: 0, gstPercent: 18, gstType: 'CGST+SGST', finalPrice: 0 }]);
        } else {
          setBasketItems(r.data.basketItems);
          setPrices(r.data.basketItems.map((item: any) => ({
            basketItemId: item._id,
            pricePerUnit: 0,
            gstPercent: 18,
            gstType: 'CGST+SGST',
            finalPrice: 0,
          })));
        }
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  const updatePrice = (idx: number, field: string, val: any) => {
    setPrices(prev => prev.map((p, i) => {
      if (i !== idx) return p;
      const updated = { ...p, [field]: val };
      // Calculate final price
      const base = +updated.pricePerUnit || 0;
      const gst = (base * (+updated.gstPercent || 0)) / 100;
      updated.finalPrice = +(base + gst).toFixed(2);
      return updated;
    }));
  };

  const handleSubmit = async () => {
    if (!vendor.vendorName || !vendor.vendorPhone) {
      toast.error('Please fill your name and phone number'); return;
    }
    const hasEmptyPrices = prices.some(p => !p.pricePerUnit || p.pricePerUnit <= 0);
    if (hasEmptyPrices) { toast.error('Please enter price for all items'); return; }

    setSubmitting(true);
    try {
      await api.post('/vendors/submit', {
        formToken: token,
        vendorName: vendor.vendorName,
        vendorEmail: vendor.vendorEmail,
        vendorPhone: vendor.vendorPhone,
        prices,
      });
      toast.success('Prices submitted successfully!');
      setSubmitted(true);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Submission failed');
    }
    setSubmitting(false);
  };

  const getRequestMediaKind = (item: any) => {
    const type = (item.type || '').toLowerCase();
    const url = (item.url || '').toLowerCase();
    if (type === 'video' || url.match(/\.(mp4|mov|avi|webm)$/)) return 'video';
    if (type === 'document' || url.match(/\.(pdf|docx?|xlsx?|pptx?|txt|csv)$/)) return 'document';
    return 'image';
  };

  if (loading) return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div className="spinner" style={{ width: 40, height: 40, borderWidth: 3 }} />
    </div>
  );

  if (submitted) return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--gray-50)' }}>
      <div style={{ background: 'white', borderRadius: 20, padding: 48, textAlign: 'center', maxWidth: 480, boxShadow: 'var(--shadow-lg)' }}>
        <div style={{ fontSize: 64, marginBottom: 16 }}>✅</div>
        <h2 style={{ fontSize: 24, fontWeight: 700, color: 'var(--green)' }}>Prices Submitted!</h2>
        <p style={{ color: 'var(--gray-600)', marginTop: 8, lineHeight: 1.7 }}>
          Thank you, <strong>{vendor.vendorName}</strong>! Your prices have been submitted to Basava Mart. The team will review and get back to you.
        </p>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight: '100vh', background: 'var(--gray-50)', padding: 24 }}>
      <div style={{ maxWidth: 760, margin: '0 auto' }}>
        {/* Header */}
        <div style={{ background: 'white', borderRadius: 16, padding: 24, marginBottom: 20, boxShadow: 'var(--shadow-sm)', textAlign: 'center', borderTop: '4px solid var(--primary)' }}>
          <div style={{ fontSize: 36, marginBottom: 8 }}>🛍️</div>
          <h1 style={{ fontSize: 24, fontWeight: 800, color: 'var(--primary)' }}>Basava Mart</h1>
          <h2 style={{ fontSize: 18, fontWeight: 600, color: 'var(--gray-700)', marginTop: 4 }}>Vendor Price Submission Form</h2>
          <p style={{ color: 'var(--gray-500)', marginTop: 8, fontSize: 14 }}>Please fill in your best prices for the products listed below. All prices are per unit.</p>
        </div>

        {/* Vendor Details */}
        <div style={{ background: 'white', borderRadius: 16, padding: 24, marginBottom: 20, boxShadow: 'var(--shadow-sm)' }}>
          <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 16 }}>👤 Your Details</h3>
          <div className="grid-2">
            <div className="form-group">
              <label className="form-label">Your Name *</label>
              <input className="form-control" placeholder="Full name" value={vendor.vendorName} onChange={e => setVendor(p => ({ ...p, vendorName: e.target.value }))} />
            </div>
            <div className="form-group">
              <label className="form-label">Phone Number *</label>
              <input className="form-control" placeholder="Mobile number" value={vendor.vendorPhone} onChange={e => setVendor(p => ({ ...p, vendorPhone: e.target.value }))} />
            </div>
            <div className="form-group" style={{ gridColumn: '1/-1' }}>
              <label className="form-label">Email (Optional)</label>
              <input className="form-control" placeholder="your@email.com" value={vendor.vendorEmail} onChange={e => setVendor(p => ({ ...p, vendorEmail: e.target.value }))} />
            </div>
          </div>
        </div>

        {/* Request details and uploads */}
        {requestItem && (
          <div style={{ background: 'white', borderRadius: 16, padding: 24, marginBottom: 16, boxShadow: 'var(--shadow-sm)' }}>
            <h3 style={{ fontSize: 18, fontWeight: 700, marginBottom: 12 }}>{requestItem.productName}</h3>
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 12 }}>
              <span className="badge badge-gray">Qty Required: {requestItem.qty || 1}</span>
            </div>
            {requestItem.description && <p style={{ color: 'var(--gray-600)', marginBottom: 8 }}>{requestItem.description}</p>}
            {requestItem.note && <p style={{ color: 'var(--gray-600)', marginBottom: 16 }}><strong>Note:</strong> {requestItem.note}</p>}
            {(requestItem.media || []).length > 0 && (
              <div>
                <h4 style={{ fontSize: 14, fontWeight: 700, marginBottom: 10 }}>Attachments</h4>
                <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
                  {requestItem.media.map((media: any, index: number) => {
                    const kind = getRequestMediaKind(media);
                    const url = getImageUrl(media.url);
                    return (
                      <div key={`${media.url}-${index}`} style={{ width: 150, border: '1px solid var(--gray-200)', borderRadius: 8, padding: 8 }}>
                        {kind === 'image' && <img src={url} alt={media.name || 'Request attachment'} style={{ width: '100%', height: 100, objectFit: 'cover', borderRadius: 5 }} />}
                        {kind === 'video' && <video src={url} controls playsInline style={{ width: '100%', height: 100, objectFit: 'cover', borderRadius: 5 }} />}
                        {kind === 'document' && (
                          <div style={{ height: 100, display: 'grid', placeItems: 'center', background: '#fff2e8', color: '#c75216', fontWeight: 700 }}>DOC</div>
                        )}
                        {kind === 'document' && <a href={url} download={media.name || 'request-document'} target="_blank" rel="noreferrer" style={{ display: 'block', marginTop: 8, fontSize: 12 }}>Download document</a>}
                        {media.name && <div style={{ marginTop: 6, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontSize: 12 }} title={media.name}>{media.name}</div>}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            <div style={{ background: 'var(--gray-50)', borderRadius: 12, padding: 16, marginTop: 20 }}>
              <h4 style={{ fontSize: 14, fontWeight: 700, marginBottom: 12, color: 'var(--gray-700)' }}>💰 Your Price Quote</h4>
              <div className="grid-2">
                <div className="form-group">
                  <label className="form-label">Price per Unit (₹) *</label>
                  <input type="number" className="form-control" placeholder="Enter your price" value={prices[0]?.pricePerUnit || ''} onChange={e => updatePrice(0, 'pricePerUnit', +e.target.value)} />
                </div>
                <div className="form-group">
                  <label className="form-label">GST %</label>
                  <input type="number" className="form-control" value={prices[0]?.gstPercent || 18} onChange={e => updatePrice(0, 'gstPercent', +e.target.value)} />
                </div>
                <div className="form-group">
                  <label className="form-label">GST Type</label>
                  <select className="form-control" value={prices[0]?.gstType || 'CGST+SGST'} onChange={e => updatePrice(0, 'gstType', e.target.value)}>
                    <option value="CGST+SGST">CGST + SGST</option>
                    <option value="IGST">IGST</option>
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Final Price (after GST)</label>
                  <div className="form-control" style={{ background: 'white', color: 'var(--primary)', fontWeight: 700, fontSize: 18 }}>₹{formatINR(prices[0]?.finalPrice)}</div>
                </div>
              </div>
              {prices[0]?.pricePerUnit > 0 && (
                <div className="price-breakdown" style={{ marginTop: 8 }}>
                  <div className="price-row"><span>Base Price</span><span>₹{formatINR(prices[0].pricePerUnit)}</span></div>
                  <div className="price-row"><span>GST ({prices[0].gstPercent}% {prices[0].gstType})</span><span>₹{formatINR((+prices[0].pricePerUnit * +prices[0].gstPercent) / 100)}</span></div>
                  <div className="price-row total"><span>Final Price per Unit</span><span style={{ color: 'var(--primary)' }}>₹{formatINR(prices[0].finalPrice)}</span></div>
                  <div className="price-row total" style={{ fontSize: 16 }}><span>Total for {requestItem.qty || 1} units</span><span style={{ color: 'var(--primary)' }}>₹{formatINR(prices[0].finalPrice * (requestItem.qty || 1))}</span></div>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Products and Prices */}
        {!requestItem && basketItems.map((item, idx) => (
          <div key={item._id} style={{ background: 'white', borderRadius: 16, padding: 24, marginBottom: 16, boxShadow: 'var(--shadow-sm)' }}>
            {/* Product Info */}
            <div style={{ display: 'flex', gap: 16, marginBottom: 20, alignItems: 'flex-start' }}>
              <img
                src={getImageUrl(item.productSnapshot?.image || item.product?.images?.[0])}
                alt={item.productSnapshot?.name}
                style={{ width: 80, height: 80, objectFit: 'cover', borderRadius: 10, border: '1px solid var(--gray-200)', flexShrink: 0 }}
                onError={e => (e.currentTarget.src = '/placeholder.png')}
              />
              <div>
                <div style={{ fontWeight: 700, fontSize: 16 }}>{item.productSnapshot?.name || item.product?.name}</div>
                <div style={{ fontSize: 13, color: 'var(--gray-600)', marginTop: 4 }}>
                  Brand: <strong>{item.productSnapshot?.brandName}</strong>
                </div>
                <div style={{ fontSize: 13, color: 'var(--gray-600)' }}>
                  Category: {item.productSnapshot?.categoryName}
                  {item.productSnapshot?.subcategoryName && ` > ${item.productSnapshot.subcategoryName}`}
                </div>
                <div style={{ display: 'flex', gap: 8, marginTop: 6, flexWrap: 'wrap' }}>
                  <span className="badge badge-orange">Variant: {item.variant?.name}</span>
                  <span className="badge badge-gray">Qty Required: {item.quantity} {item.variant?.unit}</span>
                </div>
              </div>
            </div>

            {/* Price Fields */}
            <div style={{ background: 'var(--gray-50)', borderRadius: 12, padding: 16 }}>
              <h4 style={{ fontSize: 14, fontWeight: 700, marginBottom: 12, color: 'var(--gray-700)' }}>💰 Your Price Quote</h4>
              <div className="grid-2">
                <div className="form-group">
                  <label className="form-label">Price per Unit (₹) *</label>
                  <input
                    type="number"
                    className="form-control"
                    placeholder="Enter your price"
                    value={prices[idx]?.pricePerUnit || ''}
                    onChange={e => updatePrice(idx, 'pricePerUnit', +e.target.value)}
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">GST %</label>
                  <input
                    type="number"
                    className="form-control"
                    value={prices[idx]?.gstPercent || 18}
                    onChange={e => updatePrice(idx, 'gstPercent', +e.target.value)}
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">GST Type</label>
                  <select className="form-control" value={prices[idx]?.gstType || 'CGST+SGST'} onChange={e => updatePrice(idx, 'gstType', e.target.value)}>
                    <option value="CGST+SGST">CGST + SGST</option>
                    <option value="IGST">IGST</option>
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Final Price (after GST)</label>
                  <div className="form-control" style={{ background: 'white', color: 'var(--primary)', fontWeight: 700, fontSize: 18 }}>
                    ₹{formatINR(prices[idx]?.finalPrice)}
                  </div>
                </div>
              </div>

              {/* Live calculation preview */}
              {prices[idx]?.pricePerUnit > 0 && (
                <div className="price-breakdown" style={{ marginTop: 8 }}>
                  <div className="price-row">
                    <span>Base Price</span>
                    <span>₹{formatINR(prices[idx].pricePerUnit)}</span>
                  </div>
                  <div className="price-row">
                    <span>GST ({prices[idx].gstPercent}% {prices[idx].gstType})</span>
                    <span>₹{formatINR((+prices[idx].pricePerUnit * +prices[idx].gstPercent) / 100)}</span>
                  </div>
                  <div className="price-row total">
                    <span>Final Price per Unit</span>
                    <span style={{ color: 'var(--primary)' }}>₹{formatINR(prices[idx].finalPrice)}</span>
                  </div>
                  <div className="price-row total" style={{ fontSize: 16 }}>
                    <span>Total for {item.quantity} units</span>
                    <span style={{ color: 'var(--primary)' }}>₹{formatINR(prices[idx].finalPrice * item.quantity)}</span>
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}

        {basketItems.length === 0 && !requestItem && (
          <div style={{ background: 'white', borderRadius: 16, padding: 40, textAlign: 'center', color: 'var(--gray-400)' }}>
            No products found for this form.
          </div>
        )}

        {(basketItems.length > 0 || requestItem) && (
          <div style={{ background: 'white', borderRadius: 16, padding: 24, boxShadow: 'var(--shadow-sm)', marginTop: 8 }}>
            <button
              className="btn btn-primary btn-lg"
              style={{ width: '100%' }}
              onClick={handleSubmit}
              disabled={submitting}
            >
              {submitting ? <div className="spinner" /> : '✅ Submit My Prices'}
            </button>
            <p style={{ textAlign: 'center', fontSize: 12, color: 'var(--gray-400)', marginTop: 12 }}>
              By submitting, you confirm that these prices are accurate and valid.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}
