import React, { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { createRequestVendorForm, getMiniRequests, updateRequestStatus } from '../../../mini/adminMiniApi';

interface MiniRequest {
  _id?: string;
  productName?: string;
  name?: string;
  phone?: string;
  qty?: number;
  description?: string;
  note?: string;
  media?: Array<{ url?: string; type?: string; name?: string }>;
  vendorSubmissions?: Array<{
    vendorName?: string;
    vendorEmail?: string;
    vendorPhone?: string;
    submittedAt?: string;
    submittedPrices?: Array<{ pricePerUnit?: number; gstPercent?: number; gstType?: string; finalPrice?: number }>;
  }>;
  status?: string;
}

const getMediaKind = (item: { url?: string; type?: string }) => {
  const type = (item.type || '').toLowerCase();
  const url = (item.url || '').toLowerCase();
  if (type === 'video' || url.match(/\.(mp4|mov|avi|webm)$/)) return 'video';
  if (type === 'document' || url.match(/\.(pdf|docx?|xlsx?|pptx?|txt|csv)$/)) return 'document';
  return 'image';
};

export const AdminMiniRequests = () => {
  const [requests, setRequests] = useState<MiniRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState('all');
  const [selectedMedia, setSelectedMedia] = useState<{ items: Array<{ url?: string; type?: string; name?: string }>; index: number; requestId?: string } | null>(null);
  const [vendorShareLink, setVendorShareLink] = useState('');
  const [vendorLinkLoading, setVendorLinkLoading] = useState(false);
  const [selectedVendorRequest, setSelectedVendorRequest] = useState<MiniRequest | null>(null);

  useEffect(() => {
    fetchRequests();
  }, [statusFilter]);

  const fetchRequests = async () => {
    try {
      const filter = statusFilter === 'all' ? '' : statusFilter;
      const res = await getMiniRequests(filter, '');
      if (res.data?.success) {
        setRequests(res.data.data || []);
      }
    } catch (error) {
      toast.error('Failed to load requests');
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = async (id: string, newStatus: string) => {
    try {
      await updateRequestStatus(id, newStatus);
      setRequests((prev) => prev.map((r) => (r._id === id ? { ...r, status: newStatus } : r)));
      toast.success('Status updated');
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const openMediaPreview = (media: MiniRequest['media'], index: number, requestId?: string) => {
    const items = (media || []).filter((item) => item.url);
    const selectedItem = (media || [])[index];
    const selectedIndex = selectedItem ? items.indexOf(selectedItem) : -1;
    if (selectedIndex >= 0) {
      setVendorShareLink('');
      setSelectedMedia({ items, index: selectedIndex, requestId });
    }
  };

  const moveMedia = (direction: number) => {
    setSelectedMedia((current) => {
      if (!current) return current;
      const nextIndex = current.index + direction;
      if (nextIndex < 0 || nextIndex >= current.items.length) return current;
      return { ...current, index: nextIndex };
    });
  };

  const shareRequestWithVendor = async (requestId: string) => {
    setVendorLinkLoading(true);
    try {
      const response = await createRequestVendorForm(requestId);
      setVendorShareLink(response.data.shareLink);
      toast.success('Vendor form link generated');
    } catch (error) {
      toast.error('Failed to create vendor form link');
    } finally {
      setVendorLinkLoading(false);
    }
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="admin-section">
      <div className="section-header">
        <h2>Mini Requests (Public Requests Inbox)</h2>
        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="form-control"
          style={{ maxWidth: '200px' }}
        >
          <option value="all">All Requests</option>
          <option value="new">New</option>
          <option value="reviewed">Reviewed</option>
        </select>
      </div>

      <div className="table-responsive">
        <table className="admin-table">
          <thead>
            <tr>
              <th>Product Name</th>
              <th>Name</th>
              <th>Phone</th>
              <th>Qty</th>
              <th>Description</th>
              <th>Uploads</th>
              <th>Vendor Details</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {requests.map((request) => {
              const requestId = request._id ?? '';
              const requestStatus = request.status ?? 'new';
              const productName = request.productName ?? 'Unknown';

              return (
                <tr key={requestId || productName}>
                  <td>
                    <strong>{productName}</strong>
                  </td>
                  <td>{request.name ?? '-'}</td>
                  <td>{request.phone ?? '-'}</td>
                  <td>{request.qty ?? 0}</td>
                  <td>{request.description?.substring(0, 50) || '-'}...</td>
                  <td>
                    {(request.media || []).some((item) => item.url) ? (
                      <button
                        type="button"
                        className="btn btn-sm btn-info"
                        onClick={() => openMediaPreview(request.media, 0, requestId)}
                      >
                        Preview ({(request.media || []).filter((item) => item.url).length})
                      </button>
                    ) : '-'}
                  </td>
                  <td>
                    {(request.vendorSubmissions || []).length > 0 ? (
                      <button type="button" className="btn btn-sm btn-info" onClick={() => setSelectedVendorRequest(request)}>
                        Preview ({request.vendorSubmissions?.length})
                      </button>
                    ) : '-'}
                  </td>
                  <td>
                    <span className={`badge ${requestStatus === 'reviewed' ? 'badge-success' : 'badge-info'}`}>
                      {requestStatus}
                    </span>
                  </td>
                  <td>
                    <button
                      className="btn btn-sm btn-info"
                      onClick={() => requestId && handleStatusChange(requestId, requestStatus === 'reviewed' ? 'new' : 'reviewed')}
                    >
                      {requestStatus === 'reviewed' ? 'Mark New' : 'Mark Reviewed'}
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {selectedMedia && (() => {
        const item = selectedMedia.items[selectedMedia.index];
        const kind = getMediaKind(item);
        return (
          <div className="modal-overlay" onClick={() => { setSelectedMedia(null); setVendorShareLink(''); }}>
            <div className="modal modal-lg" onClick={(event) => event.stopPropagation()}>
              <div className="modal-header">
                <h2>Request Upload {selectedMedia.index + 1} of {selectedMedia.items.length}</h2>
                <button className="modal-close" onClick={() => { setSelectedMedia(null); setVendorShareLink(''); }} aria-label="Close preview">X</button>
              </div>
              <div className="modal-body" style={{ textAlign: 'center' }}>
                {kind === 'image' && item.url && (
                  <img src={item.url} alt={item.name || 'Request upload'} style={{ maxWidth: '100%', maxHeight: '65vh', objectFit: 'contain' }} />
                )}
                {kind === 'video' && item.url && (
                  <video src={item.url} controls autoPlay playsInline style={{ maxWidth: '100%', maxHeight: '65vh' }} />
                )}
                {kind === 'document' && item.url && (
                  <div style={{ padding: '32px 12px' }}>
                    <div className="mini-request-document" style={{ margin: '0 auto 12px', fontSize: '1.25rem' }}>DOC</div>
                    <p>{item.name || 'Uploaded document'}</p>
                    <a className="btn btn-primary" href={item.url} download={item.name || 'request-document'} target="_blank" rel="noreferrer">
                      Download Document
                    </a>
                  </div>
                )}
              </div>
              <div className="modal-footer" style={{ justifyContent: 'space-between' }}>
                <div style={{ display: 'flex', gap: 8 }}>
                  <button className="btn btn-outline" onClick={() => moveMedia(-1)} disabled={selectedMedia.index === 0}>Previous</button>
                  <button className="btn btn-outline" onClick={() => moveMedia(1)} disabled={selectedMedia.index === selectedMedia.items.length - 1}>Next</button>
                </div>
                <button
                  className="btn btn-primary"
                  onClick={() => {
                    if (selectedMedia.requestId) shareRequestWithVendor(selectedMedia.requestId);
                  }}
                  disabled={vendorLinkLoading}
                >
                  {vendorLinkLoading ? 'Creating Link...' : 'Send Details to Vendor'}
                </button>
              </div>
              {vendorShareLink && (
                <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', padding: '0 20px 20px' }}>
                  <input className="form-control" value={vendorShareLink} readOnly style={{ flex: 1, minWidth: 220 }} />
                  <button className="btn btn-gray" onClick={() => { navigator.clipboard.writeText(vendorShareLink); toast.success('Link copied'); }}>
                    Copy Link
                  </button>
                </div>
              )}
            </div>
          </div>
        );
      })()}

      {selectedVendorRequest && (
        <div className="modal-overlay" onClick={() => setSelectedVendorRequest(null)}>
          <div className="modal modal-lg" onClick={(event) => event.stopPropagation()}>
            <div className="modal-header">
              <h2>Vendor Details: {selectedVendorRequest.productName}</h2>
              <button className="modal-close" onClick={() => setSelectedVendorRequest(null)} aria-label="Close vendor details">X</button>
            </div>
            <div className="modal-body">
              {(selectedVendorRequest.vendorSubmissions || []).map((vendor, vendorIndex) => (
                <div key={`${vendor.vendorName}-${vendorIndex}`} style={{ border: '1px solid var(--gray-200)', borderRadius: 8, padding: 16, marginBottom: 12 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap', marginBottom: 12 }}>
                    <div>
                      <strong>{vendor.vendorName || 'Unnamed vendor'}</strong>
                      <div style={{ color: 'var(--gray-600)', fontSize: 13, marginTop: 4 }}>
                        {vendor.vendorPhone || '-'}{vendor.vendorEmail ? ` | ${vendor.vendorEmail}` : ''}
                      </div>
                    </div>
                    {vendor.submittedAt && <span style={{ color: 'var(--gray-500)', fontSize: 12 }}>{new Date(vendor.submittedAt).toLocaleString()}</span>}
                  </div>
                  {(vendor.submittedPrices || []).map((price, priceIndex) => (
                    <div key={priceIndex} style={{ background: 'var(--gray-50)', borderRadius: 6, padding: 12, display: 'flex', gap: 16, flexWrap: 'wrap' }}>
                      <span>Price/unit: <strong>₹{price.pricePerUnit ?? 0}</strong></span>
                      <span>GST: <strong>{price.gstPercent ?? 0}% ({price.gstType || '-'})</strong></span>
                      <span>Final/unit: <strong>₹{price.finalPrice ?? 0}</strong></span>
                      <span>Total ({selectedVendorRequest.qty || 1}): <strong>₹{((price.finalPrice || 0) * (selectedVendorRequest.qty || 1)).toFixed(2)}</strong></span>
                    </div>
                  ))}
                </div>
              ))}
            </div>
            <div className="modal-footer">
              <button className="btn btn-gray" onClick={() => setSelectedVendorRequest(null)}>Close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminMiniRequests;
