import React, { useEffect, useState } from 'react';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import api, { formatINR } from '../../utils/api';

const COLORS = ['#e26a26', '#10b981', '#3b82f6', '#f59e0b'];

const MONTH_NAMES = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

export default function AdminDashboard() {
  const [stats, setStats] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [dateFilter, setDateFilter] = useState({ startDate: '', endDate: '' });

  const loadStats = async () => {
    setLoading(true);
    try {
      const params: any = {};
      if (dateFilter.startDate) params.startDate = dateFilter.startDate;
      if (dateFilter.endDate) params.endDate = dateFilter.endDate;
      const res = await api.get('/dashboard/admin', { params });
      setStats(res.data.stats);
    } catch {}
    setLoading(false);
  };

  useEffect(() => { loadStats(); }, []);

  const statCards = stats ? [
    { label: 'Total Products', value: stats.totalProducts, icon: '📦', color: '#e26a26' },
    { label: 'Total Brands', value: stats.totalBrands, icon: '🏷️', color: '#3b82f6' },
    { label: 'Total Users', value: stats.totalUsers, icon: '👤', color: '#10b981' },
    { label: 'Total Members', value: stats.totalMembers, icon: '🥇', color: '#f59e0b' },
    { label: 'Total Orders', value: stats.totalOrders, icon: '🛒', color: '#8b5cf6' },
    { label: 'Total Revenue', value: `₹${formatINR(stats.totalRevenue)}`, icon: '💰', color: '#e26a26' },
    { label: 'Pending Orders', value: stats.pendingOrders, icon: '⏳', color: '#f59e0b' },
    { label: 'Delivered Orders', value: stats.deliveredOrders, icon: '✅', color: '#10b981' },
  ] : [];

  const revenueData = stats?.monthlyRevenue?.map((m: any) => ({
    name: MONTH_NAMES[(m._id.month - 1)],
    revenue: m.revenue,
    orders: m.count,
  })) || [];

  if (loading) return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: 400 }}>
      <div className="spinner" style={{ width: 40, height: 40, borderWidth: 3 }} />
    </div>
  );

  return (
    <div className="fade-in">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 24 }}>
        <div>
          <h1 style={{ fontSize: 24, fontWeight: 700, color: 'var(--gray-900)' }}>Dashboard</h1>
          <p style={{ color: 'var(--gray-500)', fontSize: 14 }}>Welcome back, Admin!</p>
        </div>
        {/* Date filter */}
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <input type="date" className="form-control" style={{ width: 160 }} value={dateFilter.startDate} onChange={e => setDateFilter(p => ({ ...p, startDate: e.target.value }))} />
          <span style={{ color: 'var(--gray-400)' }}>to</span>
          <input type="date" className="form-control" style={{ width: 160 }} value={dateFilter.endDate} onChange={e => setDateFilter(p => ({ ...p, endDate: e.target.value }))} />
          <button className="btn btn-primary btn-sm" onClick={loadStats}>Apply</button>
          <button className="btn btn-gray btn-sm" onClick={() => { setDateFilter({ startDate: '', endDate: '' }); loadStats(); }}>Reset</button>
        </div>
      </div>

      {/* Stat Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 16, marginBottom: 24 }}>
        {statCards.map((s, i) => (
          <div key={i} className="stat-card" style={{ '--card-color': s.color } as any}>
            <div className="stat-icon" style={{ background: `${s.color}20`, color: s.color }}>{s.icon}</div>
            <div className="stat-value" style={{ color: s.color }}>{s.value}</div>
            <div className="stat-label">{s.label}</div>
          </div>
        ))}
      </div>

      {/* Charts */}
      <div className="grid-2" style={{ marginBottom: 24 }}>
        <div className="card">
          <div className="card-header"><h3 style={{ fontSize: 16, fontWeight: 600 }}>📈 Revenue Trend (6 months)</h3></div>
          <div className="card-body">
            <ResponsiveContainer width="100%" height={220}>
              <LineChart data={revenueData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                <YAxis tick={{ fontSize: 12 }} tickFormatter={v => `₹${formatINR(v / 1000)}k`} />
                <Tooltip formatter={(v: any) => [`₹${formatINR(v)}`, 'Revenue']} />
                <Line type="monotone" dataKey="revenue" stroke="#e26a26" strokeWidth={2.5} dot={{ fill: '#e26a26' }} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="card">
          <div className="card-header"><h3 style={{ fontSize: 16, fontWeight: 600 }}>📊 Order Trend (6 months)</h3></div>
          <div className="card-body">
            <ResponsiveContainer width="100%" height={220}>
              <BarChart data={revenueData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                <YAxis tick={{ fontSize: 12 }} />
                <Tooltip />
                <Bar dataKey="orders" fill="#e26a26" radius={[4,4,0,0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Recent Orders */}
      <div className="card">
        <div className="card-header"><h3 style={{ fontSize: 16, fontWeight: 600 }}>🕐 Recent Orders</h3></div>
        <div className="table-wrapper">
          <table>
            <thead>
              <tr>
                <th>Order #</th>
                <th>Customer</th>
                <th>Amount</th>
                <th>Status</th>
                <th>Date</th>
              </tr>
            </thead>
            <tbody>
              {stats?.recentOrders?.map((order: any) => (
                <tr key={order._id}>
                  <td><code style={{ fontSize: 12, color: 'var(--primary)' }}>{order.orderNumber}</code></td>
                  <td>{order.userName}</td>
                  <td style={{ fontWeight: 600 }}>₹{formatINR(order.totalAmount)}</td>
                  <td>
                    <span className={`badge ${
                      order.deliveryStatus === 'delivered' ? 'badge-success' :
                      order.deliveryStatus === 'order_placed' ? 'badge-warning' : 'badge-info'
                    }`}>{order.deliveryStatus?.replace(/_/g, ' ')}</span>
                  </td>
                  <td style={{ color: 'var(--gray-500)', fontSize: 13 }}>{new Date(order.createdAt).toLocaleDateString('en-IN')}</td>
                </tr>
              ))}
              {!stats?.recentOrders?.length && (
                <tr><td colSpan={5} style={{ textAlign: 'center', color: 'var(--gray-400)', padding: 32 }}>No orders yet</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
