import React, { useEffect, useState } from 'react';
import { formatINR } from '../../../utils/api';
import toast from 'react-hot-toast';
import {
  getMiniUsers,
  getAdminProducts,
  createMiniProducts,
  uploadProductMedia,
  updateMiniProduct,
  deleteMiniProduct,
  updateMiniProductStatus,
} from '../../../mini/adminMiniApi';
import MiniProductForm, { MiniProductFormData } from './MiniProductForm';

interface MiniUser {
  _id?: string;
  miniId?: string;
  name?: string;
  status?: string;
}

interface MediaItem {
  url?: string;
  type?: string;
  name?: string;
}

interface MiniProduct {
  _id?: string;
  productName?: string;
  brandName?: string;
  categoryName?: string;
  subCategoryName?: string;
  description?: string;
  hsnCode?: string;
  accessLevel?: string;
  descriptions?: MiniProductFormData['descriptions'];
  videoLinks?: MiniProductFormData['videoLinks'];
  tags?: string[];
  variants?: MiniProductFormData['variants'];
  catalogs?: { url?: string; name?: string }[];
  unit?: string;
  qty?: number;
  price?: number;
  status?: string;
  media?: MediaItem[];
  miniUserId?: { _id?: string; miniId?: string; name?: string } | string | null;
}

const emptyForm = {
  productName: '',
  brandName: '',
  categoryName: '',
  subCategoryName: '',
  description: '',
  unit: 'piece',
  qty: 0,
  price: 0,
};

export const AdminMiniSphere = () => {
  const [users, setUsers] = useState<MiniUser[]>([]);
  const [selectedUserId, setSelectedUserId] = useState('');
  const [products, setProducts] = useState<MiniProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState(emptyForm);
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [editingProductId, setEditingProductId] = useState<string | null>(null);
  const [showProductForm, setShowProductForm] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 8;

  useEffect(() => {
    fetchUsers();
  }, []);

  useEffect(() => {
    if (selectedUserId) {
      fetchProducts();
    } else {
      setProducts([]);
    }
    setCurrentPage(1);
  }, [selectedUserId]);

  const fetchUsers = async () => {
    try {
      const res = await getMiniUsers();
      const userList = res.data?.data || [];
      setUsers(userList);
      if (userList[0]?._id) {
        setSelectedUserId(userList[0]._id);
      }
    } catch {
      toast.error('Failed to load mini users');
    } finally {
      setLoading(false);
    }
  };

  const fetchProducts = async () => {
    try {
      const res = await getAdminProducts(selectedUserId, '', '', '');
      setProducts(res.data?.data || []);
      setCurrentPage(1);
    } catch {
      toast.error('Failed to load sphere products');
    }
  };

  const totalPages = Math.max(1, Math.ceil(products.length / pageSize));
  const paginatedProducts = products.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const resetForm = () => {
    setForm(emptyForm);
    setSelectedFiles([]);
    setEditingProductId(null);
    setShowProductForm(false);
  };

  const handleExpandedSubmit = async (data: MiniProductFormData, images: File[], catalogs: File[]) => {
    let savedProduct: MiniProduct | null = null;
    const payload = {
      ...data,
      miniUserId: selectedUserId,
      descriptions: JSON.stringify(data.descriptions),
      videoLinks: JSON.stringify(data.videoLinks.filter((video) => video.url)),
      tags: JSON.stringify(data.tags),
      variants: JSON.stringify(data.variants),
      qty: Number(data.qty),
      price: Number(data.price),
    };

    if (editingProductId) {
      const res = await updateMiniProduct(editingProductId, payload);
      savedProduct = res.data?.data || null;
    } else {
      const res = await createMiniProducts([payload]);
      savedProduct = res.data?.data?.[0] || null;
    }
    if (savedProduct?._id && (images.length || catalogs.length)) {
      await uploadProductMedia(savedProduct._id, images, catalogs);
    }
    toast.success(editingProductId ? 'Product updated' : 'Product added to sphere');
    resetForm();
    await fetchProducts();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUserId) {
      toast.error('Select a mini user first');
      return;
    }
    if (selectedFiles.length > 5) {
      toast.error('You can upload up to 5 files only');
      return;
    }

    setSaving(true);
    try {
      let savedProduct: MiniProduct | null = null;

      if (editingProductId) {
        const res = await updateMiniProduct(editingProductId, {
          ...form,
          miniUserId: selectedUserId,
          qty: Number(form.qty),
          price: Number(form.price),
        });
        savedProduct = res.data?.data || null;
      } else {
        const res = await createMiniProducts([{
          miniUserId: selectedUserId,
          ...form,
          qty: Number(form.qty),
          price: Number(form.price),
        }]);
        savedProduct = res.data?.data?.[0] || null;
      }

      if (savedProduct?._id && selectedFiles.length > 0) {
        await uploadProductMedia(savedProduct._id, selectedFiles);
      }

      toast.success(editingProductId ? 'Product updated' : 'Product added to sphere');
      resetForm();
      await fetchProducts();
    } catch (error: any) {
      toast.error(error?.response?.data?.message || 'Failed to save product');
    } finally {
      setSaving(false);
    }
  };

  const handleEdit = (product: MiniProduct) => {
    setShowProductForm(true);
    setEditingProductId(product._id || null);
    setSelectedUserId(
      typeof product.miniUserId === 'string'
        ? product.miniUserId
        : product.miniUserId?._id || selectedUserId
    );
    setForm({
      productName: product.productName || '',
      brandName: product.brandName || '',
      categoryName: product.categoryName || '',
      subCategoryName: product.subCategoryName || '',
      description: product.description || '',
      unit: product.unit || 'piece',
      qty: product.qty || 0,
      price: product.price || 0,
    });
  };

  const handleDelete = async (productId: string) => {
    if (!window.confirm('Delete this product?')) return;
    try {
      await deleteMiniProduct(productId);
      toast.success('Product deleted');
      await fetchProducts();
    } catch (error: any) {
      toast.error(error?.response?.data?.message || 'Failed to delete product');
    }
  };

  const handleTogglePublish = async (product: MiniProduct) => {
    if (!product._id) return;
    try {
      await updateMiniProductStatus(product._id, product.status === 'published' ? 'draft' : 'published');
      toast.success('Status updated');
      await fetchProducts();
    } catch (error: any) {
      toast.error(error?.response?.data?.message || 'Failed to update status');
    }
  };

  const renderMediaThumbs = (media: MediaItem[] = []) => {
    if (!media.length) return <span style={{ color: '#777' }}>No media</span>;

    return (
      <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap', maxWidth: 220 }}>
        {media.slice(0, 3).map((item, index) => {
          const type = (item.type || '').toLowerCase();
          const url = item.url || '';
          const isVideo = type === 'video' || /\.(mp4|mov|webm|avi)$/i.test(url);
          const isDocument = type === 'document' || /\.(pdf|doc|docx|xls|xlsx|ppt|pptx|txt|csv)$/i.test(url);

          if (isVideo) {
            return <video key={`${url}-${index}`} src={url} style={{ width: 46, height: 46, objectFit: 'cover', borderRadius: 6 }} controls />;
          }

          if (isDocument) {
            return (
              <a key={`${url}-${index}`} href={url} target="_blank" rel="noreferrer" style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: 46, height: 46, borderRadius: 6, background: '#fff3e7', color: '#b75d00', fontSize: 10, fontWeight: 700, textDecoration: 'none' }}>
                DOC
              </a>
            );
          }

          return <img key={`${url}-${index}`} src={url} alt="product" style={{ width: 46, height: 46, objectFit: 'cover', borderRadius: 6 }} />;
        })}
      </div>
    );
  };

  if (loading) return <div className="admin-section"><h2>Sphere Products</h2><p>Loading…</p></div>;

  return (
    <div className="admin-section">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '1rem', marginBottom: '0.5rem' }}>
        <h2 style={{ margin: 0 }}>Sphere Products (Per-User)</h2>
        <button
          type="button"
          className="btn btn-primary"
          title="Add sphere product"
          aria-label="Add sphere product"
          onClick={() => { setEditingProductId(null); setShowProductForm(true); }}
          style={{ width: 42, height: 42, padding: 0, borderRadius: '50%', fontSize: 24, lineHeight: 1 }}
        >
          +
        </button>
      </div>
      <p style={{ color: '#666' }}>
        Products assigned to each Mini user are listed here and stay private to that user.
      </p>

      <div style={{ display: 'flex', gap: '1rem', alignItems: 'center', marginBottom: '1rem' }}>
        <label style={{ fontWeight: 600 }}>Mini user</label>
        <select value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)} className="form-control" style={{ minWidth: 220 }}>
          {users.map((user) => (
            <option key={user._id} value={user._id}>{user.miniId || 'Mini user'} - {user.name || 'Unnamed'}</option>
          ))}
        </select>
      </div>

      {showProductForm && <MiniProductForm
        key={editingProductId || 'new'}
        initialData={editingProductId ? {
          productName: form.productName,
          brandName: form.brandName,
          categoryName: form.categoryName,
          subCategoryName: form.subCategoryName,
          descriptions: products.find((product) => product._id === editingProductId)?.descriptions,
          videoLinks: products.find((product) => product._id === editingProductId)?.videoLinks,
          tags: products.find((product) => product._id === editingProductId)?.tags,
          variants: products.find((product) => product._id === editingProductId)?.variants,
          hsnCode: products.find((product) => product._id === editingProductId)?.hsnCode,
          accessLevel: products.find((product) => product._id === editingProductId)?.accessLevel,
          unit: form.unit,
          qty: form.qty,
          price: form.price,
        } : undefined}
        initialCatalogs={editingProductId ? (products.find((product) => product._id === editingProductId)?.catalogs || []).map((catalog) => ({ url: catalog.url || '', name: catalog.name || 'Catalogue' })) : []}
        saving={saving}
        submitLabel={editingProductId ? 'Update Product' : 'Add Product'}
        onSubmit={async (data, images, catalogs) => {
          setSaving(true);
          try { await handleExpandedSubmit(data, images, catalogs); }
          catch (error: any) { toast.error(error?.response?.data?.message || 'Failed to save product'); }
          finally { setSaving(false); }
        }}
        onCancel={editingProductId ? resetForm : undefined}
      />}

      <div className="table-responsive">
        <table className="admin-table" style={{ width: '100%' }}>
          <thead>
            <tr>
              <th>Product</th>
              <th>Media</th>
              <th>Qty</th>
              <th>Price</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {paginatedProducts.length > 0 ? paginatedProducts.map((product) => (
              <tr key={product._id}>
                <td>
                  <strong>{product.productName}</strong><br />
                  <span style={{ color: '#555', fontSize: 12 }}>{product.brandName || 'No brand'}</span>
                </td>
                <td>{renderMediaThumbs(product.media)}</td>
                <td>{product.qty ?? 0}</td>
                <td>₹{formatINR(product.price)}</td>
                <td>{product.status || 'draft'}</td>
                <td>
                  <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
                    <button type="button" className="btn btn-sm btn-secondary" onClick={() => handleEdit(product)}>Edit</button>
                    <button type="button" className="btn btn-sm btn-primary" onClick={() => handleTogglePublish(product)}>
                      {product.status === 'published' ? 'Draft' : 'Publish'}
                    </button>
                    <button type="button" className="btn btn-sm btn-danger" onClick={() => handleDelete(product._id || '')}>Delete</button>
                  </div>
                </td>
              </tr>
            )) : (
              <tr><td colSpan={6} style={{ textAlign: 'center', color: '#777' }}>No sphere products found for this mini user.</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {products.length > 0 && (
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '0.75rem', marginTop: '1rem', flexWrap: 'wrap' }}>
          <span style={{ color: '#555', fontSize: '0.9rem' }}>
            Showing {(products.length === 0 ? 0 : (currentPage - 1) * pageSize + 1)}-{Math.min(currentPage * pageSize, products.length)} of {products.length}
          </span>
          <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
            <button
              type="button"
              className="btn btn-secondary btn-sm"
              disabled={currentPage === 1}
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
            >
              Previous
            </button>
            <span style={{ minWidth: 68, textAlign: 'center', color: '#333', fontWeight: 600 }}>
              Page {currentPage}/{totalPages}
            </span>
            <button
              type="button"
              className="btn btn-secondary btn-sm"
              disabled={currentPage >= totalPages}
              onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
            >
              Next
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminMiniSphere;
