import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import api from '../../utils/api';
import toast from 'react-hot-toast';

export default function MemberLogin() {
  const [memberId, setMemberId] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const { loginMember } = useAuth();
  const navigate = useNavigate();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await api.post('/auth/member/login', { memberId, password });
      loginMember(res.data.token, res.data.member);
      toast.success(`Welcome back, ${res.data.member.name}!`);
      navigate('/member');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Invalid credentials');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
  style={{
    minHeight: '100vh',
    backgroundImage: `
      linear-gradient(
        rgba(0,0,0,0.55),
        rgba(0,0,0,0.55)
      ),
      url('/assets/images/bgimg1.webp')
    `,
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    backgroundRepeat: 'no-repeat',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: 24
  }}
>
      <div
  style={{
    background: 'rgba(255,255,255,0.95)',
    backdropFilter: 'blur(12px)',
    WebkitBackdropFilter: 'blur(12px)',
    borderRadius: 24,
    padding: '48px 40px',
    width: '100%',
    maxWidth: 450,
    boxShadow: '0 25px 80px rgba(0,0,0,0.35)',
    border: '1px solid rgba(255,255,255,0.2)'
  }}
>
        <div style={{ textAlign: 'center', marginBottom: 36 }}>
          <img
  src="/assets/logo/BasavaMartLogo.webp"
  alt="Basava Mart"
  style={{
    height: 90,
    width: 'auto',
    objectFit: 'contain'
  }}
/>
          <h1 style={{ color: 'var(--primary)', fontSize: 26, fontWeight: 800, marginTop: 8 }}>Member Login</h1>
          <p style={{ color: 'var(--gray-500)', marginTop: 6, fontSize: 14 }}>Basava Mart Member Panel</p>
        </div>

        <form onSubmit={handleLogin}>
          <div className="form-group">
            <label className="form-label">Member ID</label>
            <input className="form-control" type="text" value={memberId} onChange={e => setMemberId(e.target.value)} placeholder="e.g. BM001" required style={{ fontSize: 16 }} />
          </div>
          <div className="form-group">
            <label className="form-label">Password</label>
            <input className="form-control" type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Enter your password" required style={{ fontSize: 16 }} />
          </div>
          <button className="btn btn-primary" style={{ width: '100%', marginTop: 8, height: 50, fontSize: 16 }} disabled={loading}>
            {loading ? <div className="spinner" /> : '🔐 Login'}
          </button>
        </form>

        <div style={{ textAlign: 'center', marginTop: 24 }}>
          <p style={{ fontSize: 13, color: 'var(--gray-500)' }}>
            Not a member?{' '}
            <a href="/membership" style={{ color: 'var(--primary)', fontWeight: 600, textDecoration: 'none' }}>Apply for Membership →</a>
          </p>
          <p style={{ fontSize: 13, color: 'var(--gray-500)', marginTop: 6 }}>
            <a href="/" style={{ color: 'var(--gray-500)', textDecoration: 'none' }}>← Back to Store</a>
          </p>
        </div>
      </div>
    </div>
  );
}
