import React, { FormEvent, useRef, useState } from 'react';
import { FiUpload, FiX } from 'react-icons/fi';
import toast from 'react-hot-toast';
import api from '../../utils/api';

export type UserRequestType = 'product' | 'quotation';

interface UserRequestModalProps {
  requestType: UserRequestType;
  onClose: () => void;
}

const MAX_FILES = 8;
const MAX_FILE_SIZE = 25 * 1024 * 1024;

export default function UserRequestModal({ requestType, onClose }: UserRequestModalProps) {
  const [files, setFiles] = useState<File[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [emailError, setEmailError] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const emailInputRef = useRef<HTMLInputElement>(null);
  const isProductRequest = requestType === 'product';
  const title = isProductRequest ? 'Request a product' : 'Request a quotation';
  const validateEmail = (email: string) => {
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
    setEmailError(valid ? '' : 'Enter a valid email address.');
    return valid;
  };

  const addFiles = (selected: FileList | null) => {
    if (!selected) return;
    const nextFiles = Array.from(selected);
    if (files.length + nextFiles.length > MAX_FILES) {
      toast.error(`You can attach up to ${MAX_FILES} files.`);
      return;
    }
    if (nextFiles.some(file => file.size > MAX_FILE_SIZE)) {
      toast.error('Each attachment must be 25 MB or smaller.');
      return;
    }
    setFiles(current => [...current, ...nextFiles]);
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = event.currentTarget;
    const email = String(new FormData(form).get('email') || '').trim();
    if (!validateEmail(email)) {
      emailInputRef.current?.focus();
      return;
    }
    const formData = new FormData(form);
    formData.set('requestType', requestType);
    ['name', 'phone', 'email', 'productName', 'description'].forEach(name => {
      formData.set(name, String(formData.get(name) || '').trim());
    });
    files.forEach(file => formData.append('files', file));

    setSubmitting(true);
    try {
      await api.post('/requests', formData);
      toast.success('Your request has been submitted.');
      onClose();
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Unable to submit your request. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-[600] flex items-center justify-center overflow-y-auto overscroll-contain bg-ink-950/65 p-3 backdrop-blur-sm sm:p-5"
      onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}
    >
      <section
        role="dialog"
        aria-modal="true"
        aria-labelledby="user-request-title"
        className="my-auto max-h-[min(92dvh,620px)] w-full max-w-xl overflow-y-auto rounded-2xl border border-ink-100 bg-white shadow-2xl"
      >
        <header className="flex items-center gap-3 border-b border-ink-100 px-4 py-3 sm:px-5">
          <img
            src="/assets/logo/BasavaMartLogo.webp"
            alt="Basava Mart"
            className="h-10 w-14 shrink-0 object-contain"
          />
          <span className="h-9 w-px shrink-0 bg-ink-200" aria-hidden="true" />
          <div className="min-w-0">
            <h2 id="user-request-title" className="font-display text-base font-bold leading-tight text-ink-900 sm:text-lg">{title}</h2>
            <p lang="hi" className="mt-0.5 text-xs font-semibold text-primary-700">आपकी ज़रूरत, हमारा समाधान</p>
          </div>
          <button type="button" onClick={onClose} className="ml-auto flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-ink-200 bg-white text-ink-500 transition hover:border-ink-300 hover:bg-ink-50 hover:text-ink-900 focus-visible:outline focus-visible:outline-2 focus-visible:outline-primary-500" aria-label="Close request form">
            <FiX size={18} aria-hidden="true" />
          </button>
        </header>

        <div lang="hi" className="border-b border-ink-100 bg-ink-50/70 px-4 py-2.5 text-xs leading-relaxed text-ink-600 sm:px-5">
          <p>अपनी ज़रूरत का विवरण भरें और चाहें तो फ़ाइल जोड़ें।</p>
          <p>हमारी टीम सही उत्पाद या कोटेशन के लिए आपसे संपर्क करेगी।</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-3.5 p-4 sm:p-5">
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            <label className="block min-w-0 text-xs font-semibold text-ink-700">
              Name <span className="text-fire-600" aria-hidden="true">*</span>
              <input name="name" required maxLength={120} autoComplete="name" placeholder="Your name" className="mt-1 block h-10 w-full rounded-lg border border-ink-300 bg-white px-3 text-base text-ink-900 shadow-sm outline-none placeholder:text-ink-400 focus:border-primary-500 focus:ring-2 focus:ring-primary-100" />
            </label>
            <label className="block min-w-0 text-xs font-semibold text-ink-700">
              Phone number <span className="text-fire-600" aria-hidden="true">*</span>
              <input name="phone" type="tel" inputMode="tel" required maxLength={30} autoComplete="tel" placeholder="Your phone number" className="mt-1 block h-10 w-full rounded-lg border border-ink-300 bg-white px-3 text-base text-ink-900 shadow-sm outline-none placeholder:text-ink-400 focus:border-primary-500 focus:ring-2 focus:ring-primary-100" />
            </label>
          </div>
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            <label className="block min-w-0 text-xs font-semibold text-ink-700">
              Email address <span className="text-fire-600" aria-hidden="true">*</span>
                <input
                  ref={emailInputRef}
                  name="email"
                  type="email"
                  inputMode="email"
                  required
                  maxLength={254}
                  autoComplete="email"
                  autoCapitalize="none"
                  spellCheck={false}
                  placeholder="you@example.com"
                  aria-invalid={!!emailError}
                  aria-describedby={emailError ? 'request-email-error' : undefined}
                  onBlur={event => validateEmail(event.currentTarget.value)}
                  onChange={event => { if (emailError) validateEmail(event.currentTarget.value); }}
                  className={`mt-1 block h-10 w-full rounded-lg border bg-white px-3 text-base text-ink-900 shadow-sm outline-none placeholder:text-ink-400 focus:ring-2 ${emailError ? 'border-fire-500 focus:border-fire-500 focus:ring-fire-50' : 'border-ink-300 focus:border-primary-500 focus:ring-primary-100'}`}
                />
              {emailError && <span id="request-email-error" className="mt-1 block text-xs font-medium text-fire-600" role="alert">{emailError}</span>}
            </label>
            <label className="block min-w-0 text-xs font-semibold text-ink-700">
              Product name <span className="text-fire-600" aria-hidden="true">*</span>
              <input name="productName" required maxLength={200} placeholder="Product you need" className="mt-1 block h-10 w-full rounded-lg border border-ink-300 bg-white px-3 text-base text-ink-900 shadow-sm outline-none placeholder:text-ink-400 focus:border-primary-500 focus:ring-2 focus:ring-primary-100" />
            </label>
          </div>
          <label className="block text-xs font-semibold text-ink-700">
            Description
            <textarea name="description" rows={2} maxLength={5000} className="mt-1 block min-h-16 w-full resize-y rounded-lg border border-ink-300 bg-white px-3 py-2 text-base text-ink-900 shadow-sm outline-none placeholder:text-ink-400 focus:border-primary-500 focus:ring-2 focus:ring-primary-100" placeholder="Add size, quantity, or other details" />
          </label>

          <div className="min-w-0">
            <span className="block text-xs font-semibold text-ink-700">Attachments <span className="font-normal text-ink-500">(optional, up to 8)</span></span>
            <input
              ref={fileInputRef}
              type="file"
              multiple
              accept="image/*,video/*,.pdf,.doc,.docx,.xls,.xlsx,.txt,.rtf"
              className="sr-only"
              onChange={event => {
                addFiles(event.currentTarget.files);
                event.currentTarget.value = '';
              }}
            />
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="mt-1 flex min-h-10 w-full items-center justify-center gap-2 rounded-lg border border-dashed border-ink-300 bg-ink-50 px-3 text-xs font-semibold text-ink-700 transition hover:border-primary-500 hover:bg-primary-50"
            >
              <FiUpload aria-hidden="true" /> Add photos, videos, or documents
            </button>
            <p className="mt-1 text-[11px] leading-snug text-ink-500">Images, videos, or documents · Up to 25 MB each</p>
            {files.length > 0 && (
              <ul className="mt-2 grid grid-cols-1 gap-1.5 sm:grid-cols-2">
                {files.map((file, index) => (
                  <li key={`${file.name}-${file.lastModified}-${index}`} className="flex min-w-0 items-center justify-between gap-2 rounded-lg border border-ink-100 bg-ink-50 px-2.5 py-2 text-xs text-ink-700">
                    <span className="min-w-0 truncate" title={file.name}>{file.name}</span>
                    <button
                      type="button"
                      className="min-h-8 shrink-0 rounded px-2 text-xs font-semibold text-fire-600 hover:bg-fire-50 hover:text-fire-700"
                      onClick={() => setFiles(current => current.filter((_, fileIndex) => fileIndex !== index))}
                      aria-label={`Remove ${file.name}`}
                    >
                      Remove
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </div>

          <div className="flex justify-end gap-2 border-t border-ink-100 pt-3">
            <button type="button" onClick={onClose} className="bm-btn bm-btn-secondary min-h-10 px-4 text-sm">Cancel</button>
            <button type="submit" disabled={submitting} className="bm-btn bm-btn-primary min-h-10 px-4 text-sm disabled:cursor-not-allowed disabled:opacity-60">
              {submitting ? 'Submitting...' : <><span className="sm:hidden">Submit</span><span className="hidden sm:inline">{isProductRequest ? 'Request product' : 'Request quotation'}</span></>}
            </button>
          </div>
        </form>
      </section>
    </div>
  );
}
