
import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useMini } from '../MiniContext';
import { useAuth } from '../../context/AuthContext';

interface NavItem {
  label: string;
  path: string;
}

export const MiniNavbar = () => {
  const { isAuthenticated, clearMiniAuth } = useMini();
  const { user } = useAuth();
  const location = useLocation();
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const handleExit = () => {
    clearMiniAuth();
    setIsMenuOpen(false);
    window.location.href = '/';
  };

  const navItems: NavItem[] = [
    { label: 'Home', path: '/mini' },
    ...(isAuthenticated ? [
      { label: 'My Sphere', path: '/mini/my-sphere' },
      { label: 'Cart', path: '/mini/my-sphere#cart' },
      { label: 'Track & Deal', path: '/mini/track' },
    ] : []),
    ...(user && !isAuthenticated ? [{ label: 'Cart', path: '/mini#public-cart' }] : []),
    { label: 'Request Spare', path: '/mini/request' },
  ];

  const half = Math.ceil(navItems.length / 2);
  const leftItems = navItems.slice(0, half);
  const rightItems = navItems.slice(half);

  const isItemActive = (item: NavItem): boolean => {
    if (item.path.includes('#public-cart')) {
      return location.pathname === '/mini' && location.hash === '#public-cart';
    }
    const isCartTab = item.path.includes('#cart');
    if (isCartTab) return location.pathname === '/mini/my-sphere';
    return location.pathname === item.path;
  };

  const handleNavClick = (item: NavItem) => {
    setIsMenuOpen(false);
    if (item.path.includes('#public-cart')) {
      setTimeout(() => {
        document.getElementById('mini-public-cart')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 50);
    } else if (item.path.includes('#cart')) {
      setTimeout(() => {
        const cartSection = document.getElementById('mini-cart-section');
        cartSection?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 50);
    }
  };

  const renderNavLink = (item: NavItem) => (
    <Link
      key={item.path}
      to={item.path}
      className={`mini-nav-item ${isItemActive(item) ? 'active' : ''}`}
      onClick={() => handleNavClick(item)}
    >
      {item.label}
    </Link>
  );

  return (
    <nav className="mini-navbar">
      <style>{`
        .mini-navbar {
          position: sticky;
          top: 0;
          z-index: 1000;
          width: 100%;
          background: linear-gradient(135deg, #ffffff 0%, #fff7f0 100%);
          backdrop-filter: blur(10px);
          border-bottom: 1px solid rgba(255, 106, 0, 0.12);
          box-shadow: 0 2px 12px rgba(0, 0, 0, 0.04);
        }

        .mini-navbar-container {
          display: grid;
          grid-template-columns: 1fr auto 1fr;
          align-items: center;
          max-width: 1200px;
          margin: 0 auto;
          padding: 0 20px;
          height: 68px;
          gap: 12px;
        }

        .mini-navbar-side {
          display: flex;
          align-items: center;
          min-width: 0;
        }

        .mini-navbar-side--left {
          justify-content: flex-start;
        }

        .mini-navbar-side--right {
          justify-content: flex-end;
          gap: 20px;
        }

        .mini-navbar-links {
          display: flex;
          align-items: center;
          gap: 30px;
        }

        .mini-navbar-brand {
          display: flex;
          align-items: center;
          justify-content: center;
          transition: transform 0.25s ease;
        }

        .mini-navbar-brand:hover {
          transform: scale(1.06);
        }

        .mini-navbar-logo-img {
          height: 62px;
          width: auto;
          object-fit: contain;
        }

        /* Nav item with animated underline */
        .mini-nav-item {
          position: relative;
          color: #2b2b2b;
          text-decoration: none;
          font-size: 15px;
          font-weight: 500;
          white-space: nowrap;
          padding: 8px 2px;
          transition: color 0.25s ease;
        }

        .mini-nav-item::after {
          content: '';
          position: absolute;
          left: 0;
          bottom: 2px;
          width: 0%;
          height: 2px;
          background: #ff6a00;
          border-radius: 2px;
          transition: width 0.25s ease;
        }

        .mini-nav-item:hover {
          color: #ff6a00;
        }

        .mini-nav-item:hover::after {
          width: 100%;
        }

        .mini-nav-item.active {
          color: #ff6a00;
          font-weight: 700;
        }

        .mini-nav-item.active::after {
          width: 100%;
        }

        /* Exit button */
        .mini-nav-exit {
          background: #fff;
          border: 1.5px solid #ff6a00;
          color: #ff6a00;
          padding: 8px 20px;
          border-radius: 24px;
          font-size: 14px;
          font-weight: 600;
          cursor: pointer;
          white-space: nowrap;
          transition: all 0.25s ease;
        }

        .mini-nav-exit:hover {
          background: #ff6a00;
          color: #fff;
          box-shadow: 0 4px 14px rgba(255, 106, 0, 0.35);
          transform: translateY(-1px);
        }

        /* Hamburger */
        .mini-hamburger {
          display: none;
          flex-direction: column;
          justify-content: center;
          gap: 5px;
          width: 30px;
          height: 30px;
          background: none;
          border: none;
          cursor: pointer;
          padding: 0;
        }

        .mini-hamburger span {
          display: block;
          height: 2.5px;
          width: 100%;
          background: #2b2b2b;
          border-radius: 2px;
          transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .mini-hamburger.active span {
          background: #ff6a00;
        }

        .mini-hamburger.active span:nth-child(1) {
          transform: translateY(7.5px) rotate(45deg);
        }
        .mini-hamburger.active span:nth-child(2) {
          opacity: 0;
          transform: scaleX(0);
        }
        .mini-hamburger.active span:nth-child(3) {
          transform: translateY(-7.5px) rotate(-45deg);
        }

        /* Mobile dropdown */
        .mini-nav-mobile {
          grid-column: 1 / -1;
          display: flex;
          flex-direction: column;
          background: #ffffff;
          border-top: 1px solid rgba(255, 106, 0, 0.12);
          max-height: 0;
          overflow: hidden;
          opacity: 0;
          transition: max-height 0.35s ease, opacity 0.3s ease, padding 0.35s ease;
        }

        .mini-nav-mobile.open {
          max-height: 500px;
          opacity: 1;
          padding: 8px 20px 18px;
        }

        .mini-nav-mobile .mini-nav-item {
          padding: 14px 4px;
          font-size: 16px;
          border-bottom: 1px solid #f5f0eb;
          animation: slideIn 0.3s ease backwards;
        }

        .mini-nav-mobile .mini-nav-item::after {
          display: none;
        }

        .mini-nav-mobile .mini-nav-item:last-of-type {
          border-bottom: none;
        }

        .mini-nav-mobile .mini-nav-exit--mobile {
          margin-top: 10px;
          width: 100%;
          padding: 10px 0;
        }

        @keyframes slideIn {
          from {
            opacity: 0;
            transform: translateX(-8px);
          }
          to {
            opacity: 1;
            transform: translateX(0);
          }
        }

        @media (max-width: 768px) {
          .mini-navbar-container {
            grid-template-columns: auto 1fr auto;
            padding: 0 16px;
            height: 58px;
          }

          .mini-navbar-links {
            display: none;
          }

          .mini-hamburger {
            display: flex;
          }

          .mini-navbar-logo-img {
            height: 62px;
          }

          .mini-nav-exit {
            padding: 6px 16px;
            font-size: 13px;
          }
        }
      `}</style>

      <div className="mini-navbar-container">

        {/* Left: nav items (desktop) / hamburger (mobile) */}
        <div className="mini-navbar-side mini-navbar-side--left">
          <div className="mini-navbar-links">
            {leftItems.map(renderNavLink)}
          </div>
          <button
            className={`mini-hamburger ${isMenuOpen ? 'active' : ''}`}
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            aria-label="Toggle menu"
            aria-expanded={isMenuOpen}
          >
            <span></span>
            <span></span>
            <span></span>
          </button>
        </div>

        {/* Center: Logo - always mathematically centered via grid */}
        <Link to="/mini" className="mini-navbar-brand" onClick={() => setIsMenuOpen(false)}>
          <img
            src="/assets/images/Basavamart-mini.webp"
            alt="Basava Mart Mini"
            className="mini-navbar-logo-img"
          />
        </Link>

        {/* Right: nav items (desktop) + Exit (always) */}
        <div className="mini-navbar-side mini-navbar-side--right">
          <div className="mini-navbar-links">
            {rightItems.map(renderNavLink)}
          </div>
          <button className="mini-nav-exit" onClick={handleExit}>
            Exit
          </button>
        </div>

        {/* Mobile dropdown */}
        <div className={`mini-nav-mobile ${isMenuOpen ? 'open' : ''}`}>
          {navItems.map(renderNavLink)}
          <button className="mini-nav-exit mini-nav-exit--mobile" onClick={handleExit}>
            Exit
          </button>
        </div>
      </div>
    </nav>
  );
};

export default MiniNavbar;