import React, { useEffect, useMemo, useState } from 'react';
import toast from 'react-hot-toast';
import { getMiniUsers, getTrackingDashboard } from '../../../mini/adminMiniApi';
import { formatINR } from '../../../utils/api';

interface MiniUser {
  _id?: string;
  miniId?: string;
  name?: string;
  phone?: string;
  email?: string;
  address?: string;
  status?: string;
}

interface TrackingData {
  user?: MiniUser | null;
  summary?: {
    totalOrders?: number;
    totalSpent?: number;
    pendingOrders?: number;
    paidOrders?: number;
  };
  cart?: { items?: any[] };
  wishlist?: { items?: any[] };
  orders?: any[];
}

export const AdminMiniTracking = () => {
  const [users, setUsers] = useState<MiniUser[]>([]);
  const [selectedUserId, setSelectedUserId] = useState('');
  const [tracking, setTracking] = useState<TrackingData>({});
  const [loading, setLoading] = useState(true);
  const [selectedOrder, setSelectedOrder] = useState<any | null>(null);

  useEffect(() => {
    fetchUsers();
  }, []);

  useEffect(() => {
    if (selectedUserId) {
      fetchTracking();
    }
  }, [selectedUserId]);

  const fetchUsers = async () => {
    try {
      const res = await getMiniUsers();
      const userList = res.data?.data || [];
      setUsers(userList);
      if (userList[0]?._id) {
        setSelectedUserId(userList[0]._id);
      }
    } catch {
      toast.error('Failed to load mini users');
    } finally {
      setLoading(false);
    }
  };

  const fetchTracking = async () => {
    try {
      const res = await getTrackingDashboard(selectedUserId);
      setTracking(res.data?.data || {});
    } catch {
      toast.error('Failed to load tracking data');
    }
  };

  const currentUser = useMemo(
    () => tracking.user || users.find((user) => user._id === selectedUserId) || null,
    [tracking.user, users, selectedUserId]
  );

  if (loading) return <div className="admin-section"><h2>Mini Tracking Dashboard</h2><p>Loading…</p></div>;

  const summary = tracking.summary || {};

  const renderProductCard = (item: any, index: number) => {
    const product = item?.productId || {};
    const productName = product.productName || item?.name || 'Product';
    const qty = item?.qty ?? 1;
    const unit = product?.unit || item?.unit || '-';
    const price = item?.price ?? product?.price ?? 0;

    return (
      <div key={`${product?._id || productName}-${index}`} style={{ border: '1px solid #eef0f4', borderRadius: 8, padding: 12, marginBottom: 12 }}>
        <div style={{ fontWeight: 700, marginBottom: 6 }}>{productName}</div>
        <div style={{ color: '#4b5563', fontSize: 13, marginBottom: 6 }}>
          {product?.description || 'No description provided'}
        </div>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, fontSize: 12, color: '#374151' }}>
          <span>Brand: {product?.brandName || 'N/A'}</span>
          <span>Category: {product?.categoryName || 'N/A'}</span>
          <span>Qty: {qty}</span>
          <span>Unit: {unit}</span>
          <span>Price: ₹{formatINR(price)}</span>
        </div>
      </div>
    );
  };

  return (
    <div className="admin-section">
      <h2>Mini Tracking Dashboard</h2>
      <p style={{ color: '#666' }}>
        Monitor cart, wishlist, orders, and payment activity for each Mini user.
      </p>

      <div style={{ display: 'flex', gap: '1rem', alignItems: 'center', marginBottom: '1rem' }}>
        <label style={{ fontWeight: 600 }}>Mini user</label>
        <select value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)} className="form-control" style={{ minWidth: 220 }}>
          {users.map((user) => (
            <option key={user._id} value={user._id}>{user.miniId || 'Mini user'} - {user.name || 'Unnamed'}</option>
          ))}
        </select>
      </div>

      {currentUser && (
        <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: 10, padding: '1rem', marginBottom: '1.5rem' }}>
          <h4 style={{ marginTop: 0 }}>User Details</h4>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '0.75rem' }}>
            <div><strong>User ID:</strong><div>{currentUser._id || selectedUserId}</div></div>
            <div><strong>Mini ID:</strong><div>{currentUser.miniId || 'N/A'}</div></div>
            <div><strong>Name:</strong><div>{currentUser.name || 'N/A'}</div></div>
            <div><strong>Phone:</strong><div>{currentUser.phone || 'N/A'}</div></div>
            <div><strong>Email:</strong><div>{currentUser.email || 'N/A'}</div></div>
            <div><strong>Status:</strong><div>{currentUser.status || 'N/A'}</div></div>
          </div>
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '1rem', marginBottom: '1.5rem' }}>
        <div style={{ background: '#f8f8f8', padding: '1rem', borderRadius: '8px' }}>
          <strong>{summary.totalOrders ?? 0}</strong>
          <div>Total Orders</div>
        </div>
        <div style={{ background: '#f8f8f8', padding: '1rem', borderRadius: '8px' }}>
          <strong>₹{formatINR(summary.totalSpent)}</strong>
          <div>Total Spent</div>
        </div>
        <div style={{ background: '#f8f8f8', padding: '1rem', borderRadius: '8px' }}>
          <strong>{summary.pendingOrders ?? 0}</strong>
          <div>Pending</div>
        </div>
        <div style={{ background: '#f8f8f8', padding: '1rem', borderRadius: '8px' }}>
          <strong>{summary.paidOrders ?? 0}</strong>
          <div>Paid</div>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: '1rem' }}>
        <div style={{ background: '#fff', border: '1px solid #eee', borderRadius: '8px', padding: '1rem' }}>
          <h4>Cart</h4>
          {(tracking.cart?.items?.length ?? 0) > 0 ? (
            <div>{tracking.cart?.items?.map((item, index) => renderProductCard(item, index))}</div>
          ) : <p>No cart items.</p>}
        </div>
        <div style={{ background: '#fff', border: '1px solid #eee', borderRadius: '8px', padding: '1rem' }}>
          <h4>Wishlist</h4>
          {(tracking.wishlist?.items?.length ?? 0) > 0 ? (
            <div>{tracking.wishlist?.items?.map((item, index) => renderProductCard(item, index))}</div>
          ) : <p>No wishlist items.</p>}
        </div>
        <div style={{ background: '#fff', border: '1px solid #eee', borderRadius: '8px', padding: '1rem', gridColumn: '1 / -1' }}>
          <h4>Recent Orders</h4>
          {(tracking.orders?.length ?? 0) > 0 ? (
            <div style={{ display: 'grid', gap: '0.75rem' }}>
              {tracking.orders?.slice(0, 5).map((order: any, idx: number) => (
                <div key={order._id || idx} style={{ border: '1px solid #edf2f7', borderRadius: 8, padding: 12, display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'center', flexWrap: 'wrap' }}>
                  <div>
                    <strong>Order #{(order._id || '').slice(-8).toUpperCase()}</strong>
                    <div style={{ color: '#4b5563', fontSize: 13 }}>
                      ₹{formatINR(order.total)} · {order.orderStatus || 'placed'} · {new Date(order.createdAt || Date.now()).toLocaleDateString()}
                    </div>
                  </div>
                  <button className="btn btn-sm btn-primary" onClick={() => setSelectedOrder(order)}>
                    View Details
                  </button>
                </div>
              ))}
            </div>
          ) : <p>No orders yet.</p>}
        </div>
      </div>

      {selectedOrder && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(15, 23, 42, 0.55)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: 16 }} onClick={() => setSelectedOrder(null)}>
          <div style={{ background: '#fff', width: 'min(900px, 100%)', maxHeight: '90vh', overflowY: 'auto', borderRadius: 12, padding: 20, boxShadow: '0 20px 50px rgba(0,0,0,0.25)' }} onClick={(e) => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
              <h3 style={{ margin: 0 }}>Order Details</h3>
              <button className="btn btn-secondary" onClick={() => setSelectedOrder(null)}>Close</button>
            </div>

            <div style={{ display: 'grid', gap: 16 }}>
              <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: 10, padding: 12 }}>
                <div><strong>User ID:</strong> {currentUser?._id || selectedUserId}</div>
                <div><strong>Mini ID:</strong> {currentUser?.miniId || 'N/A'}</div>
                <div><strong>Order ID:</strong> {selectedOrder._id || 'N/A'}</div>
                <div><strong>Status:</strong> {selectedOrder.orderStatus || 'placed'}</div>
                <div><strong>Total:</strong> ₹{formatINR(selectedOrder.total)}</div>
                <div><strong>Created:</strong> {new Date(selectedOrder.createdAt || Date.now()).toLocaleString()}</div>
              </div>

              <div>
                <h4>Products</h4>
                {(selectedOrder.items || []).map((item: any, idx: number) => renderProductCard(item, idx))}
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: 16 }}>
                <div style={{ background: '#fff', border: '1px solid #eaecf0', borderRadius: 8, padding: 12 }}>
                  <h4>Billing Address</h4>
                  <div>{selectedOrder.billingAddress?.name || 'N/A'}</div>
                  <div>{selectedOrder.billingAddress?.line1 || 'N/A'}</div>
                  {selectedOrder.billingAddress?.line2 && <div>{selectedOrder.billingAddress.line2}</div>}
                  <div>{selectedOrder.billingAddress?.city || ''} {selectedOrder.billingAddress?.state || ''}</div>
                  <div>{selectedOrder.billingAddress?.pincode || ''}</div>
                  <div>{selectedOrder.billingAddress?.phone || 'N/A'}</div>
                </div>

                <div style={{ background: '#fff', border: '1px solid #eaecf0', borderRadius: 8, padding: 12 }}>
                  <h4>Shipping Address</h4>
                  <div>{selectedOrder.shippingAddress?.name || 'N/A'}</div>
                  <div>{selectedOrder.shippingAddress?.line1 || 'N/A'}</div>
                  {selectedOrder.shippingAddress?.line2 && <div>{selectedOrder.shippingAddress.line2}</div>}
                  <div>{selectedOrder.shippingAddress?.city || ''} {selectedOrder.shippingAddress?.state || ''}</div>
                  <div>{selectedOrder.shippingAddress?.pincode || ''}</div>
                  <div>{selectedOrder.shippingAddress?.phone || 'N/A'}</div>
                </div>
              </div>

              <div style={{ background: '#fff', border: '1px solid #eaecf0', borderRadius: 8, padding: 12 }}>
                <h4>Payment Information</h4>
                <div><strong>Payment Status:</strong> {selectedOrder.payment?.status || 'pending'}</div>
                <div><strong>Subtotal:</strong> ₹{formatINR(selectedOrder.subtotal)}</div>
                <div><strong>GST:</strong> ₹{formatINR(selectedOrder.gstAmount)}</div>
                <div><strong>Total:</strong> ₹{formatINR(selectedOrder.total)}</div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminMiniTracking;
