function injectMemberStyles() {
  if (document.getElementById('member-responsive-styles')) return;
  const tag = document.createElement('style');
  tag.id = 'member-responsive-styles';
  tag.textContent = memberStyles;
  document.head.appendChild(tag);
}

/* ─── MemberDashboard ─── */
export function MemberDashboard() {
  const [stats, setStats] = useState<any>(null);
  const [brands, setBrands] = useState<any[]>([]);
  const [selectedBrand, setSelectedBrand] = useState('');
  const [categories, setCategories] = useState<any[]>([]);
  const [subcategories, setSubcategories] = useState<any[]>([]);
  const [selectedCategory, setSelectedCategory] = useState('');
  const [selectedSubcategory, setSelectedSubcategory] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(true);
  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(100);
  const [totalProducts, setTotalProducts] = useState(0);

  useEffect(() => { injectMemberStyles(); }, []);

  const totalPages = Math.max(1, Math.ceil(totalProducts / limit));

  const getPageNumbers = () => {
    const pages: (number | string)[] = [];
    if (totalPages <= 7) {
      for (let i = 1; i <= totalPages; i++) pages.push(i);
    } else {
      pages.push(1);
      if (page > 3) pages.push('...');
      for (let i = Math.max(2, page - 1); i <= Math.min(totalPages - 1, page + 1); i++) pages.push(i);
      if (page < totalPages - 2) pages.push('...');
      pages.push(totalPages);
    }
    return pages;
  };

  useEffect(() => { setPage(1); }, [selectedBrand, selectedCategory, selectedSubcategory, limit]);

  useEffect(() => {
    api.get('/dashboard/member').then(r => setStats(r.data.stats));
    api.get('/brands', { params: { limit: 50, accessLevel: 'member' } }).then(r => setBrands(r.data.brands));
  }, []);

  useEffect(() => {
    if (!selectedBrand) { setCategories([]); setSubcategories([]); return; }
    api.get(`/categories/brand/${selectedBrand}`, { params: { accessLevel: 'member' } }).then(res => setCategories(res.data.categories || [])).catch(() => setCategories([]));
  }, [selectedBrand]);

  useEffect(() => {
    if (!selectedCategory) { setSubcategories([]); return; }
    api.get(`/categories/subcategory/category/${selectedCategory}`, { params: { accessLevel: 'member' } }).then(res => setSubcategories(res.data.subcategories || [])).catch(() => setSubcategories([]));
  }, [selectedCategory]);

  useEffect(() => {
    const load = async () => {
      setLoadingProducts(true);
      const params: any = { page, limit };
      if (selectedBrand) params.brand = selectedBrand;
      if (selectedCategory) params.category = selectedCategory;
      if (selectedSubcategory) params.subcategory = selectedSubcategory;
      const [productResponse, pipeResponse] = await Promise.all([
        api.get('/products/member', { params }),
        api.get('/pipes/member', { params }),
      ]);
      const pipeProducts = (pipeResponse.data.pipes || []).map((pipe: any) => ({ ...pipe, _catalogType: 'pipe' }));
      setProducts([...(productResponse.data.products || []), ...pipeProducts]);
      setTotalProducts((productResponse.data.total || 0) + (pipeResponse.data.total || 0));
      setLoadingProducts(false);
    };
    load();
  }, [selectedBrand, selectedCategory, selectedSubcategory, page, limit]);

  const statCards = stats ? [
    { label: 'Basket Items', value: stats.basketTotal, icon: <MdOutlineShoppingBasket size={22} />, color: 'var(--primary)' },
    { label: 'Paid Orders', value: stats.paidOrders, icon: <FiCheckCircle size={22} />, color: 'var(--green)' },
    { label: 'Pending', value: stats.pendingBasket, icon: <FiClock size={22} />, color: 'var(--yellow)' },
    { label: 'Delivered', value: stats.deliveredOrders, icon: <FiTruck size={22} />, color: 'var(--blue)' },
    { label: 'Total Spent', value: `₹${formatINR(stats.totalRevenue)}`, icon: <FiDollarSign size={22} />, color: 'var(--primary)' },
  ] : [];

  const quickLinks = [
    { href: '/member/products', label: 'Browse Products', icon: <MdOutlineInventory2 size={16} />, cls: 'btn-primary' },
    { href: '/member/basket', label: 'View Basket', icon: <MdOutlineShoppingBasket size={16} />, cls: 'btn-outline' },
    { href: '/member/orders', label: 'My Orders', icon: <FiList size={16} />, cls: 'btn-gray' },
    { href: '/member/sites', label: 'My Sites', icon: <MdConstruction size={16} />, cls: 'btn-gray' },
  ];

  const sectionLabel = (label: string) => (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
      <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--gray-500)', textTransform: 'uppercase', letterSpacing: 1 }}>{label}</span>
      <div style={{ flex: 1, height: 1, background: 'var(--gray-200)' }} />
    </div>
  );

  return (
    <div className="member-page fade-in">
      <div className="page-header">
        <h1 className="page-title"><MdAnalytics size={24} color="var(--primary)" /> Member Dashboard</h1>
      </div>

      {/* Stats */}
      <div className="stats-grid">
        {statCards.map((c, i) => (
          <div key={i} className="stat-card">
            <div className="stat-icon" style={{ background: `${c.color}20`, color: c.color }}>{c.icon}</div>
            <div className="stat-value" style={{ color: c.color }}>{c.value}</div>
            <div className="stat-label">{c.label}</div>
          </div>
        ))}
      </div>

      {/* Quick Actions */}
      <div className="card" style={{ padding: 'clamp(16px,3vw,24px)', marginBottom: 'clamp(20px,4vw,32px)' }}>
        <h3 style={{ fontSize: 15, fontWeight: 600, marginBottom: 12 }}>Quick Actions</h3>
        <div className="quick-actions">
          {quickLinks.map(({ href, label, icon, cls }) => (
            <a key={href} href={href} className={`btn ${cls}`}>{icon} {label}</a>
          ))}
        </div>
      </div>

      {/* Brands */}
      <div style={{ marginBottom: 32 }}>
        <h2 style={{ fontSize: 'clamp(17px,4vw,22px)', fontWeight: 700, marginBottom: 14, display: 'flex', alignItems: 'center', gap: 8 }}>
          <FiTag color="var(--primary)" /> Shop by Brand
        </h2>
        <div className="brand-pills">
          <button className={`brand-pill ${!selectedBrand ? 'active' : ''}`}
            onClick={() => { setSelectedBrand(''); setSelectedCategory(''); setSelectedSubcategory(''); }}>
            <MdOutlineStorefront size={28} color={!selectedBrand ? 'var(--primary)' : 'var(--gray-400)'} />
            <span className="label" style={{ color: !selectedBrand ? 'var(--primary)' : 'var(--gray-600)' }}>All</span>
          </button>
          {brands.map(brand => (
            <button key={brand._id} className={`brand-pill ${selectedBrand === brand._id ? 'active' : ''}`}
              onClick={() => { setSelectedBrand(brand._id); setSelectedCategory(''); setSelectedSubcategory(''); }}>
              <img src={getImageUrl(brand.logo)} alt={brand.name} style={{ width: 40, height: 40, objectFit: 'contain', borderRadius: 8 }} />
              <span className="label" style={{ color: selectedBrand === brand._id ? 'var(--primary)' : 'var(--gray-600)' }}>{brand.name}</span>
            </button>
          ))}
        </div>

        {/* Categories */}
        {selectedBrand && categories.length > 0 && (
          <div style={{ marginTop: 20 }}>
            {sectionLabel('Select Category')}
            <div className="brand-pills">
              <button className={`brand-pill ${!selectedCategory ? 'active' : ''}`}
                onClick={() => { setSelectedCategory(''); setSelectedSubcategory(''); }}>
                <FiGrid size={26} color={!selectedCategory ? 'var(--primary)' : 'var(--gray-400)'} />
                <span className="label" style={{ color: !selectedCategory ? 'var(--primary)' : 'var(--gray-600)' }}>All</span>
              </button>
              {categories.map(cat => (
                <button key={cat._id} className={`brand-pill ${selectedCategory === cat._id ? 'active' : ''}`}
                  onClick={() => { setSelectedCategory(cat._id); setSelectedSubcategory(''); }}>
                  {cat.image
                    ? <img src={getImageUrl(cat.image)} alt={cat.name} style={{ width: 40, height: 40, objectFit: 'contain', borderRadius: 8 }} />
                    : <FiPackage size={26} color={selectedCategory === cat._id ? 'var(--primary)' : 'var(--gray-400)'} />}
                  <span className="label" style={{ color: selectedCategory === cat._id ? 'var(--primary)' : 'var(--gray-600)' }}>{cat.name}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Subcategories */}
        {selectedCategory && subcategories.length > 0 && (
          <div style={{ marginTop: 16 }}>
            {sectionLabel('Select Subcategory')}
            <div className="brand-pills">
              <button className={`brand-pill ${!selectedSubcategory ? 'active' : ''}`}
                onClick={() => setSelectedSubcategory('')}>
                <FiList size={26} color={!selectedSubcategory ? 'var(--primary)' : 'var(--gray-400)'} />
                <span className="label" style={{ color: !selectedSubcategory ? 'var(--primary)' : 'var(--gray-600)' }}>All</span>
              </button>
              {subcategories.map(sub => (
                <button key={sub._id} className={`brand-pill ${selectedSubcategory === sub._id ? 'active' : ''}`}
                  onClick={() => setSelectedSubcategory(sub._id)}>
                  {sub.image
                    ? <img src={getImageUrl(sub.image)} alt={sub.name} style={{ width: 40, height: 40, objectFit: 'contain', borderRadius: 8 }} />
                    : <FiFileText size={26} color={selectedSubcategory === sub._id ? 'var(--primary)' : 'var(--gray-400)'} />}
                  <span className="label" style={{ color: selectedSubcategory === sub._id ? 'var(--primary)' : 'var(--gray-600)' }}>{sub.name}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Active Filters */}
        {(selectedBrand || selectedCategory || selectedSubcategory) && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 14, padding: '10px 14px', background: 'var(--primary-bg)', borderRadius: 10, border: '1px solid var(--primary)', flexWrap: 'wrap' }}>
            <FiFilter size={14} color="var(--primary)" />
            <span style={{ fontSize: 13, color: 'var(--primary)', fontWeight: 600 }}>Filtering:</span>
            {selectedBrand && <span style={{ fontSize: 12, background: 'var(--primary)', color: 'white', borderRadius: 6, padding: '2px 10px' }}>{brands.find(b => b._id === selectedBrand)?.name}</span>}
            {selectedCategory && <span style={{ fontSize: 12, background: 'var(--primary)', color: 'white', borderRadius: 6, padding: '2px 10px' }}>{categories.find(c => c._id === selectedCategory)?.name}</span>}
            {selectedSubcategory && <span style={{ fontSize: 12, background: 'var(--primary)', color: 'white', borderRadius: 6, padding: '2px 10px' }}>{subcategories.find(s => s._id === selectedSubcategory)?.name}</span>}
            <button onClick={() => { setSelectedBrand(''); setSelectedCategory(''); setSelectedSubcategory(''); }}
              style={{ marginLeft: 'auto', fontSize: 12, color: 'var(--primary)', background: 'none', border: 'none', cursor: 'pointer', fontWeight: 600, display: 'flex', alignItems: 'center', gap: 4 }}>
              <FiX size={14} /> Clear All
            </button>
          </div>
        )}
      </div>

      {/* Featured Products */}
      {/* Featured Products */}
      <div style={{ marginBottom: 40 }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 14, flexWrap: 'wrap', gap: 8 }}>
          <h2 style={{ fontSize: 'clamp(16px,4vw,22px)', fontWeight: 700, display: 'flex', alignItems: 'center', gap: 8 }}>
            <FiPackage color="var(--primary)" />
            {selectedBrand ? `${brands.find(b => b._id === selectedBrand)?.name} Products` : 'Featured Products'}
          </h2>
          <a href="/member/products" style={{ color: 'var(--primary)', textDecoration: 'none', fontSize: 13, fontWeight: 500, display: 'flex', alignItems: 'center', gap: 4 }}>
            View All <FiChevronRight size={14} />
          </a>
        </div>

        {/* Product count highlight */}
        {!loadingProducts && totalProducts > 0 && (
          <div style={{
            display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16,
            padding: '10px 16px', background: 'var(--primary-bg)', border: '1px solid var(--primary)',
            borderRadius: 10, width: 'fit-content'
          }}>
            <FiPackage size={16} color="var(--primary)" />
            <span style={{ fontSize: 14, color: 'var(--gray-700)' }}>
              Showing <strong style={{ color: 'var(--primary)', fontSize: 16 }}>{products.length}</strong> of{' '}
              <strong style={{ color: 'var(--primary)', fontSize: 16 }}>{totalProducts}</strong> products
            </span>
          </div>
        )}

        {loadingProducts ? (
          <div className="products-grid">
            {Array.from({ length: 8 }).map((_, i) => <div key={i} style={{ background: 'var(--gray-100)', borderRadius: 12, height: 260, animation: 'pulse 1.5s ease-in-out infinite' }} />)}
          </div>
        ) : products.length === 0 ? (
          <div style={{ textAlign: 'center', padding: 60, color: 'var(--gray-400)' }}>
            <FiPackage size={48} />
            <div style={{ fontSize: 15, marginTop: 10 }}>No products found</div>
          </div>
        ) : (
          <>
            <div className="products-grid">
              {products.map(p => (
                <ProductCard key={p._id} product={p} href={`/member/products/${p._id}`} idPrefix="dash" />
              ))}
            </div>

            {/* Pagination controls */}
            {totalPages > 1 && (
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, marginTop: 24, flexWrap: 'wrap' }}>
                <button className="btn btn-gray btn-sm" disabled={page === 1} onClick={() => setPage(p => Math.max(1, p - 1))}>
                  Prev
                </button>
                {getPageNumbers().map((pn, i) =>
                  pn === '...' ? (
                    <span key={`ellipsis-${i}`} style={{ padding: '0 6px', color: 'var(--gray-400)' }}>…</span>
                  ) : (
                    <button
                      key={pn}
                      onClick={() => setPage(pn as number)}
                      className={`btn btn-sm ${page === pn ? 'btn-primary' : 'btn-gray'}`}
                      style={{ minWidth: 36 }}
                    >
                      {pn}
                    </button>
                  )
                )}
                <button className="btn btn-gray btn-sm" disabled={page === totalPages} onClick={() => setPage(p => Math.min(totalPages, p + 1))}>
                  Next
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

/* ─── Shared Product Card ─── */
function ProductCard({ product: p, href, idPrefix }: { product: any; href: string; idPrefix: string }) {
  const addToCart = (e: React.MouseEvent) => {
    e.stopPropagation();
    const sel = document.getElementById(`${idPrefix}-var-${p._id}`) as HTMLSelectElement;
    const v = p.variants?.find((vv: any) => vv._id === sel?.value) || p.variants?.[0];
    if (!v) return;
    const existing = JSON.parse(localStorage.getItem('bm_member_cart') || '[]');
    const idx = existing.findIndex((c: any) => c.productId === p._id && c.variantId === v._id);
    if (idx > -1) existing[idx].qty += 1;
    else existing.push({ productId: p._id, variantId: v._id, productName: p.name, productImage: p.images?.[0] || '', brandName: p.brand?.name || '', variantName: v.name, unit: v.unit, primaryThreshold: v.primaryThreshold || 0, secondaryThreshold: v.secondaryThreshold || 0, tertiaryThreshold: v.tertiaryThreshold || 0, qty: 1 });
    localStorage.setItem('bm_member_cart', JSON.stringify(existing));
    toast.success('Added to cart!');
  };

  return (
    <div className="product-card" onClick={() => window.location.href = href}>
      <div className="product-card-image">
        <img src={getImageUrl(p.images?.[0])} alt={p.name} onError={e => (e.currentTarget.src = '/placeholder.png')} />
      </div>
      <div className="product-card-body">
        <div className="product-card-brand">{p.brand?.name}</div>
        <div className="product-card-name">{p.name}</div>
        <div className="product-card-pricing"><div className="product-card-price-label">Know the Price</div></div>
        {p.variants?.length > 0 && (
          <div style={{ marginTop: 8 }} onClick={e => e.stopPropagation()}>
            <select className="form-control" style={{ fontSize: 12, marginBottom: 8 }} id={`${idPrefix}-var-${p._id}`}>
              {p.variants.map((v: any) => <option key={v._id} value={v._id}>{v.name} ({v.unit})</option>)}
            </select>
            <button className="btn btn-primary" style={{ width: '100%', fontSize: 13, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6 }} onClick={addToCart}>
              <FiShoppingCart size={14} /> Add to Cart
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

