export function MemberProducts() {
  const [products, setProducts] = useState<any[]>([]);
  const [brands, setBrands] = useState<any[]>([]);
  const [filters, setFilters] = useState({ brand: '', search: '' });
  const [cart, setCart] = useState<any[]>(() => { try { return JSON.parse(localStorage.getItem('bm_member_cart') || '[]'); } catch { return []; } });

  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(100);
  const [totalProducts, setTotalProducts] = useState(0);
  const [loading, setLoading] = useState(true);

  const totalPages = Math.max(1, Math.ceil(totalProducts / limit));

  useEffect(() => { injectMemberStyles(); }, []);
  useEffect(() => { api.get('/brands', { params: { limit: 100, accessLevel: 'member' } }).then(r => setBrands(r.data.brands)); }, []);

  // Reset to page 1 whenever filters or page size change
  useEffect(() => { setPage(1); }, [filters, limit]);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      const params: any = { page, limit };
      if (filters.brand) params.brand = filters.brand;
      if (filters.search) params.search = filters.search;
      const [productResponse, pipeResponse] = await Promise.all([
        api.get('/products/member', { params }),
        api.get('/pipes/member', { params }),
      ]);
      const pipeProducts = (pipeResponse.data.pipes || []).map((pipe: any) => ({ ...pipe, _catalogType: 'pipe' }));
      setProducts([...(productResponse.data.products || []), ...pipeProducts]);
      setTotalProducts((productResponse.data.total || 0) + (pipeResponse.data.total || 0));
      setLoading(false);
    };
    load();
  }, [filters, page, limit]);

  const addToCart = (product: any, variant: any) => {
    const existing = cart.find((c: any) => c.productId === product._id && c.variantId === variant._id);
    let newCart;
    if (existing) newCart = cart.map((c: any) => c.productId === product._id && c.variantId === variant._id ? { ...c, qty: c.qty + 1 } : c);
    else newCart = [...cart, { productId: product._id, variantId: variant._id, productName: product.name, productImage: product.images?.[0] || '', brandName: product.brand?.name || '', variantName: variant.name, unit: variant.unit, primaryThreshold: variant.primaryThreshold || 0, secondaryThreshold: variant.secondaryThreshold || 0, tertiaryThreshold: variant.tertiaryThreshold || 0, qty: 1 }];
    setCart(newCart);
    localStorage.setItem('bm_member_cart', JSON.stringify(newCart));
    toast.success('Added to cart!');
  };

  const cartCount = cart.reduce((s: number, c: any) => s + c.qty, 0);

  // Build a compact page-number list (with ellipsis) for larger page counts
  const getPageNumbers = () => {
    const pages: (number | string)[] = [];
    if (totalPages <= 7) {
      for (let i = 1; i <= totalPages; i++) pages.push(i);
    } else {
      pages.push(1);
      if (page > 3) pages.push('...');
      for (let i = Math.max(2, page - 1); i <= Math.min(totalPages - 1, page + 1); i++) pages.push(i);
      if (page < totalPages - 2) pages.push('...');
      pages.push(totalPages);
    }
    return pages;
  };

  return (
    <div className="member-page fade-in">
      <div className="page-header">
        <h1 className="page-title"><MdOutlineInventory2 size={24} color="var(--primary)" /> Products</h1>
        <a href="/member/cart" className="btn btn-primary" style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <FiShoppingCart size={16} /> Cart ({cartCount})
        </a>
      </div>

      {/* Product count highlight */}
      <div style={{
        display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16,
        padding: '10px 16px', background: 'var(--primary-bg)', border: '1px solid var(--primary)',
        borderRadius: 10, width: 'fit-content'
      }}>
        <FiPackage size={16} color="var(--primary)" />
        <span style={{ fontSize: 14, color: 'var(--gray-700)' }}>
          Showing <strong style={{ color: 'var(--primary)', fontSize: 16 }}>{products.length}</strong> of{' '}
          <strong style={{ color: 'var(--primary)', fontSize: 16 }}>{totalProducts}</strong> products
        </span>
      </div>

      <div className="filter-bar">
        <div style={{ position: 'relative', flex: 1, minWidth: 140 }}>
          <FiSearch size={15} style={{ position: 'absolute', left: 10, top: '50%', transform: 'translateY(-50%)', color: 'var(--gray-400)' }} />
          <input className="form-control" placeholder="Search products..." style={{ paddingLeft: 34, fontSize: 'clamp(12px,3.5vw,14px)' }} value={filters.search} onChange={e => setFilters(p => ({ ...p, search: e.target.value }))} />
        </div>
        <select className="form-control" style={{ width: 'clamp(130px,30vw,180px)', fontSize: 'clamp(12px,3.5vw,14px)' }} value={filters.brand} onChange={e => setFilters(p => ({ ...p, brand: e.target.value }))}>
          <option value="">All Brands</option>
          {brands.map(b => <option key={b._id} value={b._id}>{b.name}</option>)}
        </select>
        <select className="form-control" style={{ width: 120, fontSize: 'clamp(12px,3.5vw,14px)' }} value={limit} onChange={e => setLimit(+e.target.value)}>
          <option value={100}>100 / page</option>
          <option value={80}>80 / page</option>
          <option value={60}>60 / page</option>
          <option value={20}>20 / page</option>
        </select>
      </div>

      {loading ? (
        <div className="products-grid">
          {Array.from({ length: 8 }).map((_, i) => <div key={i} style={{ background: 'var(--gray-100)', borderRadius: 12, height: 260, animation: 'pulse 1.5s ease-in-out infinite' }} />)}
        </div>
      ) : (
        <div className="products-grid">
          {products.map(p => (
            <div key={p._id} className="product-card">
              <div className="product-card-image" onClick={() => window.location.href = `/member/products/${p._id}`}>
                <img src={getImageUrl(p.images?.[0])} alt={p.name} onError={e => (e.currentTarget.src = '/placeholder.png')} />
              </div>
              <div className="product-card-body">
                <div className="product-card-brand">{p.brand?.name}</div>
                <div className="product-card-name">{p.name}</div>
                {p.category?.name && <div style={{ fontSize: 11, color: 'var(--gray-600)', marginTop: 3 }}>Category: {p.category.name}</div>}
                {p.subcategory?.name && <div style={{ fontSize: 11, color: 'var(--gray-500)' }}>Subcategory: {p.subcategory.name}</div>}
                <div className="product-card-pricing"><div className="product-card-price-label">Know the Price</div></div>
                {p.variants?.length > 0 && (
                  <div style={{ marginTop: 8 }}>
                    <select className="form-control" style={{ fontSize: 12, marginBottom: 8 }} id={`prod-var-${p._id}`}>
                      {p.variants.map((v: any) => <option key={v._id} value={v._id}>{v.name} ({v.weight || 0} kg, {v.unit})</option>)}
                    </select>
                    <button className="btn btn-primary" style={{ width: '100%', fontSize: 13, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6 }}
                      onClick={() => { const sel = document.getElementById(`prod-var-${p._id}`) as HTMLSelectElement; const v = p.variants.find((vv: any) => vv._id === sel.value) || p.variants[0]; addToCart(p, v); }}>
                      <FiShoppingCart size={14} /> Add to Cart
                    </button>
                  </div>
                )}
              </div>
            </div>
          ))}
          {!products.length && (
            <div style={{ gridColumn: '1/-1', textAlign: 'center', padding: 60, color: 'var(--gray-400)' }}>
              <FiPackage size={48} />
              <div style={{ marginTop: 10 }}>No products found</div>
            </div>
          )}
        </div>
      )}

      {/* Pagination controls */}
      {totalPages > 1 && (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, marginTop: 28, flexWrap: 'wrap' }}>
          <button className="btn btn-gray btn-sm" disabled={page === 1} onClick={() => setPage(p => Math.max(1, p - 1))}>
            Prev
          </button>
          {getPageNumbers().map((pn, i) =>
            pn === '...' ? (
              <span key={`ellipsis-${i}`} style={{ padding: '0 6px', color: 'var(--gray-400)' }}>…</span>
            ) : (
              <button
                key={pn}
                onClick={() => setPage(pn as number)}
                className={`btn btn-sm ${page === pn ? 'btn-primary' : 'btn-gray'}`}
                style={{ minWidth: 36 }}
              >
                {pn}
              </button>
            )
          )}
          <button className="btn btn-gray btn-sm" disabled={page === totalPages} onClick={() => setPage(p => Math.min(totalPages, p + 1))}>
            Next
          </button>
        </div>
      )}
    </div>
  );
}

/* ─── MemberCart ─── */
function calcPkg(qty: number, t: number, s: number, p: number) {
  let rem = qty;
  const res = { tertiary: { count: 0, total: 0, qty: t }, secondary: { count: 0, total: 0, qty: s }, primary: { count: 0, total: 0, qty: p }, remainder: 0 };
  if (t > 0) { res.tertiary.count = Math.floor(rem / t); rem %= t; res.tertiary.total = res.tertiary.count * t; }
  if (s > 0) { res.secondary.count = Math.floor(rem / s); rem %= s; res.secondary.total = res.secondary.count * s; }
  if (p > 0) { res.primary.count = Math.floor(rem / p); rem %= p; res.primary.total = res.primary.count * p; }
  res.remainder = rem; return res;
}

export function MemberCart() {
  const [cart, setCart] = useState<any[]>(() => { try { return JSON.parse(localStorage.getItem('bm_member_cart') || '[]'); } catch { return []; } });
  const [movingToBasket, setMovingToBasket] = useState('');
  const navigate = useNavigate();

  useEffect(() => { injectMemberStyles(); }, []);

  const updateCart = (newCart: any[]) => { setCart(newCart); localStorage.setItem('bm_member_cart', JSON.stringify(newCart)); };
  const updateQty = (productId: string, variantId: string, qty: number) => {
    if (qty <= 0) { updateCart(cart.filter((c: any) => !(c.productId === productId && c.variantId === variantId))); return; }
    updateCart(cart.map((c: any) => c.productId === productId && c.variantId === variantId ? { ...c, qty } : c));
  };

  const knowPrice = async (item: any) => {
    setMovingToBasket(`${item.productId}-${item.variantId}`);
    try {
      await api.post('/basket/add', { productId: item.productId, variantId: item.variantId, quantity: item.qty });
      toast.success('Moved to Basket! Admin will set the price.');
      updateCart(cart.filter((c: any) => !(c.productId === item.productId && c.variantId === item.variantId)));
    } catch (e: any) { toast.error(e.response?.data?.message || 'Error'); }
    setMovingToBasket('');
  };

  const [attachData, setAttachData] = useState<{ [key: string]: { files: File[]; note: string } }>({});

  const addFiles = (key: string, fileList: FileList | null) => {
    const incoming = Array.from(fileList || []);
    setAttachData(prev => {
      const current = prev[key]?.files || [];
      const combined = [...current, ...incoming].slice(0, 7);
      return { ...prev, [key]: { ...(prev[key] || { note: '' }), files: combined } };
    });
  };

  const removeFile = (key: string, index: number) => {
    setAttachData(prev => {
      const current = prev[key]?.files || [];
      const updated = current.filter((_, i) => i !== index);
      return { ...prev, [key]: { ...(prev[key] || { note: '' }), files: updated } };
    });
  };

  const setNote = (key: string, note: string) => {
    setAttachData(prev => ({ ...prev, [key]: { ...(prev[key] || { files: [] }), note } }));
  };

  const [submittingKey, setSubmittingKey] = useState('');

  const submitAttachment = async (item: any) => {
    const key = `${item.productId}-${item.variantId}`;
    setSubmittingKey(key);
    try {
      const data = attachData[key] || { files: [], note: '' };
      const fd = new FormData();
      fd.append('productId', item.productId);
      fd.append('variantId', item.variantId);
      fd.append('quantity', String(item.qty));
      fd.append('memberNote', data.note || '');
      data.files.forEach((f: File) => fd.append('files', f));
      await api.post('/basket/add', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      toast.success('Submitted! Moved to Basket — admin will set the price.');
      updateCart(cart.filter((c: any) => !(c.productId === item.productId && c.variantId === item.variantId)));
    } catch (e: any) { toast.error(e.response?.data?.message || 'Error'); }
    setSubmittingKey('');
  };

  if (!cart.length) return (
    <div style={{ textAlign: 'center', padding: 80 }}>
      <FiShoppingCart size={64} color="var(--gray-300)" />
      <h2 style={{ fontSize: 20, fontWeight: 700, marginTop: 16 }}>Your cart is empty</h2>
      <a href="/member/products" className="btn btn-primary" style={{ marginTop: 16, display: 'inline-flex', gap: 6 }}>
        <MdOutlineInventory2 size={16} /> Browse Products
      </a>
    </div>
  );

  return (
    <div className="member-page fade-in">
      <div className="page-header">
        <h1 className="page-title"><FiShoppingCart size={22} color="var(--primary)" /> Member Cart</h1>
        <span style={{ fontSize: 13, color: 'var(--gray-500)' }}>{cart.length} item{cart.length !== 1 ? 's' : ''}</span>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
        {cart.map((item: any) => {
          const pkg = calcPkg(item.qty, item.tertiaryThreshold, item.secondaryThreshold, item.primaryThreshold);
          const key = `${item.productId}-${item.variantId}`;
          return (
            <div key={key} className="card" style={{ padding: 'clamp(14px,3vw,20px)' }}>
              {/* Clickable row → navigates to product detail */}
              <div
                className="cart-item-row"
                style={{ cursor: 'pointer' }}
                onClick={() => navigate(`/member/products/${item.productId}`)}
              >
                <img src={getImageUrl(item.productImage)} style={{ width: 68, height: 68, objectFit: 'contain', borderRadius: 8, border: '1px solid var(--gray-200)', background: 'var(--gray-50)', flexShrink: 0 }} />
                <div className="cart-item-details">
                  <div style={{ fontWeight: 600, fontSize: 'clamp(13px,3.5vw,15px)' }}>{item.productName}</div>
                  <div style={{ fontSize: 12, color: 'var(--gray-600)' }}>{item.variantName} ({item.unit})</div>
                  <div style={{ fontSize: 11, color: 'var(--gray-400)' }}>{item.brandName}</div>

                  <div className="cart-item-actions" onClick={e => e.stopPropagation()}>
                    <div className="qty-control">
                      <button className="qty-btn" onClick={() => updateQty(item.productId, item.variantId, item.qty - 1)}><FiMinus size={13} /></button>
                      <input type="number" className="qty-input" value={item.qty} onChange={e => updateQty(item.productId, item.variantId, Math.max(1, +e.target.value))} />
                      <button className="qty-btn" onClick={() => updateQty(item.productId, item.variantId, item.qty + 1)}><FiPlus size={13} /></button>
                    </div>
                    <button className="btn btn-primary btn-sm" style={{ display: 'flex', alignItems: 'center', gap: 5 }} onClick={() => knowPrice(item)} disabled={movingToBasket === key}>
                      {movingToBasket === key ? <div className="spinner" /> : <><FiDollarSign size={13} /> Know Price</>}
                    </button>
                    <button style={{ border: 'none', background: 'none', cursor: 'pointer', color: 'var(--red)', padding: 4 }} onClick={() => updateCart(cart.filter((c: any) => !(c.productId === item.productId && c.variantId === item.variantId)))}>
                      <FiTrash2 size={17} />
                    </button>
                  </div>

                  {(item.primaryThreshold > 0 || item.secondaryThreshold > 0 || item.tertiaryThreshold > 0) && (
                    <div className="pkg-breakdown" style={{ marginTop: 10 }}>
                      <div style={{ fontSize: 11, fontWeight: 600, color: 'var(--primary)', marginBottom: 4, display: 'flex', alignItems: 'center', gap: 4 }}>
                        <FiPackage size={12} /> Package Breakdown
                      </div>
                      {pkg.tertiary.count > 0 && <div className="pkg-row"><span className="pkg-label">Tertiary ({pkg.tertiary.qty})</span><span>{pkg.tertiary.count} × {pkg.tertiary.qty} = {pkg.tertiary.total}</span></div>}
                      {pkg.secondary.count > 0 && <div className="pkg-row"><span className="pkg-label">Secondary ({pkg.secondary.qty})</span><span>{pkg.secondary.count} × {pkg.secondary.qty} = {pkg.secondary.total}</span></div>}
                      {pkg.primary.count > 0 && <div className="pkg-row"><span className="pkg-label">Primary ({pkg.primary.qty})</span><span>{pkg.primary.count} × {pkg.primary.qty} = {pkg.primary.total}</span></div>}
                      {pkg.remainder > 0 && <div className="pkg-row"><span className="pkg-label">Loose</span><span>{pkg.remainder} pcs</span></div>}
                    </div>
                  )}
                </div>
              </div>

              {/* Full-width attach section, OUTSIDE the flex row, not clickable-to-navigate */}
              <div className="attach-section" onClick={e => e.stopPropagation()}>
                <div className="attach-label">
                  <FiPaperclip size={13} /> Attach images / videos / documents (up to 7)
                </div>

                <input
                  type="file"
                  multiple
                  accept="image/*,video/*,.pdf,.doc,.docx,.xls,.xlsx,.csv"
                  onChange={e => { addFiles(key, e.target.files); e.target.value = ''; }}
                  className="attach-file-input"
                />

                {attachData[key]?.files?.length > 0 && (
                  <div className="attach-file-list">
                    {attachData[key].files.map((f, i) => (
                      <div key={i} className="attach-file-row">
                        <span className="attach-file-name">{f.name}</span>
                        <button
                          type="button"
                          onClick={() => removeFile(key, i)}
                          style={{ border: 'none', background: 'none', color: 'var(--red)', cursor: 'pointer', padding: 2, display: 'flex', alignItems: 'center', flexShrink: 0 }}
                          title="Remove file"
                        >
                          <FiX size={14} />
                        </button>
                      </div>
                    ))}
                    <div style={{ fontSize: 11, color: 'var(--gray-500)' }}>
                      {attachData[key].files.length} / 7 file(s) selected
                    </div>
                  </div>
                )}

                <textarea
                  className="form-control attach-note"
                  rows={2}
                  placeholder="Write anything about this product to Basava Mart..."
                  value={attachData[key]?.note || ''}
                  onChange={e => setNote(key, e.target.value)}
                />

                <button
                  className="btn btn-primary btn-sm attach-submit-btn"
                  style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}
                  disabled={submittingKey === key}
                  onClick={() => submitAttachment(item)}
                >
                  {submittingKey === key ? <div className="spinner" /> : <><FiSend size={13} /> Submit</>}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

