/* ─── MemberProfile ─── */
export function MemberProfile() {
  const { member, refreshUser } = useAuth();
  const [form, setForm] = useState({ companyName: '', companyLogoText: '', companyDescription: '', gstNumber: '', address: '' });
  const [files, setFiles] = useState<any>({});
  const [saving, setSaving] = useState(false);

  useEffect(() => { injectMemberStyles(); }, []);

  useEffect(() => {
    if (member?.businessProfile) {
      const bp = member.businessProfile;
      setForm({ companyName: bp.companyName || '', companyLogoText: bp.companyLogoText || '', companyDescription: bp.companyDescription || '', gstNumber: bp.gstNumber || '', address: bp.address || '' });
    }
  }, [member]);

  const save = async () => {
    setSaving(true);
    try {
      const fd = new FormData();
      Object.entries(form).forEach(([k, v]) => fd.append(k, v));
      if (files.companyLogo) fd.append('companyLogo', files.companyLogo);
      if (files.gstCertificate) fd.append('gstCertificate', files.gstCertificate);
      if (files.aadhaarCard) fd.append('aadhaarCard', files.aadhaarCard);
      await api.put('/members/profile', fd);
      toast.success('Profile updated!');
      refreshUser();
    } catch { toast.error('Error saving'); }
    setSaving(false);
  };

  const profileFields: [keyof typeof form, string, React.ReactNode][] = [
    ['companyName', 'Company Name', <BsBuilding size={14} />],
    ['companyLogoText', 'Company Logo Text', <FiTag size={14} />],
    ['gstNumber', 'GST Number', <HiOutlineReceiptTax size={14} />],
    ['address', 'Business Address', <FiMapPin size={14} />],
  ];

  const docFields: [string, string, React.ReactNode][] = [
    ['companyLogo', 'Company Logo', <BsBuilding size={14} />],
    ['gstCertificate', 'GST Certificate', <HiOutlineReceiptTax size={14} />],
    ['aadhaarCard', 'Aadhaar Card', <FiUser size={14} />],
  ];

  return (
    <div className="member-page fade-in" style={{ maxWidth: 720 }}>
      <div className="page-header">
        <h1 className="page-title"><FiUser size={22} color="var(--primary)" /> Member Profile</h1>
      </div>

      {/* Basic Info */}
      <div className="card" style={{ padding: 'clamp(16px,3vw,24px)', marginBottom: 16 }}>
        <div className="profile-header">
          <div style={{ width: 60, height: 60, borderRadius: '50%', background: 'var(--primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 800, fontSize: 22, flexShrink: 0 }}>
            {member?.name?.charAt(0)}
          </div>
          <div style={{ minWidth: 0 }}>
            <div style={{ fontSize: 'clamp(16px,4vw,20px)', fontWeight: 700 }}>{member?.name}</div>
            <div style={{ color: 'var(--primary)', fontWeight: 600, fontSize: 'clamp(12px,3vw,14px)' }}>{member?.memberId}</div>
            <div style={{ color: 'var(--gray-500)', fontSize: 13, display: 'flex', alignItems: 'center', gap: 4, marginTop: 2 }}>
              <FiMail size={12} /> {member?.email}
            </div>
          </div>
        </div>
      </div>

      {/* Business Profile */}
      <div className="card" style={{ padding: 'clamp(16px,3vw,24px)', marginBottom: 16 }}>
        <h3 style={{ fontSize: 15, fontWeight: 700, marginBottom: 16, display: 'flex', alignItems: 'center', gap: 7 }}>
          <BsBuilding size={16} color="var(--primary)" /> Business Profile
        </h3>
        <div className="grid-2">
          {profileFields.map(([k, l, icon]) => (
            <div key={k} className="form-group">
              <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 5 }}>{icon} {l}</label>
              <input className="form-control" value={form[k]} onChange={e => setForm(p => ({ ...p, [k]: e.target.value }))} style={{ fontSize: 'clamp(12px,3.5vw,14px)' }} />
            </div>
          ))}
          <div className="form-group" style={{ gridColumn: '1/-1' }}>
            <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 5 }}><FiFileText size={14} /> Company Description</label>
            <textarea className="form-control" value={form.companyDescription} onChange={e => setForm(p => ({ ...p, companyDescription: e.target.value }))} rows={3} style={{ fontSize: 'clamp(12px,3.5vw,14px)', resize: 'vertical' }} />
          </div>
        </div>

        <div className="grid-3">
          {docFields.map(([k, l, icon]) => (
            <div key={k} className="form-group">
              <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 5 }}>{icon} {l}</label>
              <input type="file" accept="image/*,application/pdf" onChange={e => setFiles((p: any) => ({ ...p, [k]: e.target.files?.[0] }))} style={{ fontSize: 12 }} />
              {member?.businessProfile?.[k] && <div style={{ fontSize: 11, color: 'var(--green)', marginTop: 4, display: 'flex', alignItems: 'center', gap: 3 }}><FiCheckCircle size={11} /> Uploaded</div>}
            </div>
          ))}
        </div>

        <button className="btn btn-primary" style={{ marginTop: 12, display: 'flex', alignItems: 'center', gap: 6 }} onClick={save} disabled={saving}>
          {saving ? <div className="spinner" /> : <><FiSave size={15} /> Save Profile</>}
        </button>
      </div>

      {/* Report / Query */}
      <div className="card" style={{ padding: 'clamp(16px,3vw,24px)' }}>
        <h3 style={{ fontSize: 15, fontWeight: 700, marginBottom: 12, display: 'flex', alignItems: 'center', gap: 7 }}>
          <FiSend size={15} color="var(--primary)" /> Submit Query
        </h3>
        <ReportForm memberId={member?._id} memberName={member?.name} memberEmail={member?.email} />
      </div>
    </div>
  );
}

function ReportForm({ memberId, memberName, memberEmail }: any) {
  const [form, setForm] = useState({ type: 'query', subject: '', message: '' });
  const [saving, setSaving] = useState(false);

  const submit = async () => {
    setSaving(true);
    try {
      await api.post('/reports', { ...form, memberId, name: memberName, email: memberEmail, panelType: 'member' });
      toast.success('Submitted!'); setForm({ type: 'query', subject: '', message: '' });
    } catch { toast.error('Error'); }
    setSaving(false);
  };

  return (
    <div>
      <div className="form-group">
        <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 5 }}><FiFileText size={13} /> Type</label>
        <select className="form-control" value={form.type} onChange={e => setForm(p => ({ ...p, type: e.target.value }))}>
          <option value="query">Query</option>
          <option value="report">Report</option>
          <option value="spam">Spam</option>
        </select>
      </div>
      <div className="form-group">
        <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 5 }}><FiFileText size={13} /> Subject</label>
        <input className="form-control" value={form.subject} onChange={e => setForm(p => ({ ...p, subject: e.target.value }))} />
      </div>
      <div className="form-group">
        <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 5 }}><FiMail size={13} /> Message</label>
        <textarea className="form-control" value={form.message} onChange={e => setForm(p => ({ ...p, message: e.target.value }))} rows={3} style={{ resize: 'vertical' }} />
      </div>
      <button className="btn btn-primary btn-sm" style={{ display: 'flex', alignItems: 'center', gap: 6 }} onClick={submit} disabled={saving}>
        {saving ? <div className="spinner" /> : <><FiSend size={13} /> Submit</>}
      </button>
    </div>
  );
}

/* ─── MemberSites ─── */
export function MemberSites() {
  const [sites, setSites] = useState<any[]>([]);
  const [showCreate, setShowCreate] = useState(false);
  const [editingSite, setEditingSite] = useState<any>(null);
  const [deletingSiteId, setDeletingSiteId] = useState('');
  const [form, setForm] = useState({ siteName: '', siteLocation: '', timeline: '', estimatedBudget: 0, notes: '' });
  const [saving, setSaving] = useState(false);

  useEffect(() => { injectMemberStyles(); api.get('/sites/my').then(r => setSites(r.data.sites)); }, []);

  const saveSite = async () => {
    if (!form.siteName.trim()) { toast.error('Site name is required'); return; }
    setSaving(true);
    try {
      if (editingSite) {
        await api.put(`/sites/${editingSite._id}`, form);
        toast.success('Site updated');
      } else {
        await api.post('/sites', { ...form, selectedProducts: [] });
        toast.success('Site created!');
      }
      setShowCreate(false);
      setEditingSite(null);
      const response = await api.get('/sites/my');
      setSites(response.data.sites || []);
      setForm({ siteName: '', siteLocation: '', timeline: '', estimatedBudget: 0, notes: '' });
    } catch (error: any) { toast.error(error.response?.data?.message || 'Could not save site'); }
    setSaving(false);
  };

  const editSite = (site: any) => {
    setEditingSite(site);
    setForm({ siteName: site.siteName || '', siteLocation: site.siteLocation || '', timeline: site.timeline || '', estimatedBudget: Number(site.estimatedBudget) || 0, notes: site.notes || '' });
    setShowCreate(true);
  };

  const deleteSite = async (site: any) => {
    if (!window.confirm(`Delete ${site.siteName}? Products assigned to this site will return to the unassigned basket.`)) return;
    setDeletingSiteId(site._id);
    try {
      await api.delete(`/sites/${site._id}`);
      setSites(current => current.filter(currentSite => currentSite._id !== site._id));
      toast.success('Site deleted');
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Could not delete site');
    } finally { setDeletingSiteId(''); }
  };

  const statusColors: any = { completed: 'badge-success', cancelled: 'badge-danger', submitted: 'badge-warning', approved: 'badge-info', in_progress: 'badge-info' };

  const siteFormFields: [keyof typeof form, string, string, React.ReactNode][] = [
    ['siteName', 'Site Name *', 'text', <BsBuilding size={14} />],
    ['siteLocation', 'Location', 'text', <FiMapPin size={14} />],
    ['timeline', 'Timeline (e.g. 3 months)', 'text', <FiCalendar size={14} />],
  ];

  return (
    <div className="member-page fade-in">
      <div className="page-header">
        <h1 className="page-title"><MdConstruction size={24} color="var(--primary)" /> My Sites</h1>
        <button className="btn btn-primary" style={{ display: 'flex', alignItems: 'center', gap: 6 }} onClick={() => { setEditingSite(null); setForm({ siteName: '', siteLocation: '', timeline: '', estimatedBudget: 0, notes: '' }); setShowCreate(true); }}>
          <FiPlus size={16} /> Create Site
        </button>
      </div>

      <div className="sites-list">
        {sites.map(site => (
          <div key={site._id} className="card" style={{ padding: 'clamp(14px,3vw,20px)' }}>
            <div className="site-card-header">
              <div style={{ minWidth: 0 }}>
                <div style={{ fontWeight: 600, fontSize: 'clamp(14px,3.5vw,16px)' }}>{site.siteName}</div>
                <div style={{ fontSize: 13, color: 'var(--gray-600)', marginTop: 5, display: 'flex', flexWrap: 'wrap', gap: '4px 12px' }}>
                  <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}><FiMapPin size={12} /> {site.siteLocation}</span>
                  <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}><FiCalendar size={12} /> {site.timeline}</span>
                  <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}><FiDollarSign size={12} /> ₹{formatINR(site.estimatedBudget)}</span>
                </div>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
                <span className={`badge ${statusColors[site.status] || 'badge-gray'}`}>{site.status?.replace(/_/g, ' ')}</span>
                <button className="btn btn-outline btn-sm" style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }} onClick={() => editSite(site)}><FiEdit2 size={13} /> Edit</button>
                <button className="btn btn-outline btn-sm" style={{ display: 'inline-flex', alignItems: 'center', gap: 4, color: 'var(--red)' }} disabled={deletingSiteId === site._id} onClick={() => deleteSite(site)}>{deletingSiteId === site._id ? <div className="spinner" /> : <><FiTrash2 size={13} /> Delete</>}</button>
              </div>
            </div>

            {site.notes && <div style={{ marginTop: 8, fontSize: 13, color: 'var(--gray-600)', display: 'flex', gap: 5 }}><FiFileText size={13} style={{ flexShrink: 0, marginTop: 1 }} /> {site.notes}</div>}

            {site.statusUpdates?.length > 0 && (
              <div style={{ marginTop: 12 }}>
                <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--gray-500)', marginBottom: 6 }}>Latest Updates</div>
                {[...site.statusUpdates].reverse().slice(0, 2).map((u: any, i: number) => (
                  <div key={i} style={{ fontSize: 12, color: 'var(--gray-600)', padding: '4px 0', borderBottom: '1px solid var(--gray-100)' }}>
                    <strong>{u.status?.replace(/_/g, ' ')}</strong> — {u.note} <span style={{ color: 'var(--gray-400)' }}>({new Date(u.updatedAt).toLocaleDateString('en-IN')})</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
        {!sites.length && (
          <div style={{ textAlign: 'center', padding: 60, color: 'var(--gray-400)' }}>
            <MdConstruction size={48} />
            <div style={{ marginTop: 12 }}>No sites created yet</div>
          </div>
        )}
      </div>

      {/* Create / Edit Modal */}
      {showCreate && (
        <div className="modal-overlay" onClick={() => { setShowCreate(false); setEditingSite(null); }}>
          <div className="modal" onClick={e => e.stopPropagation()} style={{ width: 'min(520px, 95vw)', margin: '0 auto' }}>
            <div className="modal-header">
              <h2 style={{ display: 'flex', alignItems: 'center', gap: 8 }}><MdConstruction size={20} /> {editingSite ? 'Edit Site' : 'Create New Site'}</h2>
              <button className="modal-close" onClick={() => { setShowCreate(false); setEditingSite(null); }}><FiX size={18} /></button>
            </div>
            <div className="modal-body">
              {siteFormFields.map(([k, l, type, icon]) => (
                <div key={k} className="form-group">
                  <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 5 }}>{icon} {l}</label>
                  <input type={type} className="form-control" value={form[k] as string} onChange={e => setForm(p => ({ ...p, [k]: e.target.value }))} />
                </div>
              ))}
              <div className="form-group">
                <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 5 }}><FiDollarSign size={14} /> Estimated Budget (₹)</label>
                <input type="number" className="form-control" value={form.estimatedBudget} onChange={e => setForm(p => ({ ...p, estimatedBudget: +e.target.value }))} />
              </div>
              <div className="form-group">
                <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 5 }}><FiFileText size={14} /> Notes</label>
                <textarea className="form-control" value={form.notes} onChange={e => setForm(p => ({ ...p, notes: e.target.value }))} rows={3} style={{ resize: 'vertical' }} />
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-gray" onClick={() => { setShowCreate(false); setEditingSite(null); }}>Cancel</button>
              <button className="btn btn-primary" style={{ display: 'flex', alignItems: 'center', gap: 6 }} onClick={saveSite} disabled={saving}>
                {saving ? <div className="spinner" /> : editingSite ? <><FiSave size={15} /> Save Changes</> : <><FiPlus size={15} /> Create Site</>}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default MemberDashboard;