import React, { useCallback, useEffect, useState } from 'react';
import {
  Area,
  AreaChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import api from '../../utils/api';

interface VisitorAnalytics {
  uniqueVisitors: number;
  sessions: number;
  pageViews: number;
  totalTimeSeconds: number;
  averageSessionSeconds: number;
  pages: Array<{
    path: string;
    pageTitle: string;
    pageViews: number;
    uniqueVisitors: number;
    totalTimeSeconds: number;
    averageTimeSeconds: number;
  }>;
  devices: Array<{ name: string; pageViews: number; uniqueVisitors: number }>;
  browsers: Array<{ name: string; pageViews: number; uniqueVisitors: number }>;
  daily: Array<{ date: string; uniqueVisitors: number; pageViews: number }>;
  recentVisits: Array<{
    _id: string;
    visitorId: string;
    path: string;
    pageTitle: string;
    device: string;
    browser: string;
    startedAt: string;
    lastSeenAt: string;
    durationSeconds: number;
  }>;
}

const localDate = (date: Date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const formatDuration = (seconds: number) => {
  const safeSeconds = Math.max(0, Math.round(seconds || 0));
  const minutes = Math.floor(safeSeconds / 60);
  const remainingSeconds = safeSeconds % 60;
  if (minutes < 1) return `${remainingSeconds}s`;
  const hours = Math.floor(minutes / 60);
  if (hours < 1) return `${minutes}m ${remainingSeconds}s`;
  return `${hours}h ${minutes % 60}m`;
};

const formatNumber = (value: number) => new Intl.NumberFormat('en-IN').format(value || 0);
const formatDateTime = (value: string) => new Date(value).toLocaleString('en-IN');

export default function AdminVisitors() {
  const today = new Date();
  const monthAgo = new Date(today);
  monthAgo.setDate(monthAgo.getDate() - 29);
  const [dateFilter, setDateFilter] = useState({ startDate: localDate(monthAgo), endDate: localDate(today) });
  const [analytics, setAnalytics] = useState<VisitorAnalytics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const loadAnalytics = useCallback(async (range = dateFilter) => {
    if (range.startDate && range.endDate && range.startDate > range.endDate) {
      setError('Start date must be on or before end date.');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const response = await api.get('/visitors/admin', {
        params: {
          ...range,
          timezoneOffset: new Date().getTimezoneOffset(),
        },
      });
      setAnalytics(response.data.data as VisitorAnalytics);
    } catch (requestError: unknown) {
      console.error('Could not load visitor analytics:', requestError);
      setError('Visitor analytics could not be loaded. Please try again.');
    } finally {
      setLoading(false);
    }
  }, [dateFilter]);

  useEffect(() => {
    void loadAnalytics();
  }, [loadAnalytics]);

  const clearDateFilter = () => {
    const allDates = { startDate: '', endDate: '' };
    setDateFilter(allDates);
    void loadAnalytics(allDates);
  };

  const cards = analytics ? [
    { label: 'Unique visitors', value: formatNumber(analytics.uniqueVisitors), detail: 'Distinct browsers in the selected dates', color: '#2563eb' },
    { label: 'Sessions', value: formatNumber(analytics.sessions), detail: 'Distinct browser sessions', color: '#7c3aed' },
    { label: 'Page views', value: formatNumber(analytics.pageViews), detail: 'Recorded page visits', color: '#0891b2' },
    { label: 'Total engaged time', value: formatDuration(analytics.totalTimeSeconds), detail: 'Time measured while pages were active', color: '#059669' },
    { label: 'Average session time', value: formatDuration(analytics.averageSessionSeconds), detail: 'Average across recorded sessions', color: '#d97706' },
  ] : [];

  return (
    <div className="fade-in" style={{ display: 'grid', gap: 20 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 16, flexWrap: 'wrap' }}>
        <div>
          <h1 style={{ fontSize: 24, fontWeight: 700, color: 'var(--gray-900)', margin: 0 }}>Visitors</h1>
          <p style={{ color: 'var(--gray-500)', fontSize: 14, marginTop: 6 }}>
            Anonymous first-party browser analytics. Unique visitors represent browser IDs, not verified people.
          </p>
        </div>
        <form
          onSubmit={(event) => { event.preventDefault(); void loadAnalytics(); }}
          style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8 }}
        >
          <label style={{ display: 'grid', gap: 4, fontSize: 12, color: 'var(--gray-600)' }}>
            From
            <input
              type="date"
              className="form-control"
              value={dateFilter.startDate}
              max={dateFilter.endDate || undefined}
              onChange={(event) => setDateFilter((current) => ({ ...current, startDate: event.target.value }))}
            />
          </label>
          <label style={{ display: 'grid', gap: 4, fontSize: 12, color: 'var(--gray-600)' }}>
            To
            <input
              type="date"
              className="form-control"
              value={dateFilter.endDate}
              min={dateFilter.startDate || undefined}
              max={localDate(today)}
              onChange={(event) => setDateFilter((current) => ({ ...current, endDate: event.target.value }))}
            />
          </label>
          <button type="submit" className="btn btn-primary btn-sm" style={{ alignSelf: 'end' }}>Apply</button>
          <button type="button" className="btn btn-gray btn-sm" style={{ alignSelf: 'end' }} onClick={() => void loadAnalytics()}>Refresh</button>
          <button type="button" className="btn btn-gray btn-sm" style={{ alignSelf: 'end' }} onClick={clearDateFilter}>All time</button>
        </form>
      </div>

      {error && <div role="alert" className="card" style={{ padding: 14, color: '#b91c1c' }}>{error}</div>}

      {loading ? (
        <div style={{ display: 'flex', justifyContent: 'center', padding: 72 }}>
          <div className="spinner" style={{ width: 40, height: 40, borderWidth: 3 }} />
        </div>
      ) : analytics && (
        <>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(190px, 1fr))', gap: 14 }}>
            {cards.map((card) => (
              <div key={card.label} className="card" style={{ padding: 18, borderTop: `3px solid ${card.color}` }}>
                <div style={{ color: 'var(--gray-500)', fontSize: 13 }}>{card.label}</div>
                <div style={{ color: card.color, fontSize: 26, fontWeight: 800, marginTop: 8 }}>{card.value}</div>
                <div style={{ color: 'var(--gray-500)', fontSize: 11, marginTop: 6 }}>{card.detail}</div>
              </div>
            ))}
          </div>

          <section className="card">
            <div className="card-header"><h2 style={{ fontSize: 16, fontWeight: 700, margin: 0 }}>Daily visitors and page views</h2></div>
            <div className="card-body">
              {analytics.daily.length ? (
                <ResponsiveContainer width="100%" height={280}>
                  <AreaChart data={analytics.daily}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="date" tick={{ fontSize: 11 }} />
                    <YAxis allowDecimals={false} tick={{ fontSize: 11 }} />
                    <Tooltip />
                    <Area type="monotone" dataKey="uniqueVisitors" name="Unique visitors" stroke="#2563eb" fill="#dbeafe" />
                    <Area type="monotone" dataKey="pageViews" name="Page views" stroke="#0891b2" fill="#cffafe" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : <p style={{ color: 'var(--gray-500)' }}>No visits recorded for these dates yet.</p>}
            </div>
          </section>

          <div className="grid-2">
            <section className="card">
              <div className="card-header"><h2 style={{ fontSize: 16, fontWeight: 700, margin: 0 }}>Pages with most time spent</h2></div>
              <div className="table-wrapper">
                <table>
                  <thead><tr><th>Page</th><th>Views</th><th>Visitors</th><th>Avg. time</th><th>Total time</th></tr></thead>
                  <tbody>
                    {analytics.pages.map((page) => (
                      <tr key={page.path}>
                        <td><strong>{page.pageTitle || page.path}</strong><br /><small>{page.path}</small></td>
                        <td>{formatNumber(page.pageViews)}</td>
                        <td>{formatNumber(page.uniqueVisitors)}</td>
                        <td>{formatDuration(page.averageTimeSeconds)}</td>
                        <td>{formatDuration(page.totalTimeSeconds)}</td>
                      </tr>
                    ))}
                    {!analytics.pages.length && <tr><td colSpan={5}>No page visits recorded.</td></tr>}
                  </tbody>
                </table>
              </div>
            </section>

            <section className="card">
              <div className="card-header"><h2 style={{ fontSize: 16, fontWeight: 700, margin: 0 }}>Devices and browsers</h2></div>
              <div className="card-body" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: 24 }}>
                {[['Devices', analytics.devices], ['Browsers', analytics.browsers]].map(([heading, rows]) => (
                  <div key={heading as string}>
                    <h3 style={{ fontSize: 14, margin: '0 0 12px' }}>{heading as string}</h3>
                    {(rows as VisitorAnalytics['devices']).map((row) => (
                      <div key={row.name} style={{ display: 'flex', justifyContent: 'space-between', gap: 12, padding: '8px 0', borderBottom: '1px solid #eee' }}>
                        <span>{row.name}</span>
                        <span style={{ color: 'var(--gray-500)', whiteSpace: 'nowrap' }}>{formatNumber(row.uniqueVisitors)} visitors</span>
                      </div>
                    ))}
                    {!(rows as VisitorAnalytics['devices']).length && <p style={{ color: 'var(--gray-500)' }}>No data</p>}
                  </div>
                ))}
              </div>
            </section>
          </div>

          <section className="card">
            <div className="card-header"><h2 style={{ fontSize: 16, fontWeight: 700, margin: 0 }}>Recent page visits</h2></div>
            <div className="table-wrapper">
              <table>
                <thead><tr><th>Visited at</th><th>Visitor</th><th>Page</th><th>Device</th><th>Browser</th><th>Time spent</th></tr></thead>
                <tbody>
                  {analytics.recentVisits.map((visit) => (
                    <tr key={visit._id}>
                      <td>{formatDateTime(visit.startedAt)}</td>
                      <td><code>{visit.visitorId}</code></td>
                      <td><strong>{visit.pageTitle || visit.path}</strong><br /><small>{visit.path}</small></td>
                      <td>{visit.device}</td>
                      <td>{visit.browser}</td>
                      <td>{formatDuration(visit.durationSeconds)}</td>
                    </tr>
                  ))}
                  {!analytics.recentVisits.length && <tr><td colSpan={6}>No page visits recorded.</td></tr>}
                </tbody>
              </table>
            </div>
          </section>
        </>
      )}
    </div>
  );
}
