
import React, { useEffect, useState } from 'react';
import './MiniBrandFlip.css';

interface MiniBrandFlipProps {
  small?: boolean;
}

export const MiniBrandFlip = ({ small = false }: MiniBrandFlipProps) => {
  const [activeIndex, setActiveIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  const totalSlides = 3;

  useEffect(() => {
    if (isPaused) return;

    const interval = setInterval(() => {
      setActiveIndex((prev) => (prev + 1) % totalSlides);
    }, 5000);

    return () => clearInterval(interval);
  }, [isPaused]);

  const togglePause = () => {
    setIsPaused((prev) => !prev);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      togglePause();
    }
  };

  return (
    <div
      className={`mini-panel ${small ? 'is-small' : 'is-large'}`}
      onClick={togglePause}
      onKeyDown={handleKeyDown}
      role="button"
      tabIndex={0}
      aria-label={
        isPaused
          ? 'Resume brand preview'
          : 'Pause brand preview'
      }
    >

      {/* =========================================
          BACKGROUND VIDEO
      ========================================= */}
      <video
        className="mini-panel-background"
        autoPlay
        muted
        loop
        playsInline
        preload="auto"
      >
        <source
          src="/assets/images/wavevideo.webm"
          type="video/webm"
        />
      </video>

      {/* Background overlay */}
      <div className="mini-panel-background-overlay" />

      {/* =========================================
          MAIN DISPLAY
      ========================================= */}
      <div className="mini-panel-bezel">

        <div className="mini-panel-screen">

          {/* CARD 1 - LOGO */}
          <div
            className={`mini-panel-face logo-face ${
              activeIndex === 0 ? 'is-active' : ''
            }`}
          >
            <img
              src="/assets/images/Basavamart-mini.webp"
              alt="Basava Mart"
            />
          </div>

          {/* CARD 2 - VIDEO 1 */}
          <div
            className={`mini-panel-face video-face ${
              activeIndex === 1 ? 'is-active' : ''
            }`}
          >
            <video
              autoPlay
              muted
              loop
              playsInline
              preload="metadata"
            >
              <source
                src="/assets/images/bmvideo.webm"
                type="video/webm"
              />
            </video>
          </div>

          {/* CARD 3 - VIDEO 2 */}
          <div
            className={`mini-panel-face video-face ${
              activeIndex === 2 ? 'is-active' : ''
            }`}
          >
            <video
              autoPlay
              muted
              loop
              playsInline
              preload="metadata"
            >
              <source
                src="/assets/images/bmvideo2.webm"
                type="video/webm"
              />
            </video>
          </div>

        </div>

        {/* META */}
        <div className="mini-panel-meta">
          <span
            className={`mini-panel-status ${
              isPaused ? 'is-paused' : ''
            }`}
          />

          <span className="mini-panel-label">
            {isPaused ? 'Paused' : `Live preview ${activeIndex + 1}/3`}
          </span>
        </div>

        {/* DOTS */}
        <div className="mini-panel-dots">
          {[0, 1, 2].map((index) => (
            <span
              key={index}
              className={`mini-dot ${
                activeIndex === index ? 'active' : ''
              }`}
            />
          ))}
        </div>

      </div>

      <span className="mini-panel-hint">
        Tap to {isPaused ? 'resume' : 'pause'}
      </span>

    </div>
  );
};

export default MiniBrandFlip;
