import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import api from '../utils/api';

interface AuthUser { _id: string; name: string; email: string; avatar?: string; membershipStatus?: string; }
interface AuthMember { _id: string; memberId: string; name: string; email: string; businessProfile?: any; }

interface AuthContextType {
  user: AuthUser | null;
  member: AuthMember | null;
  isAdmin: boolean;
  role: string | null;
  loading: boolean;
  loginAdmin: (token: string) => void;
  loginMember: (token: string, memberData: AuthMember) => void;
  loginUser: (token: string) => void;
  logout: () => void;
  refreshUser: () => void;
}

const AuthContext = createContext<AuthContextType>({} as AuthContextType);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [member, setMember] = useState<AuthMember | null>(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [role, setRole] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const savedRole = localStorage.getItem('role');
    const token = localStorage.getItem('token');
    if (!token || !savedRole) { setLoading(false); return; }

    setRole(savedRole);
    if (savedRole === 'admin') { setIsAdmin(true); setLoading(false); return; }

    if (savedRole === 'user') {
      api.get('/auth/me/user').then(res => { setUser(res.data.user); }).catch(() => logout()).finally(() => setLoading(false));
    } else if (savedRole === 'member') {
      api.get('/auth/me/member').then(res => { setMember(res.data.member); }).catch(() => logout()).finally(() => setLoading(false));
    } else { setLoading(false); }
  }, []);

  const loginAdmin = (token: string) => {
    localStorage.setItem('token', token);
    localStorage.setItem('role', 'admin');
    setIsAdmin(true);
    setRole('admin');
  };

  const loginUser = async (token: string) => {
    localStorage.setItem('token', token);
    localStorage.setItem('role', 'user');
    setRole('user');
    const res = await api.get('/auth/me/user');
    setUser(res.data.user);
  };

  const loginMember = (token: string, memberData: AuthMember) => {
    localStorage.setItem('token', token);
    localStorage.setItem('role', 'member');
    setRole('member');
    setMember(memberData);
  };

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('role');
    setUser(null);
    setMember(null);
    setIsAdmin(false);
    setRole(null);
  };

  const refreshUser = async () => {
    if (role === 'user') {
      const res = await api.get('/auth/me/user');
      setUser(res.data.user);
    } else if (role === 'member') {
      const res = await api.get('/auth/me/member');
      setMember(res.data.member);
    }
  };

  return (
    <AuthContext.Provider value={{ user, member, isAdmin, role, loading, loginAdmin, loginUser, loginMember, logout, refreshUser }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
