import React from 'react';
import { FiLoader } from 'react-icons/fi';
import { cn } from '../../lib/cn';

type ButtonVariant = 'primary' | 'secondary' | 'dark' | 'ghost';
type ButtonSize = 'sm' | 'md' | 'lg';

type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
};

const buttonVariants: Record<ButtonVariant, string> = {
  primary: 'bm-btn-primary',
  secondary: 'bm-btn-secondary',
  dark: 'bm-btn-dark',
  ghost: 'bm-btn-ghost',
};

const buttonSizes: Record<ButtonSize, string> = {
  sm: 'bm-btn-sm',
  md: '',
  lg: 'bm-btn-lg',
};

export function Button({
  variant = 'primary',
  size = 'md',
  loading = false,
  disabled,
  type = 'button',
  className,
  children,
  ...props
}: ButtonProps) {
  return (
    <button
      {...props}
      type={type}
      className={cn('bm-btn border-0', buttonVariants[variant], buttonSizes[size], className)}
      disabled={disabled || loading}
      aria-busy={loading ? true : props['aria-busy']}
    >
      {loading && <FiLoader className="h-4 w-4 animate-spin" aria-hidden="true" />}
      {children}
    </button>
  );
}

type BadgeProps = React.HTMLAttributes<HTMLSpanElement> & {
  variant?: 'default' | 'sale' | 'new' | 'success' | 'warning' | 'info';
};

export function Badge({ variant = 'default', className, ...props }: BadgeProps) {
  const styles: Record<NonNullable<BadgeProps['variant']>, string> = {
    default: 'bg-ink-100 text-ink-700',
    sale: 'bm-badge-sale',
    new: 'bm-badge-new',
    success: 'bg-green-50 text-success',
    warning: 'bg-amber-50 text-warning',
    info: 'bg-sky-50 text-info',
  };

  return <span className={cn('bm-badge', styles[variant], className)} {...props} />;
}

type SectionHeadingProps = React.HTMLAttributes<HTMLDivElement> & {
  eyebrow?: React.ReactNode;
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  align?: 'left' | 'center';
};

export function SectionHeading({
  eyebrow,
  title,
  subtitle,
  align = 'left',
  className,
  ...props
}: SectionHeadingProps) {
  return (
    <div className={cn('mb-6', align === 'center' && 'text-center', className)} {...props}>
      {eyebrow && <p className="mb-2 text-xs font-bold uppercase text-primary-600">{eyebrow}</p>}
      <h2 className="bm-section-title">{title}</h2>
      {subtitle && <p className="mt-2 max-w-2xl text-sm leading-6 text-ink-600">{subtitle}</p>}
    </div>
  );
}

export function Skeleton({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div aria-hidden="true" className={cn('bm-skeleton h-4 w-full', className)} {...props} />;
}

export function Container({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8', className)} {...props} />;
}

type IconButtonProps = Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'aria-label'> & {
  'aria-label': string;
};

export function IconButton({ className, type = 'button', ...props }: IconButtonProps) {
  return (
    <button
      {...props}
      type={type}
      className={cn('bm-btn bm-btn-ghost min-w-[44px] border-0 px-2', className)}
    />
  );
}
