import React, { useEffect, useState } from 'react';
import './MediaSlider.css';

const mediaItems = [
  {
    type: 'video',
    src: '/assets/videos/bsvideo.webm'
  },
  {
    type: 'video',
    src: '/assets/videos/bsvideo2.webm'
  },
  {
    type: 'video',
    src: '/assets/videos/bsvideo4.webm'
  },
  {
    type: 'image',
    src: '/assets/images/bgimg1.webp'
  },
  {
    type: 'image',
    src: '/assets/images/bgimg2.webp'
  },
  {
    type: 'video',
    src: '/assets/videos/bmadsvideo.webm'
  },
  {
    type: 'image',
    src: '/assets/images/bgimg3.webp'
  },
  {
    type: 'image',
    src: '/assets/images/bgimg4.webp'
  },
    {
    type: 'video',
    src: '/assets/videos/bsvideo3.webm'
  },
  {
    type: 'image',
    src: '/assets/images/bgimg6.webp'
  },
  {
    type: 'video',
    src: '/assets/videos/basavamart2.webm'
  }
];

export default function MediaSlider() {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    const currentItem = mediaItems[current];

    if (currentItem.type === 'image') {
      const timer = setTimeout(() => {
        setCurrent((prev) => (prev + 1) % mediaItems.length);
      }, 5000);

      return () => clearTimeout(timer);
    }
  }, [current]);

  const nextSlide = () => {
    setCurrent((prev) => (prev + 1) % mediaItems.length);
  };

  return (
    <div className="media-slider">
      {mediaItems.map((item, index) => (
        <div
          key={index}
          className={`slide ${index === current ? 'active' : ''}`}
        >
          {item.type === 'image' ? (
            <img
              src={item.src}
              alt={`slide-${index}`}
            />
          ) : (
            <video
              key={`${item.src}-${current}`}
              src={item.src}
              autoPlay
              muted
              playsInline
              preload="auto"
              onEnded={nextSlide}
            />
          )}
        </div>
      ))}

      <div className="dots">
        {mediaItems.map((_, index) => (
          <span
            key={index}
            className={current === index ? 'dot active' : 'dot'}
            onClick={() => setCurrent(index)}
          />
        ))}
      </div>
    </div>
  );
}