import React, { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { FiArrowLeft, FiChevronLeft, FiChevronRight, FiPackage, FiSearch } from 'react-icons/fi';
import toast from 'react-hot-toast';
import api, { formatINR, getImageUrl } from '../../utils/api';
import { ProductCard, ProductCardSkeleton } from '../../components/shared/ProductCard';
import SEO from '../../components/shared/SEO';
import { useCart } from '../../context/CartContext';
import { useAuth } from '../../context/AuthContext';

const PAGE_SIZE = 20;

export default function BrandCategoryPage() {
  const { categoryId } = useParams<{ categoryId: string }>();
  const navigate = useNavigate();
  const { addItem } = useCart();
  const { user } = useAuth();
  const [category, setCategory] = useState<any>(null);
  const [categoryLoading, setCategoryLoading] = useState(true);
  const [categoryError, setCategoryError] = useState(false);
  const [brandFilter, setBrandFilter] = useState('');
  const [brandSearch, setBrandSearch] = useState('');
  const [productSearch, setProductSearch] = useState('');
  const [submittedSearch, setSubmittedSearch] = useState('');
  const [products, setProducts] = useState<any[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [productsLoading, setProductsLoading] = useState(true);

  useEffect(() => {
    let active = true;
    setBrandFilter('');
    setBrandSearch('');
    setProductSearch('');
    setSubmittedSearch('');
    setPage(1);
    setCategoryLoading(true);
    setCategoryError(false);
    api.get('/brand-categories', { params: { accessLevel: 'user' } })
      .then(response => {
        if (active) {
          const found = (response.data.brandCategories || []).find((item: any) => item._id === categoryId);
          setCategory(found || null);
          setCategoryError(!found);
        }
      })
      .catch(error => {
        console.error('Unable to load brand category', error);
        if (active) {
          setCategory(null);
          setCategoryError(true);
        }
      })
      .finally(() => { if (active) setCategoryLoading(false); });
    return () => { active = false; };
  }, [categoryId]);

  useEffect(() => {
    if (!category) {
      setProducts([]);
      setTotal(0);
      setPages(1);
      setProductsLoading(false);
      return;
    }

    let active = true;
    setProductsLoading(true);
    const brandIds = (category.brands || []).map((brand: any) => brand._id);
    const params: Record<string, string | number> = {
      page,
      limit: PAGE_SIZE,
      accessLevel: 'user',
      brand: brandFilter || brandIds.join(','),
    };
    if (submittedSearch) params.search = submittedSearch;

    api.get('/products', { params })
      .then(response => {
        if (!active) return;
        setProducts(response.data.products || []);
        setTotal(response.data.total || 0);
        setPages(Math.max(1, response.data.pages || 1));
      })
      .catch(error => {
        console.error('Unable to load brand-category products', error);
        if (active) {
          setProducts([]);
          setTotal(0);
          toast.error('Unable to load products. Please try again.');
        }
      })
      .finally(() => { if (active) setProductsLoading(false); });

    return () => { active = false; };
  }, [category, brandFilter, submittedSearch, page]);

  const visibleBrands = useMemo(() => {
    const search = brandSearch.trim().toLowerCase();
    return (category?.brands || []).filter((brand: any) => brand.name.toLowerCase().includes(search));
  }, [category, brandSearch]);

  const submitSearch = (event: React.FormEvent) => {
    event.preventDefault();
    setPage(1);
    setSubmittedSearch(productSearch.trim());
  };

  const addProductToCart = (product: any) => {
    const variant = product.variants?.[0];
    if (!variant) {
      toast.error('This product has no available option to add to cart.');
      return;
    }
    if (!user) {
      toast.error('Please login to add to cart');
      navigate('/login');
      return;
    }
    addItem({
      productId: product._id,
      variantId: variant._id,
      productName: product.name,
      productImage: product.images?.[0] || '',
      brandName: product.brand?.name || '',
      variantName: variant.name,
      unit: variant.unit,
      listPrice: variant.listPrice,
      discountPercent: variant.discountPercent,
      discountAmount: variant.discountAmount,
      gstPercent: variant.gstPercent,
      gstType: variant.gstType,
      gstAmount: variant.gstAmount,
      finalPrice: variant.finalPrice,
      primaryThreshold: variant.primaryThreshold || 0,
      secondaryThreshold: variant.secondaryThreshold || 0,
      tertiaryThreshold: variant.tertiaryThreshold || 0,
    });
    toast.success('Added to cart!');
  };

  const seoTitle = category
    ? `${category.name} – Fire Safety Products | Basava Mart`
    : 'Category not found | Basava Mart';
  const seoDescription = category?.description?.trim()
    ? `${category.description.trim().replace(/\s+/g, ' ').slice(0, 155)}`
    : category
      ? `Explore ${category.name} fire safety products from Basava Mart in Bengaluru and across India.`
      : 'This category could not be found.';

  return (
    <>
      <SEO title={seoTitle} description={seoDescription} canonical={category ? `/brand-categories/${categoryId}` : '/products'} noindex={!category} />
      <main className="min-h-[70vh] space-y-6 px-4 pb-10 pt-5 sm:space-y-8 sm:px-6 lg:mx-auto lg:max-w-7xl">
      <Link to="/" className="inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-primary-700 hover:text-primary-800">
        <FiArrowLeft aria-hidden="true" /> Back to home
      </Link>

      {categoryLoading ? (
        <div className="space-y-5" aria-live="polite">
          <div className="bm-skeleton h-20 rounded-2xl" />
          <div className="bm-skeleton h-28 rounded-2xl" />
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
            {[1, 2, 3, 4].map(index => <ProductCardSkeleton key={index} />)}
          </div>
        </div>
      ) : categoryError ? (
        <section className="rounded-2xl border border-ink-100 bg-white px-5 py-16 text-center shadow-card">
          <FiPackage className="mx-auto h-12 w-12 text-ink-400" aria-hidden="true" />
          <h1 className="mt-4 font-display text-xl font-bold text-ink-900">Category not found</h1>
          <p className="mt-2 text-sm text-ink-600">This category may have been removed or is not currently available.</p>
        </section>
      ) : (
        <>
          <header className="flex items-center gap-4 rounded-2xl border border-ink-100 bg-white p-4 shadow-card sm:p-6">
            <span className="flex h-16 w-16 shrink-0 items-center justify-center rounded-2xl bg-ink-50 p-2 sm:h-20 sm:w-20">
              <img src={getImageUrl(category.icon)} alt="" className="h-full w-full object-contain" />
            </span>
            <div className="min-w-0 flex-1">
              <h1 className="font-display text-xl font-bold text-ink-900 sm:text-2xl">{category.name}</h1>
              <p className="mt-1 text-sm text-ink-600">{category.brands.length} brands · {total} products</p>
            </div>
          </header>

          {category.description?.trim() && (
            <section aria-labelledby="brand-category-description-title" className="rounded-2xl border border-primary-100 bg-primary-50/60 px-4 py-4 shadow-sm sm:px-6">
              <h2 id="brand-category-description-title" className="font-display text-base font-bold text-ink-900 sm:text-lg">What’s inside {category.name}</h2>
              <p className="mt-2 whitespace-pre-line break-words text-sm leading-6 text-ink-700 sm:text-base">{category.description.trim()}</p>
            </section>
          )}

          <section aria-labelledby="brand-category-brands-title" className="rounded-2xl border border-ink-100 bg-white p-4 shadow-card sm:p-5">
            <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
              <h2 id="brand-category-brands-title" className="font-display text-lg font-bold text-ink-900">Brands in {category.name}</h2>
              {category.brands.length > 5 && (
                <label className="flex min-h-10 w-full items-center gap-2 rounded-xl border border-ink-200 px-3 sm:w-64">
                  <FiSearch className="h-4 w-4 shrink-0 text-ink-400" aria-hidden="true" />
                  <input className="min-w-0 flex-1 border-0 bg-transparent text-sm outline-none focus:ring-0" value={brandSearch} onChange={event => setBrandSearch(event.target.value)} placeholder="Find a brand" aria-label="Find a brand" />
                </label>
              )}
            </div>
            <div className="grid grid-cols-3 gap-2 sm:grid-cols-4 sm:gap-3 md:grid-cols-6 lg:grid-cols-8">
              <button
                type="button"
                onClick={() => { setBrandFilter(''); setPage(1); }}
                aria-pressed={!brandFilter}
                className={`flex min-h-20 min-w-0 flex-col items-center justify-center gap-1 rounded-xl border p-2 text-center transition sm:min-h-24 ${!brandFilter ? 'border-primary-400 bg-primary-50 text-primary-800' : 'border-ink-100 bg-white text-ink-700 hover:border-primary-300'}`}
              >
                <FiPackage className="h-7 w-7" aria-hidden="true" />
                <span className="line-clamp-1 w-full text-xs font-bold">All brands</span>
              </button>
              {visibleBrands.map((brand: any) => (
                <button
                  type="button"
                  key={brand._id}
                  title={brand.name}
                  onClick={() => { setBrandFilter(current => current === brand._id ? '' : brand._id); setPage(1); }}
                  aria-pressed={brandFilter === brand._id}
                  className={`flex min-h-20 min-w-0 flex-col items-center justify-center gap-1 rounded-xl border p-2 text-center transition sm:min-h-24 ${brandFilter === brand._id ? 'border-primary-400 bg-primary-50 text-primary-800' : 'border-ink-100 bg-white text-ink-700 hover:border-primary-300'}`}
                >
                  <span className="flex h-9 w-9 items-center justify-center sm:h-11 sm:w-11">
                    <img src={getImageUrl(brand.logo)} alt="" loading="lazy" className="h-full w-full object-contain" />
                  </span>
                  <span className="line-clamp-2 w-full text-[11px] font-semibold leading-4 sm:text-xs">{brand.name}</span>
                </button>
              ))}
              {!visibleBrands.length && <p className="col-span-full py-5 text-center text-sm text-ink-500">No matching brands.</p>}
            </div>
          </section>

          <section aria-labelledby="brand-category-products-title">
            <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
              <div>
                <h2 id="brand-category-products-title" className="font-display text-xl font-bold text-ink-900">
                  {brandFilter ? `${category.brands.find((brand: any) => brand._id === brandFilter)?.name || 'Brand'} Products` : `${category.name} Products`}
                </h2>
                <p className="mt-1 text-sm text-ink-600">{total} products</p>
              </div>
              <form onSubmit={submitSearch} className="flex min-h-12 w-full gap-2 rounded-xl border border-ink-200 bg-white p-1.5 shadow-sm focus-within:border-primary-400 sm:max-w-md">
                <label className="flex min-w-0 flex-1 items-center gap-2 px-2">
                  <FiSearch className="h-4 w-4 shrink-0 text-ink-400" aria-hidden="true" />
                  <input className="min-w-0 flex-1 border-0 bg-transparent text-sm outline-none focus:ring-0" value={productSearch} onChange={event => setProductSearch(event.target.value)} placeholder="Search products..." aria-label="Search products in this category" />
                </label>
                <button type="submit" className="bm-btn bm-btn-primary min-h-10 border-0 px-4 text-sm">Search</button>
              </form>
            </div>

            {productsLoading ? (
              <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 sm:gap-4 lg:grid-cols-4">
                {[1, 2, 3, 4].map(index => <ProductCardSkeleton key={index} />)}
              </div>
            ) : products.length ? (
              <>
                <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 sm:gap-4 lg:grid-cols-4 xl:grid-cols-5">
                  {products.map(product => {
                    const variant = product.variants?.[0];
                    const listPrice = variant?.listPrice;
                    const sellingPrice = variant?.basePrice ?? variant?.finalPrice;
                    const finalDiscount = variant && listPrice
                      ? Math.max(0, ((listPrice - (sellingPrice ?? 0)) / listPrice) * 100).toFixed(2)
                      : undefined;
                    return (
                      <ProductCard
                        key={product._id}
                        image={getImageUrl(product.images?.[0])}
                        name={product.name}
                        brandName={product.brand?.name}
                        price={variant ? formatINR(sellingPrice) : undefined}
                        mrp={variant ? formatINR(listPrice) : undefined}
                        discountPercent={variant?.discountPercent || 0}
                        finalDiscount={finalDiscount}
                        categoryName={product.category?.name}
                        subcategoryName={product.subcategory?.name}
                        stock={variant ? Number(variant.stock || 0) : undefined}
                        unit={variant?.unit || '-'}
                        onNavigate={() => navigate(`/products/${product._id}`)}
                        onAddToCart={() => addProductToCart(product)}
                        onImageError={event => { event.currentTarget.src = '/placeholder.png'; }}
                      />
                    );
                  })}
                </div>
                {pages > 1 && (
                  <nav aria-label="Product pages" className="mt-6 flex items-center justify-center gap-3">
                    <button type="button" className="bm-btn bm-btn-secondary min-h-11 px-4" onClick={() => setPage(current => Math.max(1, current - 1))} disabled={page <= 1}>
                      <FiChevronLeft aria-hidden="true" /> Previous
                    </button>
                    <span className="text-sm font-semibold text-ink-700">Page {page} of {pages}</span>
                    <button type="button" className="bm-btn bm-btn-secondary min-h-11 px-4" onClick={() => setPage(current => Math.min(pages, current + 1))} disabled={page >= pages}>
                      Next <FiChevronRight aria-hidden="true" />
                    </button>
                  </nav>
                )}
              </>
            ) : (
              <div className="rounded-2xl border border-dashed border-ink-300 bg-ink-50 px-5 py-14 text-center">
                <FiPackage className="mx-auto h-12 w-12 text-ink-400" aria-hidden="true" />
                <h3 className="mt-4 text-lg font-bold text-ink-900">No products found</h3>
                <p className="mt-1 text-sm text-ink-600">{submittedSearch ? 'Try a different search term.' : 'There are no published products for these brands yet.'}</p>
              </div>
            )}
          </section>
        </>
      )}
    </main>
    </>
  );
}
