import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api, { formatINR } from '../../utils/api';
import { trackGoogleAdsPurchase } from '../../utils/googleAds';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';

declare global { interface Window { Razorpay: any; } }

export default function MyOrdersPage() {
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewOrder, setViewOrder] = useState<any>(null);

  useEffect(() => {
    api.get('/orders/my').then(r => { setOrders(r.data.orders); setLoading(false); });
    const s = document.createElement('script'); s.src = 'https://checkout.razorpay.com/v1/checkout.js'; document.body.appendChild(s);
  }, []);

  const downloadInvoice = async (orderId: string, orderNumber: string) => {
    const res = await api.get(`/invoice/user/${orderId}`, { responseType: 'blob' });
    const url = window.URL.createObjectURL(new Blob([res.data]));
    const a = document.createElement('a'); a.href = url; a.download = `invoice-${orderNumber}.pdf`; a.click();
  };

  const payNow = async (order: any) => {
    const keyRes = await api.get('/payment/key');
    const orderRes = await api.post('/payment/create-order', { amount: order.totalAmount });
    const rzp = new window.Razorpay({
      key: keyRes.data.key, amount: orderRes.data.order.amount, currency: 'INR',
      name: 'Basava Mart', order_id: orderRes.data.order.id,
      handler: async (res: any) => {
        const payRes = await api.post(`/orders/${order._id}/pay`, { razorpayOrderId: res.razorpay_order_id, razorpayPaymentId: res.razorpay_payment_id, razorpaySignature: res.razorpay_signature });
        const updatedOrder = payRes.data?.order;
        if (updatedOrder && updatedOrder._id && updatedOrder.paymentStatus === 'paid') {
          try { trackGoogleAdsPurchase({ orderId: updatedOrder._id, value: updatedOrder.totalAmount }); } catch (e) { }
        }
        toast.success('Payment successful!');
        api.get('/orders/my').then(r => setOrders(r.data.orders));
      },
      theme: { color: '#e26a26' }
    });
    rzp.open();
  };

  const statusColors: any = { delivered: 'badge-success', cancelled: 'badge-danger', order_placed: 'badge-warning', shipped: 'badge-info', confirmed: 'badge-info' };

  return (
    <div style={{ paddingTop: 24, paddingBottom: 48 }}>
      <h1 style={{ fontSize: 22, fontWeight: 700, marginBottom: 24 }}>📦 My Orders</h1>
      {loading ? <div style={{ textAlign: 'center', padding: 60 }}><div className="spinner" style={{ width: 40, height: 40, borderWidth: 3, margin: '0 auto' }} /></div> : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {orders.map(order => (
            <div key={order._id} className="card" style={{ padding: 20 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: 10 }}>
                <div>
                  <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
                    <code style={{ color: 'var(--primary)', fontWeight: 700, fontSize: 15 }}>{order.orderNumber}</code>
                    <span className={`badge ${order.paymentStatus === 'paid' ? 'badge-success' : 'badge-warning'}`}>{order.paymentStatus}</span>
                    <span className={`badge ${statusColors[order.deliveryStatus] || 'badge-gray'}`}>{order.deliveryStatus?.replace(/_/g, ' ')}</span>
                  </div>
                  <div style={{ fontSize: 13, color: 'var(--gray-500)', marginTop: 4 }}>{order.items?.length} item(s) • {new Date(order.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' })}</div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <div style={{ fontSize: 22, fontWeight: 700, color: 'var(--primary)' }}>₹{formatINR(order.totalAmount)}</div>
                  <div style={{ display: 'flex', gap: 8, marginTop: 8, justifyContent: 'flex-end' }}>
                    <button className="btn btn-gray btn-sm" onClick={() => setViewOrder(order)}>View Details</button>
                    {order.paymentStatus === 'paid' && <button className="btn btn-outline btn-sm" onClick={() => downloadInvoice(order._id, order.orderNumber)}>📄 Receipt</button>}
                    {order.paymentMethod === 'pay_later' && order.paymentStatus === 'pending' && <button className="btn btn-primary btn-sm" onClick={() => payNow(order)}>💳 Pay Now</button>}
                  </div>
                </div>
              </div>
              {order.paymentMethod === 'bank_transfer' && (
                <div style={{ marginTop: 10, fontSize: 13, color: 'var(--gray-600)' }}>
                  Bank transfer: {order.paymentStatus === 'paid' ? 'payment confirmed' : 'screenshot submitted, awaiting confirmation'}
                </div>
              )}
              {/* Items preview */}
              <div style={{ display: 'flex', gap: 8, marginTop: 12, overflowX: 'auto' }}>
                {order.items?.slice(0, 4).map((item: any, i: number) => (
                  <img key={i} src={item.productImage ? `${item.productImage}` : '/placeholder.png'} alt={item.productName} style={{ width: 56, height: 56, objectFit: 'cover', borderRadius: 8, border: '1px solid var(--gray-200)', flexShrink: 0 }} />
                ))}
              </div>
              {/* Delivery timeline */}
              {order.deliveryUpdates?.length > 0 && (
                <div style={{ marginTop: 12, background: 'var(--gray-50)', borderRadius: 8, padding: 12 }}>
                  <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--gray-600)', marginBottom: 6 }}>Delivery Updates</div>
                  <div style={{ display: 'flex', gap: 8, overflowX: 'auto' }}>
                    {[...order.deliveryUpdates].reverse().slice(0, 3).map((u: any, i: number) => (
                      <div key={i} style={{ flexShrink: 0, background: 'white', borderRadius: 6, padding: '6px 10px', border: '1px solid var(--gray-200)', fontSize: 11 }}>
                        <div style={{ fontWeight: 600, color: 'var(--primary)' }}>{u.status?.replace(/_/g, ' ')}</div>
                        {u.message && <div style={{ color: 'var(--gray-500)', marginTop: 2 }}>{u.message}</div>}
                        <div style={{ color: 'var(--gray-400)', marginTop: 2 }}>{new Date(u.updatedAt).toLocaleDateString('en-IN')}</div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ))}
          {orders.length === 0 && (
            <div style={{ textAlign: 'center', padding: 80, color: 'var(--gray-400)' }}>
              <div style={{ fontSize: 64 }}>📦</div>
              <div style={{ fontSize: 18, marginTop: 12 }}>No orders yet</div>
              <button className="btn btn-primary" style={{ marginTop: 16 }} onClick={() => window.location.href = '/products'}>Start Shopping</button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
