import React, { useEffect, useRef, useState } from "react";
import type { TouchEvent, TransitionEvent } from "react";

const images: string[] = [
  "/assets/images/basavamart11.webp",
  "/assets/images/basavamart.webp",
  "/assets/images/basavamart1.webp",
  "/assets/images/basavamart2.webp",
  "/assets/images/basavamart3.webp",
  "/assets/images/basavamart4.webp",
  "/assets/images/basavamart5.webp",
  "/assets/images/basavamart8.webp",
  "/assets/images/basavamart9.webp",
  "/assets/images/basavamart10.webp",
  "/assets/images/basavamart11.webp",
 
];

const SLIDE_TIME = 3500; // how long each image stays (ms)
const ANIM_TIME = 800; // slide animation speed (ms)
const SWIPE_DISTANCE = 40; // minimum finger movement to count as a swipe (px)

const total = images.length;
// Clones on both ends give a seamless loop: [last, ...images, first]
const slides: string[] = [images[total - 1], ...images, images[0]];

export default function ImageSlider() {
  const [index, setIndex] = useState<number>(1); // 1 = first real image
  const [animate, setAnimate] = useState<boolean>(true);
  const [paused, setPaused] = useState<boolean>(false);
  const touchStartX = useRef<number | null>(null);

  // Move one step. Ignored while the loop is resetting from a clone.
  const move = (dir: 1 | -1) => {
    setAnimate(true);
    setIndex((i) => (i < 1 || i > total ? i : i + dir));
  };

  // Auto slide (the timer restarts after every change, so swipes are not interrupted)
  useEffect(() => {
    if (paused) return;
    const t = setTimeout(() => move(1), SLIDE_TIME);
    return () => clearTimeout(t);
  }, [index, paused]);

  // After a silent jump from a clone, turn the animation back on
  useEffect(() => {
    if (animate) return;
    const id = requestAnimationFrame(() =>
      requestAnimationFrame(() => setAnimate(true))
    );
    return () => cancelAnimationFrame(id);
  }, [animate]);

  // When a clone is reached, jump to the matching real slide without animation
  const handleTransitionEnd = (e: TransitionEvent<HTMLDivElement>) => {
    if (e.target !== e.currentTarget) return;
    if (index === total + 1) {
      setAnimate(false);
      setIndex(1);
    } else if (index === 0) {
      setAnimate(false);
      setIndex(total);
    }
  };

  // Touch swipe
  const onTouchStart = (e: TouchEvent<HTMLElement>) => {
    touchStartX.current = e.touches[0].clientX;
    setPaused(true);
  };
  const onTouchEnd = (e: TouchEvent<HTMLElement>) => {
    if (touchStartX.current !== null) {
      const diff = e.changedTouches[0].clientX - touchStartX.current;
      if (Math.abs(diff) > SWIPE_DISTANCE) move(diff < 0 ? 1 : -1);
    }
    touchStartX.current = null;
    setPaused(false);
  };

  const active = (index - 1 + total) % total;

  return (
    <section
      aria-label="Image slider"
      className="relative aspect-[8/3] w-full select-none overflow-hidden bg-ink-900"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onTouchStart={onTouchStart}
      onTouchEnd={onTouchEnd}
    >
      {/* Sliding track */}
      <div
        className="flex h-full w-full will-change-transform"
        style={{
          transform: `translateX(-${index * 100}%)`,
          transition: animate
            ? `transform ${ANIM_TIME}ms cubic-bezier(0.65, 0, 0.35, 1)`
            : "none",
        }}
        onTransitionEnd={handleTransitionEnd}
      >
        {slides.map((src, i) => (
          <div key={i} className="h-full w-full shrink-0">
            <img
              src={src}
              alt=""
              draggable={false}
              loading={i <= 2 ? "eager" : "lazy"}
              className="h-full w-full object-contain object-center"
            />
          </div>
        ))}
      </div>

      {/* Dots (no text). Delete this block if you don't want them */}
      <div className="absolute bottom-2 left-1/2 flex -translate-x-1/2 gap-1.5 sm:bottom-3 sm:gap-2">
        {images.map((_, i) => (
          <button
            key={i}
            type="button"
            aria-label={`Go to slide ${i + 1}`}
            onClick={() => {
              setAnimate(true);
              setIndex(i + 1);
            }}
            className={`h-1.5 rounded-full transition-all duration-300 sm:h-2 ${
              active === i
                ? "w-5 bg-white sm:w-6"
                : "w-1.5 bg-white/50 hover:bg-white/80 sm:w-2"
            }`}
          />
        ))}
      </div>
    </section>
  );
}