import React, { useEffect, useState } from 'react';
import api, { formatINR, getImageUrl } from '../../utils/api';
import toast from 'react-hot-toast';

const formatAddress = (address: any) => [
  address?.addressLine1,
  address?.addressLine2,
  [address?.city, address?.state, address?.pincode].filter(Boolean).join(', '),
  address?.country,
].filter(Boolean).join(', ');

export default function AdminPaymentVerifications() {
  const [orders, setOrders] = useState<any[]>([]);
  const [sitePayments, setSitePayments] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [updatingId, setUpdatingId] = useState('');
  const [updatingSitePaymentId, setUpdatingSitePaymentId] = useState('');
  const [loadError, setLoadError] = useState('');

  useEffect(() => {
    let active = true;
    const load = async () => {
      try {
        const [response, siteResponse] = await Promise.all([
          api.get('/orders/admin/payment-verifications'),
          api.get('/basket/admin/site-payments/pending'),
        ]);
        if (active) {
          setOrders(response.data.orders || []);
          setSitePayments(siteResponse.data.payments || []);
          setLoadError('');
        }
      } catch (error: any) {
        if (active) setLoadError(error.response?.data?.message || 'Could not load payment verifications');
      } finally {
        if (active) setLoading(false);
      }
    };
    load();
    const interval = window.setInterval(load, 15000);
    return () => { active = false; window.clearInterval(interval); };
  }, []);

  const markPaymentDone = async (orderId: string) => {
    setUpdatingId(orderId);
    try {
      await api.patch(`/orders/admin/${orderId}/mark-paid`);
      setOrders(current => current.filter(order => order._id !== orderId));
      toast.success('Payment marked as done');
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Could not update payment status');
    } finally {
      setUpdatingId('');
    }
  };

  const markSitePaymentDone = async (paymentId: string) => {
    setUpdatingSitePaymentId(paymentId);
    try {
      await api.patch(`/basket/admin/site-payments/${paymentId}/mark-paid`);
      setSitePayments(current => current.filter(payment => payment._id !== paymentId));
      toast.success('Site payment verified; basket items are now orders');
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Could not update site payment');
    } finally {
      setUpdatingSitePaymentId('');
    }
  };

  return (
    <div className="fade-in">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap', marginBottom: 20 }}>
        <div>
          <h1 style={{ fontSize: 22, fontWeight: 700, margin: 0 }}>Payment Verifications</h1>
          <div style={{ fontSize: 13, color: 'var(--gray-500)', marginTop: 5 }}>Bank transfer screenshots awaiting review</div>
        </div>
        <span className="badge badge-warning">{orders.length + sitePayments.length} pending</span>
      </div>

      {loadError && <div className="card" style={{ padding: 16, color: 'var(--danger, #b42318)', marginBottom: 16 }}>{loadError}</div>}
      {loading ? (
        <div style={{ textAlign: 'center', padding: 60 }}><div className="spinner" style={{ margin: '0 auto' }} /></div>
      ) : orders.length || sitePayments.length ? (
        <div style={{ display: 'grid', gap: 16 }}>
          {sitePayments.map(payment => (
            <article className="card" key={payment._id} style={{ padding: 20 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12, flexWrap: 'wrap', borderBottom: '1px solid var(--gray-200)', paddingBottom: 14, marginBottom: 14 }}>
                <div>
                  <strong style={{ color: 'var(--primary)', fontSize: 15 }}>Site payment · {payment.site?.siteName || 'Site'}</strong>
                  <div style={{ color: 'var(--gray-500)', fontSize: 12, marginTop: 4 }}>
                    {payment.member?.name || 'Member'} · {payment.member?.memberId || ''} · Submitted {payment.paymentSubmittedAt ? new Date(payment.paymentSubmittedAt).toLocaleString('en-IN') : ''}
                  </div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <div style={{ fontSize: 20, fontWeight: 800, color: 'var(--primary)' }}>₹{formatINR(payment.amount)}</div>
                  <span className="badge badge-warning">Awaiting verification</span>
                </div>
              </div>
              <h3 style={{ fontSize: 14, margin: '0 0 8px' }}>Site products ({payment.basketItems?.length || 0})</h3>
              <div style={{ borderTop: '1px solid var(--gray-200)' }}>
                {payment.basketItems?.map((item: any) => (
                  <div key={item._id} style={{ display: 'flex', gap: 12, padding: '10px 0', borderBottom: '1px solid var(--gray-100)' }}>
                    <img src={getImageUrl(item.product?.images?.[0] || item.productSnapshot?.image)} alt={item.productSnapshot?.name} style={{ width: 52, height: 52, objectFit: 'cover', borderRadius: 6, border: '1px solid var(--gray-200)', flexShrink: 0 }} />
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <div style={{ fontWeight: 600 }}>{item.productSnapshot?.name}</div>
                      <div style={{ fontSize: 12, color: 'var(--gray-600)', marginTop: 3 }}>Variant: {item.variant?.name || '-'} · Qty: {item.quantity} · Total: ₹{formatINR((item.vendorPrice?.finalPrice || 0) * item.quantity)}</div>
                    </div>
                  </div>
                ))}
              </div>
              <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16, flexWrap: 'wrap', borderTop: '1px solid var(--gray-200)', paddingTop: 14, marginTop: 8 }}>
                <div>
                  <h3 style={{ fontSize: 14, margin: '0 0 8px' }}>Payment screenshot</h3>
                  {payment.paymentProof?.url ? (
                    <a href={getImageUrl(payment.paymentProof.url)} target="_blank" rel="noreferrer" aria-label={`Open payment proof for ${payment.site?.siteName || 'site'}`}>
                      <img src={getImageUrl(payment.paymentProof.url)} alt="Site payment proof" style={{ display: 'block', maxWidth: 220, maxHeight: 260, objectFit: 'contain', border: '1px solid var(--gray-200)', borderRadius: 6 }} />
                    </a>
                  ) : <span style={{ color: 'var(--gray-500)', fontSize: 13 }}>No screenshot attached</span>}
                </div>
                <button className="btn btn-primary" onClick={() => markSitePaymentDone(payment._id)} disabled={updatingSitePaymentId === payment._id}>
                  {updatingSitePaymentId === payment._id ? <div className="spinner" /> : 'Verify site payment'}
                </button>
              </div>
            </article>
          ))}
          {orders.map(order => (
            <article className="card" key={order._id} style={{ padding: 20 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12, flexWrap: 'wrap', borderBottom: '1px solid var(--gray-200)', paddingBottom: 14, marginBottom: 14 }}>
                <div>
                  <strong style={{ color: 'var(--primary)', fontSize: 15 }}>{order.orderNumber}</strong>
                  <div style={{ color: 'var(--gray-500)', fontSize: 12, marginTop: 4 }}>
                    Submitted {order.paymentSubmittedAt ? new Date(order.paymentSubmittedAt).toLocaleString('en-IN') : new Date(order.createdAt).toLocaleString('en-IN')}
                  </div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <div style={{ fontSize: 20, fontWeight: 800, color: 'var(--primary)' }}>₹{formatINR(order.totalAmount)}</div>
                  <span className="badge badge-warning">Awaiting verification</span>
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: 16, marginBottom: 18 }}>
                <section>
                  <h3 style={{ fontSize: 14, margin: '0 0 8px' }}>Customer</h3>
                  <div style={{ fontWeight: 600 }}>{order.userName}</div>
                  <div style={{ fontSize: 13, color: 'var(--gray-600)', marginTop: 3 }}>{order.userEmail}</div>
                  <div style={{ fontSize: 13, color: 'var(--gray-600)', marginTop: 3 }}>{order.userPhone || order.billingAddress?.mobile}</div>
                </section>
                <section>
                  <h3 style={{ fontSize: 14, margin: '0 0 8px' }}>Billing address</h3>
                  <div style={{ fontSize: 13, color: 'var(--gray-600)' }}>{order.billingAddress?.name} · {order.billingAddress?.mobile}</div>
                  <div style={{ fontSize: 13, color: 'var(--gray-600)', marginTop: 3 }}>{formatAddress(order.billingAddress)}</div>
                </section>
                <section>
                  <h3 style={{ fontSize: 14, margin: '0 0 8px' }}>Shipping address</h3>
                  <div style={{ fontSize: 13, color: 'var(--gray-600)' }}>{order.shippingAddress?.name} · {order.shippingAddress?.mobile}</div>
                  <div style={{ fontSize: 13, color: 'var(--gray-600)', marginTop: 3 }}>{formatAddress(order.shippingAddress)}</div>
                </section>
              </div>

              <h3 style={{ fontSize: 14, margin: '0 0 8px' }}>Products ({order.items?.length || 0})</h3>
              <div style={{ borderTop: '1px solid var(--gray-200)' }}>
                {order.items?.map((item: any) => (
                  <div key={item._id} style={{ display: 'flex', gap: 12, padding: '12px 0', borderBottom: '1px solid var(--gray-100)' }}>
                    <img src={getImageUrl(item.productImage)} alt={item.productName} style={{ width: 64, height: 64, objectFit: 'cover', borderRadius: 6, border: '1px solid var(--gray-200)', flexShrink: 0 }} />
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <div style={{ fontWeight: 600 }}>{item.productName}</div>
                      <div style={{ fontSize: 12, color: 'var(--gray-500)', marginTop: 3 }}>{item.brandName} {item.categoryName ? `· ${item.categoryName}` : ''}</div>
                      <div style={{ fontSize: 12, color: 'var(--gray-600)', marginTop: 4 }}>
                        Variant: {item.variant?.name || '-'} · Unit: {item.variant?.unit || '-'} · Qty: {item.quantity}
                      </div>
                      <div style={{ fontSize: 12, color: 'var(--gray-600)', marginTop: 3 }}>
                        Unit price: ₹{formatINR(item.variant?.finalPrice)} · Line total: ₹{formatINR(item.itemTotal)}
                      </div>
                      {item.packageBreakdown && (
                        <div style={{ fontSize: 11, color: 'var(--gray-500)', marginTop: 4 }}>
                          Package breakdown: {[
                            ['Tertiary', item.packageBreakdown.tertiary],
                            ['Secondary', item.packageBreakdown.secondary],
                            ['Primary', item.packageBreakdown.primary],
                          ].filter(([, part]: any) => part?.count > 0).map(([label, part]: any) => `${label} ${part.count} × ${part.qty} = ${part.total}`).join(' · ')}
                          {item.packageBreakdown.remainder?.count > 0 ? ` · Loose ${item.packageBreakdown.remainder.count} pcs` : ''}
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(170px, 1fr))', gap: 8, padding: '12px 0', fontSize: 13 }}>
                <div>Subtotal: <strong>₹{formatINR(order.subtotal)}</strong></div>
                <div>Discount: <strong>₹{formatINR(order.totalDiscount)}</strong></div>
                <div>GST: <strong>₹{formatINR(order.totalGst)}</strong></div>
                <div>Total paid: <strong>₹{formatINR(order.totalAmount)}</strong></div>
              </div>

              <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16, flexWrap: 'wrap', borderTop: '1px solid var(--gray-200)', paddingTop: 14 }}>
                <div>
                  <h3 style={{ fontSize: 14, margin: '0 0 8px' }}>Payment screenshot</h3>
                  {order.paymentProof?.url ? (
                    <a href={getImageUrl(order.paymentProof.url)} target="_blank" rel="noreferrer" aria-label={`Open payment proof for ${order.orderNumber}`}>
                      <img src={getImageUrl(order.paymentProof.url)} alt={`Payment proof for ${order.orderNumber}`} style={{ display: 'block', maxWidth: 220, maxHeight: 260, objectFit: 'contain', border: '1px solid var(--gray-200)', borderRadius: 6 }} />
                    </a>
                  ) : <span style={{ color: 'var(--gray-500)', fontSize: 13 }}>No screenshot attached</span>}
                </div>
                <button className="btn btn-primary" onClick={() => markPaymentDone(order._id)} disabled={updatingId === order._id}>
                  {updatingId === order._id ? <div className="spinner" /> : 'Mark payment done'}
                </button>
              </div>
            </article>
          ))}
        </div>
      ) : (
        <div className="card" style={{ padding: 48, textAlign: 'center', color: 'var(--gray-500)' }}>No bank payments are waiting for verification.</div>
      )}
    </div>
  );
}