import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { getOrder, createRazorpayOrder, verifyPayment } from '../miniApi';
import { useMini } from '../MiniContext';
import { formatINR } from '../../utils/api';
import './PaymentPage.css';

declare global {
  interface Window {
    Razorpay: any;
  }
}

interface MiniAddress {
  name?: string;
  phone?: string;
  line1?: string;
  line2?: string;
  city?: string;
  state?: string;
  pincode?: string;
}

interface MiniOrderItem {
  name: string;
  qty: number;
  price: number;
}

interface MiniOrder {
  _id?: string;
  subtotal?: number;
  gstRate?: number;
  gstAmount?: number;
  total?: number;
  items?: MiniOrderItem[];
  billingAddress?: MiniAddress;
  payment?: {
    status?: 'pending' | 'paid' | 'failed';
  };
}

export const PaymentPage = () => {
  const { orderId } = useParams();
  const navigate = useNavigate();
  const { isAuthenticated } = useMini();
  const [order, setOrder] = useState<MiniOrder | null>(null);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);

  useEffect(() => {
    if (!isAuthenticated) {
      navigate('/mini');
      return;
    }
    fetchOrder();
  }, [orderId, isAuthenticated, navigate]);

  const fetchOrder = async () => {
    setLoading(true);
    try {
      const res = await getOrder(orderId ?? '');
      if (res.data?.success) {
        setOrder(res.data.data as MiniOrder);
      }
    } catch (error) {
      console.error('Error fetching order:', error);
      toast.error('Failed to load order');
      navigate('/mini/track');
    } finally {
      setLoading(false);
    }
  };

  const handlePayment = async () => {
    if (!order || !order.payment) return;

    if ((order.payment?.status ?? 'pending') === 'paid') {
      toast('This order is already paid');
      navigate(`/mini/track`);
      return;
    }

    setProcessing(true);
    try {
      // Create Razorpay order
      const razorpayRes = await createRazorpayOrder(orderId ?? '');

      if (!razorpayRes.data?.success) {
        toast.error('Failed to initiate payment');
        setProcessing(false);
        return;
      }

      const { razorpayOrder, keyId } = razorpayRes.data;

      // Load Razorpay script
      const script = document.createElement('script');
      script.src = 'https://checkout.razorpay.com/v1/checkout.js';
      script.async = true;
      document.body.appendChild(script);

      script.onload = () => {
        const options = {
          key: keyId,
          amount: razorpayOrder.amount,
          currency: razorpayOrder.currency,
          order_id: razorpayOrder.id,
          handler: async (response: { razorpay_payment_id?: string; razorpay_order_id?: string; razorpay_signature?: string }) => {
            try {
              const verifyRes = await verifyPayment(
                orderId ?? '',
                response.razorpay_payment_id ?? '',
                response.razorpay_order_id ?? '',
                response.razorpay_signature ?? ''
              );

              if (verifyRes.data?.success) {
                toast.success('Payment successful!');
                navigate(`/mini/track`);
              }
            } catch (error) {
              console.error('Verification error:', error);
              toast.error('Payment verification failed');
            }
          },
          prefill: {
            email: 'customer@example.com',
            contact: order.billingAddress?.phone || '',
          },
          theme: {
            color: '#ff8c42',
          },
        };

        const razorpay = new window.Razorpay(options);
        razorpay.open();
        setProcessing(false);
      };
    } catch (error) {
      console.error('Payment error:', error);
      toast.error('Failed to process payment');
      setProcessing(false);
    }
  };

  if (loading) return <div className="loading">Loading order...</div>;

  if (!order) return <div className="loading">Order not found</div>;

  return (
    <div className="payment-page">
      <div className="payment-container">
        <h1>Payment</h1>

        <div className="payment-card">
          <h2>Order Summary</h2>

          <div className="order-summary">
            <div className="summary-item">
              <span>Order ID:</span>
              <span className="order-id">{orderId?.slice(-8).toUpperCase()}</span>
            </div>

            <div className="items-list">
              <h3>Items:</h3>
              {order.items?.map((item, idx) => (
                <div key={idx} className="item-row">
                  <span>{item.name}</span>
                  <span>
                    {item.qty} x ₹{formatINR(item.price)}
                  </span>
                </div>
              ))}
            </div>

            <div className="summary-divider" />

            <div className="summary-item">
              <span>Subtotal:</span>
              <span>₹{formatINR(order.subtotal)}</span>
            </div>

            <div className="summary-item">
              <span>GST ({order.gstRate}%):</span>
              <span>₹{formatINR(order.gstAmount)}</span>
            </div>

            <div className="summary-item total">
              <span>Total Amount:</span>
              <span>₹{formatINR(order.total)}</span>
            </div>
          </div>

          <div className="payment-status">
            <p>
              Status:{' '}
              <span
                className={`status ${order.payment?.status ?? 'pending'}`}
              >
                {(order.payment?.status ?? 'pending').toUpperCase()}
              </span>
            </p>
          </div>

          {order.payment?.status === 'pending' && (
            <button
              className="pay-button"
              onClick={handlePayment}
              disabled={processing}
            >
              {processing ? 'Processing...' : `Pay ₹${formatINR(order.total)}`}
            </button>
          )}

          {order.payment?.status === 'paid' && (
            <div className="paid-message">
              ✓ Payment completed successfully!
            </div>
          )}
        </div>

        <button className="back-button" onClick={() => navigate('/mini/track')}>
          Back to Orders
        </button>
      </div>
    </div>
  );
};

export default PaymentPage;
