import React, { useState } from 'react';
import toast from 'react-hot-toast';
import { submitMiniRequests } from '../miniApi';
import './RequestSphere.css';

interface RequestItem {
  productName: string;
  qty: number;
  name: string;
  phone: string;
  description: string;
  note: string;
  media: File[];
}

const MAX_MEDIA = 10;

export const RequestSphere = () => {
  const [requests, setRequests] = useState<RequestItem[]>([
    {
      productName: '',
      qty: 1,
      name: '',
      phone: '',
      description: '',
      note: '',
      media: [],
    },
  ]);

  const [loading, setLoading] = useState(false);

  const addRequest = () => {
    setRequests([
      ...requests,
      {
        productName: '',
        qty: 1,
        name: '',
        phone: '',
        description: '',
        note: '',
        media: [],
      },
    ]);
  };

  const updateRequest = (index: number, field: keyof RequestItem, value: string | number | File[]) => {
    const updated = [...requests];
    updated[index] = { ...updated[index], [field]: value };
    setRequests(updated);
  };

  const updateRequestMedia = (index: number, files: FileList | null) => {
    if (!files) return;
    const selectedFiles = Array.from(files);
    const currentFiles = requests[index].media;
    const nextFiles = [...currentFiles, ...selectedFiles];
    if (nextFiles.length > MAX_MEDIA) {
      toast.error(`Each request can have up to ${MAX_MEDIA} files`);
      return;
    }
    const invalidFile = selectedFiles.find((file) => !file.type.startsWith('image/') && !file.type.startsWith('video/') && !file.type.startsWith('application/') && !file.type.startsWith('text/'));
    if (invalidFile) {
      toast.error('Only image, video, and document files are allowed');
      return;
    }
    const updated = [...requests];
    updated[index] = { ...updated[index], media: nextFiles };
    setRequests(updated);
  };

  const removeMedia = (requestIndex: number, mediaIndex: number) => {
    const updated = [...requests];
    updated[requestIndex] = {
      ...updated[requestIndex],
      media: updated[requestIndex].media.filter((_, index) => index !== mediaIndex),
    };
    setRequests(updated);
  };

  const removeRequest = (index: number) => {
    if (requests.length === 1) {
      toast.error('Must have at least one request');
      return;
    }
    setRequests(requests.filter((_, i) => i !== index));
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    for (let i = 0; i < requests.length; i++) {
      const req = requests[i];
      if (!req.productName.trim() || !req.name.trim() || !req.phone.trim()) {
        toast.error(`Request ${i + 1}: Please fill product name, name, and phone`);
        return;
      }
    }

    setLoading(true);
    try {
      const res = await submitMiniRequests(requests);

      if (res.data?.success) {
        toast.success('Requests submitted successfully!');
        setRequests([
          {
            productName: '',
            qty: 1,
            name: '',
            phone: '',
            description: '',
            note: '',
            media: [],
          },
        ]);
      }
    } catch (error: unknown) {
      const err = error as { response?: { data?: { message?: string } } };
      console.error('Error submitting requests:', error);
      toast.error(err.response?.data?.message || 'Failed to submit requests');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="request-sphere">
      <div className="request-container">
        <h1>Request Spare</h1>
        <p className="request-intro">
          Can't find the exact part you need? Submit your request and we'll find it for you!
        </p>

        <form onSubmit={handleSubmit} className="request-form">
          {requests.map((request, index) => (
            <div key={index} className="request-row">
              <div className="request-header">
                <h3>Request #{index + 1}</h3>
                {requests.length > 1 && (
                  <button
                    type="button"
                    className="remove-row-btn"
                    onClick={() => removeRequest(index)}
                  >
                    Remove
                  </button>
                )}
              </div>

              <div className="request-grid">
                <div className="form-group">
                  <label>Product Name *</label>
                  <input
                    type="text"
                    placeholder="What part do you need?"
                    value={request.productName}
                    onChange={(e) => updateRequest(index, 'productName', e.target.value)}
                    className="form-input"
                    required
                  />
                </div>

                <div className="form-group">
                  <label>Quantity</label>
                  <input
                    type="number"
                    placeholder="How many?"
                    value={request.qty}
                    onChange={(e) => updateRequest(index, 'qty', Number(e.target.value))}
                    className="form-input"
                    min="1"
                  />
                </div>

                <div className="form-group">
                  <label>Your Name *</label>
                  <input
                    type="text"
                    placeholder="Full name"
                    value={request.name}
                    onChange={(e) => updateRequest(index, 'name', e.target.value)}
                    className="form-input"
                    required
                  />
                </div>

                <div className="form-group">
                  <label>Your Phone *</label>
                  <input
                    type="tel"
                    placeholder="10-digit number"
                    value={request.phone}
                    onChange={(e) => updateRequest(index, 'phone', e.target.value)}
                    className="form-input"
                    required
                  />
                </div>

                <div className="form-group full-width">
                  <label>Description</label>
                  <textarea
                    placeholder="Describe the part in detail..."
                    value={request.description}
                    onChange={(e) => updateRequest(index, 'description', e.target.value)}
                    className="form-textarea"
                    rows={3}
                  />
                </div>

                <div className="form-group full-width">
                  <label>Additional Notes</label>
                  <textarea
                    placeholder="Any other information?"
                    value={request.note}
                    onChange={(e) => updateRequest(index, 'note', e.target.value)}
                    className="form-textarea"
                    rows={2}
                  />
                </div>

                <div className="form-group full-width">
                  <label>Photos, videos, or documents (up to {MAX_MEDIA})</label>
                  <input
                    type="file"
                    className="form-input"
                    accept="image/*,video/*,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.csv"
                    multiple
                    onChange={(e) => updateRequestMedia(index, e.target.files)}
                  />
                  {request.media.length > 0 && (
                    <div className="request-media-preview">
                      {request.media.map((file, mediaIndex) => {
                        const previewUrl = URL.createObjectURL(file);
                        const isImage = file.type.startsWith('image/');
                        const isVideo = file.type.startsWith('video/');
                        return (
                          <div className="request-media-item" key={`${file.name}-${file.lastModified}`}>
                            {isImage && <img src={previewUrl} alt={file.name} />}
                            {isVideo && <video src={previewUrl} controls playsInline />}
                            {!isImage && !isVideo && <span className="request-document-preview">DOC</span>}
                            <span title={file.name}>{file.name}</span>
                            <button type="button" onClick={() => removeMedia(index, mediaIndex)} aria-label={`Remove ${file.name}`}>
                              Remove
                            </button>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}

          <div className="request-actions">
            <button type="button" className="add-row-btn" onClick={addRequest}>
              + Add Another Request
            </button>
            <button type="submit" className="submit-btn" disabled={loading}>
              {loading ? 'Submitting...' : 'Submit Requests'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default RequestSphere;
