import React from 'react';
import { FiCheckCircle, FiShoppingCart, FiXCircle } from 'react-icons/fi';
import { cn } from '../../lib/cn';
import { Badge } from './UI';

type ProductCardProps = {
  image: string;
  name: string;
  brandName?: string;
  price?: string;
  mrp?: string;
  discountPercent?: number;
  finalDiscount?: string;
  categoryName?: string;
  subcategoryName?: string;
  stock?: number;
  unit?: string;
  onNavigate: () => void;
  onAddToCart: () => void;
  onImageError?: React.ReactEventHandler<HTMLImageElement>;
};

export function ProductCard({
  image,
  name,
  brandName,
  price,
  mrp,
  discountPercent = 0,
  finalDiscount,
  categoryName,
  subcategoryName,
  stock,
  unit,
  onNavigate,
  onAddToCart,
  onImageError,
}: ProductCardProps) {
  const inStock = (stock || 0) > 0;

  return (
    <article
      className="bm-card group flex min-w-0 cursor-pointer flex-col overflow-hidden rounded-2xl transition-all duration-200 hover:-translate-y-1 hover:shadow-card-hover focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500"
      role="link"
      tabIndex={0}
      onClick={onNavigate}
      onKeyDown={event => {
        if (event.key === 'Enter') {
          event.preventDefault();
          onNavigate();
        }
      }}
    >
      <div className="relative aspect-square overflow-hidden bg-ink-50">
        {discountPercent > 0 && (
          <Badge variant="sale" className="absolute left-3 top-3 z-10 shadow-sm">
            {discountPercent}% OFF
          </Badge>
        )}
        <img
          src={image}
          alt={name}
          width={400}
          height={400}
          loading="lazy"
          decoding="async"
          onError={onImageError}
          className="h-full w-full object-contain p-4 transition-transform duration-300 group-hover:scale-105"
        />
      </div>

      <div className="flex flex-1 flex-col p-3 sm:p-4">
        {brandName && <div className="mb-1 truncate text-[11px] font-bold uppercase text-primary-700">{brandName}</div>}
        <h3 className="line-clamp-2 min-h-10 text-sm font-semibold leading-5 text-ink-900">{name}</h3>
        {(categoryName || subcategoryName) && (
          <div className="mt-1 space-y-0.5 text-xs leading-4 text-ink-500">
            {categoryName && <p className="line-clamp-1">Category: {categoryName}</p>}
            {subcategoryName && <p className="line-clamp-1">Subcategory: {subcategoryName}</p>}
          </div>
        )}

        {price !== undefined && (
          <>
            <div className="mt-3 text-[11px] font-bold text-ink-600">Selling Price</div>
            <div className="mt-3 flex flex-wrap items-baseline gap-x-2 gap-y-1">
              <span className="text-lg font-extrabold text-primary-700">₹{price}</span>
              {mrp !== undefined && <span className="text-xs text-ink-500 line-through">₹{mrp}</span>}
            </div>
            {finalDiscount && <div className="mt-1 text-xs font-semibold text-success">Final Discount {finalDiscount}</div>}
          </>
        )}

        {stock !== undefined && (
          <div className={cn('mt-2 flex items-center gap-1.5 text-xs font-semibold', inStock ? 'text-success' : 'text-ink-500')}>
            {inStock
              ? <FiCheckCircle className="h-4 w-4 shrink-0" aria-hidden="true" />
              : <FiXCircle className="h-4 w-4 shrink-0" aria-hidden="true" />}
            <span>{inStock ? 'In stock' : 'Out of stock'}{unit ? ` · ${unit}` : ''}</span>
          </div>
        )}

        <button
          type="button"
          className="bm-btn bm-btn-primary mt-3 min-h-11 w-full border-0 px-3 text-sm sm:mt-auto sm:translate-y-1 sm:opacity-95 sm:group-hover:translate-y-0 sm:group-hover:opacity-100 sm:group-focus-within:translate-y-0 sm:group-focus-within:opacity-100"
          onClick={event => {
            event.stopPropagation();
            onAddToCart();
          }}
          aria-label={`Add ${name} to cart`}
        >
          <FiShoppingCart className="h-4 w-4" aria-hidden="true" />
          Add to Cart
        </button>
      </div>
    </article>
  );
}

export function ProductCardSkeleton() {
  return (
    <div className="bm-card overflow-hidden rounded-2xl" aria-hidden="true">
      <div className="aspect-square bg-ink-50 p-4">
        <div className="bm-skeleton h-full w-full rounded-xl" />
      </div>
      <div className="space-y-3 p-3 sm:p-4">
        <div className="bm-skeleton h-3 w-1/3 rounded" />
        <div className="bm-skeleton h-4 w-full rounded" />
        <div className="bm-skeleton h-4 w-4/5 rounded" />
        <div className="bm-skeleton h-6 w-1/2 rounded" />
        <div className="bm-skeleton h-11 w-full rounded-xl" />
      </div>
    </div>
  );
}
