/* ─────────────────────────────────────────────
   AI SEARCH MODAL
───────────────────────────────────────────── */
function AiSearchModal({ onClose, onResult }: { onClose: () => void; onResult: (q: string) => void }) {
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
    const navigate = useNavigate();
    const [result, setResult] = useState<any[]>([]);



  const handleAsk = async () => {
    if (!query.trim()) return;

    setLoading(true);

    try {
      const res = await fetch(
        "/api/ai-search",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ query }),
        }
      );

      const data = await res.json();

      if (data.success) {
        setResult(data.products);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[1000] flex items-end justify-center bg-ink-950/65 p-0 backdrop-blur-sm sm:items-center sm:p-4" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="max-h-[min(90dvh,720px)] w-full overflow-y-auto rounded-t-3xl bg-white shadow-2xl sm:max-w-xl sm:rounded-2xl" role="dialog" aria-modal="true" aria-labelledby="ai-search-title">
        <div className="flex items-center gap-3 bg-dark-gradient px-5 py-5 sm:px-6">
          <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-primary-500/20 text-primary-200"><FiZap className="h-6 w-6" aria-hidden="true" /></span>
          <div>
            <h2 id="ai-search-title" className="font-display text-lg font-bold text-white">AI Product Assistant</h2>
            <p className="text-xs text-ink-300">Describe what you need in plain language</p>
          </div>
          <button onClick={onClose} className="ml-auto flex min-h-11 min-w-11 items-center justify-center rounded-full border-0 bg-white/10 text-white transition hover:bg-white/20 focus-visible:outline focus-visible:outline-2 focus-visible:outline-white" aria-label="Close AI product assistant"><FiX aria-hidden="true" /></button>
        </div>
        <div className="p-4 sm:p-6">
          <textarea
            className="bm-input min-h-28 resize-y"
            placeholder="e.g. I need fire safety valves for a 5-floor building, pressure rated 150 PSI..."
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleAsk())}
          />
          <button className="bm-btn bm-btn-primary mt-3 w-full border-0" onClick={handleAsk} disabled={loading}>
            {loading ? '⏳ Thinking...' : '✨ Get AI Suggestions'}
          </button>
          {result.length > 0 && (
            <div className="mt-5 max-h-56 space-y-3 overflow-y-auto rounded-xl border border-ink-100 bg-ink-50 p-4">
              <p className="font-semibold text-primary-700">✨ AI Recommendations:</p>
              <h3 className="font-semibold text-ink-900">✨ Suggested Products</h3>
              {result.map((product: any) => (
                <div
                  key={product._id}
                  role="link"
                  tabIndex={0}
                  onClick={() => {
                    console.log("Clicked:", product._id);
                    onClose();
                    navigate(`/products/${product._id}`);
                  }}
                  onKeyDown={event => {
                    if (event.key === 'Enter') {
                      onClose();
                      navigate(`/products/${product._id}`);
                    }
                  }}
                  className="cursor-pointer rounded-xl border border-ink-100 bg-white p-3 transition hover:border-primary-300 hover:shadow-soft focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500"
                >
                  <h4 className="font-semibold text-ink-900">{product.name}</h4>
                  <p className="mt-1 text-sm text-ink-600">{product.brand?.name}</p>
                </div>
              ))}
            </div>
          )}
          {result.length > 0 && (
            <button
              onClick={() => { onResult(query); onClose(); }}
              className="bm-btn bm-btn-secondary mt-3 w-full"
            >
              <FiSearch aria-hidden="true" /> 🔍 Search for "{query}"
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

