type TrackArgs = { orderId: string; value: number | string };

const SEND_TO = 'AW-18398138722/GJAUCL3lt-QcEOKi9cRE';

export const trackGoogleAdsPurchase = ({ orderId, value }: TrackArgs) => {
  if (typeof window === 'undefined') return;
  const w: any = window as any;
  if (typeof w.gtag !== 'function') return;
  try {
    const tid = String(orderId);
    const key = `google_ads_purchase_${tid}`;
    if (typeof sessionStorage !== 'undefined' && sessionStorage.getItem(key)) return;

    w.gtag('event', 'conversion', {
      send_to: SEND_TO,
      value: Number(value),
      currency: 'INR',
      transaction_id: tid,
    });

    if (typeof sessionStorage !== 'undefined') sessionStorage.setItem(key, 'true');
  } catch (err) {
    // swallow errors to avoid breaking checkout
    // console.error('Google Ads tracking error', err);
  }
};

export default trackGoogleAdsPurchase;
