
//mobil

import React, { useEffect, useState } from 'react';
import { Outlet, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import api from '../../utils/api';
import {
  MdDashboard,
  MdInventory,
  MdShoppingBasket,
  MdAssignment,
  MdLocalShipping,
  MdLocationCity,
} from 'react-icons/md';
import { FiShoppingCart } from 'react-icons/fi';
import {
  FiMenu,
  FiX,
  FiUser,
  FiLogOut,
  FiChevronDown,
  FiBell,
} from 'react-icons/fi';

/* ─── Layout styles ─── */
const layoutStyles = `
  * { box-sizing: border-box; }

  .member-layout { min-height: 100vh; background: white; }

  /* Broadcast bar */
  .broadcast-bar {
    background: var(--primary);
    color: white;
    text-align: center;
    padding: 7px 16px;
    font-size: clamp(11px, 3vw, 13px);
    font-weight: 500;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
  }

  /* Top nav */
  .member-nav {
    background: white;
    border-bottom: 1px solid var(--gray-200);
    position: sticky;
    top: 0;
    z-index: 200;
    box-shadow: var(--shadow-sm);
  }
  .member-nav-inner {
    max-width: 1280px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 0 clamp(12px, 3vw, 24px);
    height: 62px;
  }

  /* Brand */
  .nav-brand { display: flex; align-items: center; gap: 8px; flex-shrink: 0; text-decoration: none; }
  .nav-brand-name { font-size: 14px; font-weight: 700; color: var(--gray-700); white-space: nowrap; }

  /* Desktop links */
  .nav-links {
    display: flex;
    gap: 2px;
    flex: 1;
    overflow-x: auto;
    scrollbar-width: none;
  }
  .nav-links::-webkit-scrollbar { display: none; }
  .nav-link {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 7px 12px;
    border-radius: 8px;
    text-decoration: none;
    font-size: 13px;
    font-weight: 500;
    color: var(--gray-600);
    white-space: nowrap;
    transition: all 0.15s;
  }
  .nav-link:hover { color: var(--primary); background: var(--primary-bg); }
  .nav-link.active { color: var(--primary); background: var(--primary-bg); }

  /* Profile dropdown */
  .profile-trigger {
    display: flex;
    align-items: center;
    gap: 7px;
    cursor: pointer;
    padding: 5px 10px;
    border-radius: 8px;
    border: 1.5px solid var(--gray-200);
    flex-shrink: 0;
    background: white;
    transition: border-color 0.2s;
    position: relative;
  }
  .profile-trigger:hover { border-color: var(--primary); }
  .profile-avatar {
    width: 30px; height: 30px;
    border-radius: 50%;
    background: var(--primary);
    display: flex; align-items: center; justify-content: center;
    color: white; font-weight: 700; font-size: 13px;
    flex-shrink: 0;
  }
  .profile-names { display: flex; flex-direction: column; }
  .profile-names .pname { font-size: 12px; font-weight: 600; color: var(--gray-800); }
  .profile-names .pmid  { font-size: 11px; color: var(--primary); font-weight: 600; }

  .profile-dropdown {
    display: none;
    position: absolute;
    top: calc(100% + 4px);
    right: 0;
    background: white;
    border: 1px solid var(--gray-200);
    border-radius: 10px;
    box-shadow: var(--shadow-md);
    min-width: 170px;
    z-index: 400;
    overflow: hidden;
  }
  .profile-wrap:hover .profile-dropdown { display: block; }
  .profile-wrap { position: relative; flex-shrink: 0; }

  .dropdown-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 11px 15px;
    text-decoration: none;
    color: var(--gray-700);
    font-size: 13px;
    cursor: pointer;
    transition: background 0.15s;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
  }
  .dropdown-item:hover { background: var(--gray-50); }
  .dropdown-item.danger { color: var(--red); }

  /* Hamburger (mobile only) */
  .hamburger {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    padding: 6px;
    border-radius: 8px;
    color: var(--gray-700);
    flex-shrink: 0;
  }
  .hamburger:hover { background: var(--gray-100); }

  /* Mobile drawer */
  .mobile-drawer {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 500;
  }
  .mobile-drawer.open { display: flex; }

  .drawer-overlay {
    position: absolute;
    inset: 0;
    background: rgba(0,0,0,0.4);
  }
  .drawer-panel {
    position: relative;
    width: min(280px, 82vw);
    height: 100%;
    background: white;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    z-index: 1;
    box-shadow: 4px 0 24px rgba(0,0,0,0.15);
  }
  .drawer-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 18px;
    border-bottom: 1px solid var(--gray-200);
  }
  .drawer-nav { padding: 12px 10px; flex: 1; }
  .drawer-link {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 11px 14px;
    border-radius: 10px;
    text-decoration: none;
    font-size: 14px;
    font-weight: 500;
    color: var(--gray-700);
    margin-bottom: 2px;
    transition: all 0.15s;
  }
  .drawer-link:hover { background: var(--gray-50); color: var(--primary); }
  .drawer-link.active { background: var(--primary-bg); color: var(--primary); font-weight: 600; }
  .drawer-link svg { font-size: 18px; flex-shrink: 0; }

  .drawer-footer {
    border-top: 1px solid var(--gray-200);
    padding: 12px 10px;
  }
  .drawer-user {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    border-radius: 10px;
    background: var(--gray-50);
    margin-bottom: 8px;
  }

  /* Main content */
  .member-main {
    max-width: 1280px;
    margin: 0 auto;
    padding: clamp(12px, 3vw, 24px) clamp(12px, 3vw, 24px) 48px;
  }

  /* Responsive */
  @media (max-width: 768px) {
    .nav-links { display: none; }
    .profile-wrap { display: none; }
    .hamburger { display: flex; align-items: center; justify-content: center; }
    .nav-brand-name { display: none; }
  }

  @media (min-width: 769px) {
    .mobile-drawer { display: none !important; }
  }
`;

function injectLayoutStyles() {
  if (document.getElementById('member-layout-styles')) return;
  const tag = document.createElement('style');
  tag.id = 'member-layout-styles';
  tag.textContent = layoutStyles;
  document.head.appendChild(tag);
}

const navLinks = [
  { to: '/member', label: 'Dashboard', icon: <MdDashboard size={18} />, end: true },
  { to: '/member/products', label: 'Products', icon: <MdInventory size={18} /> },
  { to: '/member/basket', label: 'Basket', icon: <MdShoppingBasket size={18} /> },
  { to: '/member/orders', label: 'My Orders', icon: <MdAssignment size={18} /> },
  { to: '/member/delivery', label: 'Delivery', icon: <MdLocalShipping size={18} /> },
  { to: '/member/sites', label: 'Sites', icon: <MdLocationCity size={18} /> },
];

export default function MemberLayout() {
  const { member, logout } = useAuth();
  const navigate = useNavigate();
  const [broadcast, setBroadcast] = useState('');
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [cartCount, setCartCount] = useState(0);
  useEffect(() => {
    const updateCartCount = () => {
      try {
        const cart = JSON.parse(localStorage.getItem('bm_member_cart') || '[]');
        const total = cart.reduce((sum: number, item: any) => sum + (item.qty || 0), 0);
        setCartCount(total);
      } catch {
        setCartCount(0);
      }
    };

    // Initial load
    updateCartCount();

    // Update when localStorage changes
    window.addEventListener('storage', updateCartCount);

    // Update when cart changes in same tab
    const interval = setInterval(updateCartCount, 500);

    return () => {
      window.removeEventListener('storage', updateCartCount);
      clearInterval(interval);
    };
  }, []);

  useEffect(() => { injectLayoutStyles(); }, []);

  useEffect(() => {
    api.get('/settings/public').then(r => setBroadcast(r.data.settings?.broadcastMember || ''));
  }, []);

  // Close drawer on route change
  useEffect(() => { setDrawerOpen(false); }, []);

  const companyName = member?.businessProfile?.companyLogoText || member?.name;
  const companyLogo = member?.businessProfile?.companyLogo;

  const handleLogout = () => { logout(); navigate('/member/login'); };

  return (
    <div className="member-layout">

      {/* Broadcast */}
      {broadcast && (
        <div className="broadcast-bar">
          <FiBell size={14} style={{ flexShrink: 0 }} />
          {broadcast}
        </div>
      )}

      {/* ── Top Nav ── */}
      <nav className="member-nav">
        <div className="member-nav-inner">

          {/* Hamburger (mobile) */}
          <button className="hamburger" onClick={() => setDrawerOpen(true)} aria-label="Open menu">
            <FiMenu size={22} />
          </button>

          {/* Brand */}
          <a href="/member" className="nav-brand">
            <img
              src="/assets/logo/BasavaMartLogo.webp"
              alt="Basava Mart"
              style={{ height: 48, width: 'auto', objectFit: 'contain' }}
            />
            {companyLogo && (
              <>
                <span style={{ color: 'var(--gray-300)', fontSize: 20 }}>|</span>
                <img
                  src={`${companyLogo}`}
                  className="flip-logo"
                  style={{ width: 30, height: 30, objectFit: 'contain', borderRadius: 6 }}
                  alt="Company"
                />
              </>
            )}
            {companyName && <span className="nav-brand-name">{companyName}</span>}
          </a>

          {/* Desktop nav links */}
          <div className="nav-links">
            {navLinks.map(link => (
              <NavLink key={link.to} to={link.to} end={link.end}
                className={({ isActive }) => `nav-link${isActive ? ' active' : ''}`}>
                {link.icon} {link.label}
              </NavLink>
            ))}
          </div>



          <NavLink
            to="/member/cart"
            style={{
              position: 'relative',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              width: 42,
              height: 42,
              borderRadius: 10,
              border: '1.5px solid var(--gray-200)',
              background: 'white',
              color: 'var(--gray-700)',
              textDecoration: 'none',
              flexShrink: 0,
            }}
          >
            <FiShoppingCart size={20} />

            {cartCount > 0 && (
              <span
                style={{
                  position: 'absolute',
                  top: -6,
                  right: -6,
                  minWidth: 20,
                  height: 20,
                  borderRadius: '50%',
                  background: '#e26a26',
                  color: 'white',
                  fontSize: 11,
                  fontWeight: 700,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  padding: '0 6px',
                  boxShadow: '0 2px 6px rgba(0,0,0,0.2)',
                }}
              >
                {cartCount}
              </span>
            )}
          </NavLink>


          {/* Profile dropdown (desktop) */}
          <div className="profile-wrap">
            <div className="profile-trigger">
              <div className="profile-avatar">{member?.name?.charAt(0)}</div>
              <div className="profile-names">
                <span className="pname">{member?.name?.split(' ')[0]}</span>
                <span className="pmid">{member?.memberId}</span>
              </div>
              <FiChevronDown size={14} color="var(--gray-400)" />
            </div>
            <div className="profile-dropdown">
              <NavLink to="/member/profile" className="dropdown-item">
                <FiUser size={18} /> My Profile
              </NavLink>
              <div style={{ borderTop: '1px solid var(--gray-200)' }}>
                <button className="dropdown-item danger" onClick={handleLogout}>
                  <FiLogOut size={18} /> Logout
                </button>
              </div>
            </div>

          </div>


        </div>
      </nav>

      {/* ── Mobile Drawer ── */}
      <div className={`mobile-drawer${drawerOpen ? ' open' : ''}`}>
        <div className="drawer-overlay" onClick={() => setDrawerOpen(false)} />
        <div className="drawer-panel">

          {/* Drawer header */}
          <div className="drawer-header">
            <img src="/assets/logo/BasavaMartLogo.webp" alt="Basava Mart" style={{ height: 40, objectFit: 'contain' }} />
            <button
              onClick={() => setDrawerOpen(false)}
              style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 6, borderRadius: 8, color: 'var(--gray-600)' }}
            >
              <FiX size={22} />
            </button>
          </div>

          {/* Drawer nav links */}
          <nav className="drawer-nav">
            {navLinks.map(link => (
              <NavLink key={link.to} to={link.to} end={link.end}
                className={({ isActive }) => `drawer-link${isActive ? ' active' : ''}`}
                onClick={() => setDrawerOpen(false)}>
                {link.icon} {link.label}
              </NavLink>
            ))}
          </nav>

          {/* Drawer footer: user info + profile + logout */}
          <div className="drawer-footer">
            <div className="drawer-user">
              <div className="profile-avatar" style={{ width: 36, height: 36, fontSize: 15 }}>
                {member?.name?.charAt(0)}
              </div>
              <div>
                <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--gray-800)' }}>{member?.name}</div>
                <div style={{ fontSize: 12, color: 'var(--primary)', fontWeight: 600 }}>{member?.memberId}</div>
              </div>
            </div>

            <NavLink to="/member/profile" className="drawer-link" onClick={() => setDrawerOpen(false)}>
              <FiUser size={18} /> My Profile
            </NavLink>

            <button
              className="drawer-link"
              style={{ width: '100%', border: 'none', background: 'none', cursor: 'pointer', color: 'var(--red)', textAlign: 'left' }}
              onClick={() => { setDrawerOpen(false); handleLogout(); }}
            >
              <FiLogOut size={18} /> Logout
            </button>
          </div>
        </div>
      </div>

      {/* ── Main content ── */}
      <main className="member-main">
        <Outlet />
      </main>
    </div>
  );
}