import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || '/api/mini';

const adminMiniApi = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

adminMiniApi.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

adminMiniApi.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
      localStorage.removeItem('role');
      window.location.href = '/admin/login';
    }
    return Promise.reject(error);
  }
);

export const getMiniUsers = (q = '', status = '') =>
  adminMiniApi.get('/admin/users', { params: { q, status } });

export const createMiniUser = (data: Record<string, unknown>) =>
  adminMiniApi.post('/admin/users', data);

export const updateMiniUser = (id: string, data: Record<string, unknown>) =>
  adminMiniApi.put(`/admin/users/${id}`, data);

export const deleteMiniUser = (id: string) =>
  adminMiniApi.delete(`/admin/users/${id}`);

export const updateMiniUserStatus = (id: string, status: string) =>
  adminMiniApi.patch(`/admin/users/${id}/status`, { status });

export const getNextMiniId = () =>
  adminMiniApi.get('/auth/next-id');

export const getMiniRequests = (status = '', q = '') =>
  adminMiniApi.get('/admin/requests', { params: { status, q } });

export const updateRequestStatus = (id: string, status: string) =>
  adminMiniApi.patch(`/admin/requests/${id}/status`, { status });

export const createRequestVendorForm = (id: string) =>
  adminMiniApi.post(`/admin/requests/${id}/vendor-form`);

export const uploadProductMedia = (productId: string, files: File[], catalogs: File[] = []) => {
  const formData = new FormData();
  files.forEach((file) => formData.append('media', file));
  catalogs.forEach((file) => formData.append('catalogs', file));
  return adminMiniApi.post(`/admin/products/${productId}/media`, formData, {
    headers: { 'Content-Type': 'multipart/form-data' },
  });
};

export const getAdminProducts = (userId = '', q = '', minPrice = '', maxPrice = '') =>
  adminMiniApi.get('/admin/products', { params: { userId, q, minPrice, maxPrice } });

export const createMiniProducts = (products: unknown[]) =>
  adminMiniApi.post('/admin/products', { products });

export const updateMiniProduct = (id: string, data: Record<string, unknown>) =>
  adminMiniApi.put(`/admin/products/${id}`, data);

export const deleteMiniProduct = (id: string) =>
  adminMiniApi.delete(`/admin/products/${id}`);

export const updateMiniProductStatus = (id: string, status: string) =>
  adminMiniApi.patch(`/admin/products/${id}/status`, { status });

export const getPublicMiniProducts = (q = '') =>
  adminMiniApi.get('/admin/public-products', { params: { q } });

export const createPublicProducts = (products: unknown[]) =>
  adminMiniApi.post('/admin/public-products', { products });

export const updatePublicProduct = (id: string, data: Record<string, unknown>) =>
  adminMiniApi.put(`/admin/public-products/${id}`, data);

export const deletePublicProduct = (id: string) =>
  adminMiniApi.delete(`/admin/public-products/${id}`);

export const updatePublicProductStatus = (id: string, status: string) =>
  adminMiniApi.patch(`/admin/public-products/${id}/status`, { status });

export const getTrackingDashboard = (userId: string) =>
  adminMiniApi.get(`/admin/tracking/${userId}`);

export const addAdminNote = (userId: string, orderId: string, message: string) =>
  adminMiniApi.post(`/admin/tracking/${userId}/notes/${orderId}`, { message });

export default adminMiniApi;
