

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { verifyMiniKey, getPublicProducts, submitMiniRequests } from '../miniApi';
import { useMini } from '../MiniContext';
import { useAuth } from '../../context/AuthContext';
import { formatINR } from '../../utils/api';
import MiniBrandFlip from '../components/MiniBrandFlip';
import MiniProductVariants, { MiniProductVariant } from '../components/MiniProductVariants';
import './MiniHome.css';

interface MiniProduct {
  _id?: string;
  productName?: string;
  brandName?: string;
  categoryName?: string;
  subCategoryName?: string;
  hsnCode?: string;
  description?: string;
  descriptions?: Array<{ heading?: string; subHeading?: string; paragraph?: string }>;
  catalogs?: Array<{ url?: string; name?: string }>;
  price?: number;
  unit?: string;
  qty?: number;
  variants?: MiniProductVariant[];
  media?: Array<{ type?: string; url?: string }>;
}

interface PublicCartItem {
  product: MiniProduct;
  qty: number;
}

const isPublicCartItem = (value: unknown): value is PublicCartItem => {
  if (typeof value !== 'object' || value === null || !('product' in value) || !('qty' in value)) {
    return false;
  }
  const item = value as { product: unknown; qty: unknown };
  return typeof item.product === 'object'
    && item.product !== null
    && '_id' in item.product
    && typeof item.product._id === 'string'
    && typeof item.qty === 'number'
    && Number.isInteger(item.qty)
    && item.qty > 0;
};

const PUBLIC_PRODUCTS_PER_PAGE = 10;
const PUBLIC_CART_KEY_PREFIX = 'miniPublicCart';
const PENDING_PUBLIC_PRODUCT_KEY = 'miniGooglePendingProduct';
const MINI_GOOGLE_RETURN_KEY = 'miniGoogleReturnTo';

// Add/remove entries here as you drop more clips into /assets/images.
const HERO_VIDEOS = [
  { src: '/assets/images/bmvideo.webm', caption: 'Genuine parts, sourced fast' },
  { src: '/assets/images/bmvideo2.webm', caption: 'Every component, tested and true' },
  // { src: '/assets/images/bmvideo3.mp4', caption: 'Delivered to your doorstep' },
  // { src: '/assets/images/bmvideo4.mp4', caption: 'Trusted by safety teams' },
];

const SLIDE_DURATION = 766000; // ms between auto-advances

const ABOUT_SLIDES = [
  {
    video: '/assets/videos/step-1.webm',
    eyebrow: 'Step 1',
    heading: 'Tell us what part you need',
    description: 'Find the right spare part or component for your fire-safety equipment.',
  },
  {
    video: '/assets/videos/step-2.webm',
    eyebrow: 'Step 2',
    heading: 'We help you get it',
    description: 'Submit your request and our team will source the exact component for you.',
  },
];

export const MiniHome = () => {
  const navigate = useNavigate();
  const { isAuthenticated, setMiniAuth } = useMini();
  const { user } = useAuth();
  const [miniId, setMiniId] = useState('');
  const [loading, setLoading] = useState(false);
  const [publicProducts, setPublicProducts] = useState<MiniProduct[]>([]);
  const [publicProductsLoaded, setPublicProductsLoaded] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [publicCart, setPublicCart] = useState<PublicCartItem[]>([]);
  const [publicCartReady, setPublicCartReady] = useState(false);
  const [deliveryDetails, setDeliveryDetails] = useState({ name: '', phone: '' });
  const [submittingDelivery, setSubmittingDelivery] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<MiniProduct | null>(null);
  const [modalIndex, setModalIndex] = useState(0);
  const [lightboxOpen, setLightboxOpen] = useState(false);

  const [activeSlide, setActiveSlide] = useState(0);
  const [activeAboutSlide, setActiveAboutSlide] = useState(0);
  const [heroReady, setHeroReady] = useState(false);
  const videoRefs = useRef<Array<HTMLVideoElement | null>>([]);

  useEffect(() => {
    if (isAuthenticated) {
      navigate('/mini/my-sphere');
    }
    fetchPublicProducts();
    const t = setTimeout(() => setHeroReady(true), 60);
    return () => clearTimeout(t);
  }, [isAuthenticated, navigate]);

  useEffect(() => {
    if (!user) {
      setPublicCart([]);
      setPublicCartReady(false);
      return;
    }

    const cartKey = `${PUBLIC_CART_KEY_PREFIX}:${user._id}`;
    try {
      const storedCart = localStorage.getItem(cartKey);
      const parsedCart: unknown = storedCart ? JSON.parse(storedCart) : [];
      if (!Array.isArray(parsedCart) || !parsedCart.every(isPublicCartItem)) {
        throw new Error('Stored Mini cart is not valid');
      }
      setPublicCart(parsedCart);
      setDeliveryDetails((current) => ({ ...current, name: current.name || user.name || '' }));
      setPublicCartReady(true);
    } catch (error) {
      console.error('Error loading Mini public cart:', error);
      toast.error('Could not load your Mini cart');
      setPublicCartReady(false);
    }
  }, [user]);

  useEffect(() => {
    const timer = setInterval(() => {
      setActiveSlide((prev) => (prev + 1) % HERO_VIDEOS.length);
    }, SLIDE_DURATION);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    videoRefs.current.forEach((v, i) => {
      if (!v) return;
      if (i === activeSlide) {
        v.currentTime = 0;
        v.play().catch(() => {
          /* autoplay can be blocked before user interaction on some browsers; muted+inline avoids most cases */
        });
      }
    });
  }, [activeSlide]);

  const fetchPublicProducts = async () => {
    try {
      const res = await getPublicProducts('');
      if (res.data?.success) {
        setPublicProducts((res.data.data || []) as MiniProduct[]);
        setPublicProductsLoaded(true);
      }
    } catch (error) {
      console.error('Error fetching public products:', error);
      toast.error('Could not load products');
    }
  };

  const persistPublicCart = useCallback((items: PublicCartItem[]) => {
    if (!user) return false;
    try {
      localStorage.setItem(`${PUBLIC_CART_KEY_PREFIX}:${user._id}`, JSON.stringify(items));
      setPublicCart(items);
      return true;
    } catch (error) {
      console.error('Error saving Mini public cart:', error);
      toast.error('Could not save your Mini cart');
      return false;
    }
  }, [user]);

  const handleAddPublicProduct = useCallback((product: MiniProduct) => {
    if (!product._id) {
      toast.error('This product cannot be added to the cart');
      return;
    }

    if (!user) {
      sessionStorage.setItem(PENDING_PUBLIC_PRODUCT_KEY, product._id);
      sessionStorage.setItem(MINI_GOOGLE_RETURN_KEY, '/mini#public-cart');
      navigate('/login');
      return;
    }

    if (!publicCartReady) {
      toast.error('Your cart is still loading. Please try again.');
      return;
    }

    const existingItem = publicCart.find((item) => item.product._id === product._id);
    const maxQty = product.qty ?? 0;
    if (maxQty < 1 || (existingItem?.qty ?? 0) >= maxQty) {
      toast.error(maxQty < 1 ? 'This product is out of stock' : 'No more stock is available');
      return;
    }

    const updatedCart = existingItem
      ? publicCart.map((item) => item.product._id === product._id ? { ...item, qty: item.qty + 1, product } : item)
      : [...publicCart, { product, qty: 1 }];
    if (!persistPublicCart(updatedCart)) return;
    toast.success('Added to cart');
    window.setTimeout(() => {
      document.getElementById('mini-public-cart')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 0);
  }, [navigate, persistPublicCart, publicCart, publicCartReady, user]);

  useEffect(() => {
    if (!user || !publicProductsLoaded || !publicCartReady) return;
    const pendingProductId = sessionStorage.getItem(PENDING_PUBLIC_PRODUCT_KEY);
    if (!pendingProductId) return;

    sessionStorage.removeItem(PENDING_PUBLIC_PRODUCT_KEY);
    const pendingProduct = publicProducts.find((product) => product._id === pendingProductId);
    if (!pendingProduct) {
      toast.error('The product you selected is no longer available');
      return;
    }
    handleAddPublicProduct(pendingProduct);
  }, [handleAddPublicProduct, user, publicProducts, publicProductsLoaded, publicCartReady]);

  const handleRemovePublicProduct = (productId: string) => {
    persistPublicCart(publicCart.filter((item) => item.product._id !== productId));
  };

  const handleChangePublicQty = (productId: string, qty: number) => {
    const item = publicCart.find((cartItem) => cartItem.product._id === productId);
    if (!item || qty < 1) return;
    if (qty > (item.product.qty ?? 0)) {
      toast.error('No more stock is available');
      return;
    }
    persistPublicCart(publicCart.map((cartItem) =>
      cartItem.product._id === productId ? { ...cartItem, qty } : cartItem
    ));
  };

  const handleSubmitDeliveryRequest = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!deliveryDetails.name.trim() || !deliveryDetails.phone.trim()) {
      toast.error('Please enter your name and phone number');
      return;
    }
    if (publicCart.length === 0) {
      toast.error('Your cart is empty');
      return;
    }

    setSubmittingDelivery(true);
    try {
      const res = await submitMiniRequests(publicCart.map(({ product, qty }) => ({
        productName: product.productName || 'Mini product',
        qty,
        name: deliveryDetails.name.trim(),
        phone: deliveryDetails.phone.trim(),
        description: product.description || '',
        note: 'Delivery requested from the Mini public products cart',
      })));
      if (!res.data?.success) {
        throw new Error(res.data?.message || 'Delivery request was not submitted');
      }
      if (persistPublicCart([])) {
        toast.success('Delivery request submitted successfully');
      } else {
        toast.error('Request submitted, but the cart could not be cleared on this device');
      }
    } catch (error: unknown) {
      const err = error as { response?: { data?: { message?: string } }; message?: string };
      console.error('Error submitting Mini delivery request:', error);
      toast.error(err.response?.data?.message || err.message || 'Could not submit delivery request');
    } finally {
      setSubmittingDelivery(false);
    }
  };

  const handleVerifyKey = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    if (!miniId.trim()) {
      toast.error('Please enter your Mini ID');
      return;
    }

    setLoading(true);
    try {
      const res = await verifyMiniKey(miniId.trim());

      if (res.success) {
        setMiniAuth(res.miniUser, res.token);
        toast.success('Mini ID verified! Welcome!');
        navigate('/mini/my-sphere');
      } else {
        toast.error(res.message || 'Invalid Mini ID');
      }
    } catch (error: unknown) {
      const err = error as { response?: { data?: { message?: string } } };
      console.error('Error verifying key:', error);
      toast.error(err.response?.data?.message || 'Error verifying Mini ID');
    } finally {
      setLoading(false);
    }
  };

  const handleSearchPublicProducts = async (query: string) => {
    setSearchQuery(query);
    setCurrentPage(1);
    try {
      const res = await getPublicProducts(query);
      if (res.data?.success) {
        setPublicProducts((res.data.data || []) as MiniProduct[]);
        setPublicProductsLoaded(true);
      }
    } catch (error) {
      console.error('Error searching products:', error);
      toast.error('Could not search products');
    }
  };

  const totalPages = Math.max(1, Math.ceil(publicProducts.length / PUBLIC_PRODUCTS_PER_PAGE));
  const visibleProducts = publicProducts.slice(
    (currentPage - 1) * PUBLIC_PRODUCTS_PER_PAGE,
    currentPage * PUBLIC_PRODUCTS_PER_PAGE
  );

  const getMediaKind = (item?: { type?: string; url?: string }) => {
    if (!item || !item.url) return 'image';
    const type = (item.type || '').toLowerCase();
    if (type.includes('video')) return 'video';
    if (type.includes('pdf') || type.includes('document') || item.url.toLowerCase().endsWith('.pdf')) return 'document';
    return 'image';
  };

  const openProductPreview = (product: MiniProduct) => {
    setSelectedProduct(product);
    setModalIndex(0);
    setLightboxOpen(false);
  };

  const closeProductPreview = () => {
    setSelectedProduct(null);
    setModalIndex(0);
    setLightboxOpen(false);
  };

  const renderProductPreviewMedia = () => {
    if (!selectedProduct) return null;
    const media = selectedProduct.media || [];
    if (media.length === 0) {
      return <div className="mini-preview-empty">No Image</div>;
    }

    const item = media[modalIndex];
    const kind = getMediaKind(item);

    if (kind === 'video') {
      return <video src={item.url} controls autoPlay playsInline className="mini-preview-media" />;
    }

    if (kind === 'document') {
      return (
        <a href={item.url} target="_blank" rel="noreferrer" className="mini-preview-doc">
          <span className="mini-preview-doc-icon">📄</span>
          <span>View Document</span>
        </a>
      );
    }

    return <img src={item.url} alt={selectedProduct.productName || 'Product'} className="mini-preview-media" />;
  };

  return (
    <div className="mini-home">
      {/* ── Header / Logo bar — floats over the hero ── */}
      <header className="mini-header">
        <div className="mini-header-inner">
          <div className="mini-logo">
            {/* Swap this block for <img src="/assets/images/logo.png" className="mini-logo-img" /> once you point it at your real logo file */}
            <span className="mini-logo-badge">BM</span>
            <span className="mini-logo-text">
              Basava Mart <span className="mini-logo-accent">Mini</span>
            </span>
          </div>
          <span className="mini-header-tag">Small Part. Big Protection.</span>
        </div>
      </header>

      {/* ── Hero video slider ── */}
      <section className="mini-hero">
        {HERO_VIDEOS.map((slide, i) => (
          <video
            key={slide.src}
            ref={(el) => (videoRefs.current[i] = el)}
            src={slide.src}
            muted
            loop
            playsInline
            autoPlay={i === 0}
            className={`mini-hero-video ${i === activeSlide ? 'is-active' : ''}`}
          />
        ))}

        <div className="mini-hero-overlay" />

        <div className={`mini-hero-content ${heroReady ? 'is-ready' : ''}`}>
          <span className="mini-hero-badge">{HERO_VIDEOS[activeSlide].caption}</span>
          <h1 className="mini-hero-title">Every spare part your fire-safety gear needs</h1>
          <p className="mini-hero-subtitle">
            One nozzle, one seal, one valve at a time — sourced, tested, and delivered.
          </p>
        </div>

        <div className="mini-hero-dots">
          {HERO_VIDEOS.map((_, i) => (
            <button
              key={i}
              onClick={() => setActiveSlide(i)}
              aria-label={`Show slide ${i + 1}`}
              className={`mini-hero-dot ${i === activeSlide ? 'is-active' : ''}`}
            />
          ))}
        </div>
      </section>

      {/* ── Mini Key verification card — overlaps the hero for depth ── */}
      <section className="mini-key-section">
        <div className="mini-key-container">
          <h2 className="mini-key-title">Enter Your Mini Key</h2>
          <form onSubmit={handleVerifyKey} className="mini-key-form">
            <input
              type="text"
              placeholder="e.g., BM26001"
              value={miniId}
              onChange={(e) => setMiniId(e.target.value.toUpperCase())}
              className="mini-key-input"
              disabled={loading}
            />
            <button type="submit" className="mini-key-button" disabled={loading}>
              {loading ? 'Verifying…' : 'Verify'}
            </button>
          </form>
          {miniId && !loading && (
            <p className="mini-key-hint">Format: Enter a Basava Mart Provided Number (e.g., BM27001)</p>
          )}
        </div>
      </section>

      {/* ── Brand flip strip ── */}
      <section className="mini-brand-section">
        <MiniBrandFlip />
      </section>

      {/* ── About ── */}
      <section className="mini-about-section">
        <div className="mini-about-container">
          <h2>What is Basava Mart Mini?</h2>
          <p className="mini-tagline">
            <strong>"Small Part. Big Protection."</strong>
          </p>
          <div className="mini-about-content">
            <p>
              Basava Mart Mini is the <strong>spare-parts and component division</strong> of Basava Mart.
              While Basava Mart sells complete fire-safety, fire-protection, and building-safety products,
              we understand that customers sometimes need just one part—a nozzle, hose, valve, pin, handle,
              pressure gauge, seal, or any other component.
            </p>
            <p>
              Basava Mart Mini exists so you don't have to buy the whole product when you only need one part.
            </p>
            <div className="mini-about-feature">
              <div className="mini-about-feature-copy">
                <span className="mini-about-feature-eyebrow">{ABOUT_SLIDES[activeAboutSlide].eyebrow}</span>
                <h3>{ABOUT_SLIDES[activeAboutSlide].heading}</h3>
                <p>{ABOUT_SLIDES[activeAboutSlide].description}</p>
              </div>
              <div className="mini-about-feature-video-wrap">
                <video
                  key={ABOUT_SLIDES[activeAboutSlide].video}
                  className="mini-about-feature-video"
                  src={ABOUT_SLIDES[activeAboutSlide].video}
                  autoPlay
                  muted
                  playsInline
                  preload="auto"
                  onEnded={() => setActiveAboutSlide((prev) => (prev + 1) % ABOUT_SLIDES.length)}
                  onCanPlay={(event) => { event.currentTarget.play().catch(() => undefined); }}
                />
              </div>
            </div>
            <div className="mini-about-feature-dots" aria-label="How Mini works slides">
              {ABOUT_SLIDES.map((slide, index) => (
                <button
                  key={slide.video}
                  type="button"
                  aria-label={`Show ${slide.eyebrow}`}
                  className={index === activeAboutSlide ? 'active' : ''}
                  onClick={() => setActiveAboutSlide(index)}
                />
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* ── Products ── */}
      <section className="mini-public-products-section">
        <div className="mini-products-container">
          <div className="mini-products-header">
            <h2>Available Mini Products</h2>
            <div className="mini-product-search">
              <input
                type="text"
                placeholder="Search products…"
                value={searchQuery}
                onChange={(e) => handleSearchPublicProducts(e.target.value)}
                className="mini-product-search-input"
              />
            </div>
          </div>

          {user && (
            <section id="mini-public-cart" className="mini-public-cart">
              <div className="mini-public-cart-heading">
                <h3>Your Mini Cart ({publicCart.reduce((count, item) => count + item.qty, 0)})</h3>
              </div>
              {!publicCartReady ? (
                <p className="mini-public-cart-empty">Loading your cart…</p>
              ) : publicCart.length === 0 ? (
                <p className="mini-public-cart-empty">Your cart is empty. Add products to request delivery.</p>
              ) : (
                <>
                  <div className="mini-public-cart-items">
                    {publicCart.map(({ product, qty }) => (
                      <div key={product._id} className="mini-public-cart-item">
                        <div>
                          <strong>{product.productName || 'Product'}</strong>
                          <span>₹{formatINR(product.price)} / {product.unit || 'unit'}</span>
                        </div>
                        <div className="mini-public-cart-controls">
                          <button type="button" onClick={() => handleChangePublicQty(product._id || '', qty - 1)} aria-label="Decrease quantity">−</button>
                          <span>{qty}</span>
                          <button type="button" onClick={() => handleChangePublicQty(product._id || '', qty + 1)} aria-label="Increase quantity">+</button>
                          <button type="button" className="mini-public-cart-remove" onClick={() => handleRemovePublicProduct(product._id || '')}>Remove</button>
                        </div>
                      </div>
                    ))}
                  </div>
                  <form className="mini-delivery-form" onSubmit={handleSubmitDeliveryRequest}>
                    <h4>Request delivery</h4>
                    <div className="mini-delivery-fields">
                      <label>
                        Name
                        <input
                          type="text"
                          required
                          value={deliveryDetails.name}
                          onChange={(event) => setDeliveryDetails({ ...deliveryDetails, name: event.target.value })}
                        />
                      </label>
                      <label>
                        Phone number
                        <input
                          type="tel"
                          required
                          value={deliveryDetails.phone}
                          onChange={(event) => setDeliveryDetails({ ...deliveryDetails, phone: event.target.value })}
                        />
                      </label>
                    </div>
                    <button type="submit" className="mini-delivery-submit" disabled={submittingDelivery}>
                      {submittingDelivery ? 'Submitting…' : 'Submit for delivery'}
                    </button>
                  </form>
                </>
              )}
            </section>
          )}

          {publicProducts.length > 0 ? (
            <div className="mini-public-table-wrap">
              <table className="mini-public-table">
                <thead>
                  <tr>
                    <th>Image Preview</th>
                    <th>Product</th>
                    <th>Brand</th>
                    <th>Category</th>
                    <th>Subcategory</th>
                    <th>HSN</th>
                    <th>Details / Description</th>
                    <th>Price / Stock</th>
                    <th>Catalogue</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {visibleProducts.map((product) => (
                    <tr key={product._id}>
                      <td data-label="Image Preview">
                        <div className="mini-public-media-preview" onClick={() => openProductPreview(product)} role="button" tabIndex={0} onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') openProductPreview(product); }}>
                          {product.media?.[0] ? (
                            getMediaKind(product.media[0]) === 'video' ? <video src={product.media[0].url} muted playsInline /> : <img src={product.media[0].url} alt={product.productName} />
                          ) : <span>No Image</span>}
                          {product.media && product.media.length > 1 && <div className="mini-public-media-strip">{product.media.slice(0, 4).map((item, index) => <span key={`${item.url}-${index}`}>{getMediaKind(item) === 'image' ? <img src={item.url} alt="" /> : getMediaKind(item) === 'video' ? '▶' : '📄'}</span>)}</div>}
                        </div>
                      </td>
                      <td data-label="Product"><strong>{product.productName || 'Product'}</strong></td>
                      <td data-label="Brand">{product.brandName || '—'}</td>
                      <td data-label="Category">{product.categoryName || '—'}</td>
                      <td data-label="Subcategory">{product.subCategoryName || '—'}</td>
                      <td data-label="HSN">{product.hsnCode || '—'}</td>
                      <td data-label="Details / Description"><div className="mini-public-description">{product.description || product.descriptions?.find((item) => item.paragraph)?.paragraph || '—'}</div></td>
                      <td data-label="Price / Stock"><strong className="mini-public-price">₹{formatINR(product.price)}</strong><span className="mini-public-stock">{product.qty ?? 0} available</span><span className="mini-product-unit">/ {product.unit || 'unit'}</span>{!!product.variants?.length && <span className="mini-variants-count">{product.variants.length} variant{product.variants.length === 1 ? '' : 's'} — open preview</span>}</td>
                      <td data-label="Catalogue"><div className="mini-public-links">{product.catalogs?.filter((catalog) => catalog.url).map((catalog, index) => <a key={`${catalog.url}-${index}`} href={catalog.url} target="_blank" rel="noreferrer" download>📄 {catalog.name || `Download ${index + 1}`}</a>) || <span>—</span>}</div></td>
                      <td data-label="Action">
                        <button
                          className="mini-public-preview-btn"
                          onClick={() => openProductPreview(product)}
                        >
                          View Preview
                        </button>
                        <button
                          className="mini-public-add-btn"
                          onClick={() => handleAddPublicProduct(product)}
                          disabled={user ? !publicCartReady || (product.qty ?? 0) < 1 : false}
                        >
                          {publicCart.find((item) => item.product._id === product._id)
                            ? `Add again (${publicCart.find((item) => item.product._id === product._id)?.qty})`
                            : 'Add to cart'}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p className="mini-no-products">No products available. Check back soon!</p>
          )}
          {totalPages > 1 && (
            <div className="mini-products-pagination" aria-label="Product pages">
              <button
                type="button"
                onClick={() => setCurrentPage((page) => Math.max(1, page - 1))}
                disabled={currentPage === 1}
              >
                Previous
              </button>
              <span>Page {currentPage} of {totalPages}</span>
              <button
                type="button"
                onClick={() => setCurrentPage((page) => Math.min(totalPages, page + 1))}
                disabled={currentPage === totalPages}
              >
                Next
              </button>
            </div>
          )}
        </div>
      </section>

      {selectedProduct && (
        <div className="mini-preview-overlay" onClick={closeProductPreview}>
          <div className="mini-preview-modal" onClick={(e) => e.stopPropagation()}>
            <button className="mini-preview-close" onClick={closeProductPreview} aria-label="Close preview">
              ✕
            </button>

            <div className="mini-preview-content">
              <div className="mini-preview-gallery">
                <div className="mini-preview-main" onClick={() => {
                  const media = selectedProduct.media || [];
                  if (media.length > 0 && getMediaKind(media[modalIndex]) === 'image') setLightboxOpen(true);
                }}>
                  {renderProductPreviewMedia()}
                  {(selectedProduct.media?.length || 0) > 1 && (
                    <>
                      <button
                        className="mini-preview-arrow mini-preview-arrow-left"
                        onClick={(e) => {
                          e.stopPropagation();
                          setModalIndex((prev) => {
                            const len = selectedProduct.media?.length || 1;
                            return (prev - 1 + len) % len;
                          });
                        }}
                      >
                        ‹
                      </button>
                      <button
                        className="mini-preview-arrow mini-preview-arrow-right"
                        onClick={(e) => {
                          e.stopPropagation();
                          setModalIndex((prev) => {
                            const len = selectedProduct.media?.length || 1;
                            return (prev + 1) % len;
                          });
                        }}
                      >
                        ›
                      </button>
                    </>
                  )}
                </div>

                {(selectedProduct.media?.length || 0) > 1 && (
                  <div className="mini-preview-thumbs">
                    {selectedProduct.media!.map((item, idx) => (
                      <button
                        key={idx}
                        className={`mini-preview-thumb ${idx === modalIndex ? 'active' : ''}`}
                        onClick={() => setModalIndex(idx)}
                      >
                        {getMediaKind(item) === 'video' ? (
                          <div className="mini-preview-thumb-video">
                            <video src={item.url} muted playsInline />
                            <span>▶</span>
                          </div>
                        ) : getMediaKind(item) === 'document' ? (
                          <div className="mini-preview-thumb-doc">📄</div>
                        ) : (
                          <img src={item.url} alt={`${selectedProduct.productName || 'Product'}-${idx}`} />
                        )}
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <div className="mini-preview-info">
                {selectedProduct.brandName && <span className="mini-preview-brand">{selectedProduct.brandName}</span>}
                <h2>{selectedProduct.productName}</h2>
                <div className="mini-preview-price-row">
                  <span className="mini-preview-price">₹{formatINR(selectedProduct.price)}</span>
                  <span className="mini-preview-unit">/ {selectedProduct.unit || 'unit'}</span>
                </div>

                {selectedProduct.description && (
                  <div className="mini-preview-description">
                    <h3>About this product</h3>
                    <p>{selectedProduct.description}</p>
                  </div>
                )}

                <div className="mini-preview-meta">
                  <span>Brand: {selectedProduct.brandName || '—'}</span>
                  <span>Available: {selectedProduct?.qty ?? 0}</span>
                </div>
                <MiniProductVariants variants={selectedProduct.variants} />
              </div>
            </div>
          </div>
        </div>
      )}

      {lightboxOpen && selectedProduct && (
        <div className="mini-lightbox" onClick={() => setLightboxOpen(false)}>
          <button className="mini-lightbox-close" onClick={() => setLightboxOpen(false)}>✕</button>
          <img src={(selectedProduct.media || [])[modalIndex]?.url} alt="Product preview" />
        </div>
      )}

      {/* ── Footer ── */}
      <footer className="mini-footer">
        <p>&copy; 2026 Basava Mart Mini. Small Parts. Big Protection. All rights reserved.</p>
      </footer>
    </div>
  );
};

export default MiniHome;