import React from 'react';
import { formatINR } from '../../utils/api';
import './MiniProductVariants.css';

export interface MiniProductVariant {
  name?: string;
  date?: string;
  stock?: number;
  unit?: string;
  weight?: number;
  listPrice?: number;
  discountPercent?: number;
  profitPercent?: number;
  gstPercent?: number;
  gstType?: string;
  primaryThreshold?: number;
  primaryThresholdUnit?: string;
  secondaryThreshold?: number;
  secondaryThresholdUnit?: string;
  tertiaryThreshold?: number;
  tertiaryThresholdUnit?: string;
  discountAmount?: number;
  profitAmount?: number;
  basePrice?: number;
  gstAmount?: number;
  finalPrice?: number;
  finalDiscountPercent?: number;
}

type Props = {
  variants?: MiniProductVariant[];
};

const getPricing = (variant: MiniProductVariant) => {
  const listPrice = Number(variant.listPrice) || 0;
  const discountAmount = (listPrice * (Number(variant.discountPercent) || 0)) / 100;
  const discountedPrice = listPrice - discountAmount;
  const profitAmount = (discountedPrice * (Number(variant.profitPercent) || 0)) / 100;
  const basePrice = discountedPrice + profitAmount;
  const gstAmount = (basePrice * (Number(variant.gstPercent) || 0)) / 100;

  return {
    listPrice,
    discountAmount: Number.isFinite(variant.discountAmount) ? Number(variant.discountAmount) : discountAmount,
    profitAmount: Number.isFinite(variant.profitAmount) ? Number(variant.profitAmount) : profitAmount,
    basePrice: Number.isFinite(variant.basePrice) ? Number(variant.basePrice) : basePrice,
    gstAmount: Number.isFinite(variant.gstAmount) ? Number(variant.gstAmount) : gstAmount,
    finalPrice: Number.isFinite(variant.finalPrice) ? Number(variant.finalPrice) : basePrice + gstAmount,
    finalDiscountPercent: Number.isFinite(variant.finalDiscountPercent)
      ? Number(variant.finalDiscountPercent)
      : listPrice > 0 ? ((listPrice - basePrice) / listPrice) * 100 : 0,
  };
};

const formatDate = (value?: string) => {
  if (!value) return '—';
  const dateParts = value.slice(0, 10).split('-');
  return dateParts.length === 3 ? `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}` : value;
};

const thresholdLabel = (value?: number, unit?: string) =>
  `${value ?? 0} ${unit || 'pcs'}`;

export const MiniProductVariants = ({ variants = [] }: Props) => {
  if (!variants.length) return null;

  return (
    <section className="mini-variants" aria-label="Product variants">
      <div className="mini-variants-heading">
        <div>
          <h3>Available Variants</h3>
          <p>{variants.length} option{variants.length === 1 ? '' : 's'} available</p>
        </div>
      </div>
      <div className="mini-variants-list">
        {variants.map((variant, index) => {
          const pricing = getPricing(variant);
          const inStock = (Number(variant.stock) || 0) > 0;
          return (
            <article className="mini-variant-card" key={`${variant.name || 'variant'}-${index}`}>
              <header className="mini-variant-header">
                <div>
                  <span className="mini-variant-index">OPTION {index + 1}</span>
                  <h4>{variant.name || `Variant ${index + 1}`}</h4>
                </div>
                <span className={`mini-variant-stock ${inStock ? 'is-in-stock' : 'is-out-of-stock'}`}>
                  {inStock ? `${variant.stock} in stock` : 'Out of stock'}
                </span>
              </header>

              <div className="mini-variant-details">
                <div><span>Selected Date</span><strong>{formatDate(variant.date)}</strong></div>
                <div><span>Unit</span><strong>{variant.unit || '—'}</strong></div>
                <div><span>Weight</span><strong>{variant.weight ?? 0} kg</strong></div>
                <div><span>GST Type</span><strong>{variant.gstType || 'CGST+SGST'}</strong></div>
                <div><span>Primary Threshold</span><strong>{thresholdLabel(variant.primaryThreshold, variant.primaryThresholdUnit)}</strong></div>
                <div><span>Secondary Threshold</span><strong>{thresholdLabel(variant.secondaryThreshold, variant.secondaryThresholdUnit)}</strong></div>
                <div><span>Tertiary Threshold</span><strong>{thresholdLabel(variant.tertiaryThreshold, variant.tertiaryThresholdUnit)}</strong></div>
              </div>

              <div className="mini-variant-pricing">
                <h5>Price Breakdown</h5>
                <div className="mini-variant-price-grid">
                  <div><span>List Price</span><strong>₹{formatINR(pricing.listPrice)}</strong></div>
                  <div><span>Discount ({variant.discountPercent ?? 0}%)</span><strong className="mini-variant-negative">− ₹{formatINR(pricing.discountAmount)}</strong></div>
                  <div><span>Profit ({variant.profitPercent ?? 0}%)</span><strong>+ ₹{formatINR(pricing.profitAmount)}</strong></div>
                  <div><span>Selling Price</span><strong>₹{formatINR(pricing.basePrice)}</strong></div>
                  <div><span>GST ({variant.gstPercent ?? 0}%)</span><strong>+ ₹{formatINR(pricing.gstAmount)}</strong></div>
                  <div className="mini-variant-final-price"><span>Final Price</span><strong>₹{formatINR(pricing.finalPrice)}</strong></div>
                  <div className="mini-variant-final-discount"><span>Final Discount</span><strong>{pricing.finalDiscountPercent.toFixed(2)}%</strong></div>
                </div>
              </div>
            </article>
          );
        })}
      </div>
    </section>
  );
};

export default MiniProductVariants;
