import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || '/api/mini';

const getMiniToken = (): string | null => localStorage.getItem('miniToken');
const setMiniToken = (token: string) => localStorage.setItem('miniToken', token);
const clearMiniToken = () => localStorage.removeItem('miniToken');

const miniApi = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor to add token
miniApi.interceptors.request.use(
  (config) => {
    const token = getMiniToken();
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Response interceptor to handle token expiry
miniApi.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      clearMiniToken();
      window.location.href = '/mini';
    }
    return Promise.reject(error);
  }
);

// Auth
export const verifyMiniKey = (miniId: string) =>
  miniApi.post('/auth/verify-key', { miniId }).then((res) => {
    if (res.data.success && res.data.token) {
      setMiniToken(res.data.token);
    }
    return res.data;
  });

export const getNextMiniId = () =>
  miniApi.get('/auth/next-id');

// Mini Users (Admin)
export const getMiniUsers = (q = '', status = '') =>
  miniApi.get('/admin/users', { params: { q, status } });

export const createMiniUser = (data: Record<string, unknown>) =>
  miniApi.post('/admin/users', data);

export const updateMiniUser = (id: string, data: Record<string, unknown>) =>
  miniApi.put(`/admin/users/${id}`, data);

export const deleteMiniUser = (id: string) =>
  miniApi.delete(`/admin/users/${id}`);

export const updateMiniUserStatus = (id: string, status: string) =>
  miniApi.patch(`/admin/users/${id}/status`, { status });

// Products (Admin)
export const getAdminProducts = (userId = '', q = '', minPrice = '', maxPrice = '') =>
  miniApi.get('/admin/products', { params: { userId, q, minPrice, maxPrice } });

export const createMiniProducts = (products: unknown[]) =>
  miniApi.post('/admin/products', { products });

export const uploadProductMedia = (productId: string, files: File[]) => {
  const formData = new FormData();
  files.forEach((file: File) => formData.append('media', file));
  return miniApi.post(`/admin/products/${productId}/media`, formData, {
    headers: { 'Content-Type': 'multipart/form-data' },
  });
};

