// Requests (Public)
export const submitMiniRequests = (requests: unknown[]) => {
  const formData = new FormData();
  const requestData = requests.map((request) => {
    const { media, ...requestData } = request as { media?: File[] } & Record<string, unknown>;
    return requestData;
  });
  formData.append('requests', JSON.stringify(requestData));

  requests.forEach((request, index) => {
    const media = (request as { media?: File[] }).media;
    media?.forEach((file) => formData.append(`media_${index}`, file));
  });

  return miniApi.post('/requests', formData, {
    headers: { 'Content-Type': 'multipart/form-data' },
  });
};

// Helper to check if user is authenticated in mini
export const isMiniAuthenticated = () => !!getMiniToken();

export default miniApi;
