import { useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import api from '../utils/api';

interface VisitState {
  visitorId: string;
  sessionId: string;
  pageVisitId: string;
  path: string;
}

const createId = (): string => {
  const bytes = new Uint8Array(16);
  window.crypto.getRandomValues(bytes);
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
};

const getOrCreateId = (storage: Storage, key: string): string => {
  const existingId = storage.getItem(key);
  if (existingId) return existingId;
  const id = createId();
  storage.setItem(key, id);
  return id;
};

const sendVisitEvent = (visit: VisitState, event: string, useBeacon = false) => {
  const payload = { ...visit, pageTitle: document.title, event };
  if (useBeacon && navigator.sendBeacon) {
    const baseUrl = String(api.defaults.baseURL || '/api').replace(/\/$/, '');
    const body = new Blob([JSON.stringify(payload)], { type: 'application/json' });
    if (navigator.sendBeacon(`${baseUrl}/visitors/track`, body)) return;
  }
  api.post('/visitors/track', payload).catch((error: unknown) => {
    console.error('Visitor analytics event could not be recorded:', error);
  });
};

export default function VisitorTracker() {
  const location = useLocation();
  const visitRef = useRef<VisitState | null>(null);
  const pageRoute = location.pathname;

  useEffect(() => {
    let visitorId: string;
    let sessionId: string;
    try {
      if (localStorage.getItem('role') === 'admin' || location.pathname.startsWith('/admin')) return;
      visitorId = getOrCreateId(localStorage, 'bm_visitor_id');
      sessionId = getOrCreateId(sessionStorage, 'bm_visitor_session_id');
    } catch (error) {
      console.error('Visitor analytics storage is unavailable:', error);
      return;
    }

    if (visitRef.current?.path !== pageRoute) {
      visitRef.current = {
        visitorId,
        sessionId,
        pageVisitId: createId(),
        path: pageRoute,
      };
    }
    const currentVisit = visitRef.current;
    sendVisitEvent(currentVisit, 'start');

    const heartbeat = window.setInterval(() => {
      if (document.visibilityState === 'visible') sendVisitEvent(currentVisit, 'heartbeat');
    }, 15000);

    const handleVisibilityChange = () => {
      if (document.visibilityState === 'hidden') {
        sendVisitEvent(currentVisit, 'pause', true);
      } else {
        sendVisitEvent(currentVisit, 'resume');
      }
    };
    const handlePageHide = () => sendVisitEvent(currentVisit, 'end', true);

    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('pagehide', handlePageHide);
    return () => {
      window.clearInterval(heartbeat);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('pagehide', handlePageHide);
      sendVisitEvent(currentVisit, 'end', true);
    };
  }, [location.pathname, pageRoute]);

  return null;
}
