import React, { useState, useEffect } from 'react';
import api, { formatINR, getImageUrl } from '../../utils/api';
import toast from 'react-hot-toast';

// ─── ADMIN ORDERS ────────────────────────────────────────────────────────────
export function AdminOrders() {
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewOrder, setViewOrder] = useState<any>(null);
  const [filters, setFilters] = useState({ status: '', paymentStatus: '', search: '', startDate: '', endDate: '' });
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  const load = async () => {
    setLoading(true);
    const res = await api.get('/orders/admin/all', { params: { ...filters, page, limit: 15 } });
    setOrders(res.data.orders); setTotalPages(res.data.pages);
    setLoading(false);
  };
  useEffect(() => { load(); }, [page, filters]);

  const updateDelivery = async (orderId: string, status: string, message: string, adminNote: string) => {
    await api.put(`/orders/admin/${orderId}/delivery`, { status, message, adminNote });
    toast.success('Status updated'); load();
    if (viewOrder?._id === orderId) { const r = await api.get(`/orders/admin/${orderId}`); setViewOrder(r.data.order); }
  };

  const downloadInvoice = async (orderId: string, orderNumber: string) => {
    const res = await api.get(`/invoice/admin/order/${orderId}`, { responseType: 'blob' });
    const url = window.URL.createObjectURL(new Blob([res.data]));
    const a = document.createElement('a'); a.href = url; a.download = `invoice-${orderNumber}.pdf`; a.click();
  };

  const statuses = ['order_placed','confirmed','processing','shipped','out_for_delivery','delivered','cancelled','returned'];
  const statusColors: any = { delivered: 'badge-success', cancelled: 'badge-danger', order_placed: 'badge-warning', shipped: 'badge-info', confirmed: 'badge-info', processing: 'badge-info' };

  return (
    <div className="fade-in">
      <h1 style={{ fontSize: 22, fontWeight: 700, marginBottom: 20 }}>🛒 User Orders</h1>
      <div style={{ display: 'flex', gap: 10, marginBottom: 20, flexWrap: 'wrap' }}>
        <input className="form-control" placeholder="Search order/user..." style={{ width: 200 }} value={filters.search} onChange={e => setFilters(p => ({ ...p, search: e.target.value }))} />
        <select className="form-control" style={{ width: 160 }} value={filters.status} onChange={e => setFilters(p => ({ ...p, status: e.target.value }))}>
          <option value="">All Status</option>
          {statuses.map(s => <option key={s} value={s}>{s.replace(/_/g, ' ')}</option>)}
        </select>
        <select className="form-control" style={{ width: 150 }} value={filters.paymentStatus} onChange={e => setFilters(p => ({ ...p, paymentStatus: e.target.value }))}>
          <option value="">All Payment</option>
          <option value="paid">Paid</option>
          <option value="pending">Pending</option>
          <option value="failed">Failed</option>
        </select>
        <input type="date" className="form-control" style={{ width: 160 }} value={filters.startDate} onChange={e => setFilters(p => ({ ...p, startDate: e.target.value }))} />
        <input type="date" className="form-control" style={{ width: 160 }} value={filters.endDate} onChange={e => setFilters(p => ({ ...p, endDate: e.target.value }))} />
      </div>
      <div className="card">
        <div className="table-wrapper">
          <table>
            <thead><tr><th>Order #</th><th>Customer</th><th>Items</th><th>Amount</th><th>Payment</th><th>Delivery</th><th>Date</th><th>Actions</th></tr></thead>
            <tbody>
              {orders.map(o => (
                <tr key={o._id}>
                  <td><code style={{ color: 'var(--primary)', fontSize: 12 }}>{o.orderNumber}</code></td>
                  <td><div style={{ fontWeight: 500 }}>{o.userName}</div><div style={{ fontSize: 11, color: 'var(--gray-500)' }}>{o.userEmail}</div></td>
                  <td>{o.items?.length} item(s)</td>
                  <td style={{ fontWeight: 600 }}>₹{formatINR(o.totalAmount)}</td>
                  <td><span className={`badge ${o.paymentStatus === 'paid' ? 'badge-success' : o.paymentStatus === 'failed' ? 'badge-danger' : 'badge-warning'}`}>{o.paymentStatus}</span></td>
                  <td><span className={`badge ${statusColors[o.deliveryStatus] || 'badge-gray'}`} style={{ fontSize: 10 }}>{o.deliveryStatus?.replace(/_/g, ' ')}</span></td>
                  <td style={{ fontSize: 12, color: 'var(--gray-500)' }}>{new Date(o.createdAt).toLocaleDateString('en-IN')}</td>
                  <td>
                    <div style={{ display: 'flex', gap: 4 }}>
                      <button className="btn btn-gray btn-sm" onClick={() => setViewOrder(o)}>👁️ View</button>
                      {o.paymentStatus === 'paid' && <button className="btn btn-outline btn-sm" onClick={() => downloadInvoice(o._id, o.orderNumber)}>📄</button>}
                    </div>
                  </td>
                </tr>
              ))}
              {!orders.length && !loading && <tr><td colSpan={8} style={{ textAlign: 'center', padding: 40, color: 'var(--gray-400)' }}>No orders found</td></tr>}
            </tbody>
          </table>
        </div>
        {totalPages > 1 && <div style={{ padding: 16, display: 'flex', justifyContent: 'center', gap: 4 }}>
          {Array.from({ length: totalPages }, (_, i) => <button key={i} className={`page-btn${page === i+1 ? ' active' : ''}`} onClick={() => setPage(i+1)}>{i+1}</button>)}
        </div>}
      </div>

      {/* Order detail modal */}
      {viewOrder && (
        <div className="modal-overlay" onClick={() => setViewOrder(null)}>
          <div className="modal modal-lg" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Order: {viewOrder.orderNumber}</h2>
              <button className="modal-close" onClick={() => setViewOrder(null)}>✕</button>
            </div>
            <div className="modal-body">
              <div className="grid-2" style={{ marginBottom: 16 }}>
                <div><strong>Customer:</strong> {viewOrder.userName}</div>
                <div><strong>Email:</strong> {viewOrder.userEmail}</div>
                <div><strong>Total:</strong> ₹{formatINR(viewOrder.totalAmount)}</div>
                <div><strong>Payment:</strong> {viewOrder.paymentStatus}</div>
                <div><strong>Razorpay ID:</strong> {viewOrder.razorpayPaymentId || '-'}</div>
                <div><strong>Paid At:</strong> {viewOrder.paidAt ? new Date(viewOrder.paidAt).toLocaleString('en-IN') : '-'}</div>
              </div>
              <h4 style={{ marginBottom: 8 }}>Items</h4>
              {viewOrder.items?.map((item: any) => (
                <div key={item._id} style={{ display: 'flex', gap: 12, padding: '10px 0', borderBottom: '1px solid var(--gray-100)' }}>
                  <img src={getImageUrl(item.productImage)} style={{ width: 56, height: 56, objectFit: 'cover', borderRadius: 8 }} />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 500 }}>{item.productName}</div>
                    <div style={{ fontSize: 12, color: 'var(--gray-500)' }}>Variant: {item.variant?.name} | Qty: {item.quantity}</div>
                    <div style={{ fontSize: 12, color: 'var(--gray-500)' }}>Price: ₹{formatINR(item.variant?.finalPrice)} × {item.quantity} = ₹{formatINR(item.itemTotal)}</div>
                    {item.packageBreakdown && (
                      <div className="pkg-breakdown" style={{ marginTop: 4 }}>
                        {item.packageBreakdown.tertiary?.count > 0 && <div className="pkg-row"><span className="pkg-label">Tertiary</span><span>{item.packageBreakdown.tertiary.count} × {item.packageBreakdown.tertiary.qty} = {item.packageBreakdown.tertiary.total}</span></div>}
                        {item.packageBreakdown.secondary?.count > 0 && <div className="pkg-row"><span className="pkg-label">Secondary</span><span>{item.packageBreakdown.secondary.count} × {item.packageBreakdown.secondary.qty} = {item.packageBreakdown.secondary.total}</span></div>}
                        {item.packageBreakdown.primary?.count > 0 && <div className="pkg-row"><span className="pkg-label">Primary</span><span>{item.packageBreakdown.primary.count} × {item.packageBreakdown.primary.qty} = {item.packageBreakdown.primary.total}</span></div>}
                        {item.packageBreakdown.remainder?.count > 0 && <div className="pkg-row"><span className="pkg-label">Loose</span><span>{item.packageBreakdown.remainder.count} pcs</span></div>}
                      </div>
                    )}
                  </div>
                </div>
              ))}
              {/* Delivery update */}
              <div style={{ marginTop: 16, background: 'var(--gray-50)', borderRadius: 8, padding: 16 }}>
                <h4 style={{ marginBottom: 12 }}>Update Delivery Status</h4>
                <DeliveryStatusUpdater orderId={viewOrder._id} currentStatus={viewOrder.deliveryStatus} onUpdate={updateDelivery} statuses={statuses} />
              </div>
              {/* Delivery history */}
              <div style={{ marginTop: 12 }}>
                <h4 style={{ marginBottom: 8 }}>Delivery Timeline</h4>
                {viewOrder.deliveryUpdates?.map((u: any, i: number) => (
                  <div key={i} style={{ display: 'flex', gap: 12, paddingBottom: 8, borderBottom: '1px solid var(--gray-100)', marginBottom: 8 }}>
                    <div style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--primary)', marginTop: 6, flexShrink: 0 }} />
                    <div>
                      <div style={{ fontSize: 13, fontWeight: 500 }}>{u.status?.replace(/_/g, ' ')}</div>
                      <div style={{ fontSize: 12, color: 'var(--gray-500)' }}>{u.message}</div>
                      <div style={{ fontSize: 11, color: 'var(--gray-400)' }}>{new Date(u.updatedAt).toLocaleString('en-IN')}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function DeliveryStatusUpdater({ orderId, currentStatus, onUpdate, statuses }: any) {
  const [status, setStatus] = useState(currentStatus);
  const [message, setMessage] = useState('');
  const [adminNote, setAdminNote] = useState('');
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      <select className="form-control" value={status} onChange={e => setStatus(e.target.value)}>
        {statuses.map((s: string) => <option key={s} value={s}>{s.replace(/_/g, ' ')}</option>)}
      </select>
      <input className="form-control" placeholder="Status message (shown to customer)" value={message} onChange={e => setMessage(e.target.value)} />
      <input className="form-control" placeholder="Admin note (internal)" value={adminNote} onChange={e => setAdminNote(e.target.value)} />
      <button className="btn btn-primary btn-sm" onClick={() => onUpdate(orderId, status, message, adminNote)}>Update Status</button>
    </div>
  );
}

export default AdminOrders;
