import React from 'react';
import { Link } from 'react-router-dom';
import { FiGrid, FiHome, FiSearch, FiShoppingCart, FiUser } from 'react-icons/fi';
import { cn } from '../../lib/cn';

type MobileBottomNavProps = {
  pathname: string;
  cartCount: number;
  isLoggedIn: boolean;
};

export default function MobileBottomNav({ pathname, cartCount, isLoggedIn }: MobileBottomNavProps) {
  const accountPath = isLoggedIn ? '/profile' : '/login';
  const accountActive = pathname === '/profile' || pathname === '/login';
  const productsActive = pathname === '/products' || pathname.startsWith('/products/');
  const itemClass = (active: boolean) => cn(
    'flex min-h-11 min-w-0 flex-1 flex-col items-center justify-center gap-1 px-1 text-[11px] font-semibold transition-colors focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-primary-500',
    active ? 'text-primary-600' : 'text-ink-500 hover:text-ink-900',
  );

  return (
    <nav
      aria-label="Mobile bottom navigation"
      className="bm-pb-safe fixed inset-x-0 bottom-0 z-40 flex min-h-16 items-stretch border-t border-ink-200 bg-white/95 px-2 pt-1 shadow-nav backdrop-blur-xl md:hidden"
    >
      <Link to="/" className={itemClass(pathname === '/')} aria-current={pathname === '/' ? 'page' : undefined} aria-label="Home">
        <FiHome className="h-5 w-5" aria-hidden="true" />
        <span>Home</span>
      </Link>
      <Link to="/products" className={itemClass(productsActive)} aria-current={productsActive ? 'page' : undefined} aria-label="Products">
        <FiGrid className="h-5 w-5" aria-hidden="true" />
        <span>Products</span>
      </Link>
      <Link to="/products" className={itemClass(false)} aria-label="Search products">
        <FiSearch className="h-5 w-5" aria-hidden="true" />
        <span>Search</span>
      </Link>
      <Link
        to="/cart"
        className={itemClass(pathname === '/cart')}
        aria-current={pathname === '/cart' ? 'page' : undefined}
        aria-label={`Cart, ${cartCount} items`}
      >
        <span className="relative inline-flex">
          <FiShoppingCart className="h-5 w-5" aria-hidden="true" />
          {cartCount > 0 && <span className="alert-badge animate-bounce-soft">{cartCount}</span>}
        </span>
        <span>Cart</span>
      </Link>
      <Link to={accountPath} className={itemClass(accountActive)} aria-current={accountActive ? 'page' : undefined} aria-label="Account">
        <FiUser className="h-5 w-5" aria-hidden="true" />
        <span>Account</span>
      </Link>
    </nav>
  );
}
