

import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams, useParams } from 'react-router-dom';
import api, { formatINR, getImageUrl } from '../../utils/api';
import { useCart } from '../../context/CartContext';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';
import SEO from '../../components/shared/SEO';
import {
  FiFilter,
  FiX,
  FiShoppingCart,
  FiChevronLeft,
  FiChevronRight,
  FiPackage,
  FiSliders,
  FiTag,
  FiLayers,
  FiGrid,
} from 'react-icons/fi';

export default function ProductListPage() {
  const [products, setProducts] = useState<any[]>([]);
  const [brands, setBrands] = useState<any[]>([]);
  const [categories, setCategories] = useState<any[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(40);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);

  const { brandId } = useParams();
  const [searchParams, setSearchParams] = useSearchParams();

  const [filters, setFilters] = useState({
    brand: brandId || '',
    category: searchParams.get('category') || '',
    subcategory: searchParams.get('subcategory') || '',
  });

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const { addItem } = useCart();
  const { user } = useAuth();
  const navigate = useNavigate();
  const searchQuery = searchParams.get('search') || '';

  // Fetch brand list once
  useEffect(() => {
    api.get('/brands', { params: { limit: 100, accessLevel: 'user' } }).then(r => setBrands(r.data.brands));
  }, []);

  // Keep filters.brand in sync with the URL path (handles back/forward + shared links)
  useEffect(() => {
    setFilters(prev => ({ ...prev, brand: brandId || '' }));
  }, [brandId]);

  // Fetch categories whenever brand changes
  useEffect(() => {
    let active = true;
    if (!filters.brand) {
      setCategories([]);
      return () => { active = false; };
    }
    api.get(`/categories/brand/${filters.brand}`, { params: { accessLevel: 'user' } })
      .then(r => { if (active) setCategories(r.data.categories || []); })
      .catch(() => { if (active) { setCategories([]); toast.error('Unable to load brand categories'); } });
    return () => { active = false; };
  }, [filters.brand]);

  // Keep category/subcategory/search synced to query string (brand lives in the path, not here)
  useEffect(() => {
    const params: any = {};
    if (searchQuery) params.search = searchQuery;
    if (filters.category) params.category = filters.category;
    if (filters.subcategory) params.subcategory = filters.subcategory;
    setSearchParams(params, { replace: true });
  }, [filters.category, filters.subcategory, searchQuery]);

  // Fetch products whenever page/filters/search change
  useEffect(() => {
    setLoading(true);
    const params: any = { page: 1, limit: page * pageSize, accessLevel: 'user' };
    if (searchQuery) params.search = searchQuery;
    if (filters.brand) params.brand = filters.brand;
    if (filters.category) params.category = filters.category;
    if (filters.subcategory) params.subcategory = filters.subcategory;
    let active = true;
    Promise.all([api.get('/products', { params }), api.get('/pipes', { params })]).then(([productResponse, pipeResponse]) => {
      if (!active) return;
      const pipeProducts = (pipeResponse.data.pipes || []).map((pipe: any) => ({ ...pipe, _catalogType: 'pipe' }));
      const allProducts = [...(productResponse.data.products || []), ...pipeProducts]
        .sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime());
      const combinedTotal = (productResponse.data.total || 0) + (pipeResponse.data.total || 0);
      setProducts(allProducts.slice((page - 1) * pageSize, page * pageSize));
      setTotal(combinedTotal);
      setTotalPages(Math.max(1, Math.ceil(combinedTotal / pageSize)));
    }).catch(() => {
      if (!active) return;
      setProducts([]);
      setTotal(0);
      setTotalPages(1);
      toast.error('Unable to load products. Please try again.');
    }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [page, pageSize, filters, searchQuery]);

  // Reset to page 1 whenever the page size changes
  const handlePageSizeChange = (size: number) => {
    setPageSize(size);
    setPage(1);
  };

  const handleAdd = (p: any, v: any, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!user) { toast.error('Please login'); navigate('/login'); return; }
    const weightedAmount = p._catalogType === 'pipe' ? (Number(v.weight) || 0) * (Number(v.listPrice) || 0) : v.listPrice;
    addItem({
      productId: p._id, variantId: v._id, productName: p.name,
      productImage: p.images?.[0] || '', brandName: p.brand?.name || '',
      variantName: v.name, unit: v.unit, listPrice: weightedAmount,
      discountPercent: v.discountPercent, discountAmount: v.discountAmount,
      gstPercent: v.gstPercent, gstType: v.gstType, gstAmount: v.gstAmount,
      finalPrice: v.finalPrice, primaryThreshold: v.primaryThreshold || 0,
      secondaryThreshold: v.secondaryThreshold || 0, tertiaryThreshold: v.tertiaryThreshold || 0
    });
    toast.success('Added to cart!');
  };

  const activeFilterCount = [filters.brand, filters.category, filters.subcategory].filter(Boolean).length;

  const selectedBrand = brands.find(b => b._id === filters.brand);
  const otherBrands = brands.filter(b => b._id !== filters.brand);

  // Keep the selected filter responsive while the route remains shareable.
  const selectBrand = (newBrandId: string) => {
    setFilters(prev => ({ ...prev, brand: newBrandId, category: '', subcategory: '' }));
    setPage(1);
    setSidebarOpen(false);
    navigate(newBrandId ? `/products/brand/${newBrandId}` : '/products');
  };

  const clearFilters = () => {
    setFilters({ brand: '', category: '', subcategory: '' });
    setSidebarOpen(false);
    navigate('/products');
  };

  const FilterPanel = () => (
    <div style={{ padding: 16 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16 }}>
        <FiSliders size={16} color="var(--primary)" />
        <h3 style={{ fontSize: 15, fontWeight: 700, margin: 0 }}>Filters</h3>
      </div>

      <div className="form-group">
        <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <FiTag size={13} /> Brand
        </label>
        <select className="form-control" value={filters.brand}
          onChange={e => selectBrand(e.target.value)}>
          <option value="">All Brands</option>
          {brands.map(b => <option key={b._id} value={b._id}>{b.name}</option>)}
        </select>
      </div>

      {selectedBrand && (
        <>
          {/* Selected brand card */}
          <div style={{
            display: 'flex', alignItems: 'center', gap: 10,
            padding: 10, marginBottom: 16,
            border: '1px solid var(--gray-200)', borderRadius: 10,
            background: 'var(--gray-50)'
          }}>
            <div style={{
              width: 44, height: 44, borderRadius: 8,
              background: 'white', border: '1px solid var(--gray-200)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              overflow: 'hidden', flexShrink: 0
            }}>
              {selectedBrand.logo ? (
                <img src={getImageUrl(selectedBrand.logo)} alt={selectedBrand.name}
                  style={{ width: '100%', height: '100%', objectFit: 'contain' }}
                  onError={e => (e.currentTarget.src = '/placeholder.png')} />
              ) : (
                <FiTag size={18} color="var(--gray-400)" />
              )}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 11, color: 'var(--gray-500)', fontWeight: 600 }}>SELECTED BRAND</div>
              <div style={{ fontSize: 14, fontWeight: 700, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {selectedBrand.name}
              </div>
            </div>
          </div>

          {/* Recommended brands */}
          {otherBrands.length > 0 && (
            <div className="form-group">
              <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <FiGrid size={13} /> Recommended Brands
              </label>
              <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fill, minmax(70px, 1fr))',
                gap: 8
              }}>
                {otherBrands.map(b => (
                  <button
                    key={b._id}
                    onClick={() => selectBrand(b._id)}
                    title={b.name}
                    style={{
                      display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4,
                      padding: 6, border: '1px solid var(--gray-200)', borderRadius: 8,
                      background: 'white', cursor: 'pointer'
                    }}
                  >
                    <div style={{
                      width: 36, height: 36, borderRadius: 6,
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                      overflow: 'hidden', flexShrink: 0
                    }}>
                      {b.logo ? (
                        <img src={getImageUrl(b.logo)} alt={b.name}
                          style={{ width: '100%', height: '100%', objectFit: 'contain' }}
                          onError={e => (e.currentTarget.src = '/placeholder.png')} />
                      ) : (
                        <FiTag size={14} color="var(--gray-400)" />
                      )}
                    </div>
                    <span style={{
                      fontSize: 11, fontWeight: 500, color: 'var(--gray-700)',
                      overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                      maxWidth: '100%'
                    }}>
                      {b.name}
                    </span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </>
      )}

      {categories.length > 0 && (
        <div className="form-group">
          <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <FiGrid size={13} /> Category
          </label>
          <select className="form-control" value={filters.category}
            onChange={e => setFilters(p => ({ ...p, category: e.target.value, subcategory: '' }))}>
            <option value="">All Categories</option>
            {categories.map(c => <option key={c._id} value={c._id}>{c.name}</option>)}
          </select>
        </div>
      )}

      {filters.category && categories.find(c => c._id === filters.category)?.subcategories?.length > 0 && (
        <div className="form-group">
          <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <FiLayers size={13} /> Subcategory
          </label>
          <select className="form-control" value={filters.subcategory}
            onChange={e => setFilters(p => ({ ...p, subcategory: e.target.value }))}>
            <option value="">All</option>
            {categories.find(c => c._id === filters.category)?.subcategories?.map((s: any) =>
              <option key={s._id} value={s._id}>{s.name}</option>
            )}
          </select>
        </div>
      )}

      <button className="btn btn-gray btn-sm" style={{ width: '100%' }}
        onClick={clearFilters}>
        Clear Filters
      </button>
    </div>
  );

  const seoQuery = new URLSearchParams();
  if (searchQuery) seoQuery.set('search', searchQuery);
  if (filters.category) seoQuery.set('category', filters.category);
  if (filters.subcategory) seoQuery.set('subcategory', filters.subcategory);

  const seoTitle = selectedBrand
    ? `${selectedBrand.name} Fire Safety Products | Basava Mart`
    : searchQuery
      ? `${searchQuery} – Fire Safety Products Online | Basava Mart`
      : 'Fire Safety Products in Bengaluru & India | Basava Mart';

  const seoDescription = selectedBrand
    ? `Browse ${selectedBrand.name} fire safety products, extinguishers, valves, hydrants, hose pipes and industrial PPE from Basava Mart.`
    : searchQuery
      ? `Explore ${searchQuery} products from Basava Mart, including fire extinguishers, valves, hydrants, safety gloves and industrial safety equipment.`
      : 'Browse fire extinguishers, valves, hydrants, safety gloves, hoses and industrial PPE from Basava Mart in Bengaluru and across India.';

  const canonicalPath = `/products${seoQuery.toString() ? `?${seoQuery.toString()}` : ''}`;
  const itemListJsonLd = products.length ? {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name: seoTitle,
    itemListElement: products.slice(0, 20).map((product, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: product.name,
      url: `https://basavamart.com/products/${product._id}`,
    })),
  } : undefined;

  return (
    <>
      <SEO title={seoTitle} description={seoDescription} canonical={canonicalPath} jsonLd={itemListJsonLd} />
      <div style={{ paddingTop: 24 }}>

      {/* Responsive styles */}
      <style>{`
        .pl-layout { display: flex; gap: 24px; max-width: 1440px; margin: 0 auto; padding: 0 20px; }

        /* Desktop sidebar */
        .pl-sidebar {
          width: 220px;
          flex-shrink: 0;
        }
        .pl-sidebar-card {
          position: sticky;
          top: 80px;
          border: 1px solid var(--gray-200);
          border-radius: 14px;
          box-shadow: 0 4px 18px rgba(15, 23, 42, 0.05);
        }

        /* Mobile filter drawer overlay */
        .pl-filter-overlay {
          display: none;
          position: fixed; inset: 0;
          background: rgba(0,0,0,0.45);
          z-index: 400;
        }
        .pl-filter-overlay.open { display: block; }
        .pl-filter-drawer {
          position: absolute; top: 0; left: 0;
          width: 80%; max-width: 300px; height: 100%;
          background: white;
          overflow-y: auto;
          box-shadow: 4px 0 20px rgba(0,0,0,0.15);
        }
        .pl-filter-drawer-header {
          display: flex; align-items: center; justify-content: space-between;
          padding: 14px 16px;
          border-bottom: 1px solid var(--gray-200);
          position: sticky; top: 0; background: white; z-index: 1;
        }

        /* Mobile filter toggle button */
        .pl-mobile-bar {
          display: none;
          align-items: center;
          justify-content: space-between;
          margin-bottom: 12px;
          gap: 10px;
        }
        .pl-filter-btn {
          display: flex; align-items: center; gap: 6px;
          padding: 8px 14px;
          border: 1.5px solid var(--gray-200);
          border-radius: 8px;
          background: white;
          font-size: 14px; font-weight: 500;
          cursor: pointer;
          color: var(--gray-700);
          position: relative;
        }
        .pl-filter-badge {
          position: absolute; top: -6px; right: -6px;
          background: var(--primary); color: white;
          font-size: 10px; font-weight: 700;
          width: 18px; height: 18px;
          border-radius: 50%;
          display: flex; align-items: center; justify-content: center;
        }

        /* Product grid */
        .pl-grid {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(min(100%, 220px), 1fr));
          gap: 18px;
        }
        .pl-grid .product-card { display: flex; flex-direction: column; min-width: 0; border-radius: 14px; }
        .pl-grid .product-card-image { aspect-ratio: 1.15; }
        .pl-grid .product-card-body { display: flex; flex: 1; flex-direction: column; padding: 14px; }
        .pl-grid .product-card-name { min-height: 40px; }
        .pl-grid .product-card-body > button { margin-top: auto !important; }

        /* Toolbar: page-size selector row above the grid */
        .pl-toolbar {
          display: flex;
          justify-content: flex-end;
          align-items: center;
          margin-bottom: 14px;
          gap: 8px;
        }
        .pl-pagesize-label {
          font-size: 13px;
          color: var(--gray-600);
        }
        .pl-pagesize-select {
          padding: 6px 10px;
          border: 1.5px solid var(--gray-200);
          border-radius: 8px;
          background: white;
          font-size: 13px;
          font-weight: 500;
          color: var(--gray-700);
          cursor: pointer;
        }

        /* Pagination */
        .pl-pagination {
          display: flex;
          justify-content: center;
          align-items: center;
          gap: 6px;
          margin-top: 32px;
          padding-bottom: 32px;
          flex-wrap: wrap;
        }

        @media (max-width: 768px) {
          .pl-layout { display: block; padding: 0 12px; }
          .pl-sidebar  { display: none; }
          .pl-mobile-bar { display: flex; }
          .pl-grid {
            grid-template-columns: repeat(2, 1fr);
            gap: 10px;
          }
          .pl-grid .product-card-image { aspect-ratio: 1; }
          .pl-grid .product-card-body { padding: 10px; }
          .pl-grid .product-card-name { font-size: 13px; min-height: 36px; }
          .pl-grid .product-card-pricing { min-height: 58px; }
          .pl-result-text { font-size: 13px !important; }
          .pl-content { padding-top: 0 !important; }
          .pl-desktop-summary { display: none !important; }

          .pl-toolbar {
            justify-content: center;
            margin-bottom: 10px;
          }
          .pl-pagesize-label { font-size: 12px; }
          .pl-pagesize-select {
            padding: 5px 8px;
            font-size: 12px;
          }

          .pl-pagination {
            gap: 4px;
            margin-top: 20px;
            padding-bottom: 20px;
            flex-wrap: nowrap;
            overflow-x: auto;
            justify-content: flex-start;
            padding-left: 8px;
            padding-right: 8px;
            -webkit-overflow-scrolling: touch;
          }
          .page-btn {
            min-width: 32px !important;
            height: 32px !important;
            padding: 0 6px !important;
            font-size: 12px !important;
          }
        }

        @media (max-width: 400px) {
          .pl-layout { padding: 0 8px; }
          .pl-grid {
            grid-template-columns: repeat(2, 1fr);
            gap: 8px;
          }
          .pl-grid .product-card-body { padding: 8px; }
          .pl-grid .product-card-body > button { font-size: 12px; padding: 7px !important; }
          .pl-pagination {
            gap: 3px;
          }
          .page-btn {
            min-width: 28px !important;
            height: 28px !important;
            font-size: 11px !important;
          }
        }
      `}</style>

      {/* Mobile Filter Drawer */}
      <div className={`pl-filter-overlay${sidebarOpen ? ' open' : ''}`}
        onClick={e => { if (e.target === e.currentTarget) setSidebarOpen(false); }}>
        <div className="pl-filter-drawer">
          <div className="pl-filter-drawer-header">
            <span style={{ fontWeight: 700, fontSize: 15, display: 'flex', alignItems: 'center', gap: 8 }}>
              <FiSliders size={16} color="var(--primary)" /> Filters
            </span>
            <button onClick={() => setSidebarOpen(false)}
              style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--gray-600)', display: 'flex', alignItems: 'center' }}>
              <FiX size={20} />
            </button>
          </div>
          <FilterPanel />
        </div>
      </div>

      <div className="pl-layout">
        {/* Desktop Sidebar */}
        <div className="pl-sidebar">
          <div className="card pl-sidebar-card">
            <FilterPanel />
          </div>
        </div>

        {/* Products */}
        <div style={{ flex: 1 }}>
          {/* Mobile top bar: filter btn + result count */}
          <div className="pl-mobile-bar">
            <button className="pl-filter-btn" onClick={() => setSidebarOpen(true)}>
              <FiFilter size={15} />
              Filters
              {activeFilterCount > 0 && <span className="pl-filter-badge">{activeFilterCount}</span>}
            </button>
            <div className="pl-result-text" style={{ fontSize: 13, color: 'var(--gray-600)', flex: 1, textAlign: 'right' }}>
              {searchQuery && <span>"{searchQuery}" — </span>}{total} products
              {selectedBrand && (
                <span style={{ display: 'block', fontSize: 11, color: 'var(--gray-400)' }}>
                  Brand: {selectedBrand.name}
                </span>
              )}
            </div>
          </div>

          {/* Desktop result count */}
          <div className="pl-desktop-summary"
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: '10px',
              flexWrap: 'wrap',
              padding: '16px 20px',
              marginBottom: '18px',
              background: 'linear-gradient(110deg, #fff7f0, #fff)',
              border: '1px solid #fed7aa',
              borderRadius: '14px',
            }}
          >
            <FiPackage
              style={{
                color: 'var(--primary)',
                fontSize: '26px',
              }}
            />

            <span
              style={{
                fontSize: 'clamp(22px, 3vw, 30px)',
                fontWeight: 800,
                color: '#111827',
                lineHeight: 1.1,
              }}
            >
              {total}
            </span>

            <span
              style={{
                fontSize: '14px',
                fontWeight: 700,
                color: '#ff5c11',
                textTransform: 'uppercase',
                letterSpacing: '.7px',
              }}
            >
              Products Found
            </span>

            {selectedBrand && (
              <span
                style={{
                  fontSize: 13,
                  fontWeight: 600,
                  color: 'var(--gray-500)',
                  background: 'var(--gray-100)',
                  padding: '4px 10px',
                  borderRadius: 6,
                  marginLeft: 4,
                }}
              >
                Brand: {selectedBrand.name}
              </span>
            )}

          </div>

          {/* Per-page selector */}
          <div className="pl-toolbar">
            <span className="pl-pagesize-label">Show</span>
            <select
              className="pl-pagesize-select"
              value={pageSize}
              onChange={e => handlePageSizeChange(Number(e.target.value))}
            >
              <option value={40}>40 / page</option>
              <option value={80}>80 / page</option>
              <option value={100}>100 / page</option>
            </select>
          </div>

          {loading ? (
            <div className="pl-grid">
              {[1, 2, 3, 4, 5, 6].map(i => (
                <div key={i} style={{ height: 280, background: 'var(--gray-100)', borderRadius: 12 }} />
              ))}
            </div>
          ) : (
            <div className="pl-grid">
              {products.map(p => (
                <div key={`${p._catalogType || 'product'}-${p._id}`} className="product-card" onClick={() => navigate(`/products/${p._id}`)}>
                  <div className="product-card-image">
                    <img src={getImageUrl(p.images?.[0])} alt={p.name}
                      onError={e => (e.currentTarget.src = '/placeholder.png')} />
                  </div>
                  <div className="product-card-body">
                    <div className="product-card-brand">{p.brand?.name}</div>
                    <div className="product-card-name">{p.name}</div>
                    {p.category?.name && <div style={{ fontSize: 11, color: 'var(--gray-600)', marginTop: 3 }}>Category: {p.category.name}</div>}
                    {p.subcategory?.name && <div style={{ fontSize: 11, color: 'var(--gray-500)' }}>Subcategory: {p.subcategory.name}</div>}
                    {p.variants?.[0] && (
                      <>
                        {(() => { const v = p.variants[0]; const list = p._catalogType === 'pipe' ? (v.weight || 0) * (v.listPrice || 0) : v.listPrice || 0; const selling = v.basePrice ?? v.finalPrice ?? 0; return <div className="product-card-pricing"><div className="product-card-price-label">Selling Price</div><div className="product-card-price">₹{formatINR(selling)}</div><span className="product-card-list-price">₹{formatINR(list)}</span><span className="product-card-final-discount">Final Discount {Math.max(0, ((list - selling) / (list || 1)) * 100).toFixed(2)}%</span></div>; })()}
                        <div style={{ fontSize: 12, color: p.variants[0].stock > 0 ? 'var(--green)' : 'var(--gray-500)', fontWeight: 600, marginTop: 4 }}>
                          {p.variants[0].stock > 0 ? '✓ In stock' : 'Out of stock'} · {p.variants[0].unit || '-'}
                        </div>
                      </>
                    )}
                    <button
                      className="btn btn-primary"
                      style={{ width: '100%', marginTop: 10, padding: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6 }}
                      onClick={e => p.variants?.[0] && handleAdd(p, p.variants[0], e)}
                    >
                      <FiShoppingCart size={14} /> Add to Cart
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {!loading && products.length === 0 && (
            <div style={{ textAlign: 'center', padding: 80, color: 'var(--gray-400)' }}>
              <FiPackage size={56} style={{ margin: '0 auto 12px', display: 'block' }} />
              <div style={{ fontSize: 18, marginTop: 12 }}>No products found</div>
              <button className="btn btn-outline" style={{ marginTop: 16 }}
                onClick={clearFilters}>
                Clear Filters
              </button>
            </div>
          )}

          {totalPages > 1 && (
            <div className="pl-pagination">
              <button className="page-btn" onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
                style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <FiChevronLeft size={16} />
              </button>
              {Array.from({ length: totalPages }, (_, i) => (
                <button key={i} className={`page-btn${page === i + 1 ? ' active' : ''}`}
                  onClick={() => setPage(i + 1)}>{i + 1}</button>
              ))}
              <button className="page-btn" onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}
                style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <FiChevronRight size={16} />
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
    </>
  );
}