import React, { useEffect, useMemo, useState } from 'react';
import api, { formatINR } from '../../utils/api';
import toast from 'react-hot-toast';

type ColumnKey =
  | 'name'
  | 'email'
  | 'phone'
  | 'status'
  | 'lastSeenAt'
  | 'lastLoginAt'
  | 'cartItems'
  | 'cartValue'
  | 'orderCount'
  | 'totalSpent'
  | 'pendingPayments'
  | 'actions';

interface LoginEntry {
  loginAt?: string;
  ipAddress?: string;
  userAgent?: string;
}

interface OrderHistoryItem {
  _id: string;
  orderNumber?: string;
  totalAmount?: number;
  paymentStatus?: string;
  deliveryStatus?: string;
  createdAt?: string;
}

interface UserTrackRow {
  _id: string;
  name: string;
  email: string;
  phone: string;
  status: string;
  isOnline: boolean;
  lastSeenAt?: string;
  lastLoginAt?: string;
  cartItems: number;
  cartValue: number;
  orderCount: number;
  totalSpent: number;
  pendingPayments: number;
  orderHistory: OrderHistoryItem[];
  loginHistory: LoginEntry[];
}

const defaultColumns: Record<ColumnKey, boolean> = {
  name: true,
  email: true,
  phone: true,
  status: true,
  lastSeenAt: true,
  lastLoginAt: true,
  cartItems: true,
  cartValue: true,
  orderCount: true,
  totalSpent: true,
  pendingPayments: true,
  actions: true,
};

const columnLabels: Record<ColumnKey, string> = {
  name: 'User',
  email: 'Email',
  phone: 'Phone',
  status: 'Status',
  lastSeenAt: 'Last Seen',
  lastLoginAt: 'Last Login',
  cartItems: 'Cart Items',
  cartValue: 'Cart Value',
  orderCount: 'Orders',
  totalSpent: 'Total Spent',
  pendingPayments: 'Pending Pay',
  actions: 'Actions',
};

const statusColors: Record<string, string> = {
  online: 'badge-success',
  active: 'badge-info',
  offline: 'badge-gray',
};

export default function AdminUserTracking() {
  const [users, setUsers] = useState<UserTrackRow[]>([]);
  const [selectedUser, setSelectedUser] = useState<UserTrackRow | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'cart' | 'orders' | 'history'>('overview');
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({ search: '', startDate: '', endDate: '' });
  const [visibleColumns, setVisibleColumns] = useState<Record<ColumnKey, boolean>>({ ...defaultColumns });

  const fetchUsers = async () => {
    try {
      setLoading(true);
      const res = await api.get('/admin/user-tracking', {
        params: {
          search: filters.search,
          startDate: filters.startDate,
          endDate: filters.endDate,
          limit: 500,
        },
      });
      setUsers(res.data.users || []);
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Unable to load user tracking data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, [filters.search, filters.startDate, filters.endDate]);

  const summary = useMemo(() => {
    const online = users.filter((u) => u.isOnline).length;
    const cartUsers = users.filter((u) => u.cartItems > 0).length;
    const pending = users.reduce((sum, user) => sum + user.pendingPayments, 0);
    const totalOrders = users.reduce((sum, user) => sum + user.orderCount, 0);
    const totalRevenue = users.reduce((sum, user) => sum + user.totalSpent, 0);
    return { online, cartUsers, pending, totalOrders, totalRevenue };
  }, [users]);

  const visibleColumnEntries = Object.entries(visibleColumns) as [ColumnKey, boolean][];
  type ExportColumnKey = Exclude<ColumnKey, 'actions'>;

  const exportCsv = () => {
    const cols: ExportColumnKey[] = ['name', 'email', 'phone', 'status', 'lastSeenAt', 'lastLoginAt', 'cartItems', 'cartValue', 'orderCount', 'totalSpent', 'pendingPayments'];
    const header = cols.map((c) => '"' + columnLabels[c].replace(/"/g, '""') + '"').join(',');
    const rows = users.map((user) => cols.map((key) => {
      const value = {
        name: user.name,
        email: user.email,
        phone: user.phone,
        status: user.status,
        lastSeenAt: formatDateTime(user.lastSeenAt),
        lastLoginAt: formatDateTime(user.lastLoginAt),
        cartItems: user.cartItems,
        cartValue: user.cartValue,
        orderCount: user.orderCount,
        totalSpent: user.totalSpent,
        pendingPayments: user.pendingPayments,
      }[key];
      return '"' + String(value ?? '').replace(/"/g, '""') + '"';
    }).join(','));
    const csv = [header, ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'user-activity-tracking.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  const exportPdf = () => {
    const printWindow = window.open('', '_blank', 'width=1200,height=800');
    if (!printWindow) {
      toast.error('Please allow pop-ups to export PDF');
      return;
    }

    const rowsHtml = users.map((user) => `
      <tr>
        <td>${escapeHtml(user.name)}</td>
        <td>${escapeHtml(user.email)}</td>
        <td>${escapeHtml(user.phone)}</td>
        <td>${escapeHtml(user.status)}</td>
        <td>${escapeHtml(formatDateTime(user.lastSeenAt))}</td>
        <td>${escapeHtml(formatDateTime(user.lastLoginAt))}</td>
        <td>${user.cartItems}</td>
        <td>₹${formatINR(user.cartValue)}</td>
        <td>${user.orderCount}</td>
        <td>₹${formatINR(user.totalSpent)}</td>
        <td>${user.pendingPayments}</td>
      </tr>
    `).join('');

    printWindow.document.write(`
      <html>
        <head>
          <title>User Activity Tracking</title>
          <style>
            body { font-family: Arial, sans-serif; padding: 20px; color: #1f2937; }
            table { width: 100%; border-collapse: collapse; font-size: 12px; }
            th, td { border: 1px solid #d1d5db; padding: 8px; text-align: left; }
            th { background: #f3f4f6; }
            h2 { margin-bottom: 20px; }
          </style>
        </head>
        <body>
          <h2>Basava Mart - User Activity Tracking</h2>
          <table>
            <thead>
              <tr>
                <th>User</th><th>Email</th><th>Phone</th><th>Status</th><th>Last Seen</th><th>Last Login</th><th>Cart Items</th><th>Cart Value</th><th>Orders</th><th>Total Spent</th><th>Pending Pay</th>
              </tr>
            </thead>
            <tbody>${rowsHtml}</tbody>
          </table>
        </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.focus();
    printWindow.print();
  };

  const toggleColumn = (key: ColumnKey) => {
    setVisibleColumns((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <div className="fade-in">
      <h1 style={{ fontSize: 22, fontWeight: 700, marginBottom: 20 }}>👤 User Tracking Dashboard</h1>

      <div className="grid-4" style={{ marginBottom: 20 }}>
        <div className="card stat-card">
          <div style={{ color: 'var(--gray-500)', fontSize: 12 }}>Online Now</div>
          <div style={{ fontSize: 28, fontWeight: 700, marginTop: 8 }}>{summary.online}</div>
        </div>
        <div className="card stat-card">
          <div style={{ color: 'var(--gray-500)', fontSize: 12 }}>Active Carts</div>
          <div style={{ fontSize: 28, fontWeight: 700, marginTop: 8 }}>{summary.cartUsers}</div>
        </div>
        <div className="card stat-card">
          <div style={{ color: 'var(--gray-500)', fontSize: 12 }}>Pending Payments</div>
          <div style={{ fontSize: 28, fontWeight: 700, marginTop: 8 }}>{summary.pending}</div>
        </div>
        <div className="card stat-card">
          <div style={{ color: 'var(--gray-500)', fontSize: 12 }}>Total Revenue</div>
          <div style={{ fontSize: 28, fontWeight: 700, marginTop: 8 }}>₹{formatINR(summary.totalRevenue)}</div>
        </div>
      </div>

      <div className="card" style={{ marginBottom: 20, padding: 16 }}>
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center' }}>
          <input
            className="form-control"
            placeholder="Search by name, email, phone"
            value={filters.search}
            onChange={(e) => setFilters((prev) => ({ ...prev, search: e.target.value }))}
            style={{ minWidth: 260 }}
          />
          <input
            type="date"
            className="form-control"
            value={filters.startDate}
            onChange={(e) => setFilters((prev) => ({ ...prev, startDate: e.target.value }))}
          />
          <input
            type="date"
            className="form-control"
            value={filters.endDate}
            onChange={(e) => setFilters((prev) => ({ ...prev, endDate: e.target.value }))}
          />
          <button className="btn btn-primary" onClick={fetchUsers}>🔄 Refresh</button>
          <button className="btn btn-success" onClick={exportCsv}>📊 Excel</button>
          <button className="btn btn-danger" onClick={exportPdf}>📄 PDF</button>
        </div>

        <div style={{ marginTop: 16, display: 'flex', flexWrap: 'wrap', gap: 8 }}>
          {visibleColumnEntries.map(([key, visible]) => (
            <button
              key={key}
              className={`btn btn-sm ${visible ? 'btn-primary' : 'btn-gray'}`}
              onClick={() => toggleColumn(key)}
            >
              {visible ? 'Hide' : 'Show'} {columnLabels[key]}
            </button>
          ))}
        </div>
      </div>

      <div className="card">
        <div className="table-wrapper">
          <table>
            <thead>
              <tr>
                {visibleColumnEntries.filter(([, visible]) => visible).map(([key]) => (
                  <th key={key}>{columnLabels[key]}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan={visibleColumnEntries.filter(([, visible]) => visible).length || 1} style={{ textAlign: 'center', padding: 32, color: 'var(--gray-400)' }}>
                    Loading user activity...
                  </td>
                </tr>
              ) : users.length === 0 ? (
                <tr>
                  <td colSpan={visibleColumnEntries.filter(([, visible]) => visible).length || 1} style={{ textAlign: 'center', padding: 32, color: 'var(--gray-400)' }}>
                    No users found for the selected filters.
                  </td>
                </tr>
              ) : (
                users.map((user) => (
                  <tr key={user._id}>
                    {visibleColumns.name && <td><div style={{ fontWeight: 600 }}>{user.name}</div></td>}
                    {visibleColumns.email && <td>{user.email}</td>}
                    {visibleColumns.phone && <td>{user.phone}</td>}
                    {visibleColumns.status && (
                      <td>
                        <span className={`badge ${statusColors[user.status] || 'badge-gray'}`}>{user.status}</span>
                      </td>
                    )}
                    {visibleColumns.lastSeenAt && <td>{formatDateTime(user.lastSeenAt)}</td>}
                    {visibleColumns.lastLoginAt && <td>{formatDateTime(user.lastLoginAt)}</td>}
                    {visibleColumns.cartItems && <td>{user.cartItems}</td>}
                    {visibleColumns.cartValue && <td>₹{formatINR(user.cartValue)}</td>}
                    {visibleColumns.orderCount && <td>{user.orderCount}</td>}
                    {visibleColumns.totalSpent && <td>₹{formatINR(user.totalSpent)}</td>}
                    {visibleColumns.pendingPayments && <td>{user.pendingPayments}</td>}
                    {visibleColumns.actions && (
                      <td>
                        <button className="btn btn-gray btn-sm" onClick={() => setSelectedUser(user)}>👁️ View</button>
                      </td>
                    )}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {selectedUser && (
        <div className="modal-overlay" onClick={() => setSelectedUser(null)}>
          <div className="modal modal-lg" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>{selectedUser.name}</h2>
              <button className="modal-close" onClick={() => setSelectedUser(null)}>✕</button>
            </div>
            <div className="modal-body">
              <div className="grid-2" style={{ marginBottom: 16 }}>
                <div><strong>Email:</strong> {selectedUser.email}</div>
                <div><strong>Phone:</strong> {selectedUser.phone}</div>
                <div><strong>Status:</strong> <span className={`badge ${statusColors[selectedUser.status] || 'badge-gray'}`}>{selectedUser.status}</span></div>
                <div><strong>Last Seen:</strong> {formatDateTime(selectedUser.lastSeenAt)}</div>
                <div><strong>Last Login:</strong> {formatDateTime(selectedUser.lastLoginAt)}</div>
                <div><strong>Cart Items:</strong> {selectedUser.cartItems}</div>
                <div><strong>Cart Value:</strong> ₹{formatINR(selectedUser.cartValue)}</div>
                <div><strong>Orders:</strong> {selectedUser.orderCount}</div>
                <div><strong>Total Spent:</strong> ₹{formatINR(selectedUser.totalSpent)}</div>
                <div><strong>Pending Pay:</strong> {selectedUser.pendingPayments}</div>
              </div>

              <div style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
                {(['overview', 'cart', 'orders', 'history'] as const).map((tab) => (
                  <button
                    key={tab}
                    className={`btn btn-sm ${activeTab === tab ? 'btn-primary' : 'btn-gray'}`}
                    onClick={() => setActiveTab(tab)}
                  >
                    {tab.charAt(0).toUpperCase() + tab.slice(1)}
                  </button>
                ))}
              </div>

              {activeTab === 'overview' && (
                <div>
                  <h4 style={{ marginBottom: 8 }}>User Summary</h4>
                  <p style={{ color: 'var(--gray-600)' }}>
                    This user has {selectedUser.orderCount} order(s), {selectedUser.cartItems} item(s) in cart, and {selectedUser.pendingPayments} pending payment(s).
                  </p>
                </div>
              )}

              {activeTab === 'cart' && (
                <div>
                  <h4 style={{ marginBottom: 8 }}>Cart Snapshot</h4>
                  {selectedUser.cartItems > 0 ? (
                    <div style={{ background: 'var(--gray-50)', borderRadius: 8, padding: 12 }}>
                      <div style={{ fontWeight: 600 }}>Items: {selectedUser.cartItems}</div>
                      <div style={{ marginTop: 8, color: 'var(--gray-600)' }}>Cart Value: ₹{formatINR(selectedUser.cartValue)}</div>
                    </div>
                  ) : (
                    <p style={{ color: 'var(--gray-500)' }}>No active cart items.</p>
                  )}
                </div>
              )}

              {activeTab === 'orders' && (
                <div>
                  <h4 style={{ marginBottom: 8 }}>Order History</h4>
                  {selectedUser.orderHistory.length ? (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                      {selectedUser.orderHistory.map((order) => (
                        <div key={order._id} style={{ border: '1px solid var(--gray-200)', borderRadius: 8, padding: 12 }}>
                          <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap' }}>
                            <strong>{order.orderNumber || 'Order'}</strong>
                            <span>₹{formatINR(order.totalAmount)}</span>
                          </div>
                          <div style={{ fontSize: 12, color: 'var(--gray-600)', marginTop: 4 }}>
                            {order.paymentStatus} • {order.deliveryStatus} • {formatDateTime(order.createdAt)}
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p style={{ color: 'var(--gray-500)' }}>No order history found for this user.</p>
                  )}
                </div>
              )}

              {activeTab === 'history' && (
                <div>
                  <h4 style={{ marginBottom: 8 }}>Login History</h4>
                  {selectedUser.loginHistory.length ? (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                      {selectedUser.loginHistory.map((entry, index) => (
                        <div key={`${entry.loginAt || index}-${index}`} style={{ border: '1px solid var(--gray-200)', borderRadius: 8, padding: 12 }}>
                          <div style={{ fontWeight: 600 }}>{formatDateTime(entry.loginAt)}</div>
                          <div style={{ color: 'var(--gray-600)', fontSize: 12, marginTop: 4 }}>
                            {entry.ipAddress || 'IP unavailable'} • {entry.userAgent || 'User agent unavailable'}
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p style={{ color: 'var(--gray-500)' }}>No login history available.</p>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function formatDateTime(value?: string) {
  if (!value) return '—';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return '—';
  return d.toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' });
}

function escapeHtml(value: string) {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}
